def _load_audit_module():
    existing = sys.modules.get("qinao_convergence_audit")
    if existing is not None:
        specification = getattr(existing, "__spec__", None)
        loader = getattr(existing, "__loader__", None)
        if (
            Path(str(getattr(existing, "__file__", ""))) == AUDIT_PATH
            and specification is not None
            and getattr(specification, "loader", None) is loader
            and Path(str(getattr(specification, "origin", "")))
            == AUDIT_PATH
            and Path(str(getattr(loader, "path", ""))) == AUDIT_PATH
        ):
            return existing
    if not AUDIT_PATH.is_file():
        return None
    spec = importlib.util.spec_from_file_location("qinao_convergence_audit", AUDIT_PATH)
    if spec is None or spec.loader is None:
        return None
    loaded = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = loaded
    spec.loader.exec_module(loaded)
    return loaded


module = _load_audit_module()


_OSXKEYCHAIN_TOOL_FIXTURE = None


def _actual_osxkeychain_tool_fixture():
    """Return the real helper identity after two identical Git exec-path reads."""

    global _OSXKEYCHAIN_TOOL_FIXTURE
    if _OSXKEYCHAIN_TOOL_FIXTURE is None:
        environment = {
            "HOME": "/nonexistent",
            "LANG": "C",
            "LC_ALL": "C",
            "PATH": "/usr/bin:/bin",
            "GIT_CONFIG_GLOBAL": "/dev/null",
            "GIT_CONFIG_NOSYSTEM": "1",
            "GIT_CONFIG_SYSTEM": "/dev/null",
        }

        def git_output(*arguments):
            completed = subprocess.run(
                ["/usr/bin/git", *arguments],
                env=environment,
                stdin=subprocess.DEVNULL,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                timeout=10,
                check=False,
            )
            if completed.returncode != 0 or completed.stderr:
                raise AssertionError(
                    "fixed /usr/bin/git identity probe failed: "
                    + completed.stderr.decode("utf-8", "replace")
                )
            return completed.stdout

        first_exec_path = git_output("--exec-path")
        second_exec_path = git_output("--exec-path")
        if first_exec_path != second_exec_path:
            raise AssertionError("/usr/bin/git --exec-path double-read drift")
        try:
            exec_path_text = first_exec_path.decode("utf-8", "strict").strip()
        except UnicodeDecodeError as exc:
            raise AssertionError("Git exec-path encoding drift") from exc
        if not exec_path_text or "\x00" in exec_path_text:
            raise AssertionError("Git exec-path framing drift")
        exec_path = Path(exec_path_text).resolve(strict=True)
        helper = (exec_path / "git-credential-osxkeychain").resolve(strict=True)
        try:
            helper.relative_to(exec_path)
        except ValueError as exc:
            raise AssertionError("osxkeychain helper escaped Git exec-path") from exc
        helper_stat = helper.lstat()
        helper_mode = stat.S_IMODE(helper_stat.st_mode)
        if (
            helper.is_symlink()
            or not stat.S_ISREG(helper_stat.st_mode)
            or not helper_mode & stat.S_IXUSR
        ):
            raise AssertionError("osxkeychain helper is not a regular executable")
        helper_bytes = helper.read_bytes()
        if helper_stat.st_size != len(helper_bytes) or not helper_bytes:
            raise AssertionError("osxkeychain helper byte identity drift")
        version_bytes = git_output("--version")
        _OSXKEYCHAIN_TOOL_FIXTURE = {
            "execPath": str(exec_path),
            "tool": {
                "absolutePath": str(helper),
                "fileBytes": helper_bytes,
                "fileMode": helper_mode,
                "versionBytes": version_bytes,
            },
        }
    return copy.deepcopy(_OSXKEYCHAIN_TOOL_FIXTURE)


class _LifecycleProbeRLock:
    """A real reentrant lock with deterministic pre-acquire observation."""

    def __init__(self, *, before_acquire=None, after_acquire=None):
        self._lock = threading.RLock()
        self._metadata_lock = threading.Lock()
        self._owner = None
        self._depth = 0
        self._before_acquire = before_acquire
        self._after_acquire = after_acquire

    @property
    def owner(self):
        with self._metadata_lock:
            return self._owner

    def owned_by_current(self):
        return self.owner == threading.get_ident()

    def acquire(self, blocking=True, timeout=-1):
        contender = threading.get_ident()
        with self._metadata_lock:
            observed_owner = self._owner
        if self._before_acquire is not None:
            self._before_acquire(contender, observed_owner)
        if timeout == -1:
            acquired = self._lock.acquire(blocking)
        else:
            acquired = self._lock.acquire(blocking, timeout)
        if not acquired:
            return False
        with self._metadata_lock:
            if self._owner == contender:
                self._depth += 1
            elif self._owner is None:
                self._owner = contender
                self._depth = 1
            else:
                raise AssertionError("lifecycle probe owner drift")
        if self._after_acquire is not None:
            self._after_acquire(contender)
        return True

    def release(self):
        contender = threading.get_ident()
        with self._metadata_lock:
            if self._owner != contender or self._depth < 1:
                raise AssertionError("lifecycle probe release drift")
            self._depth -= 1
            if self._depth == 0:
                self._owner = None
        self._lock.release()

    def __enter__(self):
        self.acquire()
        return self

    def __exit__(self, exc_type, exc, traceback):
        self.release()
        return False


