def _independent_network_git_process_result(operation, *, source_oid=None):
    if operation == "ls-remote":
        return 0, INDEPENDENT_NETWORK_GIT_LS_REMOTE_STDOUT, b""
    if operation in ("fetch-empty", "fetch-known"):
        return 0, b"", INDEPENDENT_NETWORK_GIT_FETCH_STDERR
    if operation == "push":
        if source_oid is None:
            source_oid = "b" * 40
        return (
            0,
            INDEPENDENT_NETWORK_GIT_PUSH_STDOUT.replace(
                ("b" * 40).encode("ascii"), source_oid.encode("ascii")
            ),
            b"",
        )
    raise AssertionError("unknown independent network Git operation")


def _independent_network_git_transport_result(operation, *, source_oid=None):
    status, stdout, stderr = _independent_network_git_process_result(
        operation, source_oid=source_oid
    )
    return {
        "status": status,
        "stdoutChunks": () if not stdout else (stdout,),
        "stderrChunks": () if not stderr else (stderr,),
    }

