def _buffer_contains(haystack, needle):
    view = memoryview(haystack)
    return any(
        view[offset:offset + len(needle)] == needle
        for offset in range(max(0, len(view) - len(needle) + 1))
    )


class _FixtureRuntime(
    module.ConcreteRuntimeCapability if module is not None else object
):
    """Test-only adapter bridge below the immutable runtime capability type."""

    def __init__(self, adapter):
        super().__init__()
        object.__setattr__(self, "_fixture_adapter", adapter)

    def for_repository(self, repository):
        del repository
        return self

    def credential_fill(
        self, request_bytes, *, capsule, snapshot, preflight
    ):
        if (
            not isinstance(capsule, dict)
            or capsule.get("profile") != "credential-read"
            or capsule.get("preflightRecordDigest")
            != preflight.get("recordDigest")
            or not isinstance(snapshot, dict)
            or snapshot.get("resourceId") != capsule.get("resourceId")
        ):
            raise AssertionError(
                "fixture credential execution capsule binding drift"
            )
        value = self._fixture_adapter.credential_fill(request_bytes)
        if isinstance(value, module.OwnedSecretBuffer):
            return value
        owner = bytearray(value)
        backings = getattr(
            self._fixture_adapter, "mutable_secret_backings", None
        )
        if backings is not None:
            backings.append(owner)
        return module.OwnedSecretBuffer.take(owner)

    def resolve_gh_token(self, *, selected_tool):
        module._revalidate_selected_gh_tool(selected_tool)
        value = self._fixture_adapter.resolve_gh_token(selected_tool=selected_tool)
        if isinstance(value, module.OwnedSecretBuffer):
            return value
        owner = bytearray(value)
        backings = getattr(
            self._fixture_adapter, "mutable_secret_backings", None
        )
        if backings is not None:
            backings.append(owner)
        return module.OwnedSecretBuffer.take(owner)

    def https_request(self, **request):
        return self._fixture_adapter.https_request(**request)

    def lfs_request(self, **request):
        return self._fixture_adapter.lfs_request(**request)

    def execute(self, **request):
        return self._fixture_adapter.execute(**request)

    def resolve_public_addresses(self, host):
        return self._fixture_adapter.resolve_public_addresses(host)

    def initialize_resource(self, resource_path):
        return self._fixture_adapter.initialize_resource(resource_path)

    def observe_resource_ref(self, resource_path, requested_ref):
        return self._fixture_adapter.observe_resource_ref(
            resource_path, requested_ref
        )

    def snapshot(self):
        return self._fixture_adapter.snapshot()

    def structured_snapshot(self):
        return self._fixture_adapter.structured_snapshot()

    def attributable_objects(self, resource_path):
        return self._fixture_adapter.attributable_objects(resource_path)

    def import_resource(self, resource_path, ref, oid):
        return self._fixture_adapter.import_resource(resource_path, ref, oid)

    def complete_import_ref(self, ref, oid):
        return self._fixture_adapter.complete_import_ref(ref, oid)

    def __getattr__(self, name):
        return getattr(self._fixture_adapter, name)


def _runtime_context(adapter):
    return module.CommandContext(runtime=_FixtureRuntime(adapter))


class _ConcreteFixtureResponse:
    def __init__(self, result):
        self.status = result["status"]
        self._headers = list(result["headers"].items())
        self._body = bytearray().join(result["bodyChunks"])
        self._offset = 0

    def getheaders(self):
        return list(self._headers)

    def read(self, maximum):
        if self._offset >= len(self._body):
            return b""
        end = min(len(self._body), self._offset + maximum)
        chunk = bytes(self._body[self._offset:end])
        self._offset = end
        return chunk


class _ConcreteFixtureConnection:
    def __init__(self, adapter, *, host, resolved_addresses):
        self._adapter = adapter
        self._host = host
        self._resolved_addresses = resolved_addresses
        self._result = None

    def request(self, method, path, *, body, headers):
        if (
            self._host == "github.com"
            and path.endswith("/info/lfs/objects/batch")
        ):
            self._result = self._adapter.lfs_request(
                method=method,
                host=self._host,
                path=path,
                headers=headers,
                body=body,
                tls={
                    "verifyCertificate": True,
                    "verifyHostname": True,
                    "redirects": 0,
                    "retries": 0,
                },
            )
        else:
            if self._host != "api.github.com" and not self._resolved_addresses:
                raise AssertionError("signed job-log connection was not DNS-bound")
            self._result = self._adapter.https_request(
                authority=(
                    "gh" if self._host == "api.github.com" else "job-log"
                ),
                method=method,
                host=self._host,
                path=path,
                headers=headers,
                body=body,
            )

    def getresponse(self):
        if self._result is None:
            raise AssertionError("fixture HTTPS response requested before request")
        return _ConcreteFixtureResponse(self._result)

    def close(self):
        return None


