def _assert_credential_fill_process_contract(command, request):
    command = tuple(command)
    if command != _EXPECTED_CREDENTIAL_FILL_COMMAND:
        raise AssertionError("credential fill fixed command drift")
    settings = [
        command[index + 1]
        for index, value in enumerate(command[:-1])
        if value == "-c"
    ]
    if (
        settings.count("credential.helper=") != 1
        or settings.count(_EXPECTED_CREDENTIAL_HELPER_SETTING) != 1
        or settings.index("credential.helper=")
        >= settings.index(_EXPECTED_CREDENTIAL_HELPER_SETTING)
    ):
        raise AssertionError("credential fill helper reset/order drift")
    cwd = request.get("cwd")
    if not isinstance(cwd, Path):
        raise AssertionError("credential fill isolated cwd is absent")
    cwd = cwd.resolve()
    resource_path = cwd.parent
    if (
        cwd.name != "work"
        or not cwd.is_dir()
        or list(cwd.iterdir())
        or (cwd / ".git").exists()
        or not (resource_path / "capsule.json").is_file()
        or (resource_path / "repository.git").exists()
        or tuple(request.get("pass_fds", ()))
    ):
        raise AssertionError("credential fill cwd/capsule isolation drift")
    if dict(request.get("environment", {})) != dict(
        module._NETWORK_CHILD_ENVIRONMENT
    ):
        raise AssertionError("credential fill environment drift")


def _owned_process_runtime_fixture(testcase, *, process_seam, gh_executable="/usr/bin/gh", **runtime_arguments):
    """Model completed test children below the production lifecycle boundary."""
    original = module._run_bounded_child

    def owned_child(command, **request):
        command = tuple(command)
        callback = request.get("quiescence_callback")
        if callback is None and command[-2:] != ("credential", "fill") and command != (
            gh_executable, "auth", "token", "--hostname", "github.com"
        ):
            return original(command, **request)
        try:
            if callback is not None:
                request["child_lifetime_lease_fd"]._operate(os.fstat)
                anchor = request["cwd_anchor_fd"]._operate(os.fstat)
                if not stat.S_ISDIR(anchor.st_mode):
                    raise AssertionError("fixture cwd anchor drift")
            for feed in request["child_feeds"]:
                feed.prime_for_child()
            seam_request = {key: request[key] for key in (
                "environment", "input_bytes", "timeout_seconds",
                "stdout_max", "stderr_max", "cwd", "cwd_anchor_fd",
                "cwd_anchor_identity", "pass_fds",
            )}
            seam_request.update(
                command=command, child_feed_count=len(request["child_feeds"]),
            )
            return process_seam(**seam_request)
        finally:
            if callback is not None:
                callback()

    patcher = mock.patch.object(module, "_run_bounded_child", side_effect=owned_child)
    patcher.start()
    testcase.addCleanup(patcher.stop)
    return module.ConcreteRuntimeCapability(**runtime_arguments)


def _concrete_runtime_fixture(testcase, adapter):
    adapter.concrete_process_calls = []
    adapter.concrete_broker_child_calls = []
    adapter.concrete_https_connections = []
    selected_gh = module._observe_selected_gh_tool()
    adapter.selected_gh_tool = selected_gh

    def process_seam(**request):
        command = request["command"]
        environment = dict(request["environment"])
        adapter.concrete_process_calls.append(command)
        forbidden = {
            name
            for name, value in environment.items()
            if module._network_environment_name_is_forbidden(name)
            and module._NETWORK_SAFE_FORCED_ENVIRONMENT.get(name) != value
        }
        if forbidden:
            raise AssertionError("forbidden environment reached process seam")
        if command[-2:] == ("credential", "fill"):
            _assert_credential_fill_process_contract(command, request)
            return (
                0,
                adapter.credential_fill(request["input_bytes"]),
                b"",
            )
        if command == (
            selected_gh.path, "auth", "token", "--hostname", "github.com"
        ):
            return 0, adapter.resolve_gh_token(selected_tool=selected_gh) + b"\n", b""
        if not command or command[0] != "/usr/bin/git":
            raise AssertionError("unexpected concrete child command")
        helper_settings = [
            value for value in command
            if value.startswith("credential.helper=!")
        ]
        if len(helper_settings) != 1 or len(request["pass_fds"]) != 1:
            raise AssertionError("concrete Git broker binding drift")
        broker_argv = shlex.split(helper_settings[0].split("=", 1)[1][1:])
        inherited_fd = request["pass_fds"][0]
        if broker_argv[-1] != str(inherited_fd):
            raise AssertionError("concrete Git broker descriptor drift")
        child = subprocess.run(
            broker_argv + ["get"],
            cwd=request["cwd"],
            env=environment,
            input=module._FIXED_GIT_HELPER_GET_INPUT,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            pass_fds=(inherited_fd,),
            timeout=request["timeout_seconds"],
            check=False,
        )
        expected = (
            b"protocol=https\nhost=github.com\n"
            b"path=ChangGeng01/ProjectSix.git\n"
            b"username=qinao\npassword=" + adapter.git_secret + b"\n\n"
        )
        if child.returncode != 0 or child.stderr or child.stdout != expected:
            raise AssertionError("private broker child protocol failed")
        adapter.concrete_broker_child_calls.append(tuple(broker_argv))
        remote = getattr(adapter, "quarantine_remote", None)
        expected_oid = getattr(adapter, "quarantine_expected_oid", None)
        if remote is not None or expected_oid is not None:
            if not isinstance(remote, Path) or not isinstance(expected_oid, str):
                raise AssertionError("concrete quarantine fixture drift")
            if command[-1] != (
                "refs/heads/main:refs/qinao/fetch/observed"
            ):
                raise AssertionError("concrete quarantine refspec drift")
            resource = Path(request["cwd"])
            closure = module._run_git(
                remote,
                ["rev-list", "--objects", "--no-object-names", expected_oid],
            ).decode("ascii").split()
            for oid in closure:
                object_type = module._run_git(
                    remote, ["cat-file", "-t", oid], stdout_max=16,
                ).decode("ascii").strip()
                body = module._run_git(
                    remote, ["cat-file", object_type, oid]
                )
                written = module._run_git(
                    resource,
                    ["hash-object", "-w", "-t", object_type, "--stdin"],
                    input_bytes=body,
                    stdout_max=65,
                ).decode("ascii").strip()
                if written != oid:
                    raise AssertionError("concrete quarantine object drift")
            module._run_git(
                resource,
                [
                    "update-ref", "refs/qinao/fetch/observed",
                    expected_oid,
                ],
            )
            return (
                0,
                b"",
                (
                    b"From https://github.com/ChangGeng01/ProjectSix\n"
                    b" * [new branch]      main       -> "
                    b"refs/qinao/fetch/observed\n"
                ),
            )
        operation = getattr(adapter, "network_git_operation", None)
        if operation is None:
            raise AssertionError("concrete network Git operation is absent")
        return _independent_network_git_process_result(
            operation,
            source_oid=getattr(adapter, "push_source_oid", None),
        )

    def connection_seam(**request):
        adapter.concrete_https_connections.append(dict(request))
        return _ConcreteFixtureConnection(
            adapter,
            host=request["host"],
            resolved_addresses=request["resolved_addresses"],
        )

    return _owned_process_runtime_fixture(testcase,
        process_seam=process_seam,
        gh_executable=selected_gh.path,
        https_connection_seam=connection_seam,
        dns_seam=lambda _host, _port: ["8.8.8.8"],
    )


class _ExternalMatrixStdout:
    def __init__(self):
        self.buffer = io.BytesIO()

    def write(self, value):
        payload = (
            value.encode("utf-8", "strict")
            if isinstance(value, str) else bytes(value)
        )
        return self.buffer.write(payload)

    def flush(self):
        return None


class _ExternalAuthorityAdapter:
    git_secret = b"git-external-matrix-secret"
    gh_secret = b"gh-external-matrix-secret"

    def __init__(self, operation):
        self.operation = operation
        self.process_calls = []
        self.broker_child_calls = []
        self.https_connections = []
        self.lfs_objects = []
        self.credential_endpoint_calls = 0

    def credential_fill(self, request_bytes):
        if request_bytes != module._FIXED_GIT_CREDENTIAL_INPUT:
            raise AssertionError("external credential request drift")
        return (
            b"protocol=https\nhost=github.com\n"
            b"path=ChangGeng01/ProjectSix.git\n"
            b"username=qinao\npassword=" + self.git_secret + b"\n\n"
        )

    def resolve_gh_token(self, *, selected_tool):
        module._revalidate_selected_gh_tool(selected_tool)
        if selected_tool != self.selected_gh_tool:
            raise AssertionError("external selected gh witness drift")
        return self.gh_secret + b"\n"

    def https_request(
        self, *, authority, method, host, path, headers, body=b""
    ):
        del authority
        authorization = headers.get("authorization")
        if host == "api.github.com" and authorization is None:
            raise AssertionError("external HTTPS authorization absent")
        if path == "/user":
            self.credential_endpoint_calls += 1
            payload = b'{"id":7,"login":"qinao"}'
            response_headers = {"content-type": "application/json"}
            if self.credential_endpoint_calls <= 4:
                response_headers["x-oauth-scopes"] = "repo, workflow"
            return {
                "status": 200,
                "headers": response_headers,
                "bodyChunks": [payload[:7], payload[7:]],
            }
        if path == "/repos/ChangGeng01/ProjectSix":
            self.credential_endpoint_calls += 1
            payload = b'{"permissions":{"push":true}}'
            return {
                "status": 200,
                "headers": {
                    "content-type": "application/json",
                    "x-oauth-scopes": "repo, workflow",
                },
                "bodyChunks": [payload],
            }
        if self.operation == "job-log-read":
            if host == "api.github.com":
                if method != "GET" or body:
                    raise AssertionError("external job-log first-hop drift")
                return {
                    "status": 302,
                    "headers": {
                        "location": (
                            "https://productionresultssa1.blob.core.windows.net/"
                            "actions-results/job/opaque?sig=fixture-value"
                        )
                    },
                    "bodyChunks": [],
                }
            if (
                host != "productionresultssa1.blob.core.windows.net"
                or authorization is not None
            ):
                raise AssertionError("external signed-hop authority drift")
            return {
                "status": 200,
                "headers": {"content-type": "text/plain"},
                "bodyChunks": [
                    b"QINAO_TEST_SUMMARY passed=3 failed=0 "
                    b"skipped=0 status=passed\n"
                ],
            }
        if self.operation == "auth-read":
            payload = b'{"id":7,"login":"qinao"}'
        elif self.operation == "merge-put":
            payload = module.canonical_json_bytes({
                "sha": "c" * 40,
                "merged": True,
                "message": "Pull Request successfully merged",
            })
        else:
            payload = b'{"id":7,"status":"completed"}'
        return {
            "status": 200,
            "headers": {"content-type": "application/json"},
            "bodyChunks": [payload[:5], payload[5:]],
        }

    def lfs_request(self, **request):
        if request.get("method") != "POST":
            raise AssertionError("external LFS method drift")
        body = json.loads(request["body"].decode("utf-8", "strict"))
        if body.get("operation") != "upload":
            raise AssertionError("external LFS operation drift")
        return {
            "status": 200,
            "headers": {
                "content-type": "application/vnd.git-lfs+json"
            },
            "bodyChunks": [module.canonical_json_bytes({
                "transfer": "basic", "objects": list(self.lfs_objects),
            })],
        }


@contextlib.contextmanager
def _external_low_network_seams(adapter):
    original_run = module._run_bounded_child
    selected_gh = module._observe_selected_gh_tool()
    adapter.selected_gh_tool = selected_gh

    def run_child(command, **request):
        command = tuple(command)
        adapter.process_calls.append(command)
        owner = request.get("_stdout_owner")
        if command[-2:] == ("credential", "fill"):
            _assert_credential_fill_process_contract(command, request)
            payload = adapter.credential_fill(request.get("input_bytes", b""))
            if owner is not None:
                owner.extend(payload)
                payload = owner
            return 0, payload, b""
        if command == (
            selected_gh.path, "auth", "token", "--hostname", "github.com"
        ):
            payload = adapter.resolve_gh_token(selected_tool=selected_gh)
            if owner is not None:
                owner.extend(payload)
                payload = owner
            return 0, payload, b""
        helpers = [
            value for value in command
            if value.startswith("credential.helper=!")
        ]
        if helpers:
            if command[0] != "/usr/bin/git" or len(helpers) != 1:
                raise AssertionError("external Git transport child drift")
            pass_fds = tuple(request.get("pass_fds", ()))
            child_feeds = tuple(request.get("child_feeds", ()))
            if len(pass_fds) != 1 or len(child_feeds) != 1:
                raise AssertionError("external broker descriptor drift")
            broker_argv = shlex.split(helpers[0].split("=", 1)[1][1:])
            if broker_argv[-1] != str(pass_fds[0]):
                raise AssertionError("external broker argv/fd drift")
            child_feeds[0].prime_for_child()
            child = subprocess.run(
                broker_argv + ["get"],
                cwd=request.get("cwd"),
                env=dict(request["environment"]),
                input=module._FIXED_GIT_HELPER_GET_INPUT,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                pass_fds=pass_fds,
                timeout=request.get("timeout_seconds", 30.0),
                check=False,
            )
            expected = adapter.credential_fill(
                module._FIXED_GIT_CREDENTIAL_INPUT
            )
            if (
                child.returncode != 0 or child.stderr
                or child.stdout != expected
            ):
                raise AssertionError("external private broker protocol drift")
            adapter.broker_child_calls.append(tuple(broker_argv))
            quarantine_remote = getattr(
                adapter, "quarantine_remote", None
            )
            if quarantine_remote is not None:
                resource = Path(request.get("cwd")).resolve()
                remote = Path(quarantine_remote).resolve()
                if command[-1] != (
                    "refs/heads/main:refs/qinao/fetch/observed"
                ):
                    raise AssertionError("external quarantine refspec drift")
                shutil.copytree(
                    remote / "objects", resource / "objects",
                    dirs_exist_ok=True,
                )
                observed = adapter.quarantine_expected_oid
                module._run_git(
                    resource,
                    [
                        "update-ref", "refs/qinao/fetch/observed",
                        observed,
                    ],
                )
                result = (
                    0,
                    b"",
                    (
                        b"From https://github.com/ChangGeng01/ProjectSix\n"
                        b" * [new branch]      main       -> "
                        b"refs/qinao/fetch/observed\n"
                    ),
                )
            else:
                result = _independent_network_git_process_result(
                    adapter.operation,
                    source_oid=getattr(adapter, "push_source_oid", None),
                )
            callback = request.get("quiescence_callback")
            if callback is not None:
                callback()
            return result
        return original_run(command, **request)

    def connection(host, port=443, timeout=None, context=None):
        del port, timeout, context
        adapter.https_connections.append((host, None))
        return _ConcreteFixtureConnection(
            adapter, host=host, resolved_addresses=None
        )

    def bound_connection(
        host, addresses, *, port=443, timeout=None, context=None
    ):
        del port, timeout, context
        normalized = tuple(addresses)
        adapter.https_connections.append((host, normalized))
        return _ConcreteFixtureConnection(
            adapter, host=host, resolved_addresses=normalized
        )

    def getaddrinfo(host, port, **_kwargs):
        if (
            host != "productionresultssa1.blob.core.windows.net"
            or port != 443
        ):
            raise AssertionError("external DNS target drift")
        return [
            (
                module.socket.AF_INET, module.socket.SOCK_STREAM,
                module.socket.IPPROTO_TCP, "", ("8.8.8.8", 443),
            )
        ]

    with mock.patch.object(
        module, "_run_bounded_child", side_effect=run_child
    ), mock.patch.object(
        module.http.client, "HTTPSConnection", side_effect=connection
    ), mock.patch.object(
        module, "_AddressBoundHTTPSConnection", side_effect=bound_connection
    ), mock.patch.object(
        module.socket, "getaddrinfo", side_effect=getaddrinfo
    ):
        yield


def _invoke_production_main(arguments):
    stream = _ExternalMatrixStdout()
    with mock.patch.object(sys, "stdout", stream):
        status = module.main(list(arguments))
    payload = stream.buffer.getvalue()
    return status, None if not payload else module.parse_canonical_json(payload)


def _external_repository_and_ledger(
    base,
    *,
    allowed_child_kinds=(),
    network_remote=False,
    frontier_kind="task",
):
    repository = base / "repository"
    _mkdir(repository)
    module._run_git(repository, ["init", "--quiet"])
    module._run_git(repository, ["config", "user.name", "Qinao Test"])
    module._run_git(
        repository, ["config", "user.email", "qinao-test@invalid.local"]
    )
    (repository / ".gitattributes").write_bytes(b"*.bin -text\n")
    (repository / "safe.txt").write_bytes(b"safe\n")
    module._run_git(repository, ["add", ".gitattributes", "safe.txt"])
    module._run_git(repository, ["commit", "--quiet", "-m", "root"])
    if network_remote:
        module._run_git(
            repository,
            ["remote", "add", "origin", INDEPENDENT_NETWORK_GIT_ENDPOINT],
        )
    root = _new_run_root(base)
    module.init_run_state(root, _task_identity_fields(repository), bootstrap_imports=[])
    frontier = module.frontier_start(
        root,
        frontier_kind=frontier_kind,
        input_digest="9" * 64,
        declared_paths=[],
        expected_tests=["FullRecoveryTests"] if frontier_kind == "task" else [],
        task_number=3 if frontier_kind == "task" else None,
        allowed_child_kinds=allowed_child_kinds,
    )
    return repository, root, frontier


def _external_ledger_sterile(root, repository, target):
    environment = {
        "HOME": str(root / "home"),
        "TMPDIR": str(root / "tmp"),
        "LANG": "C",
        "LC_ALL": "C",
        "PATH": "/usr/bin:/bin",
    }
    completed = subprocess.run(
        [
            sys.executable,
            "-I", "-S", "-B",
            str(repository / "scripts" / "qinao_convergence_audit.py"),
            "sterile-python",
            "--root", str(root),
            "--repository", str(repository),
            "--profile", "ledger",
            "--", *target,
        ],
        cwd=str(repository),
        env=environment,
        stdin=subprocess.DEVNULL,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        timeout=180,
        check=False,
    )
    if completed.returncode != 0:
        raise AssertionError(
            "external ledger sterile route failed: "
            + completed.stderr.decode("utf-8", "replace")
        )
    return completed


def _ledger_completion_repository(base):
    """Real committed scanner input for task-frontier completion fixtures."""
    repository = base / "repository"
    _mkdir(repository)
    _mkdir(repository / "scripts")
    (repository / "scripts" / "qinao_convergence_audit.py").write_bytes(
        AUDIT_PATH.read_bytes()
    )
    (repository / "scripts" / "a.py").write_bytes(b"# safe task input\n")
    (repository / "scripts" / "test_qinao_convergence_audit.py").write_text(
        "import sys\n"
        "import unittest\n"
        "module = sys.modules['qinao_convergence_audit']\n"
        "class LedgerTests(unittest.TestCase):\n"
        "    def test_semantic(self):\n"
        "        self.assertIs(module, sys.modules['qinao_convergence_audit'])\n"
        "        self.assertEqual(6 * 7, 42)\n",
        encoding="utf-8",
    )
    module._run_git(repository, ["init", "--quiet"])
    module._run_git(repository, ["add", "--", "scripts"])
    module._run_git(repository, [
        "-c", "user.name=Qinao Test",
        "-c", "user.email=qinao-test@invalid.local",
        "commit", "--quiet", "-m", "task completion fixture",
    ])
    return repository


def _task_identity_fields(repository):
    """Bind test task starts to the actual fixture repository and branch."""
    identity = _identity_fields(repository)
    identity["branch"] = module._run_git(
        repository, ["symbolic-ref", "-q", "HEAD"]
    ).decode("ascii").strip()
    return identity


def _assert_raw_completion_refused_hot_and_cold(testcase, root, task):
    payload = {
        "frontierId": task["frontierId"], "frontierKind": "task",
        "parentFrontierId": None, "resourceSnapshotDigest": None,
        "terminalContext": None,
    }
    before = {path.name: path.read_bytes() for path in (root / "ledger" / "records").iterdir()}
    with testcase.assertRaisesRegex(module.AuditError, "fresh task completion contract absent"):
        module._append_record(root, "frontier-complete", task["inputDigest"],
            task["declaredPaths"], "completed", payload)
    testcase.assertEqual(before, {path.name: path.read_bytes() for path in (root / "ledger" / "records").iterdir()})
    with module.LedgerTransaction(root, operation_kind="malformed-task-completion-fixture") as transaction:
        recovered = transaction.recover()
        historical = module._new_record(recovered["identity"], recovered["nextSequence"],
            recovered["records"][-1]["recordDigest"], "frontier-complete",
            task["inputDigest"], task["declaredPaths"], "completed", payload)
        with testcase.assertRaises(module.AuditError):
            module._project_state(root, recovered["records"] + [historical], transaction=transaction)
    testcase.assertEqual(before, {path.name: path.read_bytes() for path in (root / "ledger" / "records").iterdir()})


def _initialized_task_root(base, repository=None):
    if repository is None:
        repository = _ledger_completion_repository(base)
    root = _new_run_root(base)
    module.init_run_state(root, _task_identity_fields(repository), bootstrap_imports=[])
    return root


def _ledger_task_clean_scan(root, repository, frontier):
    """Produce a real typed clean scan and its ordered linked outer success."""
    completed = _external_ledger_sterile(root, repository, [
        "secret-scan-worktree", "--root", str(root),
        "--repository", str(repository), "--phase", "ledger-task-completion",
        "--frontier-id", frontier["frontierId"],
    ])
    terminal = module.parse_canonical_json(completed.stdout)
    recovered = module.recover_run_state(root)
    outer = recovered["sterileInvocations"][
        terminal["outerInvocationStartRecordDigest"]
    ]
    if (
        terminal["completionState"] != "secret-scan-clean"
        or outer["state"] != "complete"
        or outer["completion"]["exitCode"] != 0
        or terminal["sequence"] >= outer["completion"]["sequence"]
    ):
        raise AssertionError("real task completion scan authority drift")
    return terminal


def _ledger_task_result(root, repository, frontier):
    """Create the one real changed result, preceded by its typed index scan."""
    selected = repository / frontier["declaredPaths"][0]
    selected.write_bytes(selected.read_bytes() + b"# completed fixture task\n")
    module._run_git(repository, ["add", "--", frontier["declaredPaths"][0]])
    _ledger_task_clean_scan(root, repository, frontier)
    module._run_git(repository, ["-c", "user.name=Qinao Test",
        "-c", "user.email=qinao-test@invalid.local", "commit", "--quiet",
        "-m", "single changed fixture result"])
    result_commit = module._run_git(repository, ["rev-parse", "HEAD"]).decode("ascii").strip()
    completed = _external_ledger_sterile(root, repository, [
        "task-test-run", "--root", str(root), "--repository", str(repository),
        "--target", frontier["expectedTests"][0],
    ])
    recovered = module.recover_run_state(root)
    attempts = list(recovered.get("taskTestAttempts", {}).values())
    if (
        completed.stdout != b"" or recovered.get("classification") != "complete"
        or len(attempts) != 1 or attempts[0].get("state") != "task-tests-success"
    ):
        raise AssertionError("real fixture typed result did not succeed")
    return result_commit


