def _external_seal_json_member(
    root, frontier_id, phase, filename, record, *, parents=()
):
    capture = module.allocate_capture(
        root,
        phase,
        frontier_id=frontier_id,
        parent_capture_records=list(parents),
    )
    member = Path(capture["absolutePath"]) / filename
    module.write_canonical_exclusive(member, record)
    seal = module.seal_capture(root, capture["captureId"], [filename])
    return member, module._ledger_record_path(root, seal), capture["captureId"]


def _external_sealed_preflight(
    base,
    *,
    allowed_child_kinds=(),
    complete_task=True,
    frontier_kind="remote-mutation",
):
    repository, root, task = _external_repository_and_ledger(
        base,
        allowed_child_kinds=allowed_child_kinds,
        network_remote=True,
        frontier_kind=frontier_kind,
    )

    def credential(kind):
        capture = module.allocate_capture(
            root, kind + "-credential-proof",
            frontier_id=task["frontierId"],
        )
        status, record = _invoke_production_main([
            "git-credential-auth-read", "--root", str(root),
            "--repository", str(repository),
            "--capture-id", capture["captureId"],
            "--credential-kind", kind,
        ])
        if status != 0 or record.get("credentialKind") != kind:
            raise AssertionError("external credential CLI drift")
        seal = module.seal_capture(
            root, capture["captureId"], ["credential-proof.json"]
        )
        return module._ledger_record_path(root, seal)

    git_seal = credential("git")
    gh_seal = credential("gh")
    local_capture = module.allocate_capture(
        root, "network-preflight-local", frontier_id=task["frontierId"]
    )
    status, local = _invoke_production_main([
        "network-egress-preflight", "--root", str(root),
        "--capture-id", local_capture["captureId"],
        "--repository", str(repository), "--local-only",
    ])
    if status != 0 or local.get("profile") != "local-only":
        raise AssertionError("external local preflight drift")
    local_seal = module._ledger_record_path(
        root,
        module.seal_capture(
            root, local_capture["captureId"], ["network-egress.json"]
        ),
    )
    full_capture = module.allocate_capture(
        root, "network-preflight-full", frontier_id=task["frontierId"]
    )
    status, full = _invoke_production_main([
        "network-egress-preflight", "--root", str(root),
        "--capture-id", full_capture["captureId"],
        "--repository", str(repository),
        "--baseline-local-seal", str(local_seal),
        "--git-credential-seal", str(git_seal),
        "--gh-credential-seal", str(gh_seal),
        "--fetch-policy", "qinao-fixed-v1",
    ])
    if status != 0 or full.get("profile") != "full":
        raise AssertionError("external full preflight drift")
    full_member = Path(full_capture["absolutePath"]) / "network-egress.json"
    full_seal = module._ledger_record_path(
        root,
        module.seal_capture(
            root, full_capture["captureId"], ["network-egress.json"]
        ),
    )
    if complete_task:
        module.frontier_complete(
            root,
            task["frontierId"],
            input_digest="9" * 64,
            declared_paths=[],
            outcome="completed",
        )
    return {
        "repository": repository,
        "root": root,
        "task": task,
        "preflight": full,
        "preflightPath": full_member,
        "preflightSeal": full_seal,
    }


def _assert_independent_network_authority():
    expected = set(INDEPENDENT_NETWORK_OPERATION_CASES)
    actual = set(module.NETWORK_OPERATION_SPEC)
    if actual != expected:
        raise module.AuditError("independent network authority drift")
    for operation, test_row in INDEPENDENT_NETWORK_OPERATION_CASES.items():
        production = module._network_operation_contract(operation)
        if production["wrapper"] != test_row["wrapper"]:
            raise module.AuditError("independent network wrapper drift")


def _run_independent_network_operation(operation, base):
    if operation not in INDEPENDENT_NETWORK_OPERATION_CASES:
        raise module.AuditError("unknown independent network operation")
    _assert_independent_network_authority()
    case = INDEPENDENT_NETWORK_OPERATION_CASES[operation]
    adapter = _ExternalAuthorityAdapter(operation)
    with _external_low_network_seams(adapter):
        is_fetch = operation in ("fetch-empty", "fetch-known")
        prepared = _external_sealed_preflight(
            base,
            allowed_child_kinds=("quarantine-fetch",) if is_fetch else (),
            complete_task=not is_fetch,
            frontier_kind="task" if is_fetch else "remote-mutation",
        )
        root = prepared["root"]
        wrapper = case["wrapper"]
        child_argv = (
            list(case["argv"])
            if wrapper in ("network-git", "network-gh") else []
        )
        if operation == "push":
            source_oid = module._ascii_git_line(
                prepared["repository"], ["rev-parse", "HEAD"],
                "external network push source",
            )
            child_argv[-1] = (
                source_oid + ":refs/heads/qinao-main-matrix"
            )
            adapter.push_source_oid = source_oid
        capsule = None
        frontier_kind = "remote-mutation"
        frontier_input_digest = "e" * 64
        frontier_options = {}
        if is_fetch:
            capsule = module.prepare_git_execution_capsule(
                root, "fetch-quarantine", prepared["preflight"]
            )
            frontier_kind = "local-resource"
            frontier_input_digest = capsule["snapshot"]["snapshotDigest"]
            frontier_options = {
                "parent_frontier": prepared["task"]["frontierId"],
                "component_kind": "quarantine-fetch",
                "resource_id": capsule["capsule"]["resourceId"],
                "operation_class": "read-only-no-remote-write",
            }
        frontier = module.frontier_start(
            root,
            frontier_kind=frontier_kind,
            input_digest=frontier_input_digest,
            declared_paths=[],
            expected_tests=[],
            **frontier_options,
        )
        if wrapper in ("network-git", "network-gh"):
            body_record = None
            body_path = None
            body_seal = None
            if case["body"] is not None:
                body_record = module.build_network_gh_request_body(
                    operation, case["body"]
                )
                body_path, body_seal, _capture_id = (
                    _external_seal_json_member(
                        root,
                        frontier["frontierId"],
                        "network-gh-request-body",
                        "request-body.json",
                        body_record,
                    )
                )
            manifest = module.seal_network_request_manifest(
                operation,
                child_argv,
                prepared["preflight"],
                request_body_record=body_record,
            )
            intent_path, _intent_seal, _capture_id = (
                _external_seal_json_member(
                    root,
                    frontier["frontierId"],
                    (
                        "network-request"
                        if wrapper == "network-git"
                        else "network-gh-request"
                    ),
                    "request.json",
                    manifest,
                )
            )
            arguments = [
                wrapper,
                "--preflight", str(prepared["preflightPath"]),
                "--intent", str(intent_path),
                "--operation", operation,
            ]
            if operation == "fetch-empty":
                arguments.append("--quarantine-empty")
            elif operation == "fetch-known":
                arguments.append("--quarantine-nonempty")
            if body_record is not None:
                arguments.extend([
                    "--request-body", str(body_path),
                    "--request-body-seal-record", str(body_seal),
                ])
            arguments.extend(["--"] + child_argv)
        else:
            oid = "b" * 64
            objects = [{"oid": oid, "size": 9}]
            adapter.lfs_objects = list(objects)
            candidate_ref = "refs/heads/codex/qinao-git-only-convergence"
            candidate_oid = module._ascii_git_line(
                prepared["repository"], ["rev-parse", "HEAD"],
                "external LFS candidate",
            )
            source = module.build_lfs_source_review(
                candidate_ref, candidate_oid, objects
            )
            _source_path, source_seal, source_capture = (
                _external_seal_json_member(
                    root,
                    frontier["frontierId"],
                    "lfs-source-review",
                    "lfs-source-review.json",
                    source,
                )
            )
            approved = module.build_lfs_approved_manifest(
                source,
                source_review_seal_record_path=str(source_seal),
                source_review_capture_id=source_capture,
            )
            manifest_path, _manifest_seal, _capture_id = (
                _external_seal_json_member(
                    root,
                    frontier["frontierId"],
                    "lfs-approved-manifest",
                    "lfs-approved.json",
                    approved,
                    parents=[source_seal],
                )
            )
            output_capture = module.allocate_capture(
                root,
                "lfs-presence-observation",
                frontier_id=frontier["frontierId"],
                parent_capture_records=[_manifest_seal],
            )
            output = (
                Path(output_capture["absolutePath"])
                / "lfs-remote-observation.json"
            )
            arguments = [
                "lfs-batch-observe",
                "--endpoint",
                "https://github.com/ChangGeng01/ProjectSix.git/info/lfs/objects/batch",
                "--ref", candidate_ref,
                "--manifest", str(manifest_path),
                "--preflight", str(prepared["preflightPath"]),
                "--empty-policy", "emit-no-network",
                "--output", str(output),
            ]
        first_status, _first_output = _invoke_production_main(arguments)
        if first_status != 0:
            raise AssertionError("external production-main operation failed")
        first = module.recover_run_state(root)["networkAttempts"][-1]
        first_bytes = module.canonical_json_bytes(first)
        second_status, _second_output = _invoke_production_main(arguments)
        if second_status != 0:
            raise AssertionError("external production-main reopen failed")
        recovered = module.recover_run_state(root)
        reopened = recovered["networkAttempts"][-1]
        if len(recovered["networkAttempts"]) != 1:
            raise AssertionError("external production-main duplicate attempt")
    return {
        "operation": reopened["attempt"]["operation"],
        "state": reopened["state"],
        "recoveredByteIdentical": (
            first_bytes == module.canonical_json_bytes(reopened)
        ),
        "brokerChildCount": len(adapter.broker_child_calls),
        "mainInvocationCount": 2,
    }


def _external_initialized_root(base):
    root = _new_run_root(base)
    module.init_run_state(root, _identity_fields(base), bootstrap_imports=[])
    return root


def _external_commit(repository, tree, parents, message):
    arguments = [
        "-c", "user.name=Qinao Test",
        "-c", "user.email=qinao-test@invalid.local",
        "commit-tree", tree,
    ]
    for parent in parents:
        arguments.extend(["-p", parent])
    return module._run_git(
        repository, arguments, input_bytes=(message + "\n").encode("ascii")
    ).decode("ascii", "strict").strip()


def _external_topology(repository):
    module._run_git(repository, ["init", "--quiet"])
    tree = module._run_git(repository, ["mktree"]).decode("ascii").strip()
    source = _external_commit(repository, tree, [], "source")
    design = _external_commit(repository, tree, [source], "design")
    design_merge = _external_commit(
        repository, tree, [source, design], "design merge"
    )
    convergence = _external_commit(
        repository, tree, [source, design_merge], "convergence"
    )
    head = _external_commit(repository, tree, [convergence], "head")
    return source, design, design_merge, convergence, head


def _external_tree_from_files(repository, files):
    trie = {}
    for path, payload in files.items():
        cursor = trie
        parts = path.split("/")
        for part in parts[:-1]:
            cursor = cursor.setdefault(part, {})
        cursor[parts[-1]] = payload

    def emit(node):
        rows = []
        for name in sorted(node):
            value = node[name]
            if isinstance(value, dict):
                oid = emit(value)
                mode, object_type = b"040000", b"tree"
            else:
                oid = module._run_git(
                    repository, ["hash-object", "-w", "--stdin"],
                    input_bytes=value,
                ).decode("ascii").strip()
                mode, object_type = b"100644", b"blob"
            rows.append(
                mode + b" " + object_type + b" " + oid.encode("ascii")
                + b"\t" + name.encode("utf-8") + b"\x00"
            )
        return module._run_git(
            repository, ["mktree", "-z"], input_bytes=b"".join(rows)
        ).decode("ascii").strip()

    return emit(trie)


