    advertisement = module.validate_remote_advertisement(
        advertisement_payload, object_format="sha1"
    )
    revision_input = (head_oid + "\n^" + base_oid + "\n").encode(
        "ascii"
    )
    object_oids = module._run_git(
        repository,
        ["rev-list", "--objects", "--no-object-names", "--stdin"],
        input_bytes=revision_input,
    )
    request = b"".join(
        row + b"\n" for row in object_oids[:-1].split(b"\n") if row
    )
    object_types_sizes = module._run_git(
        repository,
        ["cat-file", "--batch-check=%(objectname) %(objecttype) %(objectsize)"],
        input_bytes=request,
    )
    lineage_base = base / "remote-lineage"
    _mkdir(lineage_base)
    lineage = _external_remote_lineage(
        lineage_base, advertisement, advertisement_payload
    )
    paths = {
        "revision": base / "remote-revisions.bin",
        "objects": base / "remote-objects.bin",
        "types": base / "remote-types.bin",
    }
    for name, payload in (
        ("revision", revision_input),
        ("objects", object_oids),
        ("types", object_types_sizes),
    ):
        paths[name].write_bytes(payload)
        paths[name].chmod(0o600)
    return {
        "repository": repository,
        "base": base_oid,
        "head": head_oid,
        "advertisement": advertisement,
        "revisionInput": revision_input,
        "lineage": lineage,
        "paths": paths,
    }


