class _ModuleRequired(unittest.TestCase):
    def setUp(self):
        self.assertIsNotNone(
            module,
            "qinao_convergence_audit.py is intentionally absent during RED",
        )


def _mode(path: Path) -> int:
    return stat.S_IMODE(path.lstat().st_mode)


def _mkdir(path: Path, mode: int = 0o700) -> None:
    path.mkdir(mode=mode)
    os.chmod(path, mode)


def _new_run_root(parent: Path) -> Path:
    root = parent / "run"
    _mkdir(root)
    _mkdir(root / "home")
    _mkdir(root / "tmp")
    _mkdir(root / "bootstrap")
    return root


def _identity_fields(repository: Path) -> dict:
    return {
        "branch": "refs/heads/codex/qinao-git-only-convergence",
        "repository": str(repository.resolve()),
        "S": "f" * 40,
        "D": "d" * 40,
        "C": "c" * 40,
        "C_TREE": EXPECTED_TREE,
        "configDigest": "4" * 64,
        "erratumDigest": ERRATUM_DIGEST,
        "selectedRepairEntryMapDigest": "5" * 64,
        "schemaVersion": "qinao.run-identity.v1",
    }


def _write_exact_probe(bootstrap: Path, name: str) -> None:
    probe = bootstrap / name
    _mkdir(probe, 0o700)
    _mkdir(probe / "objects", 0o755)


def _write_n34_generation(bootstrap: Path, *, erratum_digest: str = ERRATUM_DIGEST) -> None:
    generation = bootstrap / "tree-prediction.N34crC"
    _mkdir(generation)
    _mkdir(generation / "objects")
    shared = b"objects/aa/bb\x00100644\x001\x00" + b"0" * 64 + b"\x00"
    (generation / "shared-objects.before.bin").write_bytes(shared)
    (generation / "shared-objects.after.bin").write_bytes(shared)
    shared_digest = hashlib.sha256(shared).hexdigest()
    proof = (
        "C=" + "c" * 40 + "\n"
        "predicted_tree=" + EXPECTED_TREE + "\n"
        "shared_objects_before_sha256=" + shared_digest + "\n"
        "shared_objects_after_sha256=" + shared_digest + "\n"
        "isolated_regular_file_count=0\n"
        "closure_missing_count=0\n"
        "controller_erratum_sha256=" + erratum_digest + "\n"
    ).encode("ascii")
    result = (
        "predicted_tree=" + EXPECTED_TREE + "\n"
        "shared_objects_before=" + shared_digest + "\n"
    ).encode("ascii")
    (generation / "alternate-reuse-proof.tsv").write_bytes(proof)
    (generation / "result.tsv").write_bytes(result)
    for path in generation.iterdir():
        if path.is_file():
            os.chmod(path, 0o600)


def _write_synthetic_success_scanner(bootstrap: Path, name: str) -> Path:
    generation = bootstrap / name
    _mkdir(generation)
    entries = [
        {
            "pathB64": base64.b64encode(b"safe.txt").decode("ascii"),
            "source": "index",
            "size": 4,
            "sha256": hashlib.sha256(b"safe").hexdigest(),
        }
    ]
    record = module._self_digest_record(
        {
            "schemaVersion": "qinao.secret-scan-worktree.v1",
            "ruleSetVersion": module.RULE_SET_VERSION,
            "ruleSetDigest": module.RULE_SET_DIGEST,
            "ruleCount": len(module.SECRET_RULES),
            "scannedFileCount": 1,
            "scannedByteCount": 4,
            "findingCount": 0,
            "entries": entries,
            "findings": [],
        }
    )
    module.write_canonical_exclusive(generation / "secret-scan.json", record)
    (generation / "terminal.complete").write_bytes(b"complete\n")
    os.chmod(generation / "terminal.complete", 0o600)
    return generation / "secret-scan.json"


def _structured_terminal_fixture(parent: Path, generation_name: str):
    root = _new_run_root(parent)
    bootstrap = root / "bootstrap"
    for name in EXACT_PROBES:
        _write_exact_probe(bootstrap, name)
    _write_n34_generation(bootstrap)
    shutil.copytree(
        FROZEN_BOOTSTRAP_ROOT / generation_name,
        bootstrap / generation_name,
        copy_function=shutil.copy2,
    )
    selected = _write_synthetic_success_scanner(
        bootstrap,
        "capture.task3-secret.abcdef123456",
    )
    return root, selected


def _full_repair_bootstrap_fixture(parent: Path):
    root = _new_run_root(parent)
    bootstrap = root / "bootstrap"
    for name in EXACT_PROBES:
        _write_exact_probe(bootstrap, name)
    _write_n34_generation(bootstrap)
    for name in (
        "capture.task2-merge.tL6p8x",
        "capture.task2-resume.ZbWFBk",
        "capture.tool-projection.JRp96i",
        "capture.task3-secret.ee573e0d5235",
        "capture.sterile-python.f24d9641fa44",
    ):
        shutil.copytree(
            FROZEN_BOOTSTRAP_ROOT / name,
            bootstrap / name,
            copy_function=shutil.copy2,
        )
    selected = _write_synthetic_success_scanner(
        bootstrap,
        "capture.task3-secret.abcdef123456",
    )
    selected_record = module.parse_canonical_json(selected.read_bytes())
    entry_digest = module._sha256(
        module.canonical_json_bytes(selected_record["entries"])
    )
    return root, selected, entry_digest


