    def _completed_ci_policy_fixture(self, base):
        runner, repository, root, protocol = self._real_ci_policy_fixture(base)
        head = module._ascii_git_line(repository, ["rev-parse", "HEAD"], "fixture HEAD")
        event = root.parent / "_github_workflow/event.json"
