    def test_ci_terminal_reopen_rejects_rehashed_binding_tamper(self):
        """Break caught: CI terminal retry never validates existing terminal lineage."""
        with tempfile.TemporaryDirectory() as temporary:
            _runner, _repository, _root, _protocol, diagnostic = self._completed_ci_policy_fixture(Path(temporary))
            path = diagnostic / "terminal.json"
            original = path.read_bytes()
            terminal = module.parse_canonical_json(original)
            terminal["policyCompletedRecordDigest"] = "0" * 64
            terminal.pop("recordDigest")
            terminal["recordDigest"] = hashlib.sha256(module.canonical_json_bytes(terminal)).hexdigest()
            path.write_bytes(module.canonical_json_bytes(terminal))
            try:
                with self.assertRaisesRegex(module.AuditError, "CI terminal.*binding"):
                    module._ci_invocation_finish(diagnostic, 0)
            finally:
                path.write_bytes(original)

