        """Break caught: binders activate twice or lose their explicit outer owner."""
        for profile in ("ci", "ledger"):
            for command in ("ci-bind", "ci-push-bind", "ci-supplemental-bind"):
                with self.subTest(profile=profile, command=command), tempfile.TemporaryDirectory() as temporary:
                    base = Path(temporary)
                    runner, repository, ci_root, protocol = self._real_ci_policy_fixture(base)
