    def test_every_init_publication_boundary_is_interruptible_and_monotone(self):
        expected_boundaries = frozenset(
            {
                "after-staging-directory",
                "after-subdirectory",
                "after-identity-file",
                "after-lock-file",
                "after-initial-record",
                "after-directory-fsync",
                "before-atomic-publish",
                "after-atomic-publish",
                "after-run-root-fsync",
            }
        )
        self.assertEqual(
            module.INIT_INTERRUPTION_BOUNDARIES, expected_boundaries
        )
        imports = [
            module._self_digest_record(
                {"schemaVersion": "qinao.test-bootstrap-import.v1", "name": name},
                field="bootstrapImportDigest",
            )
            for name in ("one", "two")
        ]

        def normalized_event(boundary, path):
            name = Path(path).name
            if name.startswith("ledger.init."):
                name = "."
            return boundary, name

        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)
            root = _new_run_root(base)
            observed = []
            def observe(boundary, operation, subject):
                if operation == "init-run-state":
                    observed.append(normalized_event(boundary, subject))

            module.init_run_state(
                root,
                _identity_fields(base),
                bootstrap_imports=imports,
                _faults=module.DurabilityFaults(observe),
            )
            self.assertEqual(
                frozenset(boundary for boundary, _name in observed),
                expected_boundaries,
            )
            self.assertEqual(
                [name for boundary, name in observed
                 if boundary == "after-subdirectory"],
                [
                    "records", "phases", "captures", "resources",
                    "resource-snapshots", "invocations",
                ],
            )
            self.assertEqual(
                [name for boundary, name in observed
                 if boundary == "after-initial-record"],
                [
                    "0000000000000001.json",
                    "0000000000000002.json",
                    "0000000000000003.json",
                ],
            )
            expected_events = list(observed)

        for target in expected_events:
            with self.subTest(boundary=target), tempfile.TemporaryDirectory() as temporary:
                base = Path(temporary)
                root = _new_run_root(base)
                fired = []

                def interrupt(boundary, operation, subject):
                    if operation != "init-run-state":
                        return
                    event = normalized_event(boundary, subject)
                    if event == target and not fired:
                        fired.append(event)
                        raise InterruptedError("synthetic init interruption")

                with self.assertRaisesRegex(
                    InterruptedError, "synthetic init interruption"
                ):
                    module.init_run_state(
                        root,
                        _identity_fields(base),
                        bootstrap_imports=imports,
                        _faults=module.DurabilityFaults(interrupt),
                    )
                self.assertEqual(fired, [target])
                identity = module.init_run_state(
                    root, _identity_fields(base), bootstrap_imports=imports
                )
