    def test_init_publication_race_reopens_only_a_complete_exact_winner(self):
        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)
            root = _new_run_root(base)
            copied = []

            def exact_winner(_root, staging_name, *, _faults=None):
                staging = root / staging_name
                shutil.copytree(
                    staging, root / "ledger", copy_function=shutil.copy2
                )
                copied.append(staging)
                raise FileExistsError(errno.EEXIST, "external exact winner")

            with mock.patch.object(
                module, "_publish_no_replace", side_effect=exact_winner
            ):
                identity = module.init_run_state(
                    root, _identity_fields(base), bootstrap_imports=[]
                )
            self.assertEqual(
                module.recover_run_state(root)["identity"]["runId"],
                identity["runId"],
            )
            self.assertEqual(len(copied), 1)
            self.assertTrue(copied[0].is_dir())

        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)
            root = _new_run_root(base)

            def corrupt_winner(_root, staging_name, *, _faults=None):
                staging = root / staging_name
                shutil.copytree(
                    staging, root / "ledger", copy_function=shutil.copy2
                )
                terminal = sorted((root / "ledger" / "records").iterdir())[-1]
                terminal.write_bytes(b"{}\n")
                raise FileExistsError(errno.EEXIST, "external corrupt winner")

            with mock.patch.object(
                module, "_publish_no_replace", side_effect=corrupt_winner
            ):
                with self.assertRaisesRegex(
                    module.AuditError, "winner|indeterminate"
                ):
                    module.init_run_state(
                        root, _identity_fields(base), bootstrap_imports=[]
                    )
            self.assertTrue((root / "ledger").is_dir())
            self.assertTrue(any(root.glob("ledger.init.*")))

        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)
            root = _new_run_root(base)
            with mock.patch.object(
                module,
                "_publish_no_replace",
                side_effect=module.AuditError(
                    "no-replace publication unsupported"
                ),
            ):
                with self.assertRaisesRegex(
                    module.AuditError, "unsupported"
                ):
                    module.init_run_state(
                        root, _identity_fields(base), bootstrap_imports=[]
                    )
            self.assertFalse((root / "ledger").exists())
            self.assertTrue(any(root.glob("ledger.init.*")))

