    def test_transaction_unknown_acquisition_is_not_an_empty_success(self):
        """Break caught: syscall-return interruption is certified by an empty arena."""
        for unknown in (True, False):
            with self.subTest(unknown=unknown), tempfile.TemporaryDirectory() as temporary:
                def body():
                    first, _second = self._two_roots(Path(temporary))
                    transaction = module.LedgerTransaction(first, operation_kind="unknown-acquisition")
