    def test_dependent_cleanup_preserves_first_and_ordered_later_failures(self):
        """Break caught: a later independent close masks the first or releases exclusion."""
        for family in ("transaction", "network", "task-test"):
            with self.subTest(family=family), tempfile.TemporaryDirectory() as temporary:
                def body():
                    first, _second = self._two_roots(Path(temporary))
                    if family == "transaction":
                        owner = module.LedgerTransaction(first, operation_kind="ordered-cleanup")
                        owner.__enter__()
                        siblings = (owner._fds["root"], owner._fds["ledger"])
                        dependent = owner._fds["lock"]
                        release = lambda: owner.__exit__(None, None, None)
                    else:
                        owner = (module._NetworkExecutionReservationGuard.acquire_nonblocking(first, "a" * 64)
                                 if family == "network" else
                                 module._TaskTestExecutionLeaseGuard.acquire_nonblocking(first))
                        siblings = (owner._root_fd, owner._ledger_fd)
                        dependent = owner._identity_fd
                        release = owner.close if family == "network" else owner.release_unbound
                    target_numbers = {slot.generation_descriptor for slot in siblings}
                    errors = (KeyboardInterrupt("first sibling"), SystemExit("later sibling"))
                    attempts = []
                    real_close = os.close
                    def close(fd):
                        real_close(fd)
                        if fd in target_numbers:
                            attempts.append(fd)
                            raise errors[len(attempts) - 1]
                    with mock.patch.object(module.os, "close", close):
                        with self.assertRaises(BaseException) as caught:
                            release()
                    self.assertIs(caught.exception, errors[0])
                    self.assertEqual(set(attempts), target_numbers)
                    self.assertEqual(len(attempts), 2)
                    self.assertEqual(caught.exception.cleanup_errors, [errors[1]])
                    self.assertTrue(all(slot.phase == "uncertain" for slot in siblings))
                    self.assertEqual(dependent.phase, "owned")
                    dependent._operate(os.fstat)
                self._isolated_worker(body)

    def test_cleanup_primary_is_local_to_each_ordinary_and_transaction_call(self):
        """Break caught: a caller's handled exception silently absorbs our close failure."""
        for family in ("ordinary", "snapshot", "transaction"):
            for body_fails in (False, True):
                if family == "ordinary" and body_fails:
                    continue
                with self.subTest(family=family, body_fails=body_fails), tempfile.TemporaryDirectory() as temporary:
                    def body():
                        handled = RuntimeError("already handled by caller")
                        local = SystemExit("local read interrupted")
                        cleanup = KeyboardInterrupt("first close interrupted")
                        later = RuntimeError("later sibling close interrupted")
                        owners, attempts = [], []
                        transaction = None
                        if family == "transaction":
                            first, _second = self._two_roots(Path(temporary))
                            transaction = module.LedgerTransaction(first, operation_kind="local-cleanup-primary")
                            transaction.__enter__()
                            acquire = transaction._open_member_at
                            def capture(*args, **kwargs):
                                slot = acquire(*args, **kwargs)
                                if args[1] == "lock":
                                    owners.append(slot)
                                return slot
                            acquisition = mock.patch.object(transaction, "_open_member_at", capture)
                            operation = lambda: transaction.read_bytes_at(transaction._fds["ledger"], "lock")
                        else:
                            path = Path(temporary) / "ordinary"
                            path.write_bytes(b"owned payload")
                            acquire = module._open_ordinary_file
                            def capture(*args, **kwargs):
                                result = acquire(*args, **kwargs)
                                owners.extend(result[:2])
                                return result
                            acquisition = mock.patch.object(module, "_open_ordinary_file", capture)
                            operation = lambda: (module._ordinary_file(path) if family == "ordinary"
                                                 else module._read_ordinary_snapshot(path))
                        real_close, real_read = os.close, os.read
                        def close(fd):
                            real_close(fd)
                            if fd not in attempts and any(slot.generation_descriptor == fd for slot in owners):
                                attempts.append(fd)
                                raise cleanup if len(attempts) == 1 else later
                        def read(fd, count):
                            if body_fails and owners and fd == owners[0].generation_descriptor:
                                raise local
                            return real_read(fd, count)
                        with acquisition, mock.patch.object(module.os, "close", close), mock.patch.object(module.os, "read", read):
                            try:
                                raise handled
                            except RuntimeError:
                                with self.assertRaises(BaseException) as caught:
                                    operation()
                        expected = local if body_fails else cleanup
                        self.assertIs(caught.exception, expected)
                        self.assertFalse(hasattr(handled, "cleanup_errors"))
                        self.assertEqual(attempts, [slot.generation_descriptor for slot in owners])
                        self.assertEqual(len(owners), 1 if family == "transaction" else 2)
                        if body_fails:
                            self.assertEqual(local.cleanup_errors, [cleanup] if family == "transaction" else [cleanup, later])
                        elif family != "transaction":
                            self.assertEqual(cleanup.cleanup_errors, [later])
                        if transaction is not None:
                            transaction.__exit__(type(expected), expected, None)
                            self.assertEqual(transaction._fds["lock"].phase, "owned")
                            self.assertTrue(transaction._locked)
                    self._isolated_worker(body)

