    def test_task_guard_constructor_abort_retains_identity_until_real_exit_70(self):
        """Break caught: constructor-abort cleanup releases exclusion before fatal settlement."""
        with tempfile.TemporaryDirectory() as temporary:
            reader, writer = os.pipe()
            child = os.fork()
            if child == 0:
                os.close(reader)
                signal.alarm(30)
                first, _second = self._two_roots(Path(temporary))
                primary = RuntimeError("guard constructor return interrupted")
                failures = (KeyboardInterrupt("ledger close interrupted"), SystemExit("root close interrupted"))
                captured, events = [], []
                real_init = module._TaskTestExecutionLeaseGuard.__init__
                real_close, real_exit = os.close, os._exit
                def initialize(owner, *args, **kwargs):
                    real_init(owner, *args, **kwargs)
                    captured.append(owner)
                    raise primary
                def close(fd):
                    real_close(fd)
                    if captured and fd in (captured[0]._ledger_fd.generation_descriptor, captured[0]._root_fd.generation_descriptor):
                        events.append(fd)
                        raise failures[len(events) - 1]
                def exit_process(status):
                    try:
                        owner = captured[0]
                        self.assertEqual(status, 70)
                        self.assertEqual(len(events), 2)
                        self.assertEqual(owner._identity_fd.phase, "owned")
                        owner._identity_fd._operate(os.fstat)
                        self.assertTrue(owner._process_lock.locked())
                        self.assertEqual(primary.cleanup_errors, [failures[0]])
                        self.assertEqual(failures[0].cleanup_errors, [failures[1]])
                    except BaseException as exc:
                        os.write(writer, (type(exc).__name__ + ": " + str(exc)).encode()[:4096])
                        real_exit(81)
                    os.write(writer, b"identity-retained-until-exit")
                    real_exit(status)
                with mock.patch.object(module._TaskTestExecutionLeaseGuard, "__init__", initialize), mock.patch.object(module.os, "close", close), mock.patch.object(module.os, "_exit", exit_process):
                    module._TaskTestExecutionLeaseGuard.acquire_nonblocking(first)
                real_exit(82)
            os.close(writer)
            try:
                _pid, status = os.waitpid(child, 0)
                diagnostic = os.read(reader, 4096)
            finally:
                os.close(reader)
            self.assertTrue(os.WIFEXITED(status), (status, diagnostic))
            self.assertEqual(os.WEXITSTATUS(status), 70, diagnostic)
            self.assertEqual(diagnostic, b"identity-retained-until-exit")

