    def test_component_close_interrupt_never_recloses_replacement(self):
        """Break caught: stale traversal cleanup consumes an ABA replacement."""
        for failure in (KeyboardInterrupt, SystemExit):
            with self.subTest(failure=failure.__name__), tempfile.TemporaryDirectory() as temporary:
                source = os.open(os.devnull, os.O_RDONLY)
                original_close, original_open = os.close, os.open
                acquired, replaced = [], []
                primary = failure("component close returned after replacement")
                def capture_open(*args, **kwargs):
                    result = original_open(*args, **kwargs)
                    acquired.append(result)
                    return result
                def interrupt_close(descriptor):
                    original_close(descriptor)
                    if not replaced and descriptor in acquired:
                        os.dup2(source, descriptor)
                        replaced.append(descriptor)
                        raise primary
                try:
                    with mock.patch.object(module.os, "open", capture_open), mock.patch.object(module.os, "close", interrupt_close):
                        with self.assertRaises(BaseException) as caught:
                            module._open_directory_fd(Path(temporary))
                    self.assertIs(caught.exception, primary)
                    self.assertEqual(len(replaced), 1)
                    try:
                        surviving = os.fstat(replaced[0])
                    except OSError:
                        self.fail("traversal cleanup reclosed the replacement")
                    self.assertEqual(surviving, os.fstat(source))
                    for descriptor in acquired:
                        if descriptor not in replaced:
                            with self.assertRaises(OSError):
                                os.fstat(descriptor)
                finally:
                    # Fixture alone knows which real acquisitions/replacements
                    # occurred, including the old implementation's orphan.
                    for descriptor in set(acquired + [source]):
                        try:
                            original_close(descriptor)
                        except OSError:
                            pass

