class DurableStorageHardeningTests(_ModuleRequired):
    def test_exclusive_file_and_directory_modes_ignore_hostile_umask(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            old_umask = os.umask(0o777)
            try:
                directory = root / "directory"
                payload = root / "record.json"
                module._mkdir_exclusive(directory)
                module.write_canonical_exclusive(
                    payload, {"schemaVersion": "qinao.storage-test.v1"}
                )
            finally:
                os.umask(old_umask)
            self.assertEqual(stat.S_IMODE(directory.stat().st_mode), 0o700)
            self.assertEqual(stat.S_IMODE(payload.stat().st_mode), 0o600)

    def test_fd_rooted_write_detects_ancestor_exchange_without_redirecting(self):
        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)
            trusted = base / "trusted"
            displaced = base / "displaced"
            attacker = base / "attacker"
            _mkdir(trusted)
            _mkdir(attacker)
            original = module._open_parent_dir_fd
            swapped = False

            def exchange(path):
                nonlocal swapped
                result = original(path)
                if not swapped:
                    swapped = True
                    trusted.rename(displaced)
                    trusted.symlink_to(attacker, target_is_directory=True)
                return result

            with mock.patch.object(
                module, "_open_parent_dir_fd", side_effect=exchange
            ):
                with self.assertRaisesRegex(module.AuditError, "parent identity"):
                    module._write_bytes_exclusive(
                        trusted / "record.bin", b"evidence"
                    )
            self.assertFalse((attacker / "record.bin").exists())

    def test_post_write_hardlink_insertion_is_rejected(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            target = root / "record.bin"
            alias = root / "alias.bin"
            original = module.os.fsync
            linked = False

            def link_before_sync(fd):
                nonlocal linked
                observed = os.fstat(fd)
                if stat.S_ISREG(observed.st_mode) and target.exists() and not linked:
                    linked = True
                    os.link(target, alias)
                return original(fd)

            with mock.patch.object(module.os, "fsync", side_effect=link_before_sync):
                with self.assertRaisesRegex(module.AuditError, "hard link"):
                    module._write_bytes_exclusive(target, b"evidence")
            self.assertTrue(alias.exists())

