class DarwinPIDClaimTests(_ModuleRequired):
    def _child(self):
        ticket = module._DarwinChildLifecycleTicket(module.ctypes.c_int(424242))
        ticket.begin_spawn()
        ticket.complete_spawn(0)
        streams = []
        for _ in range(2):
            reader, writer = os.pipe()
            os.close(writer)
            stream = os.fdopen(reader, "rb", buffering=0)
            self.addCleanup(stream.close)
            streams.append(stream)
        child = module._DarwinSpawnedChild(
            424242, ["/bin/true"], None, *streams, ticket, False
        )
        ticket.adopt(child)
        return child

    def _bounded(self, child, *, spawn_error=None):
        def spawn(*_args, **kwargs):
            kwargs["child_sink"].append(child.lifecycle_ticket)
            if spawn_error is not None:
                raise spawn_error
            return child

        with mock.patch.object(module.sys, "platform", "darwin"), mock.patch.object(
            module, "_spawn_darwin_anchored_child", side_effect=spawn
        ):
            return module._run_bounded_child(
                ["/bin/true"], environment={"PATH": "/usr/bin:/bin"},
                input_bytes=b"", timeout_seconds=1.0,
                stdout_max=1024, stderr_max=1024,
            )

    def test_signal_claim_excludes_wait_until_killpg_commits(self):
        """Break caught: signal's check-only gate allows concurrent reap."""
        child = self._child()
        entered, release = threading.Event(), threading.Event()
        errors, waits = [], []

        def killpg(pid, sig):
            self.assertEqual((pid, sig), (424242, module.signal.SIGKILL))
            entered.set()
            self.assertTrue(release.wait(2.0))

        def signal_child():
            try:
                child.kill()
            except BaseException as exc:
                errors.append(exc)

        def waitpid(pid, options):
            waits.append((pid, options))
            return (pid, 0)

        with mock.patch.object(module.os, "killpg", side_effect=killpg), mock.patch.object(
            module.os, "waitpid", side_effect=waitpid
        ):
            worker = threading.Thread(target=signal_child)
            worker.start()
            try:
                self.assertTrue(entered.wait(2.0))
                for operation in (child.poll, lambda: child.wait(timeout=0)):
                    try:
                        operation()
                    except module.AuditError:
                        pass
                self.assertEqual(waits, [])
            finally:
                release.set()
                worker.join(2.0)
            self.assertFalse(worker.is_alive())
            self.assertEqual(errors, [])
            self.assertEqual(child.wait(), 0)
            self.assertEqual(len(waits), 1)

    def test_terminate_claim_spans_killpg_and_waitpid(self):
        """Break caught: cleanup signals outside the ticket's wait claim."""
        child = self._child()
        signal_entered, signal_release = threading.Event(), threading.Event()
        wait_entered, wait_release = threading.Event(), threading.Event()
        waits, errors = [], []
        first_error = RuntimeError("spawn handoff fault")

        def killpg(pid, sig):
            self.assertEqual((pid, sig), (424242, module.signal.SIGKILL))
            signal_entered.set()
            self.assertTrue(signal_release.wait(2.0))

        def waitpid(pid, options):
            waits.append((pid, options))
            if threading.current_thread() is worker:
                wait_entered.set()
                self.assertTrue(wait_release.wait(2.0))
            return (pid, 0)

        def cleanup_child():
            try:
                self._bounded(child, spawn_error=first_error)
            except BaseException as exc:
                errors.append(exc)

        with mock.patch.object(module.os, "killpg", side_effect=killpg), mock.patch.object(
            module.os, "waitpid", side_effect=waitpid
        ):
            worker = threading.Thread(target=cleanup_child)
            worker.start()
            try:
                self.assertTrue(signal_entered.wait(2.0))
                for operation in (child.poll, lambda: child.wait(timeout=0)):
                    try:
                        operation()
                    except module.AuditError:
                        pass
                self.assertEqual(waits, [])
                signal_release.set()
                self.assertTrue(wait_entered.wait(2.0))
                for operation in (child.poll, lambda: child.wait(timeout=0)):
                    try:
                        operation()
                    except module.AuditError:
                        pass
                self.assertEqual(waits, [(424242, 0)])
            finally:
                signal_release.set()
                wait_release.set()
                worker.join(2.0)
            self.assertFalse(worker.is_alive())
            self.assertEqual(errors, [first_error])
            self.assertEqual(child.returncode, 0)
            self.assertEqual(len(waits), 1)

    def test_wait_return_interrupt_never_reauthorizes_pid(self):
        """Break caught: consumed but uncommitted wait remains cancellable."""
        child = self._child()
        calls, signals = [], []
        first_error = KeyboardInterrupt("consumed wait return")

        def consumed_wait(pid, options):
            calls.append((pid, options))
            raise first_error

        with mock.patch.object(module.os, "waitpid", side_effect=consumed_wait), mock.patch.object(
            module.os, "killpg", side_effect=lambda *args: signals.append(args)
        ):
            with self.assertRaises(KeyboardInterrupt) as raised:
                self._bounded(child)
            self.assertIs(raised.exception, first_error)
            self.assertEqual(len(calls), 1)
            self.assertEqual(signals, [])
            self.assertEqual(child.lifecycle_ticket.phase, "pid-uncertain")
            for operation in (child.kill, child.poll, child.wait):
                with self.assertRaises(module.AuditError):
                    operation()
            self.assertEqual(len(calls), 1)
            self.assertEqual(signals, [])

    def test_reaped_ticket_never_probes_numeric_process_group(self):
        """Break caught: post-reap killpg(0) probes a replacement PGID."""
        child = self._child()
        probes = []
        with mock.patch.object(module.os, "waitpid", return_value=(424242, 0)), mock.patch.object(
            module.os, "killpg", side_effect=lambda *args: probes.append(args)
        ):
            self.assertEqual(child.wait(), 0)
            self.assertFalse(child.process_group_is_quiescent())
            self.assertEqual(probes, [])

    def test_stale_claim_cannot_commit_or_quarantine_new_claim_or_terminal(self):
        """Break caught: kind-only settlement consumes a later wait's result."""
        child = self._child()
        ticket = child.lifecycle_ticket
        claims, results, signals = [], [], []
        entered, release = threading.Event(), threading.Event()

        def waitpid(pid, options):
            claims.append(ticket._phase[3:])
            if len(claims) == 1:
                return (0, 0)
            entered.set()
            self.assertTrue(release.wait(2.0))
            return (pid, 7 << 8)

        def waiter():
            try:
                results.append(child.wait())
            except BaseException as exc:
                results.append(exc)

        with mock.patch.object(module.os, "waitpid", side_effect=waitpid), mock.patch.object(
            module.os, "killpg", side_effect=lambda *args: signals.append(args)
        ):
            self.assertIsNone(child.poll())
            worker = threading.Thread(target=waiter)
            worker.start()
            try:
                self.assertTrue(entered.wait(2.0))
                self.assertIsNot(claims[0][1], claims[1][1])
                for stale in (claims[0], ("terminate", claims[1][1])):
                    with self.assertRaises(module.AuditError):
                        ticket.mark_supervisor_reaped(0, stale)
                    with self.assertRaises(module.AuditError):
                        ticket._finish_pid_operation(stale, "live")
                    ticket._quarantine_pid_operation(stale)
                with self.assertRaises(module.AuditError):
                    child.kill()
                self.assertIsNone(child.returncode)
                self.assertEqual(signals, [])
            finally:
                release.set()
                worker.join(2.0)
            self.assertFalse(worker.is_alive())
            self.assertEqual(results, [7])
            for stale in claims:
                with self.assertRaises(module.AuditError):
                    ticket.mark_supervisor_reaped(0, stale)
                with self.assertRaises(module.AuditError):
                    ticket._finish_pid_operation(stale, "live")
                ticket._quarantine_pid_operation(stale)
            self.assertEqual(child.returncode, 7)
            with self.assertRaises(module.AuditError):
                child.kill()
            self.assertEqual(signals, [])

    def test_eintr_retains_claim_and_only_zero_restores_wait_authority(self):
        """Break caught: EINTR releases ownership or zero is not retryable."""
        child = self._child()
        claims = []

        def waitpid(pid, options):
            claims.append(child.lifecycle_ticket._phase[3:])
            if len(claims) == 1:
                raise InterruptedError(errno.EINTR, "wait interrupted")
            return (0, 0) if len(claims) == 2 else (pid, 0)

        with mock.patch.object(module.os, "waitpid", side_effect=waitpid):
            self.assertIsNone(child.poll())
            self.assertEqual(child.wait(), 0)
        self.assertIs(claims[0][1], claims[1][1])
        self.assertIsNot(claims[1][1], claims[2][1])

    def test_uncertain_wait_results_permanently_block_numeric_operations(self):
        """Break caught: unknown results or async exceptions restore live PID."""
        for outcome in (
            KeyboardInterrupt("consumed"), SystemExit("consumed"),
            OSError(errno.EIO, "unknown"), ChildProcessError(),
            (424243, 0), (False, 0), (424242, None), (0,),
        ):
            with self.subTest(outcome=repr(outcome)):
                child = self._child()
                waits, signals = [], []

                def waitpid(pid, options):
                    waits.append((pid, options))
                    if isinstance(outcome, BaseException):
                        raise outcome
                    return outcome

                with mock.patch.object(module.os, "waitpid", side_effect=waitpid), mock.patch.object(
                    module.os, "killpg", side_effect=lambda *args: signals.append(args)
                ):
                    with self.assertRaises(BaseException):
                        child.poll()
                    for operation in (child.poll, child.wait, child.kill):
                        with self.assertRaises(module.AuditError):
                            operation()
                    self.assertFalse(child.process_group_is_quiescent())
                self.assertEqual(len(waits), 1)
                self.assertEqual(signals, [])
                self.assertEqual(
                    child.lifecycle_ticket.phase,
                    "wait-lost" if isinstance(outcome, ChildProcessError)
                    else "pid-uncertain",
                )

    def test_signal_return_interrupt_quarantines_before_cleanup(self):
        """Break caught: killpg-to-commit interrupt allows a second signal."""
        for error in (KeyboardInterrupt("signal commit"), SystemExit("signal commit")):
            with self.subTest(error=type(error).__name__):
                child = self._child()
                ticket = child.lifecycle_ticket
                signals, waits, injected = [], [], []
                finish = ticket._finish_pid_operation

                def interrupt_signal_commit(claim, phase, returncode=None):
                    if claim[0] == "signal" and phase == "live":
                        injected.append(claim)
                        raise error
                    return finish(claim, phase, returncode)

                with mock.patch.object(ticket, "_finish_pid_operation", side_effect=interrupt_signal_commit), mock.patch.object(
                    module.os, "killpg", side_effect=lambda *args: signals.append(args)
                ), mock.patch.object(module.os, "waitpid", side_effect=lambda *args: waits.append(args)):
                    with self.assertRaises(type(error)) as raised:
                        child.kill()
                    self.assertIs(raised.exception, error)
                    with self.assertRaisesRegex(RuntimeError, "cleanup entry"):
                        self._bounded(child, spawn_error=RuntimeError("cleanup entry"))
                self.assertEqual(len(injected), 1)
                self.assertEqual(signals, [(424242, module.signal.SIGKILL)])
                self.assertEqual(waits, [])
                self.assertEqual(ticket.phase, "pid-uncertain")

    def test_claim_return_interrupt_cannot_leave_cancellable_authority(self):
        """Break caught: acquisition CALL/STORE gap escapes quarantine."""
        child = self._child()
        ticket = child.lifecycle_ticket
        claim_operation = ticket._claim_pid_operation
        error = KeyboardInterrupt("claim acquired before return")
        calls = []

        def acquire_then_interrupt(claim):
            claim_operation(claim)
            raise error

        with mock.patch.object(ticket, "_claim_pid_operation", side_effect=acquire_then_interrupt), mock.patch.object(
            module.os, "waitpid", side_effect=lambda *args: calls.append(args)
        ):
            with self.assertRaises(KeyboardInterrupt) as raised:
                child.poll()
        self.assertIs(raised.exception, error)
        self.assertEqual(ticket.phase, "pid-uncertain")
        self.assertEqual(calls, [])

    def test_quarantine_commit_interrupt_settles_and_preserves_first_error(self):
        """Break caught: second interrupt leaves an outstanding claim reusable."""
        for first_error, later_error in (
            (KeyboardInterrupt("consumed wait"), KeyboardInterrupt("tombstone commit")),
            (KeyboardInterrupt("consumed wait"), SystemExit("tombstone commit")),
            (OSError(errno.EIO, "unknown wait"), KeyboardInterrupt("tombstone commit")),
            (OSError(errno.EIO, "unknown wait"), SystemExit("tombstone commit")),
        ):
            with self.subTest(first=type(first_error).__name__, later=type(later_error).__name__):
                child = self._child()
                ticket = child.lifecycle_ticket
                state = [ticket._phase]
                injected, claims, calls = [], [], []

                def get_phase(owner):
                    return state[0] if owner is ticket else owner.__dict__["_phase"]

                def set_phase(owner, value):
                    if owner is ticket:
                        if value[0] == "pid-uncertain" and not injected:
                            injected.append(value)
                            raise later_error
                        state[0] = value
                    else:
                        owner.__dict__["_phase"] = value

                def consumed_wait(pid, options):
                    calls.append((pid, options))
                    claims.append(ticket._phase[3:])
                    raise first_error

                with mock.patch.object(type(ticket), "_phase", new=property(get_phase, set_phase), create=True), mock.patch.object(
                    module.os, "waitpid", side_effect=consumed_wait
                ):
                    with self.assertRaises(BaseException) as raised:
                        child.poll()
                    self.assertIs(
                        raised.exception,
                        first_error if isinstance(first_error, KeyboardInterrupt)
                        else later_error,
                    )
                    self.assertEqual(len(injected), 1)
                    self.assertEqual(ticket.phase, "pid-uncertain")
                    with self.assertRaises(module.AuditError):
                        ticket.mark_supervisor_reaped(0, claims[0])
                    with self.assertRaises(module.AuditError):
                        child.poll()
                self.assertEqual(len(calls), 1)


class AggregateBoundsTests(_ModuleRequired):
    @unittest.skipUnless(sys.platform == "darwin", "Darwin spawn arena")
    def test_spawn_arena_close_interrupt_never_recloses_generation(self):
        """Break caught: unwind retries a consumed spawn endpoint integer."""
        for after_close in (False, True):
            with self.subTest(after_close=after_close), tempfile.TemporaryDirectory() as temporary:
                anchor = module._ChildFdOwnerSlot(os.open(temporary, os.O_RDONLY | os.O_DIRECTORY), "runtime fixture anchor")
                sentinel = os.open(Path(temporary) / "sentinel", os.O_CREAT | os.O_RDWR, 0o600)
                lease = module._ChildFdOwnerSlot(os.open(Path(temporary) / "lease", os.O_CREAT | os.O_RDWR | os.O_CLOEXEC, 0o600), "runtime fixture lease")
                real_close = os.close
                real_complete = module._DarwinChildLifecycleTicket.complete_spawn
                spawned, target, attempts, callbacks = [], [], [], []
                interrupt = KeyboardInterrupt("arena post-close") if after_close else SystemExit("arena pre-close")

                def complete(ticket, result):
                    real_complete(ticket, result)
                    spawned.append(ticket)

                def close(descriptor):
                    if spawned and not target:
                        target.append(descriptor)
                    if target and descriptor == target[0]:
                        attempts.append(descriptor)
                        if len(attempts) == 1:
                            if after_close:
                                real_close(descriptor)
                                os.dup2(sentinel, descriptor)
                            raise interrupt
                    return real_close(descriptor)

                try:
                    with mock.patch.object(module.os, "close", side_effect=close), mock.patch.object(
                        module._DarwinChildLifecycleTicket, "complete_spawn", new=complete
                    ):
                        with self.assertRaises(type(interrupt)) as raised:
                            module._run_bounded_child(
                                ["/bin/sleep", "30"],
                                environment={"PATH": "/usr/bin:/bin", "LANG": "C", "LC_ALL": "C"},
                                input_bytes=b"", timeout_seconds=3.0,
                                stdout_max=1024, stderr_max=1024,
                                cwd_anchor_fd=anchor, child_lifetime_lease_fd=lease,
                                quiescence_callback=lambda: callbacks.append("done"),
                            )
                    self.assertIs(raised.exception, interrupt)
                    self.assertEqual(callbacks, ["done"])
                    self.assertEqual(len(attempts), 1, "consumed generation was retried")
                    self.assertTrue(target)
                    if after_close:
                        self.assertEqual(os.fstat(target[0]).st_ino, os.fstat(sentinel).st_ino)
                finally:
                    if target:
                        try:
                            real_close(target[0])
                        except OSError:
                            pass
                    lease.close()
                    real_close(sentinel)
                    anchor.close()

    @unittest.skipUnless(sys.platform == "darwin", "Darwin private arena cleanup")
    def test_spawn_private_control_ack_cleanup_retains_every_generation(self):
        """Break caught: a private/control/ACK generation lacks a tombstone."""
        # Ordered parent closes after spawn: anchor, pass duplicate, three
        # supervisor duplicates, lifetime writer, death reader, ACK ends.
        for ordinal in range(4, 13):
            for error_type in (KeyboardInterrupt, SystemExit, module.AuditError):
                with self.subTest(ordinal=ordinal, error_type=error_type.__name__), tempfile.TemporaryDirectory() as temporary:
                    anchor = module._ChildFdOwnerSlot(os.open(temporary, os.O_RDONLY | os.O_DIRECTORY), "runtime fixture anchor")
                    sentinel = os.open(Path(temporary) / "sentinel", os.O_CREAT | os.O_RDWR, 0o600)
                    lease = module._ChildFdOwnerSlot(os.open(Path(temporary) / "lease", os.O_CREAT | os.O_RDWR | os.O_CLOEXEC, 0o600), "runtime fixture lease")
                    reader, writer = os.pipe()
                    real_close, real_pipe, real_open = os.close, os.pipe, os.open
                    real_fcntl = module.fcntl.fcntl
                    real_init = module._ChildFdOwnerSlot.__init__
                    real_complete = module._DarwinChildLifecycleTicket.complete_spawn
                    spawned, generations, slots, target, attempts, callbacks = [], [], [], [], [], []
                    close_count = 0
                    interrupt = error_type("private arena close fault")

                    def own(slot, descriptor, label):
                        real_init(slot, descriptor, label)
                        slots.append(slot)

                    def pipe():
                        pair = real_pipe()
                        generations.extend(pair)
                        return pair

                    def open_fd(*args, **kwargs):
                        descriptor = real_open(*args, **kwargs)
                        generations.append(descriptor)
                        return descriptor

                    def duplicate(descriptor, command, *args):
                        result = real_fcntl(descriptor, command, *args)
                        if command == module.fcntl.F_DUPFD_CLOEXEC:
                            generations.append(result)
                        return result

                    def complete(ticket, result):
                        real_complete(ticket, result)
                        spawned.append(ticket)

                    def close(descriptor):
                        nonlocal close_count
                        if spawned:
                            close_count += 1
                            if close_count == ordinal:
                                target.append(descriptor)
                        if target and descriptor == target[0]:
                            attempts.append(descriptor)
                            if len(attempts) == 1:
                                real_close(descriptor)
                                os.dup2(sentinel, descriptor)
                                raise interrupt
                        return real_close(descriptor)

                    try:
                        with mock.patch.object(module._ChildFdOwnerSlot, "__init__", new=own), mock.patch.object(
                            module.os, "pipe", side_effect=pipe
                        ), mock.patch.object(module.os, "open", side_effect=open_fd), mock.patch.object(
                            module.fcntl, "fcntl", side_effect=duplicate
                        ), mock.patch.object(module.os, "close", side_effect=close), mock.patch.object(
                            module._DarwinChildLifecycleTicket, "complete_spawn", new=complete
                        ):
                            with self.assertRaises(error_type) as raised:
                                module._run_bounded_child(
                                    ["/bin/sleep", "30"],
                                    environment={"PATH": "/usr/bin:/bin", "LANG": "C", "LC_ALL": "C"},
                                    input_bytes=b"", timeout_seconds=3.0,
                                    stdout_max=1024, stderr_max=1024,
                                    cwd_anchor_fd=anchor, pass_fds=(reader,),
                                    child_lifetime_lease_fd=lease,
                                    quiescence_callback=lambda: callbacks.append("done"),
                                )
                        self.assertIs(raised.exception, interrupt)
                        self.assertEqual(callbacks, ["done"])
                        self.assertEqual(len(attempts), 1, "cleanup retried a consumed private fd")
                        self.assertEqual(os.fstat(target[0]).st_ino, os.fstat(sentinel).st_ino)
                        self.assertCountEqual(generations, [slot.generation_descriptor for slot in slots])
                        self.assertTrue(all(slot.phase != "owned" for slot in slots))
                        self.assertEqual(sum(slot.phase == "uncertain" for slot in slots), 1)
                    finally:
                        if target:
                            try:
                                real_close(target[0])
                            except OSError:
                                pass
                        for descriptor in (reader, writer, sentinel):
                            real_close(descriptor)
                        lease.close()
                        anchor.close()

    @unittest.skipUnless(sys.platform == "darwin", "Darwin normalization arena")
    def test_spawn_normalization_consumes_source_without_reowning_reused_fd(self):
        """Break caught: normalization returns two owners or forgets a source."""
        for input_bytes in (b"", b"input"):
            with self.subTest(input_bytes=input_bytes), tempfile.TemporaryDirectory() as temporary:
                anchor = module._ChildFdOwnerSlot(os.open(temporary, os.O_RDONLY | os.O_DIRECTORY), "runtime fixture anchor")
                sentinel = os.open(Path(temporary) / "sentinel", os.O_CREAT | os.O_RDWR, 0o600)
                target, slots, attempts = [], [], []
                real_descriptor = module._ChildFdOwnerSlot.descriptor
                real_init = module._ChildFdOwnerSlot.__init__
                real_close = os.close
                label = "child stdin reader" if input_bytes else "child null stdin"

                def own(slot, descriptor, owner_label):
                    real_init(slot, descriptor, owner_label)
                    slots.append(slot)

                def descriptor(slot):
                    observed = real_descriptor(slot)
                    if slot._label == label and not target:
                        target.append(observed)
                        # Force the normalization branch without replacing the
                        # test process's real standard input/output descriptors.
                        return 2
                    return observed

                def close(fd):
                    if target and fd == target[0]:
                        attempts.append(fd)
                        if len(attempts) == 1:
                            real_close(fd)
                            os.dup2(sentinel, fd)
                            raise KeyboardInterrupt("normalization close fault")
                    return real_close(fd)

                try:
                    with mock.patch.object(module._ChildFdOwnerSlot, "__init__", new=own), mock.patch.object(
                        module._ChildFdOwnerSlot, "descriptor", new=descriptor
                    ), mock.patch.object(module.os, "close", side_effect=close):
                        with self.assertRaisesRegex(KeyboardInterrupt, "normalization close fault"):
                            module._run_bounded_child(
                                ["/bin/cat"],
                                environment={"PATH": "/usr/bin:/bin", "LANG": "C", "LC_ALL": "C"},
                                input_bytes=input_bytes, timeout_seconds=3.0,
                                stdout_max=1024, stderr_max=1024,
                                cwd_anchor_fd=anchor,
                            )
                    self.assertEqual(len(attempts), 1)
                    self.assertEqual(os.fstat(target[0]).st_ino, os.fstat(sentinel).st_ino)
                    self.assertTrue(all(slot.phase != "owned" for slot in slots))
                    self.assertEqual(sum(slot.phase == "uncertain" for slot in slots), 1)
                    self.assertEqual(len({id(slot) for slot in slots}), len(slots))
                finally:
                    if target:
                        real_close(target[0])
                    real_close(sentinel)
                    anchor.close()

