    @unittest.skipUnless(sys.platform == "darwin", "Darwin native ACK selector")
    def test_ack_native_selector_close_interrupt_preserves_reused_fd(self):
        """Characterize native selector ownership after wrapper interruption."""
        for error_type in (KeyboardInterrupt, SystemExit):
            with self.subTest(error_type=error_type.__name__), tempfile.TemporaryDirectory() as temporary:
                anchor = module._ChildFdOwnerSlot(os.open(temporary, os.O_RDONLY | os.O_DIRECTORY), "runtime fixture anchor")
                sentinel = os.open(Path(temporary) / "sentinel", os.O_CREAT | os.O_RDWR, 0o600)
                lease = module._ChildFdOwnerSlot(os.open(Path(temporary) / "lease", os.O_CREAT | os.O_RDWR | os.O_CLOEXEC, 0o600), "runtime fixture lease")
                selectors_created, callbacks = [], []
                real_default = module.selectors.DefaultSelector
                interrupt = error_type("native selector return boundary")

                def selector_factory():
                    selector = real_default()
                    descriptor = selector.fileno()
                    close_native = selector.close
                    selectors_created.append((selector, descriptor))
                    interrupted = False

                    def close():
                        nonlocal interrupted
                        close_native()
                        if not interrupted:
                            interrupted = True
                            os.dup2(sentinel, descriptor)
                            raise interrupt

                    selector.close = close
                    return selector

                try:
                    with mock.patch.object(module.selectors, "DefaultSelector", side_effect=selector_factory):
                        with self.assertRaises(error_type) as raised:
                            module._run_bounded_child(
                                ["/bin/sleep", "30"],
                                environment={"PATH": "/usr/bin:/bin", "LANG": "C", "LC_ALL": "C"},
                                input_bytes=b"", timeout_seconds=3.0,
                                stdout_max=1024, stderr_max=1024,
                                cwd_anchor_fd=anchor, child_lifetime_lease_fd=lease,
                                quiescence_callback=lambda: callbacks.append("done"),
                            )
                    self.assertIs(raised.exception, interrupt)
                    self.assertEqual(callbacks, ["done"])
                    self.assertEqual(len(selectors_created), 1)
                    for selector, descriptor in selectors_created:
                        selector.close()
                        selector.close()
                        self.assertEqual(os.fstat(descriptor).st_ino, os.fstat(sentinel).st_ino)
                finally:
                    for _selector, descriptor in selectors_created:
                        os.close(descriptor)
                    lease.close()
                    os.close(sentinel)
                    anchor.close()

    @unittest.skipUnless(sys.platform == "darwin", "Darwin spawn borrowing")
    def test_spawn_file_actions_hold_published_slots_until_spawn_returns(self):
        """Break caught: an assembled addclose action outlives its slot borrow."""
        for control_index in (0, 1):
            for interrupt_spawn in (False, True):
                with self.subTest(control_index=control_index, interrupt_spawn=interrupt_spawn), tempfile.TemporaryDirectory() as temporary:
                    anchor = module._ChildFdOwnerSlot(os.open(temporary, os.O_RDONLY | os.O_DIRECTORY), "runtime fixture anchor")
                    lease = module._ChildFdOwnerSlot(os.open(Path(temporary) / "lease", os.O_CREAT | os.O_RDWR | os.O_CLOEXEC, 0o600), "runtime fixture lease")
                    tickets, workers, blocked, errors, close_attempts = [], [], [], [], []
                    attempted, finished, returned = threading.Event(), threading.Event(), threading.Event()
                    libc = module.ctypes.CDLL(None, use_errno=True)
                    real_spawn = libc.posix_spawn
                    real_close = os.close

                    def close(descriptor):
                        if tickets and tickets[0]._control_slots is not None:
                            if descriptor == tickets[0]._control_slots[control_index].generation_descriptor:
                                close_attempts.append(descriptor)
                        return real_close(descriptor)

                    def close_control():
                        attempted.set()
                        try:
                            tickets[0]._control_slots[control_index].close()
                            if not returned.is_set():
                                errors.append("closed before spawn returned")
                        except BaseException as exc:
                            errors.append(exc)
                        finally:
                            finished.set()

                    def spawn(*args):
                        with self.assertRaisesRegex(module.AuditError, "active operation"):
                            tickets[0]._control_slots[control_index].close()
                        worker = threading.Thread(target=close_control)
                        workers.append(worker)
                        worker.start()
                        self.assertTrue(attempted.wait(2))
                        blocked.append(not finished.wait(0.1))
                        try:
                            if interrupt_spawn:
                                raise KeyboardInterrupt("assembled actions interrupt")
                            return real_spawn(*args)
                        finally:
                            returned.set()

                    libc.posix_spawn = mock.Mock(side_effect=spawn)
                    try:
                        with mock.patch.object(module.ctypes, "CDLL", return_value=libc), mock.patch.object(
                            module.os, "close", side_effect=close
                        ):
                            try:
                                module._spawn_darwin_anchored_child(
                                    ["/bin/true"],
                                    environment={"PATH": "/usr/bin:/bin", "LANG": "C", "LC_ALL": "C"},
                                    input_bytes=b"", cwd_anchor_fd=anchor,
                                    cwd_anchor_identity=None, pass_fds=(),
                                    child_sink=tickets, child_lifetime_lease_fd=lease,
                                )
                            except (module.AuditError, KeyboardInterrupt):
                                # Closing a control immediately after the boundary
                                # may intentionally abort the supervisor handshake.
                                pass
                            for worker in workers:
                                worker.join(3)
                                self.assertFalse(worker.is_alive())
                        self.assertEqual(blocked, [True])
                        self.assertEqual(errors, [])
                        self.assertEqual(len(close_attempts), 1)
                    finally:
                        returned.set()
                        for worker in workers:
                            worker.join(3)
                        for ticket in tickets:
                            if ticket.phase == "live":
                                ticket.terminate_child()
                            if ticket.child is not None:
                                for stream in (ticket.child.stdin, ticket.child.stdout, ticket.child.stderr):
                                    if stream is not None:
                                        stream.close()
                            if ticket._control_slots is not None:
                                for slot in ticket._control_slots:
                                    slot.close()
                        lease.close()
                        anchor.close()

    @unittest.skipUnless(sys.platform == "darwin", "Darwin spawn finalization")
    def test_successful_spawn_finalizer_failure_reaps_undelivered_child_and_checks_status(self):
        """Break caught: canceled child return loses ownership or native error status."""
        for status_failure in (False, True):
            with self.subTest(status=status_failure), tempfile.TemporaryDirectory() as temporary:
                anchor = module._ChildFdOwnerSlot(os.open(temporary, os.O_RDONLY | os.O_DIRECTORY), "successful finalization anchor")
                libc = module.ctypes.CDLL(None, use_errno=True)
                real_attr, real_actions = libc.posix_spawnattr_destroy, libc.posix_spawn_file_actions_destroy
                real_complete = module._DarwinChildLifecycleTicket.complete_spawn
                primary, later = KeyboardInterrupt("attribute finalizer interrupted"), SystemExit("action finalizer interrupted")
                finalized, tickets = [], []
                def complete(ticket, result):
                    real_complete(ticket, result)
                    tickets.append(ticket)
                def attr(*args):
                    real_attr(*args)
                    finalized.append("attributes")
                    if status_failure:
                        return errno.EIO
                    raise primary
                def actions(*args):
                    real_actions(*args)
                    finalized.append("actions")
                    if status_failure:
                        return errno.EINVAL
                    raise later
                libc.posix_spawnattr_destroy = mock.Mock(side_effect=attr)
                libc.posix_spawn_file_actions_destroy = mock.Mock(side_effect=actions)
                try:
                    with mock.patch.object(module.ctypes, "CDLL", return_value=libc), \
                            mock.patch.object(module._DarwinChildLifecycleTicket, "complete_spawn", complete):
                        try:
                            raise ValueError("caller already handled")
                        except ValueError:
                            try:
                                module._run_bounded_child(
                                    ["/bin/sleep", "0"], environment={"PATH": "/usr/bin:/bin", "LANG": "C", "LC_ALL": "C"},
                                    input_bytes=b"", timeout_seconds=3, stdout_max=1024, stderr_max=1024,
                                    cwd_anchor_fd=anchor)
                            except BaseException as caught:
                                if status_failure:
                                    self.assertIsInstance(caught, module.AuditError)
                                    self.assertIn("attributes destruction", str(caught))
                                    self.assertEqual(len(caught.cleanup_errors), 1)
                                    self.assertIn("file-actions destruction", str(caught.cleanup_errors[0]))
                                else:
                                    self.assertIs(caught, primary)
                                    self.assertEqual(primary.cleanup_errors, [later])
                            else:
                                self.fail("native finalizer failure was ignored")
                    self.assertEqual(finalized, ["attributes", "actions"])
                    self.assertEqual(len(tickets), 1)
                    self.assertTrue(tickets[0].supervisor_reaped)
                    child = tickets[0].child
                    self.assertIsNotNone(child, "successful body must publish child before finalization")
                    for stream in (child.stdin, child.stdout, child.stderr):
                        if stream is not None:
                            self.assertEqual(stream._slot.phase, "closed")
                finally:
                    anchor.close()

