    @unittest.skipUnless(sys.platform == "darwin", "Darwin spawn finalization")
    def test_spawn_finalization_preserves_primary_and_all_later_cleanup_evidence(self):
        """Break caught: lifecycle/native finalization replaces or drops spawn failure."""
        for after_child in (False, True):
            for error_type in (KeyboardInterrupt, SystemExit):
                with self.subTest(after_child=after_child, error=error_type), tempfile.TemporaryDirectory() as temporary:
                    anchor = module._ChildFdOwnerSlot(os.open(temporary, os.O_RDONLY | os.O_DIRECTORY), "finalization anchor")
                    primary = error_type("spawn boundary interrupted")
                    cleanup = (OSError("termination reporting fault"), KeyboardInterrupt("attribute destruction fault"), SystemExit("action destruction fault"))
                    tickets, finalized = [], []
                    libc = module.ctypes.CDLL(None, use_errno=True)
                    real_flags = libc.posix_spawnattr_setflags
                    real_attr, real_actions = libc.posix_spawnattr_destroy, libc.posix_spawn_file_actions_destroy
                    real_complete = module._DarwinChildLifecycleTicket.complete_spawn
                    real_terminate = module._DarwinChildLifecycleTicket.terminate_child
                    def flags(*args):
                        result = real_flags(*args)
                        if not after_child:
                            raise primary
                        return result
                    def complete(ticket, result):
                        real_complete(ticket, result)
                        if after_child:
                            raise primary
                    def terminate(ticket):
                        result = real_terminate(ticket)
                        finalized.append("terminate")
                        raise cleanup[0]
                    def destroy_attr(*args):
                        real_attr(*args)
                        finalized.append("attributes")
                        raise cleanup[1]
                    def destroy_actions(*args):
                        real_actions(*args)
                        finalized.append("actions")
                        raise cleanup[2]
                    libc.posix_spawnattr_setflags = mock.Mock(side_effect=flags)
                    libc.posix_spawnattr_destroy = mock.Mock(side_effect=destroy_attr)
                    libc.posix_spawn_file_actions_destroy = mock.Mock(side_effect=destroy_actions)
                    try:
                        with mock.patch.object(module.ctypes, "CDLL", return_value=libc), \
                                mock.patch.object(module._DarwinChildLifecycleTicket, "complete_spawn", complete), \
                                mock.patch.object(module._DarwinChildLifecycleTicket, "terminate_child", terminate):
                            try:
                                module._spawn_darwin_anchored_child(
                                    ["/bin/sleep", "30"], environment={"PATH": "/usr/bin:/bin", "LANG": "C", "LC_ALL": "C"},
                                    input_bytes=b"", cwd_anchor_fd=anchor, cwd_anchor_identity=None,
                                    pass_fds=(), child_sink=tickets)
                            except BaseException as caught:
                                self.assertIs(caught, primary)
                            else:
                                self.fail("spawn primary was lost")
                        self.assertEqual(finalized, (["terminate"] if after_child else []) + ["attributes", "actions"])
                        self.assertEqual(primary.cleanup_errors, list(cleanup if after_child else cleanup[1:]))
                        self.assertEqual(len(tickets), 1)
                        if after_child:
                            self.assertTrue(tickets[0].supervisor_reaped)
                        else:
                            self.assertEqual(tickets[0].phase, "no-child")
                        anchor._operate(os.fstat)
                    finally:
                        for ticket in tickets:
                            if ticket.phase == "live":
                                real_terminate(ticket)
                        anchor.close()

    @unittest.skipUnless(sys.platform == "darwin", "Darwin fd-anchored spawn")
    def test_anchored_spawn_identity_fault_closes_every_private_duplicate(self):
        environment = {"PATH": "/usr/bin:/bin", "LANG": "C", "LC_ALL": "C"}
        for boundary in ("anchor", "pass-fd"):
            with self.subTest(boundary=boundary), tempfile.TemporaryDirectory() as temporary:
                cwd = Path(temporary)
                anchor = module._ChildFdOwnerSlot(os.open(
                    cwd,
                    os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC,
                ), "runtime fixture anchor")
                read_fd, write_fd = os.pipe()
                os.set_inheritable(read_fd, False)
                os.set_inheritable(write_fd, False)
                duplicates = []
                real_fcntl = module.fcntl.fcntl
                real_identity = module._git_child_fd_identity
                anchor_identity = anchor._operate(real_identity, "test anchor")

                def record_duplicate(descriptor, command, *arguments):
                    result = real_fcntl(descriptor, command, *arguments)
                    if command == module.fcntl.F_DUPFD_CLOEXEC:
                        duplicates.append(result)
                    return result

                def fail_selected_identity(descriptor, label):
                    if (
                        boundary == "anchor"
                        and label == "private child cwd anchor"
                    ) or (
                        boundary == "pass-fd"
                        and label
                        == "anchored child private inherited descriptor"
                    ):
                        raise module.AuditError("injected private identity fault")
                    return real_identity(descriptor, label)

                try:
                    with mock.patch.object(
                        module.fcntl, "fcntl", side_effect=record_duplicate
                    ), mock.patch.object(
                        module,
                        "_git_child_fd_identity",
                        side_effect=fail_selected_identity,
                    ):
                        with self.assertRaisesRegex(
                            module.AuditError, "injected private identity fault"
                        ):
                            module._spawn_darwin_anchored_child(
                                ["/bin/true"],
                                environment=environment,
                                input_bytes=b"",
                                cwd_anchor_fd=anchor,
                                cwd_anchor_identity=(
                                    anchor_identity
                                    if boundary == "anchor" else None
                                ),
                                pass_fds=(read_fd,)
                                if boundary == "pass-fd" else (),
                            )
                    self.assertGreaterEqual(len(duplicates), 1)
                    for descriptor in duplicates:
                        with self.assertRaises(OSError) as closed:
                            os.fstat(descriptor)
                        self.assertEqual(closed.exception.errno, errno.EBADF)
                finally:
                    os.close(read_fd)
                    os.close(write_fd)
                    anchor.close()

    def test_selector_construction_failure_reaps_child_and_aborts_feed(self):
        response = (
            b"protocol=https\nhost=github.com\n"
            b"path=ChangGeng01/ProjectSix.git\n"
            b"username=qinao\npassword=selector-secret\n\n"
        )
        backing = bytearray(response)
        broker = module.OneShotCredentialBroker(
            module.OwnedSecretBuffer.take(backing)
        )
        endpoint_slots = tuple(broker._pipe_slots)
        children = []
        claims = []
        target, attribute = ((module, "_spawn_darwin_anchored_child")
                             if sys.platform == "darwin"
                             else (module.subprocess, "Popen"))
        real_spawn = getattr(target, attribute)
        injected = OSError("selector-construction-fault")

        def capture_child(*args, **kwargs):
            child = real_spawn(*args, **kwargs)
            children.append(child)
            claims.append(broker._feed_state)
            return child

        def selector_failure():
            self.assertEqual(len(children), 1, "selector fault preceded real child")
            raise injected

        try:
            with mock.patch.object(
                target, attribute, side_effect=capture_child
            ), mock.patch.object(
                module.selectors,
                "DefaultSelector",
                side_effect=selector_failure,
            ):
                with self.assertRaisesRegex(
                    module.AuditError, "child process invocation failed"
                ) as caught:
                    module._run_bounded_child(
                        ["/bin/cat", "/dev/fd/" + str(broker.read_fd)],
                        environment={
                            "PATH": "/usr/bin:/bin", "LANG": "C", "LC_ALL": "C"
                        },
                        input_bytes=b"",
                        timeout_seconds=3.0,
                        stdout_max=len(response),
                        stderr_max=1024,
                        pass_fds=(broker.read_fd,),
                        child_feeds=(broker,),
                    )
            self.assertEqual(len(children), 1)
            self.assertIn(injected, _exception_objects(caught.exception))
            self.assertIsNotNone(children[0].poll())
            self.assertEqual(len(claims), 1)
            self.assertIs(broker._feed_state[1], claims[0][1])
            self.assertIs(broker._feed_state[2], claims[0][2])
            self.assertEqual(broker._feed_state[0], "closed")
            self.assertTrue(claims[0][2].settled)
            self.assertEqual(backing, bytearray(len(backing)))
            for slot in endpoint_slots:
                self.assertEqual(slot.phase, "closed")
                with self.assertRaises(OSError) as closed:
                    os.fstat(slot.generation_descriptor)
                self.assertEqual(closed.exception.errno, errno.EBADF)
        finally:
            broker.close()

