    def test_ticket_adopts_existing_control_slots_by_identity(self):
        """Break caught: ticket rebuilds ownership from descriptor integers."""
        reader, writer = os.pipe()
        death_reader, death_writer = os.pipe()
        lifetime = module._ChildFdOwnerSlot(reader, "test lifetime")
        death = module._ChildFdOwnerSlot(death_writer, "test death")
        ticket = module._DarwinChildLifecycleTicket(module.ctypes.c_int(0))
        try:
            try:
                ticket.attach_control_fds(lifetime, death)
            except module.AuditError as exc:
                self.fail("existing control slots must be adopted: " + str(exc))
            self.assertIs(ticket._control_slots[0], lifetime)
            self.assertIs(ticket._control_slots[1], death)
            self.assertTrue(ticket.owns_control_slot(lifetime))
            self.assertFalse(ticket.owns_control_slot(reader))
            ticket.signal_parent_gone()
            self.assertEqual(death.phase, "closed")
            os.close(writer)
            writer = None
            self.assertTrue(ticket.lifetime_pipe_reached_eof())
            self.assertEqual(lifetime.phase, "eof-proved-closed")
        finally:
            for slot in (lifetime, death):
                if slot.phase == "owned":
                    slot.close()
            if writer is not None:
                os.close(writer)
            os.close(death_reader)

