    def test_stream_operation_blocks_concurrent_close(self):
        """Break caught: a snapshot fd is used after releasing ownership lock."""
        self.assertTrue(hasattr(module, "_ChildSlotStream"), "slot-backed stream missing")
        reader, writer = os.pipe()
        slot = module._ChildFdOwnerSlot(reader, "concurrent stream")
        stream = module._ChildSlotStream(slot)
        entered, release, closing, closed = (threading.Event() for _ in range(4))
        results, errors = [], []
        os.write(writer, b"safe")

        def syscall(fd, length):
            entered.set()
            if not release.wait(2.0):
                raise AssertionError("protected syscall was not released")
            return os.read(fd, length)

        def operate():
            try:
                results.append(module._child_stream_operation(stream, syscall, 4))
            except BaseException as exc:
                errors.append(exc)

        def close():
            closing.set()
            try:
                stream.close()
            except BaseException as exc:
                errors.append(exc)
            finally:
                closed.set()

        worker = threading.Thread(target=operate)
        closer = threading.Thread(target=close)
        try:
            worker.start()
            self.assertTrue(entered.wait(2.0))
            closer.start()
            self.assertTrue(closing.wait(2.0))
            self.assertFalse(closed.wait(0.05))
            release.set()
            worker.join(2.0)
            closer.join(2.0)
            self.assertFalse(worker.is_alive())
            self.assertFalse(closer.is_alive())
            self.assertEqual(errors, [])
            self.assertEqual(results, [b"safe"])
            self.assertTrue(stream.closed)
        finally:
            release.set()
            worker.join(2.0)
            if closer.ident is not None:
                closer.join(2.0)
            if slot.phase == "owned":
                slot.close()
            os.close(writer)

