    def test_lifetime_eof_proof_survives_reader_close_fault_and_fd_reuse(self):
        """Break caught: EOF proof is stored only after reader close succeeds."""

        with tempfile.TemporaryDirectory() as temporary:
            replacement_path = Path(temporary) / "replacement"
            replacement_path.write_bytes(b"replacement")
            lifetime_read_fd, lifetime_write_fd = os.pipe()
            parent_death_read_fd, parent_death_write_fd = os.pipe()
            replacement_source_fd = os.open(
                replacement_path, os.O_RDONLY | os.O_CLOEXEC
            )
            ticket = module._DarwinChildLifecycleTicket(
                module.ctypes.c_int(0)
            )
            ticket.attach_control_fds(
                module._ChildFdOwnerSlot(lifetime_read_fd, "test lifetime"),
                module._ChildFdOwnerSlot(parent_death_write_fd, "test death"),
            )
            real_close = os.close
            real_close(lifetime_write_fd)

            def close_then_reuse_and_fail(descriptor):
                real_close(descriptor)
                os.dup2(replacement_source_fd, descriptor)
                raise OSError(errno.EIO, "post-close fault")

            try:
                with mock.patch.object(
                    module.os,
                    "close",
                    side_effect=close_then_reuse_and_fail,
                ):
                    self.assertTrue(ticket.lifetime_pipe_reached_eof())
                self.assertTrue(ticket.lifetime_pipe_reached_eof())
                self.assertEqual(os.read(lifetime_read_fd, 11), b"replacement")
            finally:
                real_close(lifetime_read_fd)
                real_close(parent_death_read_fd)
                real_close(parent_death_write_fd)
                real_close(replacement_source_fd)

