    def test_lifetime_eof_poll_holds_slot_borrow_against_concurrent_close(self):
        """Break caught: unlocked fd borrow reads a concurrently reused number."""

        with tempfile.TemporaryDirectory() as temporary:
            replacement_path = Path(temporary) / "replacement"
            replacement_path.write_bytes(b"replacement")
            lifetime_read_fd, lifetime_write_fd = os.pipe()
            parent_death_read_fd, parent_death_write_fd = os.pipe()
            replacement_source_fd = os.open(
                replacement_path, os.O_RDONLY | os.O_CLOEXEC
            )
            ticket = module._DarwinChildLifecycleTicket(
                module.ctypes.c_int(0)
            )
            ticket.attach_control_fds(
                module._ChildFdOwnerSlot(lifetime_read_fd, "test lifetime"),
                module._ChildFdOwnerSlot(parent_death_write_fd, "test death"),
            )
            lifetime_slot = ticket._control_slots[0]
            poll_entered = threading.Event()
            allow_poll = threading.Event()
            close_done = threading.Event()
            poll_results = []
            poll_errors = []
            close_errors = []
            real_set_blocking = os.set_blocking

            def pause_poll(descriptor, blocking):
                if descriptor == lifetime_read_fd:
                    poll_entered.set()
                    if not allow_poll.wait(2.0):
                        raise AssertionError("poll release timed out")
                return real_set_blocking(descriptor, blocking)

            def poll_lifetime():
                try:
                    poll_results.append(
                        ticket.lifetime_pipe_reached_eof()
                    )
                except BaseException as exc:
                    poll_errors.append(exc)

            def close_lifetime():
                try:
                    lifetime_slot.close()
                except BaseException as exc:
                    close_errors.append(exc)
                finally:
                    close_done.set()

            poll_thread = threading.Thread(target=poll_lifetime)
            close_thread = threading.Thread(target=close_lifetime)
            reused_during_poll = False
            try:
                with mock.patch.object(
                    module.os, "set_blocking", side_effect=pause_poll
                ):
                    poll_thread.start()
                    self.assertTrue(poll_entered.wait(2.0))
                    close_thread.start()
                    reused_during_poll = close_done.wait(0.2)
                    if reused_during_poll:
                        os.dup2(replacement_source_fd, lifetime_read_fd)
                    allow_poll.set()
                    poll_thread.join(2.0)
                    close_thread.join(2.0)
                self.assertFalse(poll_thread.is_alive())
                self.assertFalse(close_thread.is_alive())
                self.assertFalse(reused_during_poll)
                self.assertEqual(poll_results, [False])
                self.assertEqual(poll_errors, [])
                self.assertEqual(close_errors, [])
                self.assertEqual(
                    os.lseek(replacement_source_fd, 0, os.SEEK_CUR), 0
                )
            finally:
                allow_poll.set()
                poll_thread.join(2.0)
                close_thread.join(2.0)
                if reused_during_poll:
                    os.close(lifetime_read_fd)
                elif lifetime_slot.phase == "owned":
                    lifetime_slot.close()
                parent_death_slot = ticket._control_slots[1]
                if parent_death_slot.phase == "owned":
                    parent_death_slot.close()
                os.close(lifetime_write_fd)
                os.close(parent_death_read_fd)
                os.close(replacement_source_fd)

    def test_lifetime_eof_reentry_cannot_consume_active_slot_operation(self):
        """Break caught: EOF reentry closes an outstanding operation's fd."""
        reader, writer = os.pipe()
        death_reader, death_writer = os.pipe()
        slot = module._ChildFdOwnerSlot(reader, "active lifetime")
        death = module._ChildFdOwnerSlot(death_writer, "test death")
        ticket = module._DarwinChildLifecycleTicket(module.ctypes.c_int(0))
        ticket.attach_control_fds(slot, death)
        os.close(writer)
        real_read, real_close = os.read, os.close
        nested_io, rejected = [], []

        def read(fd, count):
            nested_io.append("read")
            return real_read(fd, count)

        def close(fd):
            nested_io.append("close")
            return real_close(fd)

        def operation(fd):
            with mock.patch.object(module.os, "read", new=read), mock.patch.object(
                module.os, "close", new=close
            ):
                try:
                    ticket.lifetime_pipe_reached_eof()
                except module.AuditError as exc:
                    rejected.append(exc)
            try:
                return real_read(fd, 1)
            except OSError as exc:
                return exc

        try:
            result = slot._operate(operation)
            with self.subTest(check="outstanding operation remains valid"):
                self.assertEqual(result, b"")
            with self.subTest(check="rejected before read or close"):
                self.assertEqual(nested_io, [])
            with self.subTest(check="active operation rejection"):
                self.assertEqual(len(rejected), 1)
                self.assertIn("active operation", str(rejected[0]))
            with self.subTest(check="no EOF proof or ownership consumed"):
                self.assertEqual(slot.phase, "owned")
                self.assertFalse(ticket._lifetime_eof_proved)
            self.assertTrue(ticket.lifetime_pipe_reached_eof())
        finally:
            if slot.phase == "owned":
                slot.close()
            death.close()
            real_close(death_reader)

    def test_lifetime_eof_operation_rejects_reentrant_close_borrow_and_poll(self):
        """Break caught: EOF's read/close permits same-thread lease invalidation."""
        for boundary in ("read", "close"):
            for reentry in ("close", "borrow", "poll"):
                with self.subTest(boundary=boundary, reentry=reentry):
                    reader, writer = os.pipe()
                    slot = module._ChildFdOwnerSlot(reader, "EOF operation")
                    os.close(writer)
                    real_read, real_close = os.read, os.close
                    entered, rejected, nested_calls = [], [], []

                    def nested_operation(fd):
                        nested_calls.append(fd)
                        return real_read(fd, 1)

                    def attempt_reentry():
                        if entered:
                            return
                        entered.append(boundary)
                        try:
                            if reentry == "close":
                                slot.close()
                            elif reentry == "borrow":
                                slot._operate(nested_operation)
                            else:
                                slot.consume_lifetime_pipe_eof()
                        except module.AuditError as exc:
                            rejected.append(exc)

                    def read(fd, count):
                        if boundary == "read":
                            attempt_reentry()
                        return real_read(fd, count)

                    def close(fd):
                        if boundary == "close":
                            attempt_reentry()
                        return real_close(fd)

                    try:
                        with mock.patch.object(module.os, "read", new=read), mock.patch.object(
                            module.os, "close", new=close
                        ):
                            try:
                                result = slot.consume_lifetime_pipe_eof()
                            except OSError as exc:
                                result = exc
                        self.assertIs(result, True)
                        self.assertEqual(entered, [boundary])
                        self.assertEqual(len(rejected), 1)
                        self.assertIn("active operation", str(rejected[0]))
                        self.assertEqual(nested_calls, [])
                        self.assertEqual(slot.phase, "eof-proved-closed")
                        # The active guard unwinds; proof remains monotonic.
                        self.assertTrue(slot.consume_lifetime_pipe_eof())
                        slot.close()
                    finally:
                        if slot.phase == "owned":
                            slot.close()

    def test_lifetime_eof_consuming_commit_interrupt_converges_uncertain(self):
        """Break caught: pre-try consuming commit remains permanently stuck."""

        injected = []

        class InterruptingState:
            def __get__(self, instance, _owner):
                if instance is None:
                    return self
                return instance.__dict__["_state"]

            def __set__(self, instance, value):
                instance.__dict__["_state"] = value
                if value[0] == "eof-proved-consuming" and not injected:
                    injected.append(value)
                    raise KeyboardInterrupt("consuming commit interrupt")

        lifetime_read_fd, lifetime_write_fd = os.pipe()
        parent_death_read_fd, parent_death_write_fd = os.pipe()
        ticket = module._DarwinChildLifecycleTicket(module.ctypes.c_int(0))
        ticket.attach_control_fds(
            module._ChildFdOwnerSlot(lifetime_read_fd, "test lifetime"),
            module._ChildFdOwnerSlot(parent_death_write_fd, "test death"),
        )
        lifetime_slot = ticket._control_slots[0]
        os.close(lifetime_write_fd)
        observed = None
        close_calls = []
        real_close = os.close

        def record_close(descriptor):
            close_calls.append(descriptor)
            return real_close(descriptor)

        try:
            with mock.patch.object(
                module._ChildFdOwnerSlot,
                "_state",
                InterruptingState(),
                create=True,
            ), mock.patch.object(
                module.os, "close", side_effect=record_close
            ):
                try:
                    ticket.lifetime_pipe_reached_eof()
                except KeyboardInterrupt as exc:
                    observed = exc
                self.assertEqual(lifetime_slot.phase, "eof-proved-uncertain")
                self.assertTrue(ticket.lifetime_pipe_reached_eof())
            self.assertEqual(len(injected), 1)
            self.assertIs(type(observed), KeyboardInterrupt)
            self.assertEqual(str(observed), "consuming commit interrupt")
            self.assertEqual(close_calls, [])
        finally:
            parent_death_slot = ticket._control_slots[1]
            if parent_death_slot.phase == "owned":
                parent_death_slot.close()
            real_close(lifetime_read_fd)
            os.close(parent_death_read_fd)

