    def test_resource_manifest_bounds_entries_bytes_depth_and_streams_hash(self):
        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)

            def allocated_resource(kind):
                case_base = base / kind
                _mkdir(case_base)
                root = _new_run_root(case_base)
                module.init_run_state(
                    root, _identity_fields(case_base), bootstrap_imports=[]
                )
                resource = module.allocate_resource(root, kind)
                return root, resource, Path(resource["absolutePath"])

            count_run, count_resource, count_root = allocated_resource("count")
            for name in ("a", "b"):
                path = count_root / name
                path.write_bytes(b"x")
                path.chmod(0o600)
            with mock.patch.object(module, "MAX_RESOURCE_ENTRIES", 1):
                with self.assertRaisesRegex(module.AuditError, "resource entry count"):
                    module.snapshot_resource(
                        count_run, count_resource["resourceId"], None
                    )

            bytes_run, bytes_resource, bytes_root = allocated_resource("bytes")
            payload_path = bytes_root / "payload"
            payload_path.write_bytes(b"12345")
            payload_path.chmod(0o600)
            with mock.patch.object(module, "MAX_RESOURCE_BYTES", 4):
                with self.assertRaisesRegex(module.AuditError, "aggregate resource bytes"):
                    module.snapshot_resource(
                        bytes_run, bytes_resource["resourceId"], None
                    )

            depth_run, depth_resource, depth_root = allocated_resource("depth")
            nested = depth_root / "a"
            _mkdir(nested)
            nested = nested / "b"
            _mkdir(nested)
            deep_file = nested / "payload"
            deep_file.write_bytes(b"x")
            deep_file.chmod(0o600)
            with mock.patch.object(module, "MAX_RESOURCE_DEPTH", 1):
                with self.assertRaisesRegex(module.AuditError, "resource depth"):
                    module.snapshot_resource(
                        depth_run, depth_resource["resourceId"], None
                    )

            stream_run, stream_resource, stream_root = allocated_resource("stream")
            stream_file = stream_root / "payload"
            stream_file.write_bytes(b"streamed")
            stream_file.chmod(0o600)
            with mock.patch.object(
                module,
                "_read_ordinary",
                side_effect=AssertionError("resource file was materialized"),
            ):
                manifest = module.snapshot_resource(
                    stream_run, stream_resource["resourceId"], None
                )
            self.assertEqual(manifest["entries"][0]["size"], len(b"streamed"))
            self.assertEqual(
                manifest["entries"][0]["sha256"],
                hashlib.sha256(b"streamed").hexdigest(),
            )

