class CIIdentityTests(_ModuleRequired):
    POLICY_PATHS = (
        ".github/pull_request_template.md",
        ".github/workflows/test.yml",
        "BehavioralAISubstrate/Cargo/.cargo/config.toml",
        "BehavioralAISubstrate/Cargo/Cargo.lock",
        "docs/superpowers/evidence/2026-08-29-qinao-cargo-vendor-manifest.v1.json",
        "docs/superpowers/evidence/2026-08-29-qinao-plan-spec-inventory.v1.json",
        "docs/superpowers/evidence/2026-08-29-qinao-pr-review-configuration.v1.json",
        "docs/superpowers/evidence/2026-08-29-qinao-workflow-contract.v1.json",
        "docs/superpowers/schemas/qinao-pr-evidence.v1.json",
        "docs/superpowers/validation/qinao-cargo-seatbelt-template.v1.sb",
        "docs/superpowers/validation/qinao-full-suite-skip-baseline.v1.json",
        "docs/superpowers/validation/qinao-plan-spec-disposition.v1.json",
        "docs/superpowers/validation/qinao-pr-validation-matrix.v1.json",
        "scripts/check_chenglu_schema_parity.py",
        "scripts/check_god_files.sh",
        "scripts/check_qinao_import_boundaries.sh",
        "scripts/check_sdk_import_boundaries.sh",
        "scripts/check_sovereign_redaction.py",
        "scripts/check_sovereign_redaction.sh",
        "scripts/check_substrate_residual_markers.sh",
        "scripts/check_substrate_residuals.sh",
        "scripts/chenglu_feature_schema.py",
        "scripts/qinao_convergence_audit.py",
        "scripts/qinao_pr_protocol.py",
        "scripts/qinao_pr_validation.py",
        "scripts/qinao_workflow_inventory.py",
    )

    @staticmethod
    def _commit(repository, tree, parents, message):
        arguments = [
            "-c", "user.name=Qinao Test",
            "-c", "user.email=qinao-test@invalid.local",
            "commit-tree", tree,
        ]
        for parent in parents:
            arguments.extend(["-p", parent])
        return module._run_git(
            repository, arguments, input_bytes=(message + "\n").encode("ascii")
        ).decode("ascii").strip()

    def _real_ci_repository(self, base):
        repository = base / "repository"
        _mkdir(repository)
        module._run_git(repository, ["init", "--quiet"])
        for path in self.POLICY_PATHS:
            target = repository / path
            target.parent.mkdir(parents=True, exist_ok=True)
            if path == "scripts/qinao_pr_protocol.py":
                payload = (
                    "import hashlib\n"
                    + "POLICY_PATHS = " + repr(self.POLICY_PATHS) + "\n"
                    + "def policy_revision(inputs):\n"
                    + "    return hashlib.sha256(repr(tuple(inputs)).encode('utf-8')).hexdigest()\n"
                ).encode("utf-8")
            else:
                payload = ("policy fixture: " + path + "\n").encode("utf-8")
            target.write_bytes(payload)
        module._run_git(repository, ["add", "--"] + list(self.POLICY_PATHS))
        tree = module._run_git(repository, ["write-tree"]).decode("ascii").strip()
        base_oid = self._commit(repository, tree, [], "base")
        head_oid = self._commit(repository, tree, [base_oid], "head")
        module._run_git(repository, ["update-ref", "refs/heads/main", head_oid])
        module._run_git(repository, ["symbolic-ref", "HEAD", "refs/heads/main"])
        return repository, base_oid, head_oid, tree

    def _observation(self):
        return {
            "head": "b" * 40,
            "tree": "c" * 40,
            "parents": ["a" * 40],
            "mergeTree": "c" * 40,
            "baseIsAncestor": True,
            "policyInputsSha256": "d" * 64,
            "V": "e" * 64,
        }

    def test_pr_ci_binding_is_same_repository_and_tree_exact(self):
        event = {
            "repository": {"full_name": "ChangGeng01/ProjectSix"},
            "pull_request": {
                "base": {"ref": "main", "sha": "a" * 40},
                "head": {"sha": "b" * 40, "repo": {"full_name": "ChangGeng01/ProjectSix"}},
                "body": "body",
            },
        }
        record = module.bind_ci_identity(event, self._observation())
        self.assertEqual(record["schemaVersion"], "qinao.ci-identity.v1")
        module._verify_self_digest(record)
        for mutation in ("fork", "tree", "ancestor", "checkout"):
            changed_event = json.loads(json.dumps(event))
            observation = dict(self._observation())
            if mutation == "fork":
                changed_event["pull_request"]["head"]["repo"]["full_name"] = "fork/repo"
            elif mutation == "tree":
                observation["mergeTree"] = "f" * 40
            elif mutation == "ancestor":
                observation["baseIsAncestor"] = False
            else:
                observation["head"] = "f" * 40
            with self.subTest(mutation=mutation), self.assertRaises(module.AuditError):
                module.bind_ci_identity(changed_event, observation)

    def test_push_binding_accepts_zero_one_or_many_ordered_parents(self):
        for parents in ([], ["1" * 40], ["1" * 40, "2" * 40, "3" * 40]):
            event = {
                "repository": {"full_name": "ChangGeng01/ProjectSix"},
                "ref": "refs/heads/main",
                "before": "0" * 40,
                "after": "a" * 40,
                "deleted": False,
            }
            observation = dict(self._observation(), head="a" * 40, parents=parents)
            record = module.bind_ci_push_identity(event, observation)
            self.assertEqual(record["parents"], parents)
        with self.assertRaises(module.AuditError):
            module.bind_ci_push_identity(dict(event, ref="refs/heads/dev"), observation)

    def test_supplemental_binding_cannot_claim_candidate(self):
        event = {
            "event_name": "workflow_dispatch",
            "repository": {"full_name": "ChangGeng01/ProjectSix"},
            "ref": "refs/heads/main",
            "sha": "b" * 40,
        }
        record = module.bind_ci_supplemental_identity(event, self._observation())
        self.assertEqual(record["claimScope"], "supplemental-only")
        self.assertNotIn("B", record)
        with self.assertRaises(module.AuditError):
            module.validate_ci_identity(record, purpose="candidate")

    def test_real_ci_binders_recompute_git_and_all_26_policy_inputs(self):
        class BinaryStdout:
            def __init__(self):
                self.buffer = io.BytesIO()

            def write(self, value):
                return len(value)

            def flush(self):
                return None

        self.assertEqual(module.CI_POLICY_PATHS, self.POLICY_PATHS)
        self.assertEqual(len(module.CI_POLICY_PATHS), 26)
        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)
            repository, B, H, tree = self._real_ci_repository(base)
            root = _new_run_root(base)
            module.init_run_state(root, _identity_fields(repository), bootstrap_imports=[])
            environment = {"HOME": str(root / "home"), "TMPDIR": str(root / "tmp"),
                           "LANG": "C", "LC_ALL": "C", "PATH": "/usr/bin:/bin"}
            events = {
                "ci-bind": {
                    "repository": {"full_name": "ChangGeng01/ProjectSix"},
                    "pull_request": {
                        "base": {"ref": "main", "sha": B},
                        "head": {
                            "sha": H,
                            "repo": {"full_name": "ChangGeng01/ProjectSix"},
                        },
                        "body": "candidate body",
                    },
                },
                "ci-push-bind": {
                    "repository": {"full_name": "ChangGeng01/ProjectSix"},
                    "ref": "refs/heads/main",
                    "before": B,
                    "after": H,
                    "deleted": False,
                },
                "ci-supplemental-bind": {
                    "event_name": "workflow_dispatch",
                    "repository": {"full_name": "ChangGeng01/ProjectSix"},
                    "ref": "refs/heads/topic",
                    "sha": H,
                },
            }
            versions = []
            for program, event in events.items():
                event_path = base / (program + ".event.json")
                output_path = base / (program + ".result.json")
                event_path.write_bytes(
                    json.dumps(event, sort_keys=True, separators=(",", ":")).encode() + b"\n"
                )
                os.chmod(event_path, 0o600)
                stream = BinaryStdout()
                with mock.patch.object(module.sys, "stdout", stream), mock.patch.object(module.os, "environ", environment):
                    self.assertEqual(module._sterile_python([
                        "--root", str(root), "--repository", str(repository), "--profile", "ledger", "--",
                        program,
                        "--repository", str(repository),
                        "--event-path", str(event_path),
                        "--output", str(output_path),
                    ]), 0)
                record = module._read_canonical_file(output_path)
                versions.append(record["V"])
                expected_rows = [{"path": path, "mode": "100644", "type": "blob",
                    "blobOid": module._run_git(repository, ["rev-parse", H + ":" + path]).decode("ascii").strip()}
                    for path in self.POLICY_PATHS]
                self.assertEqual(record["policyInputsSha256"], hashlib.sha256(
                    module.canonical_json_bytes(expected_rows)).hexdigest())
                if program == "ci-bind":
                    self.assertEqual(record["T"], tree)
                else:
                    self.assertEqual(record["tree"], tree)
                    self.assertEqual(record["parents"], [B])
            self.assertEqual(versions, [versions[0], versions[0], versions[0]])


class DiffContentObservationTests(_ModuleRequired):
    def _entries(self):
        raw = (
            b":100644 100644 " + b"1" * 40 + b" " + b"2" * 40 + b" M\x00a.txt\x00"
            + b":000000 100644 " + b"0" * 40 + b" " + b"3" * 40 + b" A\x00asset.bin\x00"
        )
        return raw, module.parse_raw_diff_z(raw, "sha1")

    def test_observation_reads_every_nonzero_side_and_classifies_content(self):
        raw, entries = self._entries()
        pointer = b"version https://git-lfs.github.com/spec/v1\noid sha256:" + b"a" * 64 + b"\nsize 9\n"
        objects = {
            "1" * 40: ("blob", b"old text\n"),
            "2" * 40: ("blob", pointer),
            "3" * 40: ("blob", b"x\x00y"),
        }
        record = module.capture_diff_content_observation(
            entries,
            raw,
            source_identity_digest="4" * 64,
            object_format="sha1",
            object_reader=lambda oid: objects[oid],
        )
        self.assertEqual([row["contentKind"] for row in record["observations"]], ["text", "lfs-pointer", "binary"])
        self.assertEqual(record["observations"][1]["lfsSize"], 9)
        module.validate_diff_content_observation(entries, raw, record, "4" * 64, "sha1")

    def test_observation_rejects_missing_extra_duplicate_swapped_and_raw_drift(self):
        raw, entries = self._entries()
        objects = {oid: ("blob", oid.encode()) for oid in ("1" * 40, "2" * 40, "3" * 40)}
        record = module.capture_diff_content_observation(entries, raw, "4" * 64, "sha1", lambda oid: objects[oid])
        variants = []
        missing = dict(record); missing["observations"] = record["observations"][:-1]; variants.append(missing)
        extra = dict(record); extra["observations"] = record["observations"] + [dict(record["observations"][0], entryId="extra")]; variants.append(extra)
        duplicate = dict(record); duplicate["observations"] = record["observations"] + [record["observations"][0]]; variants.append(duplicate)
        swapped = dict(record); swapped["observations"] = [dict(record["observations"][0], side="new")] + record["observations"][1:]; variants.append(swapped)
        for variant in variants:
            variant.pop("observationDigest", None)
            variant["observationDigest"] = module._sha256(module.canonical_json_bytes(variant))
            with self.assertRaises(module.AuditError):
                module.validate_diff_content_observation(entries, raw, variant, "4" * 64, "sha1")
        with self.assertRaises(module.AuditError):
            module.validate_diff_content_observation(entries, raw + b"x", record, "4" * 64, "sha1")

    def test_observation_rejects_malformed_lfs_and_batch_read_drift(self):
        raw, entries = self._entries()
        malformed = b"version https://git-lfs.github.com/spec/v1\noid sha256:bad\nsize 9\n"
        with self.assertRaises(module.AuditError):
            module.capture_diff_content_observation(entries, raw, "4" * 64, "sha1", lambda oid: ("blob", malformed))
        calls = {}
        def changing(oid):
            calls[oid] = calls.get(oid, 0) + 1
            return ("blob", (b"first" if calls[oid] == 1 else b"second"))
        with self.assertRaisesRegex(module.AuditError, "concurrent|drift"):
            module.capture_diff_content_observation(entries, raw, "4" * 64, "sha1", changing)

