            manifest_path = base / "raw-manifest.json"
            identity_path.write_bytes(module.canonical_json_bytes(identity))
            raw_path.write_bytes(raw)
            manifest_path.write_bytes(module.canonical_json_bytes(manifest))
            for input_path in (identity_path, raw_path, manifest_path):
                os.chmod(input_path, 0o600)
            digests = []
            for program in ("risk-check-raw", "risk-check-event"):
                case = base / program
