    def test_collector_observes_shell_file_twice_without_version_process(self):
        """Break caught: fresh local observation omits interpreter bytes or executes sh."""
        reads, commands = [], []
        real_read, real_child = module._read_ordinary_snapshot, module._run_network_observation_child
        def read(path, **kwargs):
            if str(path) == module._NETWORK_GIT_SUPERVISOR_EXECUTABLE:
                reads.append(str(path))
            return real_read(path, **kwargs)
        def child(command, **kwargs):
            commands.append(tuple(command))
            return real_child(command, **kwargs)
        with mock.patch.object(module, "_read_ordinary_snapshot", read), \
                mock.patch.object(module, "_run_network_observation_child", child):
            try:
                projection = module.capture_live_network_local_projection(AUDIT_PATH.parent.parent.resolve())
            except module.AuditError as exc:
                self.fail("complete current collector failed: " + str(exc))
        self.assertEqual(reads, ["/bin/sh", "/bin/sh"])
        self.assertFalse(any(command[0] == "/bin/sh" for command in commands))
        row = next(row for row in projection["tools"] if row["name"] == "sh")
        self.assertEqual(row["absolutePath"], "/bin/sh")
        self.assertEqual(row["fileSha256"], hashlib.sha256(Path("/bin/sh").read_bytes()).hexdigest())
        self.assertEqual(row["versionByteCount"], 0)

