    def test_lfs_failed_fallback_retains_owner_and_attempts_authorization_sibling(self):
        """Break caught: failed same-backing destruction discards ownership or skips its sibling."""
        self._lfs_cleanup_fault_fixture(body_failure=True, fallback_failure=True)

    def _lfs_cleanup_fault_fixture(self, *, body_failure, fallback_failure):
        def exercise():
            broker = module.OneShotCredentialBroker(_owned_secret(
                b"protocol=https\nhost=github.com\npath=ChangGeng01/ProjectSix.git\nusername=qinao\npassword=fixture-secret\n\n"),
                generation_digest="a" * 64)
            primary = OSError("request body failed")
            wipe = KeyboardInterrupt("helper bytewise wipe interrupted")
            fallback = MemoryError("same-backing fallback interrupted")
            owners, backings, views, attempts, requests, caught = [], [], [], [], [], []
            real_take = module.OwnedSecretBuffer.take.__func__
            real_release = module.OwnedSecretBuffer.release
            def take(cls, backing):
                owner = real_take(cls, backing)
                owners.append(owner)
                backings.append(backing)
                return owner
            def release(owner):
                if not any(owner is value for value in owners):
                    return real_release(owner)
                attempts.append(owner)
                if owner is owners[0]:
                    def interrupt(frame, event, arg):
                        if event == "line" and frame.f_code is real_release.__code__ and frame.f_locals.get("index") == 1:
                            raise wipe
                        return interrupt
                    previous = sys.gettrace()
                    try:
                        sys.settrace(interrupt)
                        return real_release(owner)
                    finally:
                        sys.settrace(previous)
                return real_release(owner)
            cleanup_source, cleanup_line = inspect.getsourcelines(module._release_owned_git_streams)
            fallback_line = cleanup_line + next(index for index, line in enumerate(cleanup_source)
                if 'backing[:] = b"\\x00" * len(backing)' in line)
            def interrupt_fallback(frame, event, arg):
                if (fallback_failure and event == "line" and frame.f_code is module._release_owned_git_streams.__code__
                        and frame.f_lineno == fallback_line and frame.f_locals.get("backing") is backings[0]):
                    raise fallback
                return interrupt_fallback
            class Adapter:
                def lfs_request(inner, **request):
                    requests.append(request)
                    views.extend(memoryview(backing) for backing in backings)
                    self.assertIs(request["headers"]["authorization"].obj, backings[1])
                    self.assertTrue(any(request["headers"]["authorization"]))
                    if body_failure:
                        raise primary
                    return {"status": 200, "headers": {"content-type": "application/vnd.git-lfs+json"}, "bodyChunks": [b'{"objects":[]}']}
            previous = sys.gettrace()
            try:
                with mock.patch.object(module.OwnedSecretBuffer, "take", classmethod(take)), mock.patch.object(
                        module.OwnedSecretBuffer, "release", release):
                    sys.settrace(interrupt_fallback)
                    try:
                        module._NetworkLfsDirectTransport(Adapter()).execute(wrapper="lfs-batch", operation="lfs-batch-upload-observe",
                            credentialBroker=broker, preflight={"lfsEndpoint": "https://github.com/ChangGeng01/ProjectSix.git/info/lfs"},
                            requestBytes=b'{"operation":"upload","objects":[]}')
                    except BaseException as exc:
                        caught.append(exc)
            finally:
                sys.settrace(previous)
                broker.close()
            self.assertEqual(len(requests), 1)
            self.assertEqual(len(caught), 1)
            self.assertIs(caught[0], primary if body_failure else wipe)
            self.assertEqual(attempts, owners)
            self.assertEqual(len(owners), 2)
            expected_errors = ([wipe] if body_failure else []) + ([fallback] if fallback_failure else [])
            self.assertEqual(getattr(caught[0], "cleanup_errors", []), expected_errors)
            for index, view in enumerate(views):
                self.assertIs(view.obj, backings[index])
                if fallback_failure and index == 0:
                    self.assertIs(owners[index]._owner, backings[index])
                    self.assertTrue(any(view))
                else:
                    self.assertFalse(any(view))
                    self.assertIsNone(owners[index]._owner)
        DirectorySlotHandoffTests._isolated_worker(self, exercise)

    @contextlib.contextmanager
    def _selected_gh_fixture(self, base, *, installation="dual", repository=None):
        """Real ordinary generations; only known candidate resolution/version I/O is isolated."""
        files = {}
        for name in ("homebrew", "system"):
            path = base / ("tools-" + name) / "gh"
            path.parent.mkdir(parents=True)
            path.write_bytes(("ordinary " + name + " gh fixture\n").encode("ascii"))
            path.chmod(0o755)
            files[name] = path
        selection = {"/opt/homebrew/bin/gh": files["homebrew"] if installation != "system" else None,
                     "/usr/bin/gh": files["system"] if installation != "homebrew" else None}
        selected = files["system" if installation == "system" else "homebrew"]
        version = {"bytes": b"gh version 2.80.0 (fixture)\n"}
        original_resolve = Path.resolve
        original_observe = module._run_network_observation_child
        def resolve(path, *args, **kwargs):
            if str(path) in selection:
                value = selection[str(path)]
                if value is None:
                    raise FileNotFoundError(str(path))
                return value
            return original_resolve(path, *args, **kwargs)
        def observe(command, **kwargs):
            if len(command) == 2 and command[1] == "--version" and command[0] in {str(path) for path in files.values()}:
                return 0, version["bytes"], b""
            return original_observe(command, **kwargs)
        raw = self._network_egress_raw_surface()
        raw["repository"] = str(repository or base)
        raw["tools"]["gh"] = {"absolutePath": str(selected), "fileBytes": selected.read_bytes(), "versionBytes": version["bytes"]}
        local = module._project_network_egress_surface(module._validate_network_egress_surface(raw))
        with mock.patch.object(Path, "resolve", resolve), mock.patch.object(module, "_run_network_observation_child", side_effect=observe), \
                mock.patch.object(module, "capture_live_network_local_projection", side_effect=lambda path: copy.deepcopy(local) if str(path) == raw["repository"] else (_ for _ in ()).throw(AssertionError("projection repository drift"))):
            yield {"selected": selected, "files": files, "selection": selection, "version": version, "local": local}

    def test_selected_gh_installations_and_drift_fail_before_credential_execution(self):
        """Break caught: selected path/file/version drift reaches token execution or fallback."""
        for installation in ("homebrew", "system", "dual"):
            with self.subTest(installation=installation), tempfile.TemporaryDirectory() as temporary:
                with self._selected_gh_fixture(Path(temporary), installation=installation) as fixture:
                    calls = []
                    runtime = _owned_process_runtime_fixture(self, process_seam=lambda **request: (calls.append(request) or (0, b"fixture-token\n", b"")),
                        gh_executable=str(fixture["selected"]))
                    selected = module._selected_gh_from_projection(fixture["local"])
                    secret = runtime.resolve_gh_token(selected_tool=selected)
                    held = secret.view()
                    secret.release()
