        for drift in ("bytes", "version", "selection", "stat", "explicit-none", "explicit-map"):
            with self.subTest(drift=drift), tempfile.TemporaryDirectory() as temporary:
                with self._selected_gh_fixture(Path(temporary)) as fixture:
                    selected = module._selected_gh_from_projection(fixture["local"])
                    calls = []
                    runtime = _owned_process_runtime_fixture(self, process_seam=lambda **request: (calls.append(request) or (0, b"fixture-token\n", b"")),
                        gh_executable=str(fixture["selected"]))
                    if drift == "bytes":
                        fixture["selected"].write_bytes(b"different selected generation\n")
                    elif drift == "version":
                        fixture["version"]["bytes"] = b"gh version 2.81.0 (fixture)\n"
                    elif drift == "selection":
                        fixture["selection"]["/opt/homebrew/bin/gh"] = fixture["files"]["system"]
                    elif drift == "stat":
                        fixture["selected"].chmod(0o700)
                    elif drift == "explicit-none":
                        selected = None
