    def _wire_header_runtime(self, responses):
        """Actual HTTPS consumer with only a finite in-memory connection seam."""
        events = []
        testcase = self
        class Connection:
            def __init__(self, result):
                self.result = result
            def request(self, method, path, *, body, headers):
                events.append((method, path, bytes(body), set(headers)))
            def getresponse(self):
                status, pairs, payload = self.result
                response = _ConcreteFixtureResponse({"status": status, "headers": {}, "bodyChunks": [payload]})
                response._headers = pairs
                return response
            def close(self):
                events.append("closed")
        pending = list(responses)
        def connection(**kwargs):
            testcase.assertEqual(kwargs["port"], 443)
            testcase.assertTrue(kwargs["ssl_context"].check_hostname)
            testcase.assertEqual(kwargs["ssl_context"].verify_mode, module.ssl.CERT_REQUIRED)
            if not pending:
                raise AssertionError("unexpected retry")
            return Connection(pending.pop(0))
        return module.ConcreteRuntimeCapability(https_connection_seam=connection,
            dns_seam=lambda host, port: ["8.8.8.8"]), events, pending

    def test_wire_headers_admit_bounded_metadata_before_credential_projection(self):
        """Break caught: normal wire Date/Server fields reject valid credentials."""
        pairs = [("Content-Type", "application/json"), ("X-OAuth-Scopes", "repo, workflow"),
            ("Date", "Tue, 08 Sep 2026 00:00:00 GMT"), ("Server", "github"), ("Content-Length", "24")]
        runtime, events, pending = self._wire_header_runtime([(200, pairs, b'{"id":1,"login":"qinao"}')])
        response = runtime.https_request(authority="gh", method="GET", host="api.github.com", path="/user", headers={})
        user, headers, _capture = module._bounded_https_json_response(response, "/user")
        self.assertEqual(user, {"id": 1, "login": "qinao"})
        self.assertEqual(headers, {"content-type": "application/json", "x-oauth-scopes": "repo, workflow"})
        self.assertEqual(len(events), 2)
        self.assertEqual(events[-1], "closed")
        self.assertEqual(pending, [])

    def test_wire_headers_reject_malformed_discarded_fields_and_finite_overflow(self):
        """Break caught: discarded or retained wire fields bypass closed byte bounds."""
        invalid = [ [("Date", "ok"), ("dAtE", "duplicate")], [("Bad Name", "x")],
            [("", "x")], [("X-\u00e9", "x")], [("x" * 257, "x")], [("x", "v" * 16385)],
            [("x", "\u0100")], [("x", 1)], [(1, "x")], [("x", "a\rb")], [("x", "a\nb")],
            [("x", "a\tb")], [("x", "a\x00b")], [("x", "a\x7fb")],
            [("x%d" % i, "v") for i in range(101)], [("x%d" % i, "v" * 16384) for i in range(4)] ]
        for index, pairs in enumerate(invalid):
            with self.subTest(case=index):
                runtime, events, pending = self._wire_header_runtime([(200, pairs, b'{}')])
                with self.assertRaises(module.AuditError):
                    runtime.https_request(authority="gh", method="GET", host="api.github.com", path="/user", headers={})
                self.assertEqual(events[-1], "closed")
                self.assertEqual(pending, [])

    def test_wire_header_exact_limits_and_latin1_metadata_remain_admitted(self):
        """Break caught: finite limits become off-by-one or reject admitted Latin-1."""
        for pairs in ([("x" * 256, "")], [("x", "v" * 16384)], [("x%d" % i, "v") for i in range(100)],
                      [("x%d" % i, "v" * 16382) for i in range(4)], [("Server", "\u00ff")]):
            with self.subTest(lengths=[(len(name), len(value)) for name, value in pairs]):
                runtime, events, pending = self._wire_header_runtime([(200, pairs, b'{}')])
                result = runtime.https_request(authority="gh", method="GET", host="api.github.com", path="/user", headers={})
                self.assertEqual(result["headers"], {name.lower(): value for name, value in pairs})
                self.assertEqual(events[-1], "closed")
                self.assertEqual(pending, [])

    def _exercise_header_consumer(self, profile, extra_pairs, *, wire, invalid_status=False):
        preflight = self._full_preflight()
        location = "https://productionresultssa1.blob.core.windows.net/actions-results/job/opaque?sig=signed-value"
        if profile == "credential":
            responses = [(200, [("content-type", "application/json"), ("x-oauth-scopes", "repo, workflow")] + extra_pairs,
                b'{"id":1,"login":"qinao"}')]
        elif profile == "github-page":
            responses = [(200, [("content-type", "application/json"), ("x-github-request-id", "fixture")] + extra_pairs, b'[{"id":1}]')]
        elif profile in ("job-redirect", "signed-log"):
            responses = [(302, [("location", location)] + (extra_pairs if profile == "job-redirect" else []), b""),
                (200, [("content-type", "text/plain")] + (extra_pairs if profile == "signed-log" else []),
                 b"tests: 3 passed, 0 failed\n")]
        else:
            responses = [(200, [("content-type", "application/vnd.git-lfs+json")] + extra_pairs, b'{"objects":[]}')]
        if invalid_status:
            index = 1 if profile == "signed-log" else 0
            _status, pairs, body = responses[index]
            responses[index] = (200 if profile == "job-redirect" else 302, pairs, body)
        if wire:
            runtime, events, pending = self._wire_header_runtime(responses)
        else:
            events, pending = [], list(responses)
            class MappingAdapter:
                def https_request(self, **request):
                    events.append(request)
                    status, pairs, body = pending.pop(0)
                    return {"status": status, "headers": dict(pairs), "bodyChunks": [body] if body else []}
                def resolve_public_addresses(self, host):
                    return ["8.8.8.8"]
                def lfs_request(self, **request):
                    return self.https_request(**request)
            runtime = MappingAdapter()
        if profile == "credential":
            response = runtime.https_request(authority="gh", method="GET", host="api.github.com", path="/user", headers={})
            _body, projected, _capture = module._bounded_https_json_response(response, "/user")
            self.assertEqual(set(projected), {"content-type", "x-oauth-scopes"})
        elif profile == "lfs":
            broker = module.OneShotCredentialBroker(_owned_secret(b"protocol=https\nhost=github.com\npath=ChangGeng01/ProjectSix.git\nusername=qinao\npassword=fixture\n\n"),
                generation_digest="a" * 64)
            projected = module._NetworkLfsDirectTransport(runtime).execute(wrapper="lfs-batch", operation="lfs-batch-upload-observe",
                credentialBroker=broker, preflight={"lfsEndpoint": "https://github.com/ChangGeng01/ProjectSix.git/info/lfs"},
                requestBytes=b'{"operation":"upload","objects":[]}')
            self.assertEqual(projected["contentType"], "application/vnd.git-lfs+json")
        else:
            operation = "rest-read" if profile == "github-page" else "job-log-read"
            argv = ["api", "/repos/ChangGeng01/ProjectSix/actions/runs" if profile == "github-page"
                else "/repos/ChangGeng01/ProjectSix/actions/jobs/123/logs"]
            manifest = module.seal_network_request_manifest(operation, argv, preflight)
            projected = module._execute_network_gh_pages(runtime, operation, argv, preflight, manifest, memoryview(bytearray(b"fixture-token")))
            self.assertEqual(projected["pages"][0]["headerNames"],
                ["content-type", "x-github-request-id"] if profile == "github-page" else ["content-type"])
            self.assertEqual(projected["redirectCount"], 0 if profile == "github-page" else 1)
            self.assertNotIn("signed-value", json.dumps(projected))
        self.assertEqual(pending, [])
        return projected

