    def _live_authority_fixture(self, *, classic=True):
        self_test = self

        class Adapter:
            git_secret = b"git-live-secret"
            gh_secret = b"gh-independent-secret"

            def __init__(self):
                self.fill_inputs = []
                self.https_calls = []
                self.mutable_secret_backings = []
                self.authorization_backings = []

            def credential_fill(self, request_bytes):
                self.fill_inputs.append(request_bytes)
                return (
                    b"protocol=https\nhost=github.com\n"
                    b"path=ChangGeng01/ProjectSix.git\n"
                    b"username=qinao\npassword=" + self.git_secret + b"\n\n"
                )

            def resolve_gh_token(self, *, selected_tool):
                module._revalidate_selected_gh_tool(selected_tool)
                self_test.assertEqual(selected_tool, module._observe_selected_gh_tool())
                return bytes(self.gh_secret)

            def https_request(
                self, *, authority, method, host, path, headers, body=b""
            ):
                self_test.assertEqual(method, "GET")
                self_test.assertEqual(host, "api.github.com")
                self_test.assertEqual(body, b"")
                self_test.assertIn("authorization", headers)
                authorization = headers["authorization"]
                backing = authorization.obj
                self.authorization_backings.append(backing)
                self.https_calls.append((
                    authority,
                    path,
                    {
                        "ownerId": id(backing),
                        "sha256": hashlib.sha256(authorization).hexdigest(),
                    },
                ))
                response_headers = {"content-type": "application/json"}
                if classic:
                    response_headers["x-oauth-scopes"] = "repo, workflow"
                if path == "/user":
                    payload = b'{"id":7,"login":"qinao"}'
                elif path == "/repos/ChangGeng01/ProjectSix":
                    payload = b'{"permissions":{"push":true}}'
                else:
                    raise AssertionError("unexpected fixed proof path")
                return {
                    "status": 200,
                    "headers": response_headers,
                    "bodyChunks": [payload[:5], payload[5:]],
                }

        return Adapter()

