    def _seal_json_member(
        self, root, frontier_id, phase, filename, record
    ):
        capture = module.allocate_capture(
            root, phase, frontier_id=frontier_id
        )
        member = Path(capture["absolutePath"]) / filename
        member.write_bytes(module.canonical_json_bytes(record))
        os.chmod(member, 0o600)
        seal = module.seal_capture(root, capture["captureId"], [filename])
        return member, module._ledger_record_path(root, seal)

    def _sealed_live_preflight(
        self,
        base,
        adapter,
        *,
        allowed_child_kinds=(),
        complete_task=True,
        frontier_kind="remote-mutation",
    ):
        repository, root, task = self._live_repository_and_ledger(
            base,
            allowed_child_kinds=allowed_child_kinds,
            network_remote=True,
            frontier_kind=frontier_kind,
        )
        context = _runtime_context(adapter)

        def credential_proof(kind):
            capture = module.allocate_capture(
                root, kind + "-credential-proof",
                frontier_id=task["frontierId"],
            )
            with mock.patch.object(module, "_emit_canonical", return_value=0):
                module._dispatch_command([
                    "git-credential-auth-read",
                    "--root", str(root),
                    "--repository", str(repository),
                    "--capture-id", capture["captureId"],
                    "--credential-kind", kind,
                ], context=context)
            seal = module.seal_capture(
                root, capture["captureId"], ["credential-proof.json"]
            )
            return module._ledger_record_path(root, seal)

        git_seal = credential_proof("git")
        gh_seal = credential_proof("gh")
        local_capture = module.allocate_capture(
            root, "network-preflight-local", frontier_id=task["frontierId"]
        )
        with mock.patch.object(module, "_emit_canonical", return_value=0):
            module._dispatch_command([
                "network-egress-preflight",
                "--root", str(root),
                "--capture-id", local_capture["captureId"],
                "--repository", str(repository),
                "--local-only",
            ], context=context)
        local_seal_record = module.seal_capture(
            root, local_capture["captureId"], ["network-egress.json"]
        )
        local_seal = module._ledger_record_path(root, local_seal_record)
        full_capture = module.allocate_capture(
            root, "network-preflight-full", frontier_id=task["frontierId"]
        )
        with mock.patch.object(module, "_emit_canonical", return_value=0):
            module._dispatch_command([
                "network-egress-preflight",
                "--root", str(root),
                "--capture-id", full_capture["captureId"],
                "--repository", str(repository),
                "--baseline-local-seal", local_seal,
                "--git-credential-seal", git_seal,
                "--gh-credential-seal", gh_seal,
                "--fetch-policy", "qinao-fixed-v1",
            ], context=context)
        full_member = (
            Path(full_capture["absolutePath"]) / "network-egress.json"
        )
        full_seal_record = module.seal_capture(
            root, full_capture["captureId"], ["network-egress.json"]
        )
        if complete_task:
            module.frontier_complete(
                root,
                task["frontierId"],
                input_digest="9" * 64,
                declared_paths=[],
                outcome="completed",
            )
        return {
            "repository": repository,
            "root": root,
            "task": task,
            "preflightPath": full_member,
            "preflightSeal": module._ledger_record_path(
                root, full_seal_record
            ),
            "preflight": module._read_canonical_file(full_member),
        }

