    def _quarantine_cli_fixture(
        self, base, *, expected_oid=None, observed_oid=None, crash=False
    ):
        expected_oid = expected_oid or "b" * 40
        repository, root, task = self._live_repository_and_ledger(
            base,
            allowed_child_kinds=(
                "quarantine-fetch", "quarantine-import"
            ),
            network_remote=True,
        )
        local = module.capture_live_network_local_projection(repository)
        helper = (
            b"protocol=https\nhost=github.com\n"
            b"path=ChangGeng01/ProjectSix.git\n"
            b"username=qinao\npassword=quarantine-ephemeral-secret\n\n"
        )
        git_identity = module._digest_projection({
            "kind": "git-credential-fill",
            "executable": "/usr/bin/git",
            "protocol": "https",
            "host": "github.com",
            "path": "ChangGeng01/ProjectSix.git",
            "usernameSha256": hashlib.sha256(b"qinao").hexdigest(),
        })
        preflight = module.build_network_egress_preflight(
            local,
            local_only=False,
            destination={
                "git": "https://github.com/ChangGeng01/ProjectSix.git"
            },
            git_credential={
                "identityDigest": git_identity,
                "generationDigest": module._credential_generation_digest(
                    root, "git", b"quarantine-ephemeral-secret"
                ),
            },
            gh_credential={
                "identityDigest": "6" * 64,
                "generationDigest": "7" * 64,
            },
            fetch_policy={"version": "v1"},
        )
        preflight_path, _preflight_seal = self._seal_json_member(
            root,
            task["frontierId"],
            "network-egress-full",
            "network-egress.json",
            preflight,
        )
        plan = module.build_quarantine_fetch_plan(
            True, ["refs/heads/main"], []
        )
        manifest = module.seal_network_request_manifest(
            "fetch-empty", plan["argv"], preflight
        )
        advertisement = module.validate_remote_advertisement(
            expected_oid.encode("ascii") + b"\trefs/heads/main\n",
            object_format="sha1",
        )
        advertisement_path, advertisement_seal = self._seal_json_member(
            root,
            task["frontierId"],
            "quarantine-advertisement",
            "advertisement.json",
            advertisement,
        )
        request = module.allocate_quarantine_request(
            root,
            manifest=manifest,
            expected_ref="refs/heads/main",
            expected_oid=expected_oid,
            destination_ref="refs/qinao/evidence/main-cli",
            candidate="a" * 40,
            seal=True,
        )
        observed = observed_oid or expected_oid
        self_test = self

        class Adapter:
            calls = 0
            git_secret = b"quarantine-ephemeral-secret"
            refs = {"refs/private/local": "9" * 40}
            objects = {"9" * 40: "private-object-digest"}
            admin = "stable-admin"

            def credential_fill(self, request_bytes):
                self_test.assertEqual(
                    request_bytes, module._FIXED_GIT_CREDENTIAL_INPUT
                )
                return helper

            def execute(self, **request_value):
                self.calls += 1
                request_value["credentialBroker"].consume(
                    "get", "https", "github.com",
                    "ChangGeng01/ProjectSix.git",
                )
                self_test.assertEqual(
                    request_value["argv"][-1],
                    "refs/heads/main:refs/qinao/fetch/observed",
                )
                resource = Path(request_value["resourcePath"])
                self.resource_path = str(resource)
                if not hasattr(self, "observe_calls"):
                    self.observe_calls = []
                (resource / "objects" / observed).write_bytes(
                    ("object-" + observed).encode("ascii")
                )
                if crash:
                    raise KeyboardInterrupt("quarantine injected crash")
                return {
                    "status": 0,
                    "stdoutChunks": [b""],
                    "stderrChunks": [
                        b"From https://github.com/ChangGeng01/ProjectSix\n"
                        b" * [new branch]      main       -> "
                        b"refs/qinao/fetch/observed\n"
                    ],
                }

            def observe_resource_ref(self, resource_path, requested_ref):
                call = (str(Path(resource_path)), requested_ref)
                self_test.assertEqual(
                    call,
                    (
                        self.resource_path,
                        "refs/qinao/fetch/observed",
                    ),
                )
                self.observe_calls.append(call)
                return observed

            def snapshot(self):
                return {
                    "refs": module.canonical_json_bytes(self.refs),
                    "objects": module.canonical_json_bytes(self.objects),
                    "admin": self.admin.encode("ascii"),
                }

            def structured_snapshot(self):
                return {
                    "refs": dict(self.refs),
                    "objects": dict(self.objects),
                    "adminDigest": hashlib.sha256(
                        self.admin.encode("ascii")
                    ).hexdigest(),
                }

            def attributable_objects(self, resource_path):
                result = {}
                for path in sorted(
                    (Path(resource_path) / "objects").iterdir()
                ):
                    if not path.is_file():
                        continue
                    result[path.name] = hashlib.sha256(
                        path.read_bytes()
                    ).hexdigest()
                return result

            def import_resource(self, resource_path, ref, oid):
                self.objects.update(self.attributable_objects(resource_path))
                self.refs[ref] = oid

            def complete_import_ref(self, ref, oid):
                self.refs[ref] = oid

        return {
            "root": root,
            "task": task,
            "preflight": preflight,
            "preflightPath": preflight_path,
            "manifest": manifest,
            "advertisementPath": advertisement_path,
            "advertisementSeal": advertisement_seal,
            "request": request,
            "adapter": Adapter(),
            "expectedOid": expected_oid,
        }

