    def test_network_git_cli_rejects_broker_misuse_and_generation_rotation(self):
        for behavior in ("zero", "double", "wrong-scope"):
            with self.subTest(behavior=behavior), tempfile.TemporaryDirectory() as temporary:
                adapter = self._live_authority_fixture()
                adapter.fill_inputs = []
                adapter.https_calls = []
                prepared = self._network_git_fixture(Path(temporary), adapter)
                adapter.fill_inputs = []

                def execute(**request):
                    broker = request["credentialBroker"]
                    if behavior == "zero":
                        pass
                    elif behavior == "double":
                        broker.consume(
                            "get", "https", "github.com",
                            "ChangGeng01/ProjectSix.git",
                        )
                        broker.consume(
                            "get", "https", "github.com",
                            "ChangGeng01/ProjectSix.git",
                        )
                    else:
                        broker.consume(
                            "get", "https", "evil.invalid",
                            "ChangGeng01/ProjectSix.git",
                        )
                    return _independent_network_git_transport_result(
                        "fetch-empty"
                    )

                adapter.execute = execute
                with self.assertRaises(module.AuditError):
                    module._dispatch_command([
                        "network-git",
                        "--preflight", str(prepared["preflightPath"]),
                        "--intent", str(prepared["intentPath"]),
                        "--operation", "fetch-empty",
                        "--quarantine-empty",
                        "--",
                    ] + prepared["argv"], context=_runtime_context(adapter))
                attempts = module.recover_run_state(prepared["root"])["networkAttempts"]
                self.assertEqual(attempts[-1]["state"], "unknown-no-replay")

        with tempfile.TemporaryDirectory() as temporary:
            adapter = self._live_authority_fixture()
            adapter.fill_inputs = []
            adapter.https_calls = []
            prepared = self._network_git_fixture(Path(temporary), adapter)
            calls = []
            adapter.git_secret = b"rotated-after-preflight"
            adapter.execute = lambda **request: calls.append(request)
            with self.assertRaisesRegex(module.AuditError, "generation"):
                module._dispatch_command([
                    "network-git",
                    "--preflight", str(prepared["preflightPath"]),
                    "--intent", str(prepared["intentPath"]),
                    "--operation", "fetch-empty",
                    "--quarantine-empty",
                    "--",
                ] + prepared["argv"], context=_runtime_context(adapter))
            self.assertEqual(calls, [])
            self.assertEqual(
                module.recover_run_state(prepared["root"])["networkAttempts"],
                [],
            )

