    def test_live_preflight_cli_creates_sealed_local_and_full_records_and_reopens(self):
        adapter = self._live_authority_fixture()
        context = _runtime_context(adapter)
        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)
            repository, root, frontier = self._live_repository_and_ledger(
                base, network_remote=True
            )

            def create_proof(kind):
                capture = module.allocate_capture(
                    root, kind + "-credential-proof",
                    frontier_id=frontier["frontierId"],
                )
                with mock.patch.object(module, "_emit_canonical", return_value=0):
                    module._dispatch_command([
                        "git-credential-auth-read",
                        "--root", str(root),
                        "--repository", str(repository),
                        "--capture-id", capture["captureId"],
                        "--credential-kind", kind,
                    ], context=context)
                seal = module.seal_capture(
                    root, capture["captureId"], ["credential-proof.json"]
                )
                return module._ledger_record_path(root, seal)

            git_seal = create_proof("git")
            gh_seal = create_proof("gh")
            git_proof = module.reopen_sealed_named_record(
                root, git_seal, "credential-proof.json"
            )
            gh_proof = module.reopen_sealed_named_record(
                root, gh_seal, "credential-proof.json"
            )
            self.assertNotEqual(
                git_proof["generationDigest"], gh_proof["generationDigest"]
            )

            local_capture = module.allocate_capture(
                root, "network-preflight-local",
                frontier_id=frontier["frontierId"],
            )
            with mock.patch.object(module, "_emit_canonical", return_value=0):
                module._dispatch_command([
                    "network-egress-preflight",
                    "--root", str(root),
                    "--capture-id", local_capture["captureId"],
                    "--repository", str(repository),
                    "--local-only",
                ], context=context)
            local_seal_record = module.seal_capture(
                root, local_capture["captureId"], ["network-egress.json"]
            )
            local_seal = module._ledger_record_path(root, local_seal_record)

            full_capture = module.allocate_capture(
                root, "network-preflight-full",
                frontier_id=frontier["frontierId"],
            )
            with mock.patch.object(module, "_emit_canonical", return_value=0):
                module._dispatch_command([
                    "network-egress-preflight",
                    "--root", str(root),
                    "--capture-id", full_capture["captureId"],
                    "--repository", str(repository),
                    "--baseline-local-seal", local_seal,
                    "--git-credential-seal", git_seal,
                    "--gh-credential-seal", gh_seal,
                    "--fetch-policy", "qinao-fixed-v1",
                ], context=context)
            full_path = Path(full_capture["absolutePath"]) / "network-egress.json"
            full = module.parse_canonical_json(full_path.read_bytes())
            local = module.reopen_sealed_named_record(
                root, local_seal, "network-egress.json"
            )
            self.assertEqual(
                local["localConfigProjectionDigest"],
                full["localConfigProjectionDigest"],
            )
            self.assertIn("stableProjectionDigest", full)
            full_seal_record = module.seal_capture(
                root, full_capture["captureId"], ["network-egress.json"]
            )
            full_seal = module._ledger_record_path(root, full_seal_record)

            class BinaryStdout:
                def __init__(self):
                    self.buffer = io.BytesIO()

            stream = BinaryStdout()
            with mock.patch.object(module.sys, "stdout", stream):
                self.assertEqual(module._dispatch_command([
                    "network-egress-preflight",
                    "--root", str(root),
                    "--verify", str(full_path),
                    "--require-seal-record", full_seal,
                    "--print-field", "recordDigest",
                ], context=context), 0)
            self.assertEqual(
                stream.buffer.getvalue(),
                (full["recordDigest"] + "\n").encode("ascii"),
            )
            with self.assertRaises(module.AuditError):
                module._dispatch_command([
                    "network-egress-preflight",
                    "--root", str(root),
                    "--verify", str(full_path),
                    "--require-seal-record", local_seal,
                    "--print-field", "stableProjectionDigest",
                ], context=context)

