    def test_network_egress_pure_validator_closes_scope_origin_and_risky_keys(self):
        validator = getattr(module, "_validate_network_egress_surface", None)
        self.assertTrue(
            callable(validator),
            "network egress must validate raw observations before projection",
        )
        baseline = self._network_egress_raw_surface()
        projected = validator(copy.deepcopy(baseline))
        persisted = module.canonical_json_bytes(projected)
        self.assertIn(b"user.email", persisted)
        self.assertNotIn(
            b"network-egress-private-canary@invalid.local", persisted
        )
        self.assertNotIn(b"/private/network-egress-home-canary", persisted)

        trusted_system_helper = copy.deepcopy(baseline)
        trusted_system_helper["configRows"].append(
            {
                "sequence": len(trusted_system_helper["configRows"]) + 1,
                "scope": "system",
                "originRole": "system-config",
                "key": "credential.helper",
                "value": b"osxkeychain",
            }
        )
        trusted_projection = validator(trusted_system_helper)
        module._project_network_egress_surface(trusted_projection)
        trusted_rows = [
            row for row in trusted_projection["config"]["rows"]
            if row["key"] == "credential.helper"
        ]
        self.assertEqual(len(trusted_rows), 1)
        self.assertEqual(
            {
                key: trusted_rows[0][key]
                for key in (
                    "sequence", "scope", "originRole", "key", "byteCount"
                )
            },
            {
                "sequence": 7,
                "scope": "system",
                "originRole": "system-config",
                "key": "credential.helper",
                "byteCount": 11,
            },
        )
        self.assertRegex(trusted_rows[0]["valueDigest"], r"\A[0-9a-f]{64}\Z")

        origin_for_scope = {
            "system": "system-config",
            "global": "global-config",
            "local": "common-config",
            "worktree": "worktree-config",
            "command": "wrapper-command",
        }
        for scope, origin in origin_for_scope.items():
            risky = copy.deepcopy(baseline)
            risky["configRows"].append(
                {
                    "sequence": len(risky["configRows"]) + 1,
                    "scope": scope,
                    "originRole": origin,
                    "key": "remote.origin.pushurl",
                    "value": b"https://example.invalid/other.git",
                }
            )
            with self.subTest(scope=scope), self.assertRaises(
                module.AuditError
            ):
                validator(risky)

        unknown_scope = copy.deepcopy(baseline)
        unknown_scope["configRows"][0]["scope"] = "unknown"
        with self.assertRaises(module.AuditError):
            validator(unknown_scope)
        crossed_origin = copy.deepcopy(baseline)
        crossed_origin["configRows"][2]["originRole"] = "global-config"
        with self.assertRaises(module.AuditError):
            validator(crossed_origin)

        command_or_redirect_keys = {
            "include.path": b"/tmp/poisoned-network-config",
            "includeIf.gitdir:/repo.path": b"/tmp/conditional-poison",
            "credential.helper": b"!malicious-helper",
            "credential.https://github.com.helper": b"!scoped-helper",
            "core.alternateRefsCommand": b"malicious-negotiation-helper",
            "core.askPass": b"malicious-askpass",
            "http.curloptResolve": b"github.com:443:127.0.0.1",
            "http.cookieFile": b"/tmp/private-cookie-jar",
            "http.saveCookies": b"true",
            "http.pinnedPubkey": b"sha256//forged",
            "http.sslBackend": b"unsafe-backend",
        }
        for key, value in command_or_redirect_keys.items():
            poisoned = copy.deepcopy(baseline)
            poisoned["configRows"].append({
                "sequence": len(poisoned["configRows"]) + 1,
                "scope": "local",
                "originRole": "common-config",
                "key": key,
                "value": value,
            })
            with self.subTest(key=key), self.assertRaises(
                module.AuditError
            ):
                validator(poisoned)

    def test_network_egress_stable_projection_ignores_objects_and_blocks_redirection_drift(self):
        validator = getattr(module, "_validate_network_egress_surface", None)
        projector = getattr(module, "_project_network_egress_surface", None)
        self.assertTrue(callable(validator))
        self.assertTrue(callable(projector))
        baseline = self._network_egress_raw_surface()
        first = projector(validator(copy.deepcopy(baseline)))
        self.assertRegex(
            first["localConfigProjectionDigest"], r"\A[0-9a-f]{64}\Z"
        )

        ordinary_growth = copy.deepcopy(baseline)
        ordinary_growth["transportRisk"]["ordinaryObjects"].append("b" * 40)
        second = projector(validator(ordinary_growth))
        self.assertEqual(
            first["localConfigProjectionDigest"],
            second["localConfigProjectionDigest"],
        )

        risk_mutations = {}
        replacements = copy.deepcopy(baseline)
        replacements["transportRisk"]["replacementRefs"] = [
            {"ref": "refs/replace/" + "a" * 40, "oid": "b" * 40}
        ]
        risk_mutations["replacementRefs"] = replacements
        alternates = copy.deepcopy(baseline)
        alternates["transportRisk"]["alternates"] = ["/tmp/foreign-objects"]
        risk_mutations["alternates"] = alternates
        promisor = copy.deepcopy(baseline)
        promisor["transportRisk"]["promisorRemotes"] = [
            {"remote": "origin", "filter": "blob:none"}
        ]
        risk_mutations["promisorRemotes"] = promisor
        for field, changed in risk_mutations.items():
            with self.subTest(field=field), self.assertRaises(
                module.AuditError
            ):
                projector(validator(changed))

    def test_network_manifest_and_fetch_reject_incomplete_self_digested_preflight(self):
        incomplete = module._self_digest_record(
            {
                "schemaVersion": "qinao.network-egress.v1",
                "stableProjectionDigest": "1" * 64,
                "gitCredentialGenerationDigest": "2" * 64,
            }
        )
        argv = [
            "fetch",
            "--no-auto-maintenance",
            "--no-write-commit-graph",
            "--no-recurse-submodules",
            "--no-write-fetch-head",
            "--no-tags",
            INDEPENDENT_NETWORK_GIT_ENDPOINT,
            INDEPENDENT_NETWORK_FETCH_REFSPEC,
        ]
        manifest = module.seal_network_request_manifest(
            "fetch-empty", argv, self._full_preflight()
        )
        manifest["preflightRecordDigest"] = incomplete["recordDigest"]
        manifest["stableProjectionDigest"] = incomplete[
            "stableProjectionDigest"
        ]
        row = manifest["rows"][0]
        row["preflightRecordDigest"] = incomplete["recordDigest"]
        row["stableProjectionDigest"] = incomplete[
            "stableProjectionDigest"
        ]
        row.pop("requestId")
        row.pop("rowDigest")
        row["requestId"] = module._digest_projection(
            {
                "schemaVersion": "qinao.network-request-id.v1",
                "row": row,
            }
        )
        manifest["rows"] = [
            module._self_digest_record(row, field="rowDigest")
        ]
        manifest["rowsDigest"] = hashlib.sha256(
            module.canonical_json_bytes(manifest["rows"])
        ).hexdigest()
        manifest.pop("recordDigest")
        manifest = module._self_digest_record(manifest)
        gates = {
            "seal": lambda: module.seal_network_request_manifest(
                "fetch-empty", argv, incomplete
            ),
            "fetch-binding": lambda: module._validate_network_git_fetch_binding(
                "fetch-empty",
                argv,
                incomplete,
                manifest,
                quarantine_empty=True,
            ),
        }
        for gate, action in gates.items():
            with self.subTest(gate=gate):
                try:
                    action()
                except module.AuditError as exc:
                    self.assertIn("preflight", str(exc).lower())
                else:
                    self.fail(
                        gate + " accepted an incomplete self-digested preflight"
                    )

    def test_preflight_local_and_full_share_local_projection_only(self):
        raw = self._network_egress_raw_surface()
