            recovered_unknown = module.recover_quarantine_outcome_no_network(
                root, pending["outcomeRecordPath"]
            )
            self.assertEqual(recovered_unknown["state"], "fetch-tainted")
            self.assertEqual(
                recovered_unknown["nextAction"], "allocate-fresh-generation"
            )
            self.assertEqual(crash_transport.calls, 1)
            recovered = module.recover_run_state(root)
            self.assertEqual(
                recovered["networkAttempts"][0]["state"],
                "unknown-no-replay",
            )

