            expected_oid = commit(remote, b"selected\n", "selected", (ancestor,) if ancestor else ())
            if ancestor:
                for oid in module._run_git(remote, ["rev-list", "--objects", "--no-object-names", ancestor]).decode("ascii").split():
                    target = shared / "objects" / oid[:2] / oid[2:]
