    def test_git_credential_projection_is_secret_free_and_scope_bound(self):
        class Adapter:
            scopes = "repo, workflow"

            def credential_fill(self, request_bytes):
                self.assert_request = request_bytes
                return (
                    b"protocol=https\nhost=github.com\n"
                    b"path=ChangGeng01/ProjectSix.git\n"
                    b"username=user\npassword=super-secret-token\n\n"
                )

            def https_request(self, **request):
                value = (
                    {"login": "user", "id": 1}
                    if request["path"] == "/user"
                    else {"permissions": {"push": True}}
                )
                return {
                    "status": 200,
                    "headers": {
                        "content-type": "application/json",
                        "x-oauth-scopes": self.scopes,
                    },
                    "bodyChunks": [module.canonical_json_bytes(value)],
                }

        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)
            root = _new_run_root(base)
            module.init_run_state(
                root, _identity_fields(base), bootstrap_imports=[]
            )
            adapter = Adapter()
            result = module.capture_live_credential_authority(
                root, base, "git", _FixtureRuntime(adapter)
            )
            self.assertEqual(
                adapter.assert_request, module._FIXED_GIT_CREDENTIAL_INPUT
            )
            self.assertNotIn("super-secret-token", json.dumps(result))
            adapter.scopes = "repo"
            with self.assertRaises(module.AuditError):
                module.capture_live_credential_authority(
                    root, base, "git", _FixtureRuntime(adapter)
                )

