    def test_completed_terminal_fault_boundaries_reopen_one_byte_identical_terminal(self):
        argv = [
            "fetch", "--no-auto-maintenance", "--no-write-commit-graph",
            "--no-recurse-submodules", "--no-write-fetch-head", "--no-tags",
            INDEPENDENT_NETWORK_GIT_ENDPOINT,
            INDEPENDENT_NETWORK_FETCH_REFSPEC,
        ]
        preflight = self._full_preflight()
        manifest = module.seal_network_request_manifest(
            "fetch-empty", argv, preflight
        )

        class Transport:
            def __init__(self):
                self.calls = 0

            def execute(self, **request):
                self.calls += 1
                request["credentialBroker"].consume(
                    "get", "https", "github.com",
                    "ChangGeng01/ProjectSix.git",
                )
                return _independent_network_git_transport_result(
                    "fetch-empty"
                )

        cases = (
            "record-fsync",
            "records-fsync",
            "unlock",
            "close",
            "before-terminal-return",
        )
        for boundary in cases:
            with self.subTest(boundary=boundary), tempfile.TemporaryDirectory() as temporary:
                base = Path(temporary)
                fixture = self._fetch_execution_fixture(base, marker="e")
                root = fixture["root"]
                argv = fixture["argv"]
                preflight = fixture["preflight"]
                manifest = fixture["manifest"]
                initial_count = len(module.recover_run_state(root)["records"])
                terminal_path = (
                    root / "ledger" / "records"
                    / ("%016d.json" % (initial_count + 5))
                )
                fired = []

                def fault(observed_boundary, operation_kind, subject):
                    if (
                        observed_boundary == boundary
                        and operation_kind == "network-terminal"
                        and (
                            observed_boundary
                            not in {"record-fsync", "records-fsync"}
                            or subject == terminal_path.name
                        )
                    ):
                        fired.append(observed_boundary)
                        raise OSError("lost terminal durable return")

                transport = Transport()
                terminal = module.execute_network_wrapper(
                    root,
                    fixture["frontierId"],
                    wrapper="network-git",
                    operation="fetch-empty",
                    argv=argv,
                    preflight=preflight,
                    manifest=manifest,
                    transport=transport,
                    quarantine_empty=True,
                    credential_broker=self._git_broker(root),
                    git_execution_capsule=fixture["capsule"],
                    git_execution_capsule_snapshot=fixture["snapshot"],
                    _faults=module.DurabilityFaults(fault),
                )
                self.assertEqual(fired, [boundary])
                recovered = module.recover_run_state(root)
                terminals = [
                    row for row in recovered["records"]
                    if row["operationKind"] == "network-terminal"
                ]
                self.assertEqual(len(terminals), 1)
                self.assertEqual(
                    module.canonical_json_bytes(terminal),
                    module.canonical_json_bytes(terminals[0]),
                )
                reopened = module.execute_network_wrapper(
                    root,
                    fixture["frontierId"],
                    wrapper="network-git",
                    operation="fetch-empty",
                    argv=argv,
                    preflight=preflight,
                    manifest=manifest,
                    transport=transport,
                    quarantine_empty=True,
                    credential_broker=None,
                    git_execution_capsule=fixture["capsule"],
                    git_execution_capsule_snapshot=fixture["snapshot"],
                )
                self.assertEqual(reopened, terminal)
                self.assertEqual(transport.calls, 1)

