    def test_network_wrapper_crash_after_attempt_is_recoverable_but_not_replayable(self):
        argv = [
            "fetch", "--no-auto-maintenance", "--no-write-commit-graph",
            "--no-recurse-submodules", "--no-write-fetch-head", "--no-tags",
            INDEPENDENT_NETWORK_GIT_ENDPOINT,
            INDEPENDENT_NETWORK_FETCH_REFSPEC,
        ]
        preflight = self._full_preflight()
        manifest = module.seal_network_request_manifest("fetch-empty", argv, preflight)

        class CrashTransport:
            calls = 0

            def execute(self, **request):
                self.calls += 1
                request["credentialBroker"].consume(
                    "get", "https", "github.com",
                    "ChangGeng01/ProjectSix.git",
                )
                raise KeyboardInterrupt("simulated process death")

        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)
            fixture = self._fetch_execution_fixture(base, marker="2")
            root = fixture["root"]
            argv = fixture["argv"]
            preflight = fixture["preflight"]
            manifest = fixture["manifest"]
            transport = CrashTransport()
            with self.assertRaises(KeyboardInterrupt):
                module.execute_network_wrapper(
                    root,
                    fixture["frontierId"],
                    wrapper="network-git",
                    operation="fetch-empty",
                    argv=argv,
                    preflight=preflight,
                    manifest=manifest,
                    transport=transport,
                    quarantine_empty=True,
                    credential_broker=self._git_broker(root),
                    git_execution_capsule=fixture["capsule"],
                    git_execution_capsule_snapshot=fixture["snapshot"],
                )
            recovered = module.recover_run_state(root)
            self.assertEqual(recovered["classification"], "complete")
            self.assertEqual(recovered["networkAttempts"][0]["state"], "unknown-no-replay")
            terminal = recovered["networkAttempts"][0]["terminal"]
            reopened = module.execute_network_wrapper(
                root,
                fixture["frontierId"],
                wrapper="network-git",
                operation="fetch-empty",
                argv=argv,
                preflight=preflight,
                manifest=manifest,
                transport=transport,
                quarantine_empty=True,
                credential_broker=None,
                git_execution_capsule=fixture["capsule"],
                git_execution_capsule_snapshot=fixture["snapshot"],
            )
            self.assertEqual(reopened, terminal)
            self.assertEqual(transport.calls, 1)

    def test_one_shot_credential_broker_is_scope_bound_and_secret_free(self):
        broker = module.OneShotCredentialBroker(
            _owned_secret(
                b"protocol=https\nhost=github.com\npath=ChangGeng01/ProjectSix.git\nusername=user\npassword=secret\n\n"
            )
        )
        response = broker.consume("get", "https", "github.com", "ChangGeng01/ProjectSix.git")
        self.assertTrue(_buffer_contains(response.view(), b"password=secret"))
        self.assertNotIn("secret", json.dumps(broker.projection(), sort_keys=True))
        with self.assertRaises(module.AuditError):
            broker.consume("get", "https", "github.com", "ChangGeng01/ProjectSix.git")
        with self.assertRaises(module.AuditError):
            module.OneShotCredentialBroker(response).consume(
                "get", "https", "evil.example", "ChangGeng01/ProjectSix.git"
            )

    def test_remote_observation_capture_requires_exact_request_seal_and_attempt_parent(self):
        class BinaryStdout:
            def __init__(self):
                self.buffer = io.BytesIO()

            def write(self, value):
                return len(value)

            def flush(self):
                return None

        preflight = self._full_preflight()
        argv = ["api", "--method", "PUT", "/repos/ChangGeng01/ProjectSix/pulls/1/merge"]
        manifest = module.seal_network_request_manifest("merge-put", argv, preflight)

        class Transport:
            def execute(self, **_request):
                return {
                    "status": 200,
                    "headers": {"content-type": "application/json", "x-github-request-id": "r1"},
                    "bodyChunks": [b"{}\n"],
                }

        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)
            root = _new_run_root(base)
            module.init_run_state(root, _identity_fields(base), bootstrap_imports=[])
            request_capture = module.allocate_capture(root, "merge-put-request")
            request_file = Path(request_capture["absolutePath"]) / "request.json"
            request_file.write_bytes(module.canonical_json_bytes(manifest))
            os.chmod(request_file, 0o600)
            request_seal = module.seal_capture(root, request_capture["captureId"], ["request.json"])
            request_seal_path = root / "ledger" / "records" / ("%016d.json" % request_seal["sequence"])
            frontier = module.frontier_start(
                root,
                frontier_kind="remote-mutation",
                input_digest="8" * 64,
                declared_paths=[],
                expected_tests=[],
            )
            frontier_path = root / "ledger" / "records" / (
                "%016d.json" % frontier["sequence"]
            )
            module.execute_network_wrapper(
                root,
                frontier["frontierId"],
                wrapper="network-gh",
                operation="merge-put",
                argv=argv,
                preflight=preflight,
                manifest=manifest,
                transport=Transport(),
                request_seal_record_path=str(request_seal_path),
            )
            attempt = [
                row for row in module.recover_run_state(root)["records"]
                if row["operationKind"] == "network-attempt"
            ][0]
            attempt_path = root / "ledger" / "records" / ("%016d.json" % attempt["sequence"])
            selected_attempt = module.select_network_attempt_for_intent(
                root, str(frontier_path)
            )
            self.assertEqual(selected_attempt["attemptRecordPath"], str(attempt_path))
            self.assertEqual(
                selected_attempt["requestSealRecordPath"], str(request_seal_path)
            )
            stream = BinaryStdout()
            with mock.patch.object(module.sys, "stdout", stream):
                self.assertEqual(module._dispatch_command([
                    "recover-captures",
                    "--root", str(root),
                    "--intent", str(frontier_path),
                    "--print-field", "attemptRecordPath",
                ]), 0)
            self.assertEqual(stream.buffer.getvalue(), (str(attempt_path) + "\n").encode())
            observation = module.allocate_capture(
                root,
                "postmerge-merge-recovery-entry",
                frontier_id=frontier["frontierId"],
                parent_capture_records=[str(request_seal_path)],
                parent_attempt_record=str(attempt_path),
                read_only_recovery=True,
                blocked_frontier=frontier["frontierId"],
            )
            self.assertEqual(observation["parentAttempt"]["recordDigest"], attempt["recordDigest"])
            selected_recovery = module.select_recovery_capture(
                root,
                frontier_id=frontier["frontierId"],
                phase="postmerge-merge-recovery-entry",
                intent_record=str(frontier_path),
                require_parent_capture_records=[str(request_seal_path)],
                require_parent_attempt_records=[str(attempt_path)],
            )
            self.assertEqual(selected_recovery["state"], "replace-incomplete")
            self.assertEqual(selected_recovery["captureId"], observation["captureId"])
            stream = BinaryStdout()
            with mock.patch.object(module.sys, "stdout", stream):
                self.assertEqual(module._dispatch_command([
                    "recover-captures",
                    "--root", str(root),
                    "--select-recovery-capture",
                    "--frontier-id", frontier["frontierId"],
                    "--intent", str(frontier_path),
                    "--phase", "postmerge-merge-recovery-entry",
                    "--require-parent-capture", str(request_seal_path),
                    "--require-parent-attempt", str(attempt_path),
                    "--print-field", "captureId",
                ]), 0)
            self.assertEqual(
                stream.buffer.getvalue(), (observation["captureId"] + "\n").encode()
            )
            module.frontier_complete(
                root,
                frontier["frontierId"],
                input_digest="8" * 64,
                declared_paths=[],
                outcome="completed",
            )
            cross = module.frontier_start(
                root,
                frontier_kind="remote-mutation",
                input_digest="a" * 64,
                declared_paths=[],
                expected_tests=[],
            )
            cross_path = root / "ledger" / "records" / (
                "%016d.json" % cross["sequence"]
            )
            with self.assertRaises(module.AuditError):
                module.select_network_attempt_for_intent(root, str(cross_path))
            with self.assertRaises(module.AuditError):
                module.allocate_capture(
                    root,
                    "postmerge-merge-recovery-entry",
                    frontier_id=frontier["frontierId"],
                    parent_capture_records=[],
                    parent_attempt_record=str(attempt_path),
                    read_only_recovery=True,
                    blocked_frontier=frontier["frontierId"],
                )

