    def test_network_gh_job_log_uses_one_signed_public_hop_without_auth(self):
        preflight = self._full_preflight()
        argv = [
            "api",
            "/repos/ChangGeng01/ProjectSix/actions/jobs/123/logs",
        ]
        manifest = module.seal_network_request_manifest(
            "job-log-read", argv, preflight
        )
        location = (
            "https://productionresultssa1.blob.core.windows.net/"
            "actions-results/job/opaque?sig=signed-value"
        )

        class Adapter:
            def __init__(self):
                self.requests = []

            def resolve_public_addresses(self, host):
                self.host = host
                return ["8.8.8.8"]

            def https_request(self, **request):
                self.requests.append(request)
                if len(self.requests) == 1:
                    return {
                        "status": 302,
                        "headers": {"location": location},
                        "bodyChunks": [],
                    }
                return {
                    "status": 200,
                    "headers": {"content-type": "text/plain"},
                    "bodyChunks": [b"tests: 3 passed, 0 failed\n"],
                }

        adapter = Adapter()
        observed = module._execute_network_gh_pages(
            adapter,
            "job-log-read",
            argv,
            preflight,
            manifest,
            memoryview(bytearray(b"token")),
        )
        self.assertEqual(len(adapter.requests), 2)
        self.assertIn("authorization", adapter.requests[0]["headers"])
        self.assertNotIn("authorization", adapter.requests[1]["headers"])
        self.assertEqual(observed["redirectCount"], 1)
        self.assertEqual(observed["pageCount"], 1)
        self.assertNotIn("signed-value", json.dumps(observed))

    def test_no_seam_job_log_binds_validated_address_to_signed_tls_host(self):
        preflight = self._full_preflight()
        argv = [
            "api",
            "/repos/ChangGeng01/ProjectSix/actions/jobs/123/logs",
        ]
        manifest = module.seal_network_request_manifest(
            "job-log-read", argv, preflight
        )
        signed_host = "productionresultssa1.blob.core.windows.net"
        signed_location = (
            "https://" + signed_host
            + "/actions-results/job/opaque?sig=signed-value"
        )

        class Socket:
            def __init__(self, response, peer):
                self.response = response
                self.peer = peer
                self.sent = bytearray()

            def setsockopt(self, *unused):
                pass

            def sendall(self, payload):
                self.sent.extend(payload)

            def makefile(self, *unused):
                return io.BytesIO(self.response)

            def getpeername(self):
                return (self.peer, 443)

            def close(self):
                pass

        redirect = (
            "HTTP/1.1 302 Found\r\nLocation: " + signed_location
            + "\r\n\r\n"
        ).encode("ascii")
        log = b"QINAO_TEST_SUMMARY passed=3 failed=0 skipped=0 status=passed\n"
        completed = (
            b"HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\n\r\n" + log
        )
        all_sockets = [
            Socket(redirect, "140.82.112.5"),
            Socket(completed, "8.8.8.8"),
        ]
        sockets = list(all_sockets)
        connects = []
        tls_hosts = []

        def create_connection(target, timeout=None, source_address=None):
            connects.append(target)
            return sockets.pop(0)

        class Context:
            check_hostname = True
            verify_mode = 2
            post_handshake_auth = False

            def wrap_socket(self, raw_socket, *, server_hostname):
                tls_hosts.append(server_hostname)
                return raw_socket

        runtime = module.ConcreteRuntimeCapability()
        dns_rows = [
            (
                module.socket.AF_INET,
                module.socket.SOCK_STREAM,
                module.socket.IPPROTO_TCP,
                "",
                ("8.8.8.8", 443),
            )
        ]
        with mock.patch.object(
            module.socket, "create_connection", side_effect=create_connection
        ), mock.patch.object(
            module.socket, "getaddrinfo", return_value=dns_rows
        ), mock.patch.object(
            module.ssl, "create_default_context", return_value=Context()
        ):
            observed = module._execute_network_gh_pages(
                runtime,
                "job-log-read",
                argv,
                preflight,
                manifest,
                memoryview(bytearray(b"token")),
            )
        self.assertEqual(connects[1], ("8.8.8.8", 443))
        self.assertEqual(tls_hosts[1], signed_host)
        self.assertNotIn(b"authorization:", bytes(all_sockets[1].sent).lower())
        self.assertEqual(observed["redirectCount"], 1)
        self.assertNotIn("signed-value", json.dumps(observed))

        drift_socket = Socket(completed, "1.1.1.1")
        with mock.patch.object(
            module.socket,
            "create_connection",
            return_value=drift_socket,
        ), mock.patch.object(
            module.ssl, "create_default_context", return_value=Context()
        ), self.assertRaisesRegex(module.AuditError, "peer|address.*drift"):
            runtime.https_request(
                authority="job-log",
                method="GET",
                host=signed_host,
                path="/actions-results/job/opaque?sig=signed-value",
                headers={"accept": "text/plain"},
                resolvedAddresses=["8.8.8.8"],
            )

