    def test_safe_capture_stops_streaming_at_first_decisive_secret(self):
        class Chunks:
            reads = 0

            def __iter__(self):
                self.reads += 1
                yield b'{"token":"' + b"gh" + b'p_ABCDEFGHIJKLMNOPQRSTUVWXYZ"}'
                self.reads += 1
                raise AssertionError("safe capture read beyond decisive secret")

        chunks = Chunks()
        with self.assertRaises(module.SecretScanError):
            module.safe_capture(
                chunks,
                profile="github-rest",
                endpoint="/rate_limit",
            )
        self.assertEqual(chunks.reads, 1)

    def test_safe_capture_large_job_log_has_bounded_live_memory(self):
        import tracemalloc

        chunk = b"ordinary untrusted log line\n" * 2048
        count = 160
        tracemalloc.start()
        try:
            capture = module.safe_capture(
                (chunk for _ in range(count)),
                profile="job-log",
                endpoint=(
                    "/repos/ChangGeng01/ProjectSix/"
                    "actions/jobs/123/logs"
                ),
            )
            _current, peak = tracemalloc.get_traced_memory()
        finally:
            tracemalloc.stop()
        self.assertEqual(capture["rawByteCount"], len(chunk) * count)
        self.assertLess(peak, 6 * 1024 * 1024)

