    def test_lfs_manifest_reopens_exact_sealed_source_review_lineage(self):
        def seal_record(root, frontier_id, phase, filename, record, parents=()):
            capture = module.allocate_capture(
                root,
                phase,
                frontier_id=frontier_id,
                parent_capture_records=list(parents),
            )
            member = Path(capture["absolutePath"]) / filename
            module.write_canonical_exclusive(member, record)
            seal = module.seal_capture(
                root, capture["captureId"], [filename]
            )
            return (
                member,
                module._ledger_record_path(root, seal),
                capture["captureId"],
            )

        def resign(record):
            value = dict(record)
            value.pop("recordDigest", None)
            return module._self_digest_record(value)

        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)
            _repository, root, frontier = self._live_repository_and_ledger(base)
            candidate_ref = "refs/heads/codex/qinao-git-only-convergence"
            candidate_oid = "c" * 40
            objects = [{"oid": "a" * 64, "size": 4}]
            source = module.build_lfs_source_review(
                candidate_ref, candidate_oid, objects
            )
            _source_member, source_seal, source_capture = seal_record(
                root,
                frontier["frontierId"],
                "lfs-source-review",
                "lfs-source-review.json",
                source,
            )
            approved = module.build_lfs_approved_manifest(
                source,
                source_review_seal_record_path=str(source_seal),
                source_review_capture_id=source_capture,
            )
            _approved_member, approved_seal, _approved_capture = seal_record(
                root,
                frontier["frontierId"],
                "lfs-approved-manifest",
                "lfs-approved.json",
                approved,
                [source_seal],
            )
            reopened = module.reopen_lfs_approved_lineage(
                root, approved, str(approved_seal)
            )
            self.assertEqual(reopened["sourceReview"], source)
            self.assertEqual(
                reopened["objectSetDigest"], source["objectSetDigest"]
            )

            _alternate_member, alternate_seal, alternate_capture = seal_record(
                root,
                frontier["frontierId"],
                "lfs-source-review",
                "lfs-source-review.json",
                source,
            )
            hostile = []
            hostile.append(dict(approved, sourceReviewDigest="d" * 64))
            hostile.append(dict(
                approved,
                sourceReviewSealRecordPath=str(alternate_seal),
                sourceReviewCaptureId=alternate_capture,
            ))
            hostile.append(dict(approved, candidateOid="e" * 40))
            hostile.append(dict(approved, objects=[]))
            hostile.append(dict(
                approved,
                objects=[{"oid": "a" * 64, "size": 5}],
            ))
            hostile.append(dict(
                approved,
                objects=objects + [{"oid": "b" * 64, "size": 1}],
            ))
            unsealed = module.allocate_capture(
                root,
                "lfs-source-review",
                frontier_id=frontier["frontierId"],
            )
            module.write_canonical_exclusive(
                Path(unsealed["absolutePath"]) / "lfs-source-review.json",
                source,
            )
            hostile.append(dict(
                approved,
                sourceReviewSealRecordPath=str(
                    root / "ledger" / "records" / "unsealed.json"
                ),
                sourceReviewCaptureId=unsealed["captureId"],
            ))

            other_base = base / "other"
            other_base.mkdir()
            _other_repository, other_root, other_frontier = (
                self._live_repository_and_ledger(other_base)
            )
            _other_member, other_seal, other_capture = seal_record(
                other_root,
                other_frontier["frontierId"],
                "lfs-source-review",
                "lfs-source-review.json",
                source,
            )
            hostile.append(dict(
                approved,
                sourceReviewSealRecordPath=str(other_seal),
                sourceReviewCaptureId=other_capture,
            ))
            for index, candidate in enumerate(hostile):
                with self.subTest(hostile=index), self.assertRaises(
                    module.AuditError
                ):
                    module.reopen_lfs_approved_lineage(
                        root, resign(candidate), str(approved_seal)
                    )

