    def test_reserved_steps_preserve_primary_after_terminal_release_failure(self):
        """Break caught: terminalization/release replaces the operation's exception."""
        for step in ("preflight", "attempt"):
            for error_type in (KeyboardInterrupt, SystemExit):
                with self.subTest(step=step, error=error_type), tempfile.TemporaryDirectory() as temporary:
                    fixture = self._network_reservation_fixture(Path(temporary) / "step", "d")
                    reservation = self._reserve_network_fixture(fixture)
                    primary, cleanup = error_type("operation interrupted"), OSError("release reporting fault")
                    real_release = module._release_network_execution_guard
                    released = []
                    def release(*args):
                        real_release(*args)
                        released.append(True)
                        raise cleanup
                    def operation():
                        raise primary
                    with mock.patch.object(module, "_release_network_execution_guard", release):
                        try:
                            if step == "preflight":
                                module._run_reserved_network_preflight_step(
                                    fixture["root"], reservation, "BrokerBindingDrift", operation)
                            else:
                                module._run_reserved_network_attempt_step(fixture["root"], reservation, operation)
                        except BaseException as caught:
                            self.assertIs(caught, primary)
                        else:
                            self.fail("operation error was dropped")
                    self.assertEqual(primary.cleanup_errors, [cleanup])
                    self.assertEqual(released, [True])
                    self.assertFalse(any(g.root == fixture["root"] for g in module._current_thread_network_execution_guards()))
                    state = module.recover_run_state(fixture["root"])
                    self.assertEqual(state["networkReservations"][0]["state"], "preflight-failed-no-network")
                    self.assertEqual(state["networkAttempts"], [])

