    def test_dispatch_preserves_local_primary_and_success_cleanup_failure(self):
        """Break caught: command cleanup replaces the handler or swallows its own error."""
        for success in (False, True):
            for error_type in (KeyboardInterrupt, SystemExit):
                with self.subTest(success=success, error=error_type), tempfile.TemporaryDirectory() as temporary:
                    fixture = self._network_reservation_fixture(Path(temporary) / "dispatch", "d")
                    primary, cleanup = error_type("handler interrupted"), OSError("dispatch cleanup interrupted")
                    def handler(argv):
                        self._reserve_network_fixture(fixture)
                        if not success:
                            raise primary
                        return 0
                    real_cleanup = module._close_network_execution_guards_since
                    def close(initial):
                        real_cleanup(initial)
                        raise cleanup
                    with mock.patch.object(module, "_command_snapshot_git_state", handler), \
                            mock.patch.object(module, "_close_network_execution_guards_since", close):
                        try:
                            raise ValueError("already handled by caller")
                        except ValueError:
                            try:
                                module._dispatch_command(["snapshot-git-state"])
                            except BaseException as caught:
                                self.assertIs(caught, cleanup if success else primary)
                            else:
                                self.fail("cleanup failure was hidden")
                    if not success:
                        self.assertEqual(primary.cleanup_errors, [cleanup])
                    self.assertFalse(any(g.root == fixture["root"] for g in module._current_thread_network_execution_guards()))
                    self.assertEqual(module.recover_run_state(fixture["root"])["networkReservations"][0]["state"], "preflight-failed-no-network")

    def test_current_thread_guard_enumeration_requires_complete_owner_identity(self):
        """Break caught: recycled ident grants a foreign owner cleanup authority."""
        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._network_reservation_fixture(Path(temporary) / "owner", "d")
            reservation = self._reserve_network_fixture(fixture)
            with module._NETWORK_EXECUTION_RESERVATION_GUARDS_LOCK:
                guard = module._NETWORK_EXECUTION_RESERVATION_GUARDS[str(fixture["root"])]
            original = (guard._owner_pid, guard._owner_thread, guard._owner_thread_object)
            try:
                self.assertIn(guard, module._current_thread_network_execution_guards())
                for field, foreign in (
                    ("_owner_pid", os.getpid() + 1),
                    ("_owner_thread", threading.get_ident() + 1),
                    ("_owner_thread_object", threading.Thread()),
                ):
                    with self.subTest(field=field):
                        saved = getattr(guard, field)
                        try:
                            setattr(guard, field, foreign)
                            self.assertNotIn(guard, module._current_thread_network_execution_guards())
                        finally:
                            setattr(guard, field, saved)
                self.assertIn(guard, module._current_thread_network_execution_guards())
            finally:
                guard._owner_pid, guard._owner_thread, guard._owner_thread_object = original
                module._terminalize_network_preflight_no_network(
                    fixture["root"], reservation, "InterruptedBeforeNetworkAttempt"
                )
            self.assertNotIn(guard, module._current_thread_network_execution_guards())

    def test_uncertain_network_guard_close_is_root_local_and_retains_owner(self):
        def body():
            with tempfile.TemporaryDirectory() as temporary:
                base = Path(temporary)
                first = self._network_reservation_fixture(
                    base / "first", "d"
                )
                second = self._network_reservation_fixture(
                    base / "second", "e"
                )
                first_reservation = self._reserve_network_fixture(first)
                first_key = str(first["root"])
                with module._NETWORK_EXECUTION_RESERVATION_GUARDS_LOCK:
                    first_guard = (
                        module._NETWORK_EXECUTION_RESERVATION_GUARDS[first_key]
                    )

                real_close = module.os.close
                root_slot = first_guard._root_fd
                ledger_slot = first_guard._ledger_fd
                identity_slot = first_guard._identity_fd
                target = root_slot.generation_descriptor
                replacement = os.open(os.devnull, os.O_RDONLY)
                primary = OSError(errno.EIO, "root close interrupted")
                injected = []

                def fail_first_close(descriptor):
                    real_close(descriptor)
                    if descriptor == target and not injected:
                        injected.append(descriptor)
                        os.dup2(replacement, descriptor)
                        raise primary

                second_reservation = None
                try:
                    with mock.patch.object(
                        module.os, "close", side_effect=fail_first_close,
                    ), self.assertRaisesRegex(
                        module.AuditError, "close is uncertain"
                    ) as caught:
                        module._release_network_execution_guard(
                            first["root"], first_reservation
                        )

                    self.assertEqual(injected, [target])
                    self.assertIn(primary, _exception_objects(caught.exception))
                    self.assertEqual(root_slot.phase, "uncertain")
                    self.assertEqual(ledger_slot.phase, "closed")
                    self.assertEqual(identity_slot.phase, "owned")
                    self.assertEqual(os.fstat(target), os.fstat(replacement))
                    with module._NETWORK_EXECUTION_RESERVATION_GUARDS_LOCK:
                        self.assertIs(
                            module._NETWORK_EXECUTION_RESERVATION_GUARDS.get(
                                first_key
                            ),
                            first_guard,
                        )
                        self.assertIs(
                            module._NETWORK_EXECUTION_RESERVATION_PHYSICAL_GUARDS.get(
                                first_guard._physical_key
                            ),
                            first_guard,
                        )

                    second_reservation = self._reserve_network_fixture(second)
                    terminal = module._terminalize_network_preflight_no_network(
                        second["root"],
                        second_reservation,
                        "InterruptedBeforeNetworkAttempt",
                    )
                    second_reservation = None
                    self.assertEqual(
                        terminal["failureClass"],
                        "InterruptedBeforeNetworkAttempt",
                    )
                finally:
                    if second_reservation is not None:
                        module._terminalize_network_preflight_no_network(
                            second["root"],
                            second_reservation,
                            "InterruptedBeforeNetworkAttempt",
                        )
                    with self.assertRaises(module.AuditError):
                        first_guard.close()
                    self.assertEqual(os.fstat(target), os.fstat(replacement))
        DirectorySlotHandoffTests._isolated_worker(self, body)

