    def _persistence_records(self, root):
        recovered = module.recover_run_state(root)
        self.assertEqual(recovered["classification"], "complete")
        return [
            record
            for record in recovered["records"]
            if record["operationKind"] in self._PERSISTENCE_KINDS
        ]

    def test_static_argv_or_v1_rejection_has_no_preflight_persistence(self):
        """Break caught: unsealed authority consumes a durable use key."""

