    def test_review_assignment_verifies_canonical_manifest_identity_config_and_dispositions(self):
        raw = (
            b":000000 100644 " + b"0" * 40 + b" " + b"1" * 40
            + b" A\x00docs/superpowers/plans/new.md\x00"
            + b":100644 100644 " + b"2" * 40 + b" " + b"3" * 40
            + b" M\x00scripts/qinao_pr_protocol.py\x00"
        )
        manifest = module.build_raw_diff_manifest(raw, "sha1")
        entries = module.parse_raw_diff_z(raw, "sha1")
        identity = {
            "B": "2" * 40,
            "H": "3" * 40,
            "T": "4" * 40,
            "V": "5" * 64,
        }
        rows = [
            {
                "entryId": module._entry_id(0, entries[0]),
                "pathB64": entries[0].new_path_b64,
                "status": "A",
                "partitionIds": ["identity-history-documents"],
                "binaryDisposition": "not-applicable",
                "lfsDisposition": "not-applicable",
                "documentDisposition": "newly-authored",
            },
            {
                "entryId": module._entry_id(1, entries[1]),
                "pathB64": entries[1].new_path_b64,
                "status": "M",
                "partitionIds": [
                    "protocol-jcs-recovery",
                    "validation-testing-operations",
                ],
                "binaryDisposition": "reviewed-source",
                "lfsDisposition": "not-applicable",
                "documentDisposition": "not-applicable",
            },
        ]
        assignment = module._self_digest_record(
            {
                "schemaVersion": "qinao.review-assignment.v1",
                "configurationBlobOid": "6" * 40,
                "rawManifestSha256": module._sha256(
                    module.canonical_json_bytes(manifest)
                ),
                "identity": identity,
                "rows": rows,
            },
            field="assignmentSha256",
        )
        result = module.verify_review_assignment(
            manifest, assignment, identity
        )
        self.assertEqual(result["assignedEntryCount"], 2)
        self.assertEqual(result["partitionAssignmentCount"], 3)
        self.assertEqual(result["documentDispositionCount"], 1)
        self.assertEqual(result["binaryDispositionCount"], 1)
        self.assertEqual(
            set(result["partitionCounts"]),
            {
                "identity-history-documents",
                "protocol-jcs-recovery",
                "workflow-automation-security",
                "validation-testing-operations",
            },
        )

        def resign(value):
            value = dict(value)
            value.pop("assignmentSha256", None)
            return module._self_digest_record(
                value, field="assignmentSha256"
            )

        bad_values = [
            {"schemaVersion": "qinao.review-assignment.v0"},
            {"configurationBlobOid": "0" * 40},
            {"rawManifestSha256": "7" * 64},
            {"identity": dict(identity, H="8" * 40)},
            {"rows": rows[:1]},
            {"rows": rows + [rows[0]]},
            {"rows": list(reversed(rows))},
            {"rows": [dict(rows[0], status="M"), rows[1]]},
            {"rows": [dict(rows[0], pathB64=rows[1]["pathB64"]), rows[1]]},
            {
                "rows": [
                    dict(rows[0], partitionIds=["unknown-partition"]),
                    rows[1],
                ]
            },
            {
                "rows": [
                    dict(rows[0], documentDisposition="not-applicable"),
                    rows[1],
                ]
            },
            {
                "rows": [
                    {
                        key: value
                        for key, value in rows[0].items()
                        if key != "lfsDisposition"
                    },
                    rows[1],
                ]
            },
        ]
        for mutation in bad_values:
            with self.subTest(mutation=mutation):
                candidate = dict(assignment)
                candidate.update(mutation)
                candidate = resign(candidate)
                with self.assertRaises(module.AuditError):
                    module.verify_review_assignment(
                        manifest, candidate, identity
                    )
        with self.assertRaises(module.AuditError):
            module.verify_review_assignment(identity, assignment, identity)
        tampered = dict(assignment, assignmentSha256="9" * 64)
        with self.assertRaises(module.AuditError):
            module.verify_review_assignment(manifest, tampered, identity)

        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            manifest_path = root / "manifest.json"
            assignment_path = root / "assignment.json"
            identity_path = root / "identity.json"
            output_path = root / "verification.json"
            manifest_path.write_bytes(module.canonical_json_bytes(manifest))
            assignment_path.write_bytes(
                module.canonical_json_bytes(assignment)
            )
            identity_path.write_bytes(module.canonical_json_bytes(identity))
            for path in (
                manifest_path,
                assignment_path,
                identity_path,
            ):
                path.chmod(0o600)
            self.assertEqual(
                module._dispatch_command(
                    [
                        "review-assignment-verify",
                        "--manifest",
                        str(manifest_path),
                        "--assignment",
                        str(assignment_path),
                        "--identity",
                        str(identity_path),
                        "--output",
                        str(output_path),
                    ]
                ),
                0,
            )
            self.assertEqual(
                module.parse_canonical_json(output_path.read_bytes()),
                result,
            )


