    def test_owned_secret_buffer_has_single_mutable_owner_and_wipes_on_every_exit(self):
        for raises in (False, True):
            with self.subTest(raises=raises):
                backing = bytearray(b"mutable-secret")
                try:
                    with module.OwnedSecretBuffer.take(backing) as secret:
                        self.assertEqual(secret.view().tobytes(), b"mutable-secret")
                        self.assertIs(secret.owner(), backing)
                        if raises:
                            raise module.AuditError("injected consumer failure")
                except module.AuditError:
                    if not raises:
                        raise
                self.assertEqual(backing, bytearray(len(backing)))
                with self.assertRaisesRegex(module.AuditError, "released"):
                    secret.view()

    def test_one_shot_broker_wipes_transferred_owner_on_every_pipe_fault(self):
        helper = (
            b"protocol=https\nhost=github.com\n"
            b"path=ChangGeng01/ProjectSix.git\n"
            b"username=qinao\npassword=ephemeral-secret\n\n"
        )
        for boundary in ("consume-close", "child-feed-write"):
            with self.subTest(boundary=boundary):
                backing = bytearray(helper)
                broker = module.OneShotCredentialBroker(
                    module.OwnedSecretBuffer.take(backing)
                )
                uncertain_descriptor = None
                try:
                    if boundary == "consume-close":
                        uncertain_descriptor = broker._write_fd
                        real_close = module.os.close

                        def close_with_uncertain_result(descriptor):
                            if descriptor == uncertain_descriptor:
                                raise OSError("injected-" + boundary)
                            return real_close(descriptor)

                        patcher = mock.patch.object(
                            module.os,
                            "close",
                            side_effect=close_with_uncertain_result,
                        )
                    else:
                        patcher = mock.patch.object(
                            module.os,
                            "write",
                            side_effect=OSError("injected-" + boundary),
                        )
                    with patcher:
                        with self.assertRaisesRegex(
                            module.AuditError, "credential broker.*pipe"
                        ):
                            if boundary == "consume-close":
                                broker.consume(
                                    "get", "https", "github.com",
                                    "ChangGeng01/ProjectSix.git",
                                )
                            else:
                                broker.prime_for_child()
                    self.assertEqual(backing, bytearray(len(backing)))
                    if uncertain_descriptor is not None:
                        self.assertEqual(
                            broker._write_slot.generation_descriptor, uncertain_descriptor
                        )
                        self.assertIs(
                            module._CREDENTIAL_BROKER_POISONED.get(id(broker)),
                            broker,
                        )
                finally:
                    if uncertain_descriptor is not None:
                        with self.assertRaises(module.AuditError):
                            broker.close()
                        # The injected pre-close failure deliberately leaves
                        # an uncertain generation until process exit. Only
                        # this fixture knows that close never took effect.
                        os.fstat(uncertain_descriptor)
                        self.assertEqual(broker._write_slot.phase, "uncertain")
                        os.close(uncertain_descriptor)
                        # Test disposal knows the syscall never closed this
                        # fd; prevent __del__ from re-registering its tombstone.
                        broker.close = lambda: None
                        broker._unregister()
                    else:
                        broker.close()

    def test_broker_partial_construction_and_gc_wipe_and_close_every_owner(self):
        invalid = bytearray(b"not-a-helper-response")
        with self.assertRaises(module.AuditError):
            module.OneShotCredentialBroker(
                module.OwnedSecretBuffer.take(invalid)
            )
        self.assertEqual(invalid, bytearray(len(invalid)))

        backing = bytearray(
            b"protocol=https\nhost=github.com\n"
            b"path=ChangGeng01/ProjectSix.git\n"
            b"username=qinao\npassword=gc-secret\n\n"
        )
        broker = module.OneShotCredentialBroker(
            module.OwnedSecretBuffer.take(backing)
        )
        descriptors = (broker._read_fd, broker._write_fd)
        broker_id = id(broker)
        observed = weakref.ref(broker)
        del broker
        gc.collect()
        self.assertIsNone(observed())
        self.assertEqual(backing, bytearray(len(backing)))
        self.assertNotIn(broker_id, module._CREDENTIAL_BROKERS)
        self.assertNotIn(broker_id, module._CREDENTIAL_BROKER_POISONED)
        for descriptor in descriptors:
            with self.assertRaises(OSError) as closed:
                os.fstat(descriptor)
            self.assertEqual(closed.exception.errno, errno.EBADF)

    def test_broker_feed_completion_failure_and_owner_close_release_lock(self):
        helper = (
            b"protocol=https\nhost=github.com\n"
            b"path=ChangGeng01/ProjectSix.git\n"
            b"username=qinao\npassword=feed-secret\n\n"
        )
        for action in ("premature-complete", "owner-close"):
            with self.subTest(action=action):
                backing = bytearray(helper)
                broker = module.OneShotCredentialBroker(
                    module.OwnedSecretBuffer.take(backing)
                )
                descriptors = (broker._read_fd, broker._write_fd)
                claim = broker._begin_child_feed()
                if action == "premature-complete":
                    with self.assertRaisesRegex(
                        module.AuditError, "completion drift"
                    ):
                        broker._complete_child_feed(claim)
                else:
                    broker.close()
                self.assertFalse(broker._feed_lock_held)
                self.assertFalse(broker._feed_active)
                self.assertEqual(backing, bytearray(len(backing)))
                acquired = []

                def acquire_after_failure():
                    with broker._lifecycle_lock:
                        acquired.append(True)

                contender = threading.Thread(target=acquire_after_failure)
                contender.start()
                contender.join(2)
                self.assertFalse(contender.is_alive())
                self.assertEqual(acquired, [True])
                broker.close()
                for descriptor in descriptors:
                    with self.assertRaises(OSError) as closed:
                        os.fstat(descriptor)
                    self.assertEqual(closed.exception.errno, errno.EBADF)

    def test_parallel_weak_network_helpers_are_absent_from_authority_module(self):
        for name in (
            "execute_lfs_batch_wrapper",
            "git_credential_auth_projection",
            "validate_network_git_invocation",
            "_runtime_adapter",
            "_parse_credential_helper_bytes",
            "_resource_manifest",
            "_execute_lfs_batch_via_network_core",
            "execute_quarantine_ref_observation",
        ):
            self.assertFalse(hasattr(module, name), name)
        tree = ast.parse(AUDIT_PATH.read_text("utf-8"))
        parser_names = [
            node.name
            for node in tree.body
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
            and node.name.startswith("_parse_")
            and "credential" in node.name
        ]
        self.assertEqual(
            parser_names,
            [
                "_parse_credential_helper_owner",
                "_parse_owned_credential_helper",
            ],
        )
        good = bytearray(
            b"protocol=https\nhost=github.com\n"
            b"path=ChangGeng01/ProjectSix.git\n"
            b"username=qinao\npassword=ephemeral\n\n"
        )
        owner = module.OwnedSecretBuffer.take(good)
        try:
            fields = module._parse_owned_credential_helper(owner)
            self.assertIsInstance(fields.view("username"), memoryview)
            self.assertIsInstance(fields.view("password"), memoryview)
        finally:
            owner.release()
        self.assertEqual(good, bytearray(len(good)))
        for payload in (
            b"protocol=https\nhost=github.com\n\n",
            b"protocol=https\nhost=github.com\npath=x\nusername=u\npassword=p\n\n",
            b"protocol=https\nprotocol=https\nhost=github.com\npath=ChangGeng01/ProjectSix.git\nusername=u\npassword=p\n\n",
            b"protocol=https\nhost=github.com\npath=ChangGeng01/ProjectSix.git\nusername=u\npassword=p\x00x\n\n",
        ):
            backing = bytearray(payload)
            secret = module.OwnedSecretBuffer.take(backing)
            try:
                with self.assertRaises(module.AuditError):
                    module._parse_owned_credential_helper(secret)
            finally:
                secret.release()
            self.assertEqual(backing, bytearray(len(backing)))

