    def test_external_init_has_the_only_extended_fresh_process_deadline(self):
        observed = {}

        def completed_child(command, **request):
            observed[command[-1]] = request["timeout"]
            return subprocess.CompletedProcess(command, 0, b"", b"")

        with mock.patch.object(subprocess, "run", side_effect=completed_child):
            for command_name in sorted(INDEPENDENT_PUBLIC_SURFACE_CASES):
                _run_fresh_public_surface(command_name)

        self.assertEqual(observed["init-run-state"], 360)
        self.assertEqual(
            {value for name, value in observed.items() if name != "init-run-state"},
            {180},
        )
        self.assertEqual(max(observed.values()), 360)

    def test_all_public_surfaces_execute_non_help_semantics(self):
        expected = set(INDEPENDENT_PUBLIC_SURFACE_CASES)
        self.assertEqual(len(expected), 37)
        projections = {}
        child_pids = set()
        for command_name in sorted(expected):
            with self.subTest(command=command_name):
                completed = _run_fresh_public_surface(command_name)
                if completed.returncode != 0:
                    self.fail(
                        "fresh semantic case failed for "
                        + command_name
                        + ":\n"
                        + completed.stderr.decode("utf-8", "replace")
                    )
                projection = module.parse_canonical_json(completed.stdout)
                self.assertTrue(projection["successful"])
                self.assertEqual(projection["command"], command_name)
                self.assertNotIn(projection["pid"], child_pids)
                child_pids.add(projection["pid"])
                projections[command_name] = projection
        self.assertEqual(set(projections), expected)
        self.assertEqual(len(child_pids), 37)

    def test_remaining_plain_cli_routes_execute_non_help_semantics(self):
        class BinaryStdout:
            def __init__(self):
                self.buffer = io.BytesIO()

            def write(self, value):
                return len(value)

            def flush(self):
                return None

        def dispatch_json(arguments):
            stream = BinaryStdout()
            with mock.patch.object(module.sys, "stdout", stream):
                self.assertEqual(module._dispatch_command(arguments), 0)
            return module.parse_canonical_json(stream.buffer.getvalue())

        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)
            root = _new_run_root(base)
            module.init_run_state(
                root, _identity_fields(base), bootstrap_imports=[]
            )

            allocation = dispatch_json([
                "allocate-resource", "--root", str(root),
                "--resource-kind", "semantic-proof",
            ])
            member = Path(allocation["absolutePath"]) / "safe.bin"
            member.write_bytes(b"semantic resource\n")
            member.chmod(0o600)
            snapshot = dispatch_json([
                "snapshot-resource", "--root", str(root),
                "--resource-id", allocation["resourceId"],
            ])
            self.assertEqual(snapshot["resourceId"], allocation["resourceId"])
            self.assertRegex(snapshot["snapshotDigest"], r"\A[0-9a-f]{64}\Z")

            raw = (
                b":100644 100644 " + b"1" * 40 + b" " + b"2" * 40
                + b" M\x00safe.txt\x00"
            )
            raw_path = base / "raw.diff"
            raw_path.write_bytes(raw)
            raw_path.chmod(0o600)
            manifest_path = base / "raw-manifest.json"
            manifest = dispatch_json([
                "diff-inventory", "--raw-diff", str(raw_path),
                "--object-format", "sha1", "--output", str(manifest_path),
            ])
            self.assertEqual(manifest["entryCount"], 1)
            self.assertEqual(module._read_record(str(manifest_path)), manifest)

            advertisement_path = base / "advertisement.bin"
            advertisement_path.write_bytes(
                b"3" * 40 + b"\trefs/heads/main\n"
            )
            advertisement_path.chmod(0o600)
            validated_path = base / "advertisement.json"
            advertisement = dispatch_json([
                "validate-remote-advertisement",
                "--input", str(advertisement_path),
                "--object-format", "sha1",
                "--output", str(validated_path),
            ])
            self.assertEqual(advertisement["refCount"], 1)
            self.assertEqual(
                module._read_record(str(validated_path)), advertisement
            )

            repository = base / "repository"
            _mkdir(repository)
            module._run_git(repository, ["init", "--quiet"])
            (repository / "safe.txt").write_bytes(b"safe indexed bytes\n")
            module._run_git(repository, ["add", "--", "safe.txt"])
            scan_path = base / "worktree-scan.json"
            scan = dispatch_json([
                "secret-scan-worktree", "--repository", str(repository),
                "--output", str(scan_path),
            ])
            self.assertEqual(scan["findingCount"], 0)
            self.assertGreater(scan["scannedFileCount"], 0)
            self.assertGreater(scan["scannedByteCount"], 0)
            self.assertEqual(module._read_record(str(scan_path)), scan)

            raw_surface = NetworkBoundaryTests._network_egress_raw_surface()
            raw_surface["repository"] = str(repository)
            local_projection = module._project_network_egress_surface(
                module._validate_network_egress_surface(raw_surface)
            )
            preflight = module.build_network_egress_preflight(
                local_projection,
                local_only=False,
                destination={
                    "git":
                    "https://github.com/ChangGeng01/ProjectSix.git"
                },
                git_credential={
                    "identityDigest": "7" * 64,
                    "generationDigest": "8" * 64,
                },
                gh_credential={
                    "identityDigest": "9" * 64,
                    "generationDigest": "a" * 64,
                },
                fetch_policy={"version": "qinao-fixed-v1"},
            )
            preflight_path = base / "network-egress.json"
            preflight_path.write_bytes(module.canonical_json_bytes(preflight))
            preflight_path.chmod(0o600)
            intent_path = base / "network-intent.json"
            intent = dispatch_json([
                "seal-network-request-manifest",
                "--operation", "ls-remote",
                "--preflight", str(preflight_path),
                "--output", str(intent_path),
                "--", "ls-remote", "--refs",
                INDEPENDENT_NETWORK_GIT_ENDPOINT, "refs/heads/main",
            ])
            self.assertEqual(intent["rowCount"], 1)
            self.assertEqual(intent["rows"][0]["maximumUses"], 1)
            self.assertEqual(module._read_record(str(intent_path)), intent)

    def test_git_state_classifier_accepts_only_attributable_or_exact_poststate(self):
        before = {"refs": {}, "objects": {"old": "1"}, "adminDigest": "a"}
        partial = {"refs": {}, "objects": {"old": "1", "new": "2"}, "adminDigest": "a"}
        exact = {"refs": {"refs/qinao/main": "2"}, "objects": {"old": "1", "new": "2"}, "adminDigest": "a"}
        self.assertEqual(module.classify_local_import_state(before, partial, exact, {"new": "2"}), "attributable-objects-only")
        self.assertEqual(module.classify_local_import_state(before, exact, exact, {"new": "2"}), "exact-post-state")
        with self.assertRaises(module.AuditError):
            module.classify_local_import_state(before, dict(partial, adminDigest="b"), exact, {"new": "2"})

    def test_git_state_classifier_derives_additions_from_full_overlapping_source(self):
        """Break caught: additions are incorrectly compared to the full source object set."""
        before = {"refs": {}, "objects": {"old": "1"}, "adminDigest": "a"}
        partial = {"refs": {}, "objects": {"old": "1", "new": "2"}, "adminDigest": "a"}
        exact = {"refs": {"refs/qinao/main": "2"}, "objects": {"old": "1", "new": "2"}, "adminDigest": "a"}
        self.assertEqual(module.classify_local_import_state(before, partial, exact, {"old": "1", "new": "2"}),
            "attributable-objects-only")

    def test_git_state_classifier_exact_poststate_cannot_skip_union_or_preservation(self):
        """Break caught: exact equality accepts changed old objects/refs/admin or an incomplete union."""
        before = {"refs": {"refs/heads/main": "old"}, "objects": {"old": "1"}, "adminDigest": "a"}
        full = {"old": "1", "new": "2"}
        valid = {"refs": {"refs/heads/main": "old", "refs/qinao/main": "new"}, "objects": full, "adminDigest": "a"}
        for fault in ("object", "ref", "admin", "missing", "extra", "overlap", "shape"):
            with self.subTest(fault=fault):
                exact = copy.deepcopy(valid)
                source = dict(full)
                if fault == "object":
                    exact["objects"]["old"] = "changed"
                elif fault == "ref":
                    exact["refs"]["refs/heads/main"] = "changed"
                elif fault == "admin":
                    exact["adminDigest"] = "changed"
                elif fault == "missing":
                    exact["objects"].pop("new")
                elif fault == "extra":
                    exact["objects"]["foreign"] = "3"
                elif fault == "overlap":
                    source["old"] = "changed"
                    exact["objects"]["old"] = "changed"
                else:
                    exact["unknown"] = True
                with self.assertRaises(module.AuditError):
                    module.classify_local_import_state(before, exact, exact, source)

    def test_git_state_classifier_preserves_full_source_and_rejects_partial_foreign_drift(self):
        """Break caught: full-source projection loses all-present input or admits non-attributable partial state."""
        before = {"refs": {"refs/heads/old": "old"}, "objects": {"old": "1"}, "adminDigest": "a"}
        source = {"old": "1", "new": "2", "second": "3"}
        exact = {"refs": {"refs/heads/old": "old", "refs/qinao/main": "new"}, "objects": dict(source), "adminDigest": "a"}
        self.assertEqual(module.classify_local_import_state(before, before, exact, source), "input-unchanged")
        all_present = dict(exact, refs=dict(before["refs"]))
        self.assertEqual(module.classify_local_import_state(all_present, all_present, exact, source), "input-unchanged")
        self.assertEqual(module.classify_local_import_state(all_present, exact, exact, source), "exact-post-state")
        for fault in ("missing", "foreign", "old-changed", "old-missing", "ref", "admin", "overlap-conflict"):
            with self.subTest(fault=fault):
                observed = copy.deepcopy(all_present)
                attributable = dict(source)
                if fault == "missing":
                    observed["objects"].pop("second")
                elif fault == "foreign":
                    observed["objects"]["foreign"] = "4"
                elif fault == "old-changed":
                    observed["objects"]["old"] = "changed"
                elif fault == "old-missing":
                    observed["objects"].pop("old")
                elif fault == "ref":
                    observed["refs"]["refs/heads/old"] = "changed"
                elif fault == "admin":
                    observed["adminDigest"] = "changed"
                else:
                    attributable["old"] = "changed"
                with self.assertRaises(module.AuditError):
                    module.classify_local_import_state(before, observed, exact, attributable)
        self.assertEqual(source, {"old": "1", "new": "2", "second": "3"})

