    def test_atomic_record_stage_never_enters_records_and_residual_is_inert(self):
        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)
            repository = self._committed_repository(base)
            root, task = self._root_and_task(base, repository)
            captured = {}

            def die_after_stage_fsync(boundary, operation_kind, subject):
                if boundary != "record-stage-fsync":
                    return
                self.assertEqual(
                    operation_kind, "secret-scan-capture-allocation"
                )
                self.assertRegex(subject, r"\A[0-9]{16}\.json\Z")
                record_stages = [
                    path for path in (root / "ledger" / "records").iterdir()
                    if path.name.startswith(".record-stage-")
                ]
                self.assertEqual(record_stages, [])
                scratch = [
                    path for path in (root / "tmp").iterdir()
                    if path.name.startswith(".qinao-record-stage-")
                ]
                self.assertEqual(len(scratch), 1)
                captured["name"] = scratch[0].name
                captured["payload"] = scratch[0].read_bytes()
                captured["mode"] = _mode(scratch[0])
                raise self._ProcessDeath("simulated process disappearance")

            with self.assertRaises(self._ProcessDeath):
                module.allocate_secret_scan_capture(
                    root,
                    repository=repository,
                    phase="task3-secret-atomic",
                    frontier_id=task["frontierId"],
                    _faults=module.DurabilityFaults(die_after_stage_fsync),
                )
            self.assertTrue(captured)
            residual = root / "tmp" / captured["name"]
            residual.write_bytes(captured["payload"])
            os.chmod(residual, captured["mode"])
            recovered = module.recover_run_state(root)
            self.assertEqual(recovered["classification"], "complete")
            self.assertFalse([
                path.name for path in (root / "ledger" / "records").iterdir()
                if not (
                    len(path.name) == 21
                    and path.name[:16].isdigit()
                    and path.name[16:] == ".json"
                )
            ])
            allocated = module.allocate_secret_scan_capture(
                root,
                repository=repository,
                phase="task3-secret-atomic",
                frontier_id=task["frontierId"],
            )
            self.assertEqual(allocated["state"], "secret-scan-materialized")
            self.assertTrue(residual.is_file())

