    def test_reservation_shape_recomputes_subject_and_generation_name(self):
        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)
            repository = self._committed_repository(base)
            root, task = self._root_and_task(base, repository)
            allocated = module.allocate_secret_scan_capture(
                root,
                repository=repository,
                phase="task3-secret-shape",
                frontier_id=task["frontierId"],
            )
            reservation = dict(module.recover_run_state(root)["captures"][
                allocated["captureId"]
            ]["reservation"])

            bad_subject = dict(reservation)
            unsigned_binding = dict(reservation["binding"])
            unsigned_binding.pop("bindingDigest")
            unsigned_binding["subjectDigest"] = "f" * 64
            binding = module._self_digest_record(
                unsigned_binding, field="bindingDigest"
            )
            recovery_key = hashlib.sha256(
                module.canonical_json_bytes(binding)
            ).hexdigest()
            capture_id = hashlib.sha256(
                b"qinao-secret-scan-capture\x00"
                + recovery_key.encode("ascii")
            ).hexdigest()[:32]
            absolute = Path(reservation["absolutePath"]).parent / (
                "%016d-%s" % (reservation["sequence"], capture_id)
            )
            bad_subject.update({
                "binding": binding,
                "bindingDigest": binding["bindingDigest"],
                "recoveryKey": recovery_key,
                "inputDigest": recovery_key,
                "captureId": capture_id,
                "absolutePath": str(absolute),
                "outputPath": str(absolute / "secret-scan.json"),
            })
            bad_subject.pop("recordDigest")
            bad_subject = module._self_digest_record(bad_subject)
            with self.assertRaises(module.AuditError):
                module._validate_ledger_record_shape(bad_subject)

            bad_generation = dict(reservation)
            bad_absolute = Path(reservation["absolutePath"]).parent / (
                "%016d-%s"
                % (reservation["sequence"] + 1, reservation["captureId"])
            )
            bad_generation["absolutePath"] = str(bad_absolute)
            bad_generation["outputPath"] = str(
                bad_absolute / "secret-scan.json"
            )
            bad_generation.pop("recordDigest")
            bad_generation = module._self_digest_record(bad_generation)
            with self.assertRaises(module.AuditError):
                module._validate_ledger_record_shape(bad_generation)

