    def test_subject_digest_binds_git_metadata_dirty_mode_and_module(self):
        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)
            repository = self._committed_repository(base)
            root, task = self._root_and_task(
                base, repository, declared_paths=["dirty.txt"]
            )
            (repository / "tracked.txt").write_bytes(b"staged replacement\n")
            module._run_git(repository, ["add", "--", "tracked.txt"])
            (repository / "dirty.txt").write_bytes(b"dirty replacement\n")
            os.chmod(repository / "dirty.txt", 0o600)
            allocated = module.allocate_secret_scan_capture(
                root,
                repository=repository,
                phase="task3-secret-metadata",
                frontier_id=task["frontierId"],
            )
            binding = module.recover_run_state(root)["captures"][
                allocated["captureId"]
            ]["reservation"]["binding"]

            index_rows = []
            raw = module._run_git(repository, ["ls-files", "--stage", "-z"])
            for token in raw.split(b"\x00"):
                if not token:
                    continue
                header, path = token.split(b"\t", 1)
                git_mode, blob_oid, stage = header.split(b" ")
                self.assertEqual(stage, b"0")
                payload = module._run_git(
                    repository, ["cat-file", "blob", blob_oid.decode("ascii")]
                )
                index_rows.append({
                    "pathB64": base64.b64encode(path).decode("ascii"),
                    "source": "index",
                    "gitMode": git_mode.decode("ascii"),
                    "blobOid": blob_oid.decode("ascii"),
                    "size": len(payload),
                    "sha256": hashlib.sha256(payload).hexdigest(),
                })
            index_rows.sort(key=lambda row: base64.b64decode(row["pathB64"]))
            dirty_payload = (repository / "dirty.txt").read_bytes()
            dirty_row = {
                "pathB64": base64.b64encode(b"dirty.txt").decode("ascii"),
                "source": "worktree",
                "mode": "0600",
                "size": len(dirty_payload),
                "sha256": hashlib.sha256(dirty_payload).hexdigest(),
            }
            self.assertEqual(
                binding["indexEntryMapDigest"],
                hashlib.sha256(
                    module.canonical_json_bytes(index_rows)
                ).hexdigest(),
            )
            self.assertEqual(
                binding["selectedEntriesDigest"],
                hashlib.sha256(
                    module.canonical_json_bytes(index_rows + [dirty_row])
                ).hexdigest(),
            )
            module_path = (
                repository / "scripts" / "qinao_convergence_audit.py"
            )
            module_payload = module_path.read_bytes()
            self.assertEqual(binding.get("scannerModulePath"), str(module_path))
            self.assertEqual(binding.get("scannerModuleMode"), "0644")
            self.assertEqual(binding.get("scannerModuleSize"), len(module_payload))
            self.assertEqual(
                binding.get("scannerModuleSha256"),
                hashlib.sha256(module_payload).hexdigest(),
            )

    def test_atomic_record_publish_rejects_source_and_published_swaps(self):
        # Deliberate mode poison must remain retained until worker exit.
        # Removing quarantine or allowing its child to continue is a regression.
        source_mutations = ("same-size", "symlink", "hardlink", "mode")
        for mutation in source_mutations:
            with self.subTest(mutation=mutation):
                owners_before = dict(module._LEDGER_TRANSACTION_OWNERS)
                quarantine_before = dict(module._LEDGER_TRANSACTION_QUARANTINE)

                def exercise():
                    with tempfile.TemporaryDirectory() as temporary:
                        base = Path(temporary)
                        root = _new_run_root(base)
                        module.init_run_state(
                            root, _identity_fields(base), bootstrap_imports=[]
                        )
                        final_name = None

                        def mutate_source(boundary, _operation, subject):
                            nonlocal final_name
                            if boundary != "record-stage-parent-fsync":
                                return
                            final_name = subject
                            stages = sorted(
                                (root / "tmp").glob(".qinao-record-stage-*")
                            )
                            self.assertEqual(len(stages), 1)
                            stage = stages[0]
                            payload = stage.read_bytes()
                            replacement = payload.replace(
                                b'"snapshotDigest":"b',
                                b'"snapshotDigest":"c',
                                1,
                            )
                            self.assertEqual(len(replacement), len(payload))
                            if mutation == "mode":
                                os.chmod(stage, 0o644)
                                return
                            stage.unlink()
                            source = base / "replacement.json"
                            source.write_bytes(replacement)
                            os.chmod(source, 0o600)
                            if mutation == "same-size":
                                stage.write_bytes(replacement)
                                os.chmod(stage, 0o600)
                            elif mutation == "symlink":
                                os.symlink(source, stage)
                            else:
                                os.link(source, stage)

                        expected_exit = (
                            self.assertRaisesRegex(module.AuditError, "close is uncertain")
                            if mutation == "mode" else contextlib.nullcontext()
                        )
                        with expected_exit:
                            with module.LedgerTransaction(
                                root,
                                operation_kind="secret-scan-capture-allocation",
                                faults=module.DurabilityFaults(mutate_source),
                            ) as transaction:
                                recovered = transaction.recover()
                                record = module._new_record(
                                    recovered["identity"],
                                    recovered["nextSequence"],
                                    recovered["records"][-1]["recordDigest"],
                                    "git-state-snapshot",
                                    "1" * 64,
                                    [],
                                    "complete",
                                    {
                                        "frontierId": "a" * 32,
                                        "snapshotDigest": "b" * 64,
                                        "fields": {},
                                    },
                                )
                                with self.assertRaises(module.AuditError) as primary:
                                    transaction.write_record_atomic(
                                        recovered["nextSequence"], record
                                    )
                        self.assertIsNotNone(final_name)
                        self.assertFalse(os.path.lexists(
                            root / "ledger" / "records" / final_name
                        ))

                        if mutation == "mode":
                            self.assertIsInstance(primary.exception, module.AuditError)
                            self.assertTrue(primary.exception.cleanup_errors)
                            self.assertIn("descriptor identity drift",
                                          str(primary.exception.cleanup_errors[0]))
                            self.assertIs(transaction._settlement_failure,
                                          expected_exit.exception)
                            self.assertIs(module._LEDGER_TRANSACTION_OWNERS[id(transaction)],
                                          transaction)
                            self.assertIs(module._LEDGER_TRANSACTION_QUARANTINE[transaction],
                                          transaction)
                            self.assertTrue(transaction._locked)
                            self.assertEqual(transaction._fds["lock"].phase, "owned")
                            self.assertTrue(any(slot.phase == "uncertain"
                                                for slot in transaction._owned_slots))
                            child = os.fork()
                            if child == 0:
                                os._exit(23)
                            _, status = os.waitpid(child, 0)
                            self.assertTrue(os.WIFEXITED(status))
                            self.assertEqual(os.WEXITSTATUS(status), 70)
                DirectorySlotHandoffTests._isolated_worker(self, exercise)
                self.assertEqual(module._LEDGER_TRANSACTION_OWNERS, owners_before)
                self.assertEqual(module._LEDGER_TRANSACTION_QUARANTINE, quarantine_before)
        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)
            root = _new_run_root(base)
            module.init_run_state(
                root, _identity_fields(base), bootstrap_imports=[]
            )

            def replace_published(boundary, _operation, subject):
                if boundary != "record-atomic-publish":
                    return
                final = root / "ledger" / "records" / subject
                payload = final.read_bytes()
                replacement = payload.replace(
                    b'"snapshotDigest":"b',
                    b'"snapshotDigest":"c',
                    1,
                )
                self.assertEqual(len(replacement), len(payload))
                final.unlink()
                final.write_bytes(replacement)
                os.chmod(final, 0o600)

            with module.LedgerTransaction(
                root,
                operation_kind="secret-scan-capture-allocation",
                faults=module.DurabilityFaults(replace_published),
            ) as transaction:
                recovered = transaction.recover()
                record = module._new_record(
                    recovered["identity"],
                    recovered["nextSequence"],
                    recovered["records"][-1]["recordDigest"],
                    "git-state-snapshot",
                    "1" * 64,
                    [],
                    "complete",
                    {
                        "frontierId": "a" * 32,
                        "snapshotDigest": "b" * 64,
                        "fields": {},
                    },
                )
                with self.assertRaises(module.AuditError):
                    transaction.write_record_atomic(
                        recovered["nextSequence"], record
                    )

    def test_deterministic_capture_id_collision_precedes_durable_reservation(self):
        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)
            repository = self._committed_repository(base)
            root, task = self._root_and_task(base, repository)
            predicted = {}

            def observe_reservation(boundary, _operation, _subject):
                if boundary != "record-stage-fsync":
                    return
                stages = sorted(
                    (root / "tmp").glob(".qinao-record-stage-*")
                )
                self.assertEqual(len(stages), 1)
                predicted.update(json.loads(stages[0].read_text("utf-8")))
                raise self._ProcessDeath("capture identity observed")

            with self.assertRaises(self._ProcessDeath):
                module.allocate_secret_scan_capture(
                    root,
                    repository=repository,
                    phase="task3-secret-collision",
                    frontier_id=task["frontierId"],
                    _faults=module.DurabilityFaults(observe_reservation),
                )
            capture_id = predicted["captureId"]
            with mock.patch.object(
                module.secrets,
                "token_hex",
                side_effect=[capture_id, "d" * 32],
            ):
                collided = module.allocate_capture(
                    root,
                    "unrelated-collision",
                    frontier_id=task["frontierId"],
                )
            self.assertEqual(collided["captureId"], capture_id)
            before = self._ledger_snapshot(root)
            with self.assertRaises(module.AuditError):
                module.allocate_secret_scan_capture(
                    root,
                    repository=repository,
                    phase="task3-secret-collision",
                    frontier_id=task["frontierId"],
                )
            self.assertEqual(self._ledger_snapshot(root), before)

