    def test_generic_guard_is_basename_union_schema_and_final_byte_stable(self):
        cases = (
            ("secret-scan.json", b"not a canonical scan\n"),
            (
                "renamed.json",
                module.canonical_json_bytes(self._scan_record(0)),
            ),
        )
        for name, payload in cases:
            with self.subTest(name=name), tempfile.TemporaryDirectory() as temporary:
                base = Path(temporary)
                root = _new_run_root(base)
                module.init_run_state(
                    root, _identity_fields(base), bootstrap_imports=[]
                )
                capture = module.allocate_capture(root, "generic-guard")
                member = Path(capture["absolutePath"]) / name
                member.write_bytes(payload)
                os.chmod(member, 0o600)
                before_sequence = module.recover_run_state(root)["nextSequence"]
                with self.assertRaises(module.AuditError):
                    module.seal_capture(root, capture["captureId"], [name])
                self.assertEqual(
                    module.recover_run_state(root)["nextSequence"],
                    before_sequence,
                )
                self.assertFalse(
                    (Path(capture["absolutePath"]) / "manifest.json").exists()
                )

        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)
            root = _new_run_root(base)
            module.init_run_state(
                root, _identity_fields(base), bootstrap_imports=[]
            )
            blocked = module.frontier_start(
                root,
                frontier_kind="remote-mutation",
                input_digest="7" * 64,
                declared_paths=[],
                expected_tests=[],
            )
            capture = module.allocate_capture(
                root,
                "recovery-observation",
                read_only_recovery=True,
                blocked_frontier=blocked["frontierId"],
            )
            member = Path(capture["absolutePath"]) / "secret-scan.json"
            member.write_bytes(b"malformed historical scan\n")
            os.chmod(member, 0o600)
            before_sequence = module.recover_run_state(root)["nextSequence"]
            with self.assertRaises(module.AuditError):
                module.allocate_capture(
                    root,
                    "recovery-observation",
                    read_only_recovery=True,
                    blocked_frontier=blocked["frontierId"],
                    replace_incomplete_capture=capture["captureId"],
                )
            self.assertEqual(
                module.recover_run_state(root)["nextSequence"],
                before_sequence,
            )

        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)
            root = _new_run_root(base)
            module.init_run_state(
                root, _identity_fields(base), bootstrap_imports=[]
            )
            capture = module.allocate_capture(root, "stable-byte-guard")
            member = Path(capture["absolutePath"]) / "evidence.json"
            member.write_bytes(module.canonical_json_bytes({"safe": True}))
            os.chmod(member, 0o600)
            replacement = module.canonical_json_bytes(self._scan_record(0))
            original_read = module.LedgerTransaction.read_bytes_at
            observed_reads = 0

            def replace_after_classification(transaction, parent_fd, name, **kwargs):
                nonlocal observed_reads
                result = original_read(
                    transaction, parent_fd, name, **kwargs
                )
                if name == "evidence.json":
                    observed_reads += 1
                    if observed_reads == 1:
                        member.write_bytes(replacement)
                        os.chmod(member, 0o600)
                return result

            before_sequence = module.recover_run_state(root)["nextSequence"]
            with mock.patch.object(
                module.LedgerTransaction,
                "read_bytes_at",
                autospec=True,
                side_effect=replace_after_classification,
            ):
                with self.assertRaises(module.AuditError):
                    module.seal_capture(
                        root, capture["captureId"], ["evidence.json"]
                    )
            self.assertEqual(
                module.recover_run_state(root)["nextSequence"],
                before_sequence,
            )
            self.assertFalse(
                (Path(capture["absolutePath"]) / "manifest.json").exists()
            )

