    def test_allocated_scanner_classification_rejects_member_set_drift(self):
        for mutation in ("add-after-list", "rename-to-schema"):
            with self.subTest(mutation=mutation), tempfile.TemporaryDirectory() as temporary:
                base = Path(temporary)
                root = _new_run_root(base)
                module.init_run_state(
                    root, _identity_fields(base), bootstrap_imports=[]
                )
                phase = "allocated-member-drift"
                capture = module.allocate_capture(root, phase)
                capture_path = Path(capture["absolutePath"])
                evidence = capture_path / "evidence.json"
                evidence.write_bytes(
                    module.canonical_json_bytes({"safe": True})
                )
                os.chmod(evidence, 0o600)
                scanner_payload = module.canonical_json_bytes(
                    self._scan_record(0)
                )
                original_list = module.LedgerTransaction.list_directory
                original_read = module.LedgerTransaction.read_bytes_at
                classification_lists = 0
                mutated = False

                def drifting_list(transaction, descriptor, **kwargs):
                    nonlocal classification_lists, mutated
                    names = original_list(
                        transaction, descriptor, **kwargs
                    )
                    if (
                        transaction.operation_kind
                        == "generic-capture-secret-scan-classification"
                        and names == ["evidence.json"]
                    ):
                        classification_lists += 1
                        if (
                            mutation == "add-after-list"
                            and classification_lists == 2
                        ):
                            added = capture_path / "renamed.json"
                            added.write_bytes(scanner_payload)
                            os.chmod(added, 0o600)
                            mutated = True
                    return names

                def drifting_read(
                    transaction, descriptor, name, **kwargs
                ):
                    nonlocal mutated
                    result = original_read(
                        transaction, descriptor, name, **kwargs
                    )
                    if (
                        mutation == "rename-to-schema"
                        and not mutated
                        and transaction.operation_kind
                        == "generic-capture-secret-scan-classification"
                        and name == "evidence.json"
                    ):
                        evidence.unlink()
                        renamed = capture_path / "renamed.json"
                        renamed.write_bytes(scanner_payload)
                        os.chmod(renamed, 0o600)
                        mutated = True
                    return result

                before_records = {
                    path.name: path.read_bytes()
                    for path in sorted(
                        (root / "ledger" / "records").iterdir()
                    )
                }
                before_sequence = module.recover_run_state(root)[
                    "nextSequence"
                ]
                with mock.patch.object(
                    module.LedgerTransaction,
                    "list_directory",
                    autospec=True,
                    side_effect=drifting_list,
                ), mock.patch.object(
                    module.LedgerTransaction,
                    "read_bytes_at",
                    autospec=True,
                    side_effect=drifting_read,
                ):
                    with self.assertRaises(module.AuditError):
                        module.recover_capture_selection(
                            root, phase=phase, state="allocated"
                        )
                self.assertTrue(mutated)
                self.assertEqual(
                    {
                        path.name: path.read_bytes()
                        for path in sorted(
                            (root / "ledger" / "records").iterdir()
                        )
                    },
                    before_records,
                )
                self.assertEqual(
                    module.recover_run_state(root)["nextSequence"],
                    before_sequence,
                )

    def test_atomic_record_terminal_revalidation_closes_late_faults(self):
        boundaries = ("record-stage-source-fsync", "records-fsync")
        mutations = (
            "replace-final-inode", "recreate-source-name",
            "same-inode-bytes", "canonical-redigested-replacement",
        )
        for boundary in boundaries:
            for mutation in mutations:
                with self.subTest(boundary=boundary, mutation=mutation), tempfile.TemporaryDirectory() as temporary:
                    base = Path(temporary)
                    root = _new_run_root(base)
                    module.init_run_state(
                        root, _identity_fields(base), bootstrap_imports=[]
                    )
                    staged_name = None

                    def late_mutation(observed_boundary, _operation, subject):
                        nonlocal staged_name
                        if observed_boundary == "record-stage-parent-fsync":
                            stages = sorted(
                                (root / "tmp").glob(
                                    ".qinao-record-stage-*"
                                )
                            )
                            self.assertEqual(len(stages), 1)
                            staged_name = stages[0].name
                            return
                        if observed_boundary != boundary:
                            return
                        final = root / "ledger" / "records" / subject
                        payload = final.read_bytes()
                        if mutation == "replace-final-inode":
                            final.unlink()
                            final.write_bytes(payload)
                            os.chmod(final, 0o600)
                        elif mutation == "recreate-source-name":
                            self.assertIsNotNone(staged_name)
                            source = root / "tmp" / staged_name
                            source.write_bytes(payload)
                            os.chmod(source, 0o600)
                        elif mutation == "same-inode-bytes":
                            replacement = payload.replace(
                                b'"snapshotDigest":"b',
                                b'"snapshotDigest":"c',
                                1,
                            )
                            self.assertEqual(len(replacement), len(payload))
                            with final.open("r+b") as stream:
                                stream.write(replacement)
                                stream.truncate()
                        else:
                            replacement_record = json.loads(
                                payload.decode("utf-8")
                            )
                            replacement_record.pop("recordDigest")
                            replacement_record["snapshotDigest"] = "c" * 64
                            replacement = module.canonical_json_bytes(
                                module._self_digest_record(
                                    replacement_record
                                )
                            )
                            self.assertEqual(len(replacement), len(payload))
                            with final.open("r+b") as stream:
                                stream.write(replacement)
                                stream.truncate()

                    with module.LedgerTransaction(
                        root,
                        operation_kind="secret-scan-capture-allocation",
                        faults=module.DurabilityFaults(late_mutation),
                    ) as transaction:
                        recovered = transaction.recover()
                        record = module._new_record(
                            recovered["identity"],
                            recovered["nextSequence"],
                            recovered["records"][-1]["recordDigest"],
                            "git-state-snapshot",
                            "1" * 64,
                            [],
                            "complete",
                            {
                                "frontierId": "a" * 32,
                                "snapshotDigest": "b" * 64,
                                "fields": {},
                            },
                        )
                        with self.assertRaises(module.AuditError):
                            transaction.write_record_atomic(
                                recovered["nextSequence"], record
                            )

