    def test_concurrent_exact_retry_dispatches_scanner_once(self):
        """Break caught: concurrent exact retry can dispatch two scans."""

        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._capture_fixture(Path(temporary))
            first_start, first_context = self._append_outer_context(fixture)
            second_start, second_context = self._append_outer_context(fixture)
            original = module.secret_scan_worktree_selection
            entered = threading.Event()
            release = threading.Event()
            count_lock = threading.Lock()
            dispatch_count = [0]
            results = []
            errors = []

            def scanner(*args, **kwargs):
                with count_lock:
                    dispatch_count[0] += 1
                entered.set()
                if not release.wait(5):
                    raise AssertionError("concurrent scan release timed out")
                return original(*args, **kwargs)

            def run(context):
                try:
                    results.append(module.execute_secret_scan_worktree(
                        fixture["root"],
                        repository=fixture["repository"],
                        phase="task3-secret-start-unit",
                        frontier_id=fixture["task"]["frontierId"],
                        context=context,
                    ))
                except BaseException as exc:
                    errors.append(exc)

            with mock.patch.object(
                module, "secret_scan_worktree_selection", scanner
            ):
                first = threading.Thread(
                    target=run, args=(first_context,), daemon=True
                )
                second = threading.Thread(
                    target=run, args=(second_context,), daemon=True
                )
                first.start()
                self.assertTrue(entered.wait(5))
                second.start()
                release.set()
                first.join(10)
                second.join(10)
            self.assertFalse(first.is_alive() or second.is_alive())
            self.assertEqual(errors, [])
            self.assertEqual(dispatch_count, [1])
            self.assertEqual(len(results), 2)
            self.assertEqual(results[0], results[1])
            records = module.recover_run_state(fixture["root"])["records"]
            self.assertEqual(sum(
                row.get("operationKind")
                == "secret-scan-invocation-started" for row in records
            ), 1)
            self.assertEqual(sum(
                row.get("operationKind") == "secret-scan-terminal"
                for row in records
            ), 1)
            invocations = module.recover_run_state(fixture["root"])[
                "sterileInvocations"
            ]
            self.assertEqual(
                invocations[first_start["recordDigest"]]["state"],
                "complete",
            )
            self.assertEqual(
                invocations[second_start["recordDigest"]]["state"], "open"
            )

