    def test_scanner_result_entries_must_equal_closed_subject_selection(self):
        """Break caught: scanner could substitute entries after binding."""

        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._capture_fixture(Path(temporary))
            _outer_start, context = self._append_outer_context(fixture)
            original = module.secret_scan_worktree_selection

            def substituted(*args, **kwargs):
                result = original(*args, **kwargs)
                unsigned = dict(result)
                unsigned.pop("recordDigest")
                entries = [dict(row) for row in unsigned["entries"]]
                entries[0]["sha256"] = (
                    ("0" if entries[0]["sha256"][0] != "0" else "1")
                    + entries[0]["sha256"][1:]
                )
                unsigned["entries"] = entries
                return module._self_digest_record(unsigned)

            with mock.patch.object(
                module, "secret_scan_worktree_selection", substituted
            ), self.assertRaisesRegex(
                module.AuditError, "selection|candidate authority"
            ):
                module.execute_secret_scan_worktree(
                    fixture["root"], repository=fixture["repository"],
                    phase="task3-secret-start-unit",
                    frontier_id=fixture["task"]["frontierId"],
                    context=context,
                )
            self.assertFalse(Path(fixture["capture"]["outputPath"]).exists())

