    def test_exact_retry_selects_terminal_before_actual_emit_failure(self):
        """A retry must persist its chosen old terminal before output."""

        for outcome, expected_exit in (
            ("clean", 0), ("findings", 1), ("indeterminate", 2),
        ):
            with self.subTest(outcome=outcome), \
                    tempfile.TemporaryDirectory() as temporary:
                prepare = None
                declared = ()
                if outcome == "findings":
                    def prepare(repository):
                        (repository / "dirty.txt").write_bytes(
                            b"AKIA" + b"A" * 16 + b"\n"
                        )
                    declared = ("dirty.txt",)
                fixture = self._capture_fixture(
                    Path(temporary), declared_paths=declared,
                    prepare_repository=prepare,
                )
                outer_argv = [
                    "--root", str(fixture["root"]),
                    "--repository", str(fixture["repository"]),
                    "--profile", "ledger", "--", *fixture["argv"],
                ]
                environment = {
                    "HOME": str(fixture["root"] / "home"),
                    "TMPDIR": str(fixture["root"] / "tmp"),
                }
                stdout = mock.Mock(buffer=io.BytesIO())
                if outcome == "indeterminate":
                    owner_start, owner_context = (
                        self._append_outer_context(fixture)
                    )
                    module.start_secret_scan_invocation(
                        fixture["root"],
                        capture_id=fixture["capture"]["captureId"],
                        context=owner_context,
                    )
                    recovery_start, recovery_context = (
                        self._append_outer_context(fixture)
                    )
                    with mock.patch.object(
                        module, "secret_scan_worktree_selection",
                        side_effect=AssertionError("scanner replayed"),
                    ):
                        terminal = module.execute_secret_scan_worktree(
                            fixture["root"],
                            repository=fixture["repository"],
                            phase="task3-secret-start-unit",
                            frontier_id=fixture["task"]["frontierId"],
                            context=recovery_context,
                        )
                    self.assertEqual(
                        terminal["completionState"],
                        "secret-scan-indeterminate-no-replay",
                    )
                    module._append_linked_sterile_invocation_completion(
                        fixture["root"], recovery_start, exit_code=2
                    )
                    recovered_owner = module.recover_run_state(
                        fixture["root"]
                    )["sterileInvocations"][owner_start["recordDigest"]]
                    self.assertEqual(
                        recovered_owner["completion"]["exitCode"], 2
                    )
                else:
                    with mock.patch.object(
                        module.sys, "stdout", stdout
                    ), mock.patch.dict(module.os.environ, environment):
                        self.assertEqual(
                            module._sterile_python(outer_argv),
                            expected_exit,
                        )

                before = module.recover_run_state(fixture["root"])
                terminal = before["captures"][
                    fixture["capture"]["captureId"]
                ]["terminal"]
                terminal_path = (
                    fixture["root"] / "ledger" / "records"
                    / ("%016d.json" % terminal["sequence"])
                )
                terminal_bytes = terminal_path.read_bytes()
                before_starts = set(before["sterileInvocations"])
                before_terminal_count = sum(
                    record["operationKind"] == "secret-scan-terminal"
                    for record in before["records"]
                )

                with mock.patch.object(
                    module, "_emit_canonical",
                    side_effect=BrokenPipeError(
                        "actual emit failed after terminal selection"
                    ),
                ), mock.patch.object(
                    module, "secret_scan_worktree_selection",
                    side_effect=AssertionError("scanner replayed"),
                ), mock.patch.dict(module.os.environ, environment):
                    self.assertEqual(
                        module._sterile_python(outer_argv), expected_exit
                    )

                after = module.recover_run_state(fixture["root"])
                new_starts = (
                    set(after["sterileInvocations"]) - before_starts
                )
                self.assertEqual(len(new_starts), 1)
                retry = after["sterileInvocations"][new_starts.pop()]
                self.assertEqual(retry["completion"]["exitCode"],
                                 expected_exit)
                self.assertEqual(
                    retry["selectedTerminal"]["terminalRecordDigest"],
                    terminal["recordDigest"],
                )
                self.assertLess(
                    retry["selectedTerminal"]["sequence"],
                    retry["completion"]["sequence"],
                )
                self.assertEqual(terminal_path.read_bytes(), terminal_bytes)
                self.assertEqual(
                    sum(
                        record["operationKind"] == "secret-scan-terminal"
                        for record in after["records"]
                    ),
                    before_terminal_count,
                )

