    def test_deleted_and_renamed_dirty_paths_scan_without_missing_source(self):
        """Break caught: dirty deletion made allocation open an absent file."""

        for mutation in ("delete", "rename"):
            with self.subTest(mutation=mutation), \
                    tempfile.TemporaryDirectory() as temporary:
                repository = self._committed_repository(Path(temporary))
                old = repository / "tracked.txt"
                declared = ["tracked.txt"]
                if mutation == "rename":
                    declared.append("renamed.txt")
                root, task = self._root_and_task(
                    Path(temporary), repository,
                    declared_paths=tuple(declared),
                )
                old.unlink()
                if mutation == "rename":
                    (repository / "renamed.txt").write_bytes(b"renamed worktree bytes\n")
                phase = "task3-secret-dirty-" + mutation
                argv = [
                    "secret-scan-worktree", "--root", str(root),
                    "--repository", str(repository), "--phase", phase,
                    "--frontier-id", task["frontierId"],
                ]
                fixture = {
                    "root": root, "repository": repository,
                    "task": task, "argv": argv,
                }
                _outer_start, context = self._append_outer_context(fixture)
                terminal = module.execute_secret_scan_worktree(
                    root, repository=repository, phase=phase,
                    frontier_id=task["frontierId"], context=context,
                )
                self.assertEqual(terminal["completionState"],
                                 "secret-scan-clean")
                sources = [
                    (row["source"], row["pathB64"])
                    for row in terminal["result"]["entries"]
                ]
                self.assertIn((
                    "index",
                    base64.b64encode(b"tracked.txt").decode("ascii"),
                ), sources)
                if mutation == "rename":
                    self.assertIn((
                        "worktree",
                        base64.b64encode(b"renamed.txt").decode("ascii"),
                    ), sources)

