    def test_cold_flags_only_authority_drift_preserves_history_and_blocks_retry(self):
        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._capture_fixture(Path(temporary))
            outer_start, old_context = self._append_outer_context(fixture)
            started = module.start_secret_scan_invocation(
                fixture["root"],
                capture_id=fixture["capture"]["captureId"],
                context=old_context,
            )
            projection_a = started["execution"]["ruleProjection"]
            legacy_digest = started["execution"]["ruleSetDigest"]
            before_bytes = self._ledger_snapshot(fixture["root"])
            before_sequence = module.recover_run_state(fixture["root"])[
                "nextSequence"
            ]

            cold = self._activate_repository_module(fixture["repository"])
            rules = list(cold.SECRET_RULES)
            rule_id, expression = rules[0]
            new_flags = expression.flags ^ int(cold.re.MULTILINE)
            self.assertNotEqual(new_flags, expression.flags)
            rules[0] = (
                rule_id,
                cold.re.compile(expression.pattern, new_flags),
            )
            cold.SECRET_RULES = tuple(rules)
            authority_b = cold._secret_rule_set_authority()
            projection_b = authority_b["ruleProjection"]
            self.assertEqual(authority_b["ruleSetDigest"], legacy_digest)
            self.assertNotEqual(projection_b, projection_a)
            self.assertEqual(
                projection_b[0]["effectiveFlags"], new_flags
            )
            self.assertEqual(
                {
                    key: value for key, value in projection_b[0].items()
                    if key != "effectiveFlags"
                },
                {
                    key: value for key, value in projection_a[0].items()
                    if key != "effectiveFlags"
                },
            )

            with mock.patch.object(
                cold,
                "_SECRET_RULE_PROJECTION_BYTES",
                cold.canonical_json_bytes(projection_b),
            ):
                self.assertEqual(
                    cold._current_secret_rule_set_authority(), authority_b
                )
                recovered = cold.recover_run_state(fixture["root"])
                self.assertEqual(recovered["classification"], "complete")
                projected = recovered["captures"][
                    fixture["capture"]["captureId"]
                ]
                self.assertEqual(projected["state"], "secret-scan-running")
                self.assertEqual(projected["invocationStart"], started)
                self.assertEqual(
                    projected["reservation"]["binding"]["ruleProjection"],
                    projection_a,
                )
                self.assertEqual(
                    projected["invocationStart"]["execution"][
                        "ruleProjection"
                    ],
                    projection_a,
                )

                retry_context = (
                    cold.CommandContext().with_sterile_invocation_start(
                        outer_start
                    )
                )
                with self.assertRaisesRegex(
                    cold.AuditError,
                    "secret scan authoritative identity drift",
                ):
                    cold.start_secret_scan_invocation(
                        fixture["root"],
                        capture_id=fixture["capture"]["captureId"],
                        context=retry_context,
                    )
                after = cold.recover_run_state(fixture["root"])
                self.assertEqual(after["classification"], "complete")
                self.assertEqual(after["nextSequence"], before_sequence)
                after_capture = after["captures"][
                    fixture["capture"]["captureId"]
                ]
                self.assertEqual(
                    after_capture["state"], "secret-scan-running"
                )
                self.assertEqual(after_capture["invocationStart"], started)
                self.assertFalse(
                    Path(fixture["capture"]["outputPath"]).exists()
                )
                self.assertEqual(
                    self._ledger_snapshot(fixture["root"]), before_bytes
                )

    def test_running_exact_retry_rejects_live_subject_drift_without_append(self):
        for mutation in (
            "index", "declared-dirty", "module-mode", "module-bytes",
        ):
            with self.subTest(mutation=mutation), \
                    tempfile.TemporaryDirectory() as temporary:
                prepare_repository = None
                declared_paths = ()
                if mutation == "declared-dirty":
                    def prepare_repository(repository):
                        (repository / "dirty.txt").write_bytes(
                            b"declared dirty bytes before running\n"
                        )

                    declared_paths = ("dirty.txt",)
                fixture = self._capture_fixture(
                    Path(temporary),
                    declared_paths=declared_paths,
                    prepare_repository=prepare_repository,
                )
                _outer_start, context = self._append_outer_context(fixture)
                started = module.start_secret_scan_invocation(
                    fixture["root"],
                    capture_id=fixture["capture"]["captureId"],
                    context=context,
                )
                before_bytes = self._ledger_snapshot(fixture["root"])
                before_sequence = module.recover_run_state(
                    fixture["root"]
                )["nextSequence"]

                if mutation == "index":
                    (fixture["repository"] / "tracked.txt").write_bytes(
                        b"changed staged bytes after running\n"
                    )
                    module._run_git(
                        fixture["repository"],
                        ["add", "--", "tracked.txt"],
                    )
                elif mutation == "declared-dirty":
                    (fixture["repository"] / "dirty.txt").write_bytes(
                        b"changed declared dirty bytes after running\n"
                    )
                else:
                    scanner = (
                        fixture["repository"] / "scripts"
                        / "qinao_convergence_audit.py"
                    )
                    if mutation == "module-mode":
                        original_mode = stat.S_IMODE(scanner.stat().st_mode)
                        os.chmod(scanner, original_mode ^ 0o040)
                        self.assertNotEqual(
                            stat.S_IMODE(scanner.stat().st_mode),
                            original_mode,
                        )
                    else:
                        scanner.write_bytes(
                            scanner.read_bytes()
                            + b"\n# cold module byte drift fixture\n"
                        )

                historical = module.recover_run_state(fixture["root"])
                self.assertEqual(historical["classification"], "complete")
                self.assertEqual(
                    historical["captures"][
                        fixture["capture"]["captureId"]
                    ]["invocationStart"],
                    started,
                )
                with self.assertRaises(module.AuditError):
                    module.start_secret_scan_invocation(
                        fixture["root"],
                        capture_id=fixture["capture"]["captureId"],
                        context=context,
                    )

                after = module.recover_run_state(fixture["root"])
                self.assertEqual(after["classification"], "complete")
                self.assertEqual(after["nextSequence"], before_sequence)
                self.assertEqual(
                    after["captures"][fixture["capture"]["captureId"]][
                        "invocationStart"
                    ],
                    started,
                )
                self.assertFalse(
                    Path(fixture["capture"]["outputPath"]).exists()
                )
                self.assertEqual(
                    self._ledger_snapshot(fixture["root"]), before_bytes
                )

