    def test_persisted_rule_projection_values_and_digest_are_closed(self):
        authority = module._secret_rule_set_authority()
        for mutation in (
            "rule-id", "negative-flags", "unknown-flags",
            "template-flags", "locale-flags", "debug-flags",
        ):
            with self.subTest(mutation=mutation):
                projection = [dict(row) for row in authority["ruleProjection"]]
                if mutation == "rule-id":
                    projection[0]["ruleId"] = "Invalid_Rule"
                elif mutation == "negative-flags":
                    projection[0]["effectiveFlags"] = -1
                elif mutation == "unknown-flags":
                    projection[0]["effectiveFlags"] = 1 << 20
                elif mutation == "template-flags":
                    projection[0]["effectiveFlags"] |= 0x001
                elif mutation == "locale-flags":
                    projection[0]["effectiveFlags"] |= 0x004
                else:
                    projection[0]["effectiveFlags"] |= 0x080
                with self.assertRaises(module.AuditError):
                    module._validate_secret_rule_projection(projection)

        drifted = [dict(row) for row in authority["ruleProjection"]]
        drifted[0]["effectiveFlags"] ^= int(module.re.MULTILINE)
        self.assertNotEqual(drifted, authority["ruleProjection"])
        module._validate_persisted_secret_rule_authority({
            "ruleSetVersion": authority["ruleSetVersion"],
            "ruleSetDigest": authority["ruleSetDigest"],
            "ruleProjection": drifted,
        })

    def test_live_rule_authority_rejects_forbidden_flags_silently(self):
        original_rules = module.SECRET_RULES
        try:
            for flag in (0x001, 0x004, 0x080):
                with self.subTest(flag=int(flag)):
                    construction_output = io.StringIO()
                    try:
                        with contextlib.redirect_stdout(construction_output):
                            expression = module.re.compile(rb"probe", flag)
                    except (module.re.error, TypeError, ValueError):
                        continue
                    module.SECRET_RULES = (("probe", expression),)
                    authority_output = io.StringIO()
                    with contextlib.redirect_stdout(authority_output):
                        with self.assertRaises(module.AuditError):
                            module._secret_rule_set_authority()
                    self.assertEqual(authority_output.getvalue(), "")
        finally:
            module.SECRET_RULES = original_rules

