    def test_typed_start_rechecks_subject_and_rules_before_atomic_publish(self):
        boundaries = ("record-stage-fsync", "record-stage-parent-fsync")
        mutations = ("index", "dirty", "module", "rules")
        for boundary in boundaries:
            for mutation in mutations:
                with self.subTest(
                    boundary=boundary, mutation=mutation
                ), tempfile.TemporaryDirectory() as temporary:
                    fixture = self._capture_fixture(
                        Path(temporary), declared_paths=("dirty.txt",)
                    )
                    _outer, context = self._append_outer_context(fixture)
                    before = module.recover_run_state(fixture["root"])
                    module_path = (
                        fixture["repository"]
                        / "scripts" / "qinao_convergence_audit.py"
                    )
                    original_mode = _mode(module_path)
                    original_rule_digest = module.RULE_SET_DIGEST
                    changed = False

                    def mutate(observed, operation, _subject):
                        nonlocal changed
                        if observed != boundary or changed:
                            return
                        self.assertEqual(
                            operation, "secret-scan-invocation-start"
                        )
                        changed = True
                        if mutation == "index":
                            (
                                fixture["repository"] / "tracked.txt"
                            ).write_bytes(b"staged drift\n")
                            module._run_git(
                                fixture["repository"],
                                ["add", "--", "tracked.txt"],
                            )
                        elif mutation == "dirty":
                            (
                                fixture["repository"] / "dirty.txt"
                            ).write_bytes(b"dirty drift\n")
                        elif mutation == "module":
                            drift_mode = original_mode ^ 0o040
                            os.chmod(module_path, drift_mode)
                            observed_mode = _mode(module_path)
                            self.assertEqual(observed_mode, drift_mode)
                            self.assertNotEqual(observed_mode, original_mode)
                        else:
                            module.RULE_SET_DIGEST = "f" * 64

                    try:
                        with self.assertRaises(module.AuditError):
                            module.start_secret_scan_invocation(
                                fixture["root"],
                                capture_id=
                                    fixture["capture"]["captureId"],
                                context=context,
                                _faults=module.DurabilityFaults(mutate),
                            )
                    finally:
                        os.chmod(module_path, original_mode)
                        module.RULE_SET_DIGEST = original_rule_digest
                    self.assertTrue(changed)
                    after = module.recover_run_state(fixture["root"])
                    self.assertEqual(after["nextSequence"],
                                     before["nextSequence"])
                    self.assertEqual(after["records"], before["records"])
                    self.assertEqual(
                        after["captures"][
                            fixture["capture"]["captureId"]
                        ]["state"],
                        "secret-scan-materialized",
                    )

    def test_typed_start_rejects_actual_rule_drift_before_publish(self):
        boundaries = ("record-stage-fsync", "record-stage-parent-fsync")
        mutations = ("pattern", "flags", "rule-id", "order")
        for boundary in boundaries:
            for mutation in mutations:
                with self.subTest(
                    boundary=boundary, mutation=mutation
                ), tempfile.TemporaryDirectory() as temporary:
                    fixture = self._capture_fixture(Path(temporary))
                    _outer, context = self._append_outer_context(fixture)
                    before = module.recover_run_state(fixture["root"])
                    original_rules = module.SECRET_RULES
                    original_digest = module.RULE_SET_DIGEST
                    changed = False

                    def mutate(observed, operation, _subject):
                        nonlocal changed
                        if observed != boundary or changed:
                            return
                        self.assertEqual(
                            operation, "secret-scan-invocation-start"
                        )
                        self.assertEqual(
                            module.RULE_SET_DIGEST, original_digest
                        )
                        changed = True
                        rules = list(original_rules)
                        rule_id, regex = rules[0]
                        if mutation == "pattern":
                            rules[0] = (
                                rule_id,
                                module.re.compile(
                                    b"(?:)" + regex.pattern,
                                    regex.flags,
                                ),
                            )
                        elif mutation == "flags":
                            rules[0] = (
                                rule_id,
                                module.re.compile(
                                    regex.pattern,
                                    regex.flags | module.re.MULTILINE,
                                ),
                            )
                        elif mutation == "rule-id":
                            rules[0] = (rule_id + "-drift", regex)
                        else:
                            rules[0], rules[1] = rules[1], rules[0]
                        module.SECRET_RULES = tuple(rules)
                        self.assertEqual(
                            len(module.SECRET_RULES), len(original_rules)
                        )

                    try:
                        with self.assertRaises(module.AuditError):
                            module.start_secret_scan_invocation(
                                fixture["root"],
                                capture_id=
                                    fixture["capture"]["captureId"],
                                context=context,
                                _faults=module.DurabilityFaults(mutate),
                            )
                    finally:
                        module.SECRET_RULES = original_rules
                    self.assertTrue(changed)
                    self.assertEqual(
                        module.RULE_SET_DIGEST, original_digest
                    )
                    after = module.recover_run_state(fixture["root"])
                    self.assertEqual(after["nextSequence"],
                                     before["nextSequence"])
                    self.assertEqual(after["records"], before["records"])
                    self.assertEqual(
                        after["captures"][
                            fixture["capture"]["captureId"]
                        ]["state"],
                        "secret-scan-materialized",
                    )

    def test_typed_start_atomic_fault_retry_converges_to_one_running_record(self):
        boundaries = (
            "record-stage-fsync", "record-stage-parent-fsync",
            "record-atomic-publish", "record-stage-source-fsync",
            "records-fsync", "unlock", "close",
        )
        pre_publish = {
            "record-stage-fsync", "record-stage-parent-fsync",
        }
        for boundary in boundaries:
            with self.subTest(
                boundary=boundary
            ), tempfile.TemporaryDirectory() as temporary:
                fixture = self._capture_fixture(Path(temporary))
                _outer, context = self._append_outer_context(fixture)
                before = module.recover_run_state(fixture["root"])
                fired = False

                def disappear(observed, operation, _subject=None):
                    nonlocal fired
                    if observed != boundary or fired:
                        return
                    self.assertEqual(
                        operation, "secret-scan-invocation-start"
                    )
                    fired = True
                    raise self._ProcessDeath("simulated lost return")

                with self.assertRaises(self._ProcessDeath):
                    module.start_secret_scan_invocation(
                        fixture["root"],
                        capture_id=fixture["capture"]["captureId"],
                        context=context,
                        _faults=module.DurabilityFaults(disappear),
                    )
                self.assertTrue(fired)
                recovered = module.recover_run_state(fixture["root"])
                expected_state = (
                    "secret-scan-materialized"
                    if boundary in pre_publish
                    else "secret-scan-running"
                )
                self.assertEqual(
                    recovered["captures"][
                        fixture["capture"]["captureId"]
                    ]["state"],
                    expected_state,
                )
                self.assertEqual(
                    recovered["nextSequence"],
                    before["nextSequence"]
                    + (0 if boundary in pre_publish else 1),
                )
                record = module.start_secret_scan_invocation(
                    fixture["root"],
                    capture_id=fixture["capture"]["captureId"],
                    context=context,
                )
                final = module.recover_run_state(fixture["root"])
                starts = [
                    row for row in final["records"]
                    if row.get("operationKind")
                    == "secret-scan-invocation-started"
                ]
                self.assertEqual(starts, [record])
                self.assertEqual(
                    final["captures"][
                        fixture["capture"]["captureId"]
                    ]["state"],
                    "secret-scan-running",
                )
                self.assertFalse(
                    Path(fixture["capture"]["outputPath"]).exists()
                )

