class SterileInvocationLinkageSliceTests(_ModuleRequired):
    @staticmethod
    def _initialized_root(base):
        root = _new_run_root(base)
        module.init_run_state(
            root, _identity_fields(base), bootstrap_imports=[]
        )
        return root

    @staticmethod
    def _invocation():
        return module._self_digest_record(
            {
                "schemaVersion": "qinao.sterile-invocation.v1",
                "profile": "ledger",
                "argv": ["snapshot-git-state"],
                "repository": "/fixture/repository",
                "runtime": {"python": "fixture"},
                "flags": {
                    "isolated": 1,
                    "ignoreEnvironment": 1,
                    "noSite": 1,
                    "noUserSite": 1,
                    "dontWriteBytecode": 1,
                },
                "sysPath": [],
                "importInventory": {"candidateFileCount": 0},
            }
        )

    @staticmethod
    def _append_fixture_chain(root, rows):
        with module.LedgerTransaction(
            root, operation_kind="sterile-linkage-test-fixture"
        ) as transaction:
            recovered = transaction.recover()
            predecessor = recovered["records"][-1]
            appended = []
            for row in rows:
                input_digest = row["inputDigest"]
                payload = dict(row["payload"])
                if input_digest is None:
                    input_digest = predecessor["recordDigest"]
                for field, value in tuple(payload.items()):
                    if value is None:
                        payload[field] = predecessor["recordDigest"]
                record = transaction.append_record(
                    recovered,
                    row["operationKind"],
                    input_digest,
                    [],
                    row["completionState"],
                    payload,
                    predecessor=predecessor,
                )
                appended.append(record)
                predecessor = record
            return appended

    def test_command_context_binds_the_exact_outer_start_record(self):
        invocation = self._invocation()
        start = module._new_record(
            {"runId": "1" * 32},
            7,
            "2" * 64,
            "sterile-invocation-started-linked",
            invocation["recordDigest"],
            [],
            "open",
            {"invocation": invocation},
        )
        bound = module.CommandContext().with_sterile_invocation_start(
            start
        )

        self.assertEqual(
            bound.sterile_invocation_start["recordDigest"],
            start["recordDigest"],
        )
        self.assertEqual(
            bound.sterile_invocation_start["recordId"],
            start["recordId"],
        )
        self.assertEqual(
            bound.sterile_invocation_start["sequence"],
            start["sequence"],
        )
        self.assertEqual(
            bound.sterile_invocation["recordDigest"],
            invocation["recordDigest"],
        )
        with self.assertRaises(TypeError):
            bound.sterile_invocation_start["recordDigest"] = "0" * 64
        escaped = bound.sterile_invocation_start
        escaped["invocation"]["argv"].append("authority-drift")
        self.assertEqual(
            bound.sterile_invocation["argv"],
            ["snapshot-git-state"],
        )
