        self.assertNotEqual(module._task_test_proof_key({
            **subject, "outputContractDigest": "0" * 64,
        }), expected)
        self.assertNotEqual(module._task_test_proof_key({
            **subject, "schemaVersion": "qinao.task-test-subject.v4",
        }), expected)

