    @staticmethod
    def _invocation(repository, argv):
        return module._self_digest_record({
            "schemaVersion": "qinao.sterile-invocation.v1",
            "profile": "ledger",
            "argv": list(argv),
            "repository": str(repository),
            "runtime": {"runtime": "typed-test-fixture"},
            "flags": {
                "isolated": 1,
                "ignoreEnvironment": 1,
                "noSite": 1,
                "noUserSite": 1,
                "dontWriteBytecode": 1,
            },
            "sysPath": [],
            "importInventory": {"candidateFileCount": 0},
        })

    def _append_outer(self, root, repository, argv):
        invocation = self._invocation(repository, argv)
        start = module._append_record(
            root,
            "sterile-invocation-started-linked",
            invocation["recordDigest"],
            [],
            "open",
            {"invocation": invocation},
            atomic_publication=True,
        )
        return (
            start,
            module.CommandContext().with_sterile_invocation_start(start),
        )

    def _crash_after_durable_task_test_start(self, fixture):
        old_outer, old_context = self._append_outer(
            fixture["root"], fixture["repository"], fixture["argv"]
        )
        with mock.patch.object(
            module,
            "_run_task_test_targets",
            side_effect=self._ProcessDeath("after durable start"),
            create=True,
        ):
            with self.assertRaises(self._ProcessDeath):
                module._dispatch_command(
                    fixture["argv"], context=old_context
                )
        recovered = module.recover_run_state(fixture["root"])
        running = [
            value
            for value in recovered["taskTestAttempts"].values()
            if value.get("state") == "task-tests-running"
        ]
        self.assertEqual(len(running), 1)
        old_start = running[0]["start"]
        leases = [
            value
            for value in recovered["taskTestExecutionLeases"].values()
            if value.get("acquired", {}).get("recordDigest")
            == old_start["executionLeaseAcquiredRecordDigest"]
        ]
        self.assertEqual(len(leases), 1)
        old_lease = leases[0]
        self.assertIn(old_lease["state"], ("owner-lost", "owner-unwound"))
        self.assertIsInstance(old_lease.get("terminal"), dict)
        builtins.__dict__.pop(self._IMPORT_WITNESS_KEY, None)
        return {
            "outer": old_outer,
            "start": old_start,
            "leaseAcquired": old_lease["acquired"],
            "leaseTerminal": old_lease["terminal"],
        }

    def _fixture(
        self, base, *, drifting=False, variant="success", staged_change=False,
        task_number=3,
    ):
        builtins.__dict__.pop(self._IMPORT_WITNESS_KEY, None)
        builtins.__dict__.pop(self._PROTOCOL_WITNESS_KEY, None)
        self.addCleanup(
            builtins.__dict__.pop,
            self._IMPORT_WITNESS_KEY,
            None,
        )
        self.addCleanup(
            builtins.__dict__.pop,
            self._PROTOCOL_WITNESS_KEY,
            None,
        )
        builtins.__dict__.pop(self._CAPTURE_WITNESS_KEY, None)
        self.addCleanup(
            builtins.__dict__.pop, self._CAPTURE_WITNESS_KEY, None
        )
        if variant == "success":
            repository = self._repository_with_test_classes(
                base, drifting=drifting
            )
        elif variant == "outcomes" and not drifting:
            repository = self._repository_with_outcome_test_classes(base)
        elif variant == "subtest-skips" and not drifting:
            repository = self._repository_with_subtest_skip_classes(base)
        elif variant in (
            "subtest-impostor", "subtest-success-conflict"
        ) and not drifting:
            repository = (
                self._repository_with_subtest_callback_protocol_classes(
                    base, variant=variant
                )
            )
        elif variant == "protocol" and not drifting:
            repository = self._repository_with_protocol_test_classes(base)
        elif variant == "capture-integration" and not drifting:
            repository = self._repository_with_capture_integration_classes(base)
        elif variant == "fd-fault-gate" and not drifting:
            repository = self._repository_with_fd_fault_gate_classes(base)
        elif variant.startswith("lifecycle-") and not drifting:
            repository = self._repository_with_lifecycle_drift_classes(
                base, variant=variant[len("lifecycle-"):]
            )
        elif variant == "decorator-skips" and not drifting:
            repository = self._repository_with_decorator_skip_classes(base)
        elif variant.startswith("frozen-method-") and not drifting:
            repository = self._repository_with_frozen_method_attack_classes(
                base, variant=variant[len("frozen-method-"):]
            )
        elif variant.startswith("executable-mutation-") and not drifting:
            repository = self._repository_with_executable_mutation_classes(
                base, variant=variant[len("executable-mutation-"):]
            )
        elif variant.startswith("r15-") and not drifting:
            repository = self._repository_with_r15_provenance_classes(
                base, variant=variant[len("r15-"):]
            )
        else:
            raise AssertionError("unknown typed-test fixture variant")
        root = _new_run_root(base)
        module.init_run_state(
            root, _identity_fields(repository), bootstrap_imports=[]
        )
        targets = list(self._TASK_TARGETS)
        task = module.frontier_start(
            root,
            frontier_kind="task",
            input_digest="8" * 64,
            declared_paths=["tracked.txt"] if staged_change else [],
            expected_tests=targets,
            task_number=task_number,
        )
        if staged_change:
            (repository / "tracked.txt").write_bytes(
                b"changed task result safe payload\n"
            )
            module._run_git(repository, ["add", "--", "tracked.txt"])
        scan_argv = [
            "secret-scan-worktree", "--root", str(root),
            "--repository", str(repository), "--phase",
            "task-test-evidence-prerequisite", "--frontier-id",
            task["frontierId"],
        ]
        scan_outer, scan_context = self._append_outer(
            root, repository, scan_argv
        )
        scan_terminal = module.execute_secret_scan_worktree(
            root,
            repository=repository,
            phase="task-test-evidence-prerequisite",
            frontier_id=task["frontierId"],
            context=scan_context,
        )
        module._select_secret_scan_terminal_for_outer(
            root, scan_terminal, scan_context
        )
        module._append_linked_sterile_invocation_completion(
            root, scan_outer, exit_code=0
        )
        argv = [
            "task-test-run", "--root", str(root),
            "--repository", str(repository),
        ]
        for target in targets:
            argv.extend(["--target", target])
        return {
            "root": root,
            "repository": repository,
            "task": task,
            "targets": targets,
            "argv": argv,
            "scanTerminal": scan_terminal,
        }

    def test_precommit_scanned_index_reaches_real_postcommit_typed_tests(self):
        """Break caught: one precommit scan cannot authorize its result tree."""

        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._fixture(Path(temporary), staged_change=True)
            repository = fixture["repository"]
            baseline = module._run_git(repository, ["rev-parse", "HEAD"])
            scanned_tree = module._run_git(repository, ["write-tree"])
            module._run_git(repository, [
                "-c", "user.name=Qinao Test",
                "-c", "user.email=qinao-test@invalid.local",
                "commit", "--quiet", "-m", "one changed task result",
            ])
            result = module._run_git(repository, ["rev-parse", "HEAD"])
            self.assertNotEqual(result, baseline)
            self.assertEqual(
                module._run_git(repository, ["rev-parse", "HEAD^"]),
                baseline,
            )
            self.assertEqual(
                module._run_git(repository, ["rev-parse", "HEAD^{tree}"]),
                scanned_tree,
            )
            self.assertEqual(module._run_git(repository, [
                "status", "--porcelain=v2", "-z", "--untracked-files=all"
            ]), b"")
            outer, context = self._append_outer(
                fixture["root"], repository, fixture["argv"]
            )
            try:
                exit_code = module._dispatch_command(
                    fixture["argv"], context=context
                )
            except module.AuditError as error:
                self.fail("real precommit/result transition rejected: " + str(error))
            self.assertEqual(exit_code, 0)
            completion_argv = [
                "frontier-complete", "--root", str(fixture["root"]),
                "--frontier-id", fixture["task"]["frontierId"],
                "--input-digest", fixture["task"]["inputDigest"],
                "--declared-path", "tracked.txt", "--outcome", "completed",
                "--result-commit", result.decode("ascii").strip(),
            ]
            with self.assertRaises(module.AuditError):
                module._dispatch_command(completion_argv)
            module._append_linked_sterile_invocation_completion(
                fixture["root"], outer, exit_code=exit_code
            )
            recovered = module.recover_run_state(fixture["root"])
            attempts = list(recovered["taskTestAttempts"].values())
            self.assertEqual(len(attempts), 1)
            self.assertEqual(attempts[0]["state"], "task-tests-success")
            self.assertEqual(attempts[0]["terminal"]["totalTestsRun"], 7)
            wrong_result_argv = completion_argv[:-1] + [baseline.decode("ascii").strip()]
            with self.assertRaises(module.AuditError):
                module._dispatch_command(wrong_result_argv)
            self.assertEqual(module._dispatch_command(completion_argv), 0)
            completed = module.recover_run_state(fixture["root"])
            terminal = [row for row in completed["records"]
                        if row.get("operationKind") == "frontier-complete"][-1]
            proof = terminal["taskCompletion"]
            self.assertEqual(proof["resultCommitOid"], result.decode("ascii").strip())
            self.assertEqual(proof["resultTreeOid"], scanned_tree.decode("ascii").strip())
            self.assertEqual(proof["parentOid"], baseline.decode("ascii").strip())
            self.assertEqual(proof["taskNumber"], 3)
            self.assertEqual(completed["openFrontiers"], [])
            original_records = completed["records"]
            for field in (
                "resultCommitOid", "resultTreeOid", "parentOid", "rawDeltaSha256",
                "pathSetDigest", "scanResultRelationDigest", "taskStartDigest",
                "taskAttemptStartRecordDigest", "taskTerminalRecordDigest",
                "testOuterCompletionRecordDigest", "leaseTerminalRecordDigest",
                "expectedTestsDigest", "proofKeyDigest", "taskNumber", "omitted",
                "envelope-input", "envelope-paths", "envelope-outcome", "envelope-parent",
            ):
                with self.subTest(cold_completion_tamper=field):
                    changed = json.loads(json.dumps(terminal))
                    if field == "omitted":
                        changed.pop("taskCompletion")
                    elif field.startswith("envelope-"):
                        envelope_field, replacement = {
                            "envelope-input": ("inputDigest", "0" * 64),
                            "envelope-paths": ("declaredFilenames", ["dirty.txt"]),
                            "envelope-outcome": ("completionState", "confirmed-success"),
                            "envelope-parent": ("parentFrontierId", "a" * 32),
                        }[field]
                        changed[envelope_field] = replacement
                    else:
                        changed["taskCompletion"][field] = (
                            4 if field == "taskNumber"
                            else "0" * len(str(changed["taskCompletion"][field]))
                        )
                        changed["taskCompletion"].pop("completionDigest")
                        changed["taskCompletion"]["completionDigest"] = self._record_digest(
                            changed["taskCompletion"]
                        )
                    changed.pop("recordDigest")
                    changed["recordDigest"] = self._record_digest(changed)
                    try:
                        self._write_task_test_records(fixture["root"], [changed])
                        rejected = module.recover_run_state(fixture["root"])
                        self.assertEqual(rejected["classification"], "indeterminate")
                        self.assertEqual(rejected["records"], [])
                        self.assertEqual(rejected["reason"], {
                            "resultCommitOid": "ordinary task typed result is stale, failed or historical",
                            "omitted": "current task completion cannot downgrade",
                            "envelope-input": "current task completion envelope drift",
                            "envelope-paths": "current task completion envelope drift",
                            "envelope-outcome": "current task completion envelope drift",
                            "envelope-parent": "current task completion envelope drift",
                        }.get(field, "cold ordinary task completion proof drift"))
                    finally:
                        self._write_task_test_records(fixture["root"], original_records)
            self.assertEqual(
                module._dispatch_command(completion_argv + ["--recover-exact"]), 0
            )
            with self.assertRaises(module.AuditError):
                module._dispatch_command(wrong_result_argv + ["--recover-exact"])
            (repository / "dirty.txt").write_bytes(b"later ordinary task bytes\n")
            module._run_git(repository, ["add", "--", "dirty.txt"])
            module._run_git(repository, [
                "-c", "user.name=Qinao Test",
                "-c", "user.email=qinao-test@invalid.local",
                "commit", "--quiet", "-m", "later task",
            ])
            (repository / "tracked.txt").write_bytes(b"later uncommitted edit\n")
            cold = module.recover_run_state(fixture["root"])
            self.assertEqual(cold["classification"], "complete")
            self.assertEqual(cold["openFrontiers"], [])
            self.assertIn(terminal, cold["records"])
            fresh_process = _external_ledger_sterile(
                fixture["root"], repository,
                ["recover-captures", "--root", str(fixture["root"])],
            )
            fresh = json.loads(fresh_process.stdout)
            self.assertEqual(fresh["classification"], "complete")
            self.assertEqual(fresh["openFrontiers"], [])
            self.assertIn(terminal, fresh["records"])

    @staticmethod
    def _domain_digest(domain, value):
        encoded = json.dumps(
            value,
            ensure_ascii=False,
            allow_nan=False,
            separators=(",", ":"),
            sort_keys=True,
        ).encode("utf-8") + b"\n"
        return hashlib.sha256(domain + b"\x00" + encoded).hexdigest()

    def test_raw_task_start_writers_cannot_publish_legacy_absence(self):
        """Break caught: low-level writers bypass current ordinary starts."""

        for atomic in (False, True):
            with self.subTest(atomic=atomic), tempfile.TemporaryDirectory() as temporary:
                base = Path(temporary)
                repository = self._repository_with_test_classes(base)
                root, task = SecretScanTypedRecoveryRedTests._root_and_task(
                    self, base, repository
                )
                recovered = module.recover_run_state(root)
                payload = {
                    field: value for field, value in task.items()
                    if field not in module._LEDGER_BASE_FIELDS and field != "taskStart"
                }
                payload["frontierId"] = "a" * 32
                candidate = module._new_record(
                    recovered["identity"], recovered["nextSequence"],
                    recovered["records"][-1]["recordDigest"], "frontier-start",
                    task["inputDigest"], task["declaredPaths"], "open", payload,
                )

                def write(transaction):
                    method = transaction.write_record_atomic if atomic else transaction.write_record
                    return method(candidate["sequence"], candidate)

                with self.assertRaises(module.AuditError):
                    module._execute_ledger_transaction(
                        root, operation_kind="frontier-start", body=write
                    )

