    @staticmethod
    def _record_digest(value):
        encoded = json.dumps(
            value,
            ensure_ascii=False,
            allow_nan=False,
            separators=(",", ":"),
            sort_keys=True,
        ).encode("utf-8") + b"\n"
        return hashlib.sha256(encoded).hexdigest()

    def _retarget_task_test_row(self, row, identifier):
        candidate = json.loads(json.dumps(row))
        category = candidate["outcomes"][0]["category"]
        ids = [identifier]
        outcome = {
            "schemaVersion": "qinao.task-test-outcome.v1",
            "testId": identifier,
            "closed": True,
            "category": category,
        }
        outcome["outcomeDigest"] = self._record_digest(outcome)
        candidate.update({
            "testIds": ids,
            "testIdsDigest": self._domain_digest(
                b"qinao.task-test-ids.v1", ids
            ),
            "startedTestIds": ids,
            "finishedTestIds": ids,
            "testsRun": 1,
            "failures": ids if category == "failure" else [],
            "errors": ids if category == "error" else [],
            "skips": ids if category == "skip" else [],
            "expectedFailures": (
                ids if category == "expectedFailure" else []
            ),
            "unexpectedSuccesses": (
                ids if category == "unexpectedSuccess" else []
            ),
            "outcomes": [outcome],
            "outcomesDigest": self._domain_digest(
                b"qinao.task-test-outcomes.v1", [outcome]
            ),
            "successful": category in (
                "success", "skip", "expectedFailure"
            ),
        })
        candidate.pop("targetResultDigest")
        candidate["targetResultDigest"] = self._record_digest(candidate)
        return candidate

    def _rebuild_task_test_terminal(self, terminal, rows):
        candidate = json.loads(json.dumps(terminal))
        result = candidate["result"]
        result.pop("resultDigest")
        result["targetResults"] = rows
        result["targetResultsDigest"] = hashlib.sha256(
            module.canonical_json_bytes(rows)
        ).hexdigest()
        result["totalTestsRun"] = sum(row["testsRun"] for row in rows)
        result["resultDigest"] = self._record_digest(result)
        candidate["inputDigest"] = result["resultDigest"]
        candidate["result"] = result
        candidate["resultRecordDigest"] = result["resultDigest"]
        candidate["targetResults"] = rows
        candidate["totalTestsRun"] = result["totalTestsRun"]
        candidate.pop("recordDigest")
        return candidate

    def _rechain_task_test_records(self, records, *, validate=True):
        previous = records[0]["previousRecordDigest"]
        rechained = []
        for source in records:
            candidate = json.loads(json.dumps(source))
            candidate["previousRecordDigest"] = previous
            candidate.pop("recordDigest", None)
            candidate["recordDigest"] = self._record_digest(candidate)
            if validate:
                module._validate_ledger_record_shape(candidate)
            rechained.append(candidate)
            previous = candidate["recordDigest"]
        return rechained

    def _write_task_test_records(self, root, records):
        for record in records:
            path = (
                root / "ledger" / "records"
                / ("%016d.json" % record["sequence"])
            )
            path.write_bytes(module.canonical_json_bytes(record))

    def _assert_cold_terminal_plan_tamper(self, variant, exit_code):
        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._fixture(Path(temporary), variant=variant)
            outer, context = self._append_outer(
                fixture["root"], fixture["repository"], fixture["argv"]
            )
            self.assertEqual(
                module._dispatch_command(
                    fixture["argv"], context=context
                ),
                exit_code,
            )
            module._append_linked_sterile_invocation_completion(
                fixture["root"], outer, exit_code=exit_code
            )
            recovered = module.recover_run_state(fixture["root"])
            self.assertEqual(recovered["classification"], "complete")
            original = recovered["records"]
            paths = [
                fixture["root"] / "ledger" / "records"
                / ("%016d.json" % record["sequence"])
                for record in original
            ]
            original_bytes = [path.read_bytes() for path in paths]
            terminal_index = next(
                index for index, record in enumerate(original)
                if record["operationKind"]
                == "task-test-attempt-terminal"
            )
            terminal = original[terminal_index]
            base_rows = terminal["targetResults"]
            tampered_rows = {
                "group-count": base_rows[:-1],
                "group-order-and-target": [
                    base_rows[1], base_rows[0], *base_rows[2:]
                ],
                "ids-digest-and-outcome": [
                    self._retarget_task_test_row(
                        base_rows[0],
                        "scripts.test_qinao_convergence_audit."
                        "RawDiffTests.test_unplanned_method",
                    ),
                    *base_rows[1:],
                ],
            }
            for label, rows in tampered_rows.items():
                with self.subTest(variant=variant, tamper=label):
                    changed = json.loads(json.dumps(original))
                    changed[terminal_index] = (
                        self._rebuild_task_test_terminal(
                            terminal, rows
                        )
                    )
                    rechained = self._rechain_task_test_records(changed)
                    try:
                        self._write_task_test_records(
                            fixture["root"], rechained
                        )
                        cold = module.recover_run_state(fixture["root"])
                        self.assertEqual(
                            cold["classification"],
                            "indeterminate",
                            cold,
                        )
                    finally:
                        for path, payload in zip(paths, original_bytes):
                            path.write_bytes(payload)
                    self.assertEqual(
                        module.recover_run_state(fixture["root"])[
                            "classification"
                        ],
                        "complete",
                    )

    def _assert_frozen_plan(self, start, terminal=None):
        subject = start["subject"]
        plan = subject["testPlan"]
        self.assertEqual(
            set(plan),
            {
                "schemaVersion", "groups", "flattenedTestIds",
                "flattenedTestIdsDigest", "activationWitness",
                "activationWitnessDigest", "planDigest",
            },
        )
        self.assertEqual(plan["schemaVersion"], "qinao.task-test-plan.v1")
        expected_failure_ids = set()
        if terminal is not None:
            for row in terminal["targetResults"]:
                expected_failure_ids.update(row["expectedFailures"])
                expected_failure_ids.update(row["unexpectedSuccesses"])
        expected_groups = []
        for ordinal, (target, identifier) in enumerate(zip(
            self._TASK_TARGETS, self._CONCRETE_TEST_IDS
        )):
            ids = [identifier]
            group = {
                "schemaVersion": "qinao.task-test-plan-group.v1",
                "ordinal": ordinal,
                "target": target,
                "moduleName": "scripts.test_qinao_convergence_audit",
                "className": target,
                "testIds": ids,
                "testIdsDigest": self._domain_digest(
                    b"qinao.task-test-ids.v1", ids
                ),
                "executionBindings": [{
                    "testId": identifier,
                    "classExpectedFailure": False,
                    "methodExpectedFailure": (
                        identifier in expected_failure_ids
                    ),
                    "setUpOwner": "unittest.case.TestCase",
                    "tearDownOwner": "unittest.case.TestCase",
                    "failureExceptionOwner": "unittest.case.TestCase",
                    "cleanupPolicy": (
                        "qinao.task-test-cleanup-capability.v1"
                    ),
                    "unsupportedFixturePolicy": (
                        "qinao.task-test-no-module-or-class-fixtures.v1"
                    ),
                }],
            }
            group["executionBindingsDigest"] = self._domain_digest(
                b"qinao.task-test-execution-bindings.v1",
                group["executionBindings"],
            )
            group["groupDigest"] = self._domain_digest(
                b"qinao.task-test-plan-group.v1", group
            )
            expected_groups.append(group)
        self.assertEqual(plan["groups"], expected_groups)
        flattened = list(self._CONCRETE_TEST_IDS)
        self.assertEqual(plan["flattenedTestIds"], flattened)
        self.assertEqual(
            plan["flattenedTestIdsDigest"],
            self._domain_digest(b"qinao.task-test-flattened-ids.v1", flattened),
        )
        witness = plan["activationWitness"]
        self.assertEqual(
            set(witness),
            {
                "schemaVersion", "loaderSchemaVersion", "moduleOrder",
                "modules", "witnessDigest",
            },
        )
        self.assertEqual(
            witness["schemaVersion"],
            "qinao.task-test-activation-witness.v1",
        )
        self.assertEqual(
            witness["loaderSchemaVersion"],
            "qinao.verified-source-loader.v1",
        )
        self.assertEqual(
            witness["moduleOrder"],
            [
                "qinao_convergence_audit",
                "scripts.test_qinao_convergence_audit",
            ],
        )
        expected_modules = [
            {
                "role": row["role"],
                "moduleName": row["moduleName"],
                "absolutePath": row["absolutePath"],
                "size": row["size"],
                "sha256": row["sha256"],
            }
            for row in subject["moduleManifest"]
        ]
        self.assertEqual(witness["modules"], expected_modules)
        unsigned_witness = dict(witness)
        unsigned_witness.pop("witnessDigest")
        self.assertEqual(
            witness["witnessDigest"],
            self._domain_digest(
                b"qinao.task-test-activation-witness.v1",
                unsigned_witness,
            ),
        )
        self.assertEqual(
            plan["activationWitnessDigest"], witness["witnessDigest"]
        )
        unsigned_plan = dict(plan)
        unsigned_plan.pop("planDigest")
        self.assertEqual(
            plan["planDigest"],
            self._domain_digest(b"qinao.task-test-plan.v1", unsigned_plan),
        )
        self.assertEqual(subject["testPlanDigest"], plan["planDigest"])
        self.assertEqual(start["testPlanDigest"], plan["planDigest"])
        if terminal is not None:
            self.assertEqual(
                [row["target"] for row in terminal["targetResults"]],
                list(self._TASK_TARGETS),
            )
            for row, group in zip(
                terminal["targetResults"], expected_groups
            ):
                self.assertEqual(row["testIds"], group["testIds"])
                self.assertEqual(
                    row["testIdsDigest"], group["testIdsDigest"]
                )

    @staticmethod
    def _direct_task_test_result(case):
        binding = module._task_test_freeze_case_binding(
            case, type(case), case._testMethodName
        )
        return module._TaskTestTextResult(
            io.StringIO(),
            True,
            0,
            frozen_cases=(case,),
            frozen_ids=(case.id(),),
            frozen_bindings=(binding,),
        )

    def _deferred_skip_protocol(self, count):
        class DeferredSkipCase(unittest.TestCase):
            def test_marker(self):
                self.fail("direct protocol case must not execute")

        case = DeferredSkipCase("test_marker")
        result = self._direct_task_test_result(case)
        result.startTest(case)
        outcome = unittest.case._Outcome(result)
        case._outcome = outcome
        events = [
            (
                unittest.case._SubTest(
                    case, "deferred", {"ordinal": ordinal}
                ),
                "deferred skip " + str(ordinal),
            )
            for ordinal in range(count)
        ]
        outcome.skipped.extend(events)
        return case, result, outcome, events

