    def test_cleanup_facade_restores_original_identity_on_base_exception(self):
        class Case(unittest.TestCase):
            def runTest(self):
                pass

        class Result:
            def __init__(self):
                self.reasons = []

            def _violate(self, reason):
                self.reasons.append(reason)

        class Marker(BaseException):
            pass

        case = Case()
        original = case._cleanups
        result = Result()
        with module._task_test_cleanup_registry(case, result) as registry:
            self.assertIs(case._cleanups, registry)
        self.assertIs(case._cleanups, original)
        self.assertEqual(original, [])

        marker = Marker()
        pending = (lambda: None, (), {})
        with self.assertRaises(Marker) as raised:
            with module._task_test_cleanup_registry(case, result) as registry:
                registry.append(pending)
                raise marker
        self.assertIs(raised.exception, marker)
        self.assertIs(case._cleanups, original)
        self.assertEqual(len(original), 1)
        self.assertIs(original[0], pending)
        original.clear()

