    def test_decorator_skip_callbacks_require_frozen_exact_provenance(self):
        """Break caught: arbitrary parent addSkip can impersonate a decorator."""

        class PlainCase(unittest.TestCase):
            def test_marker(self):
                self.assertTrue(True)

        @unittest.skip("frozen decorator reason")
        class DecoratedCase(unittest.TestCase):
            def test_marker(self):
                self.fail("decorated test executed")

        attacks = (
            ("nondecorator", PlainCase, ("manual skip",)),
            ("wrong-reason", DecoratedCase, ("wrong reason",)),
            ("wrong-type", DecoratedCase, (object(),)),
            (
                "duplicate", DecoratedCase,
                ("frozen decorator reason", "frozen decorator reason"),
            ),
        )
        for label, case_type, reasons in attacks:
            with self.subTest(attack=label):
                case = case_type("test_marker")
                result = self._direct_task_test_result(case)
                result.startTest(case)
                for reason in reasons:
                    result.addSkip(case, reason)
                result.stopTest(case)
                with self.assertRaises(module.AuditError):
                    result.finalize_outcomes()

    def test_deferred_skip_transaction_rejects_identity_length_and_phase_drift(self):
        """Break caught: mutable deferred skip lists can rewrite callbacks."""

        def outcome_replacement():
            case, result, _outcome, events = (
                self._deferred_skip_protocol(2)
            )
            result.addSkip(*events[0])
            replacement = unittest.case._Outcome(result)
            replacement.skipped.extend(events)
            case._outcome = replacement
            result.addSkip(*events[1])
            return case, result

        def list_replacement():
            case, result, outcome, events = (
                self._deferred_skip_protocol(2)
            )
            result.addSkip(*events[0])
            outcome.skipped = list(outcome.skipped)
            result.addSkip(*events[1])
            return case, result

        def appended_event():
            case, result, outcome, events = (
                self._deferred_skip_protocol(1)
            )
            result.addSkip(*events[0])
            extra = (
                unittest.case._SubTest(
                    case, "deferred", {"ordinal": 1}
                ),
                "deferred skip 1",
            )
            outcome.skipped.append(extra)
            result.addSkip(*extra)
            return case, result

        def truncated_event():
            case, result, outcome, events = (
                self._deferred_skip_protocol(2)
            )
            result.addSkip(*events[0])
            outcome.skipped.pop()
            return case, result

        def missing_callback():
            case, result, _outcome, events = (
                self._deferred_skip_protocol(2)
            )
            result.addSkip(*events[0])
            return case, result

        def extra_callback():
            case, result, _outcome, events = (
                self._deferred_skip_protocol(1)
            )
            result.addSkip(*events[0])
            result.addSkip(*events[0])
            return case, result

        def late_callback():
            case, result, _outcome, events = (
                self._deferred_skip_protocol(1)
            )
            result.addSkip(*events[0])
            result.stopTest(case)
            result.addSkip(*events[0])
            return case, result

        attacks = (
            ("outcome-replacement", outcome_replacement),
            ("list-replacement", list_replacement),
            ("append", appended_event),
            ("truncate", truncated_event),
            ("missing", missing_callback),
            ("extra", extra_callback),
            ("late", late_callback),
        )
        for label, attack in attacks:
            with self.subTest(attack=label):
                case, result = attack()
                if result._active_ordinal is not None:
                    result.stopTest(case)
                case._outcome = None
                with self.assertRaises(module.AuditError):
                    result.finalize_outcomes()

    def test_verified_source_loader_executes_cached_bytes_after_path_drift(self):
        """Break caught: verified source is reopened during activation."""

        with tempfile.TemporaryDirectory() as temporary:
            source = Path(temporary) / "verified_fixture.py"
            original = b"VALUE = 'original-path'\n"
            verified = b"VALUE = 'verified-bytes'\n"
            replacement = b"VALUE = 'replacement-path'\n"
            source.write_bytes(original)
            loader = module._TaskTestVerifiedSourceLoader(
                "qinao_verified_fixture", source, verified
            )
            self.assertNotIsInstance(
                loader, importlib.machinery.SourceFileLoader
            )
            specification = importlib.util.spec_from_file_location(
                "qinao_verified_fixture", str(source), loader=loader
            )
            self.assertIsNotNone(specification)
            activated = importlib.util.module_from_spec(specification)
            source.write_bytes(replacement)
            try:
                loader.exec_module(activated)
                self.assertEqual(activated.VALUE, "verified-bytes")
                self.assertEqual(activated.__file__, str(source))
                self.assertIs(activated.__loader__, loader)
                self.assertIs(activated.__spec__, specification)
            finally:
                source.write_bytes(original)

