            subject = start["subject"]
            subject["schemaVersion"] = "qinao.task-test-subject.v1"
            subject.pop("captureContractVersion")
            subject.pop("captureContractDigest")
            subject.pop("executionContractVersion")
            subject.pop("executionContractDigest")
            subject.pop("scanResultRelation")
            subject.pop("scanResultRelationDigest")
            subject.pop("subjectDigest")
            subject["subjectDigest"] = self._record_digest(subject)
            proof = module._task_test_proof_key(subject)
            start.update({
                "inputDigest": subject["subjectDigest"],
                "subject": subject,
                "subjectDigest": subject["subjectDigest"],
                "proofKeyDigest": proof,
            })
            start.pop("captureContractVersion")
            start.pop("captureContractDigest")
            start.pop("executionLeaseAcquiredRecordDigest")

            terminal = converted[terminal_index]
            rows = terminal["targetResults"]
            for row in rows:
                row["schemaVersion"] = "qinao.task-test-target-result.v1"
                row["stdout"]["captureComplete"] = True
                row["stderr"]["captureComplete"] = True
                row.pop("targetResultDigest")
                row["targetResultDigest"] = self._record_digest(row)
            result = terminal["result"]
