    def test_baseexceptions_restore_capture_and_preserve_durable_state(self):
        """BaseException identity crosses capture without forged terminal."""

        def surfaces():
            return (
                (sys.stdout, sys.__stdout__, sys.stderr, sys.__stderr__),
                tuple((os.fstat(fd).st_dev, os.fstat(fd).st_ino)
                      for fd in (1, 2)),
                tuple(os.get_inheritable(fd) for fd in (1, 2)),
            )

        for marker in (KeyboardInterrupt("typed-marker"), SystemExit(73)):
            with self.subTest(kind=type(marker).__name__), \
                    tempfile.TemporaryDirectory() as temporary:
                fixture = self._fixture(Path(temporary))
                _outer, context = self._append_outer(
                    fixture["root"], fixture["repository"], fixture["argv"]
                )
                before = surfaces()
                with mock.patch.object(
                    module, "_run_task_test_targets", side_effect=marker
                ):
                    try:
                        module._dispatch_command(
                            fixture["argv"], context=context
                        )
                    except BaseException as caught:
                        self.assertIs(caught, marker)
                    else:
                        self.fail("BaseException was swallowed")
                self.assertEqual(surfaces(), before)
                recovered = module.recover_run_state(fixture["root"])
                attempt = next(iter(recovered["taskTestAttempts"].values()))
                self.assertEqual(attempt["state"], "task-tests-running")
                self.assertEqual(sum(
                    row["operationKind"] == "task-test-attempt-terminal"
                    for row in recovered["records"]
                ), 0)

