    def test_cold_retry_terminalizes_durable_start_without_replay(self):
        """Break caught: a crashed attempt is silently replayed as success."""

        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._fixture(Path(temporary))
            old_outer, old_context = self._append_outer(
                fixture["root"], fixture["repository"], fixture["argv"]
            )
            with mock.patch.object(
                module,
                "_run_task_test_targets",
                side_effect=self._ProcessDeath("after durable start"),
                create=True,
            ):
                with self.assertRaises(self._ProcessDeath):
                    module._dispatch_command(
                        fixture["argv"], context=old_context
                    )
            running_state = module.recover_run_state(fixture["root"])
            running_attempt = next(iter(
                running_state["taskTestAttempts"].values()
            ))
            self._assert_frozen_plan(running_attempt["start"])
            builtins.__dict__.pop(self._IMPORT_WITNESS_KEY, None)
            cold_outer, cold_context = self._append_outer(
                fixture["root"], fixture["repository"], fixture["argv"]
            )
            with mock.patch.object(
                module,
                "_run_task_test_targets",
                wraps=getattr(module, "_run_task_test_targets", None),
                create=True,
            ) as runner:
                self.assertEqual(
                    module._dispatch_command(
                        fixture["argv"], context=cold_context
                    ),
                    0,
                )
            self.assertEqual(runner.call_count, 1)
            recovered = module.recover_run_state(fixture["root"])
            attempts = sorted(
                recovered["taskTestAttempts"].values(),
                key=lambda value: value["start"]["sequence"],
            )
            self.assertEqual(
                [value["state"] for value in attempts],
                ["task-tests-indeterminate-no-replay", "task-tests-success"],
            )
            self.assertEqual(
                attempts[0]["terminal"]["result"]["reasonCode"],
                "durable-start-no-terminal",
            )
            self.assertEqual(
                attempts[0]["terminal"]["terminalAuthority"],
                "closedLeaseRecovery",
            )
            self.assertEqual(
                attempts[0]["terminal"]["result"][
                    "terminalAuthority"
                ],
                "closedLeaseRecovery",
            )
            unavailable = attempts[0]["terminal"]["captureEvidence"]
            self.assertEqual(unavailable["state"], "UNAVAILABLE")
            self.assertEqual(unavailable["failureCodes"],
                             ["cold-running-capture-unavailable"])
            self.assertNotIn("stdout", unavailable)
            self.assertNotIn("stderr", unavailable)
            old_projected = recovered["sterileInvocations"][
                old_outer["recordDigest"]
            ]
            self.assertEqual(old_projected["state"], "failed")
            self.assertEqual(old_projected["completion"]["exitCode"], 2)
            leases = sorted(
                recovered["taskTestExecutionLeases"].values(),
                key=lambda value: value["acquired"]["sequence"],
            )
            self.assertEqual(len(leases), 2)
            self.assertEqual(
                attempts[0]["terminal"][
                    "executionLeaseAcquiredRecordDigest"
                ],
                leases[0]["acquired"]["recordDigest"],
            )
            self.assertLess(
                leases[0]["terminal"]["sequence"],
                attempts[0]["terminal"]["sequence"],
            )
            self.assertLess(
                attempts[0]["terminal"]["sequence"],
                old_projected["completion"]["sequence"],
            )
            self.assertLess(
                old_projected["completion"]["sequence"],
                leases[1]["acquired"]["sequence"],
            )
            self.assertEqual(
                attempts[1]["start"][
                    "executionLeaseAcquiredRecordDigest"
                ],
                leases[1]["acquired"]["recordDigest"],
            )
            self.assertEqual(
                attempts[0]["terminal"]["outerInvocationStartRecordDigest"],
                old_outer["recordDigest"],
            )
            self.assertEqual(
                attempts[1]["start"]["outerInvocationStartRecordDigest"],
                cold_outer["recordDigest"],
            )
            self._assert_frozen_plan(
                attempts[1]["start"], attempts[1]["terminal"]
            )

    def test_closed_lease_terminal_lost_ack_converges_exactly_once(self):
        """Break caught: a durable recovery terminal is appended twice."""

        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._fixture(Path(temporary))
            crashed = self._crash_after_durable_task_test_start(fixture)
            guard = module._TaskTestExecutionLeaseGuard.acquire_nonblocking(
                fixture["root"]
            )
            real_execute = module._execute_ledger_transaction
            fault_hits = []

            def execute_with_lost_ack(
                root, *, operation_kind, body, faults=None
            ):
                if operation_kind != "task-test-attempt-terminal":
                    return real_execute(
                        root,
                        operation_kind=operation_kind,
                        body=body,
                        faults=faults,
                    )
                self.assertIsNone(faults)

                def lose_ack(boundary, observed_operation, _subject):
                    if (
                        boundary == "records-fsync"
                        and observed_operation
                        == "task-test-attempt-terminal"
                    ):
                        fault_hits.append(boundary)
                        raise self._ProcessDeath(
                            "recovery terminal durable before acknowledgement"
                        )

                return real_execute(
                    root,
                    operation_kind=operation_kind,
                    body=body,
                    faults=module.DurabilityFaults(callback=lose_ack),
                )

            try:
                with mock.patch.object(
                    module,
                    "_execute_ledger_transaction",
                    side_effect=execute_with_lost_ack,
                ):
                    with self.assertRaises(self._ProcessDeath):
                        module._append_task_test_terminal(
                            fixture["root"],
                            crashed["start"],
                            status="task-tests-indeterminate-no-replay",
                            target_results=[],
                            reason_code="durable-start-no-terminal",
                            capture_evidence=
                                module._task_test_capture_evidence(
                                    None, unavailable=True
                                ),
                            guard=guard,
                            lease_acquired=crashed["leaseAcquired"],
                            lease_terminal=crashed["leaseTerminal"],
                            terminal_authority="closedLeaseRecovery",
                        )
            finally:
                guard.release_unbound()
            self.assertEqual(fault_hits, ["records-fsync"])

            uncertain = module.recover_run_state(fixture["root"])
            old_attempt = uncertain["taskTestAttempts"][
                crashed["start"]["attemptId"]
            ]
            recovery_terminal = old_attempt["terminal"]
            self.assertEqual(
                (
                    old_attempt["state"],
                    recovery_terminal["terminalAuthority"],
                    recovery_terminal["result"]["reasonCode"],
                ),
                (
                    "task-tests-indeterminate-no-replay",
                    "closedLeaseRecovery",
                    "durable-start-no-terminal",
                ),
            )
            self.assertEqual(
                uncertain["sterileInvocations"][
                    crashed["outer"]["recordDigest"]
                ]["state"],
                "open",
            )
            self.assertEqual(len(
                [
                    row for row in uncertain["records"]
                    if row["operationKind"]
                    == "task-test-attempt-terminal"
                    and row.get("attemptId")
                    == crashed["start"]["attemptId"]
                ]
            ), 1)

            _cold_outer, cold_context = self._append_outer(
                fixture["root"], fixture["repository"], fixture["argv"]
            )
            with mock.patch.object(
                module,
                "_run_task_test_targets",
                wraps=module._run_task_test_targets,
            ) as runner:
                self.assertEqual(
                    module._dispatch_command(
                        fixture["argv"], context=cold_context
                    ),
                    0,
                )
            self.assertEqual(runner.call_count, 1)
            recovered = module.recover_run_state(fixture["root"])
            self.assertEqual(
                recovered["taskTestAttempts"][
                    crashed["start"]["attemptId"]
                ]["terminal"]["recordDigest"],
                recovery_terminal["recordDigest"],
            )
            self.assertEqual(len(
                [
                    row for row in recovered["records"]
                    if row["operationKind"]
                    == "task-test-attempt-terminal"
                    and row.get("attemptId")
                    == crashed["start"]["attemptId"]
                ]
            ), 1)
            completions = [
                row for row in recovered["records"]
                if row["operationKind"]
                == "sterile-invocation-completed-linked"
                and row.get("invocationStartRecordDigest")
                == crashed["outer"]["recordDigest"]
            ]
            self.assertEqual(len(completions), 1)
            self.assertEqual(completions[0]["exitCode"], 2)
            generations = sorted(
                value["acquired"]["generation"]
                for value in recovered[
                    "taskTestExecutionLeases"
                ].values()
            )
            self.assertEqual(generations, [1, 2])
            generation_two = next(
                value["acquired"]
                for value in recovered[
                    "taskTestExecutionLeases"
                ].values()
                if value["acquired"]["generation"] == 2
            )
            self.assertLess(
                crashed["leaseTerminal"]["sequence"],
                recovery_terminal["sequence"],
            )
            self.assertLess(
                recovery_terminal["sequence"],
                completions[0]["sequence"],
            )
            self.assertLess(
                completions[0]["sequence"],
                generation_two["sequence"],
            )

