    def test_process_fd_capture_observes_both_native_channels_without_payload(self):
        """Break caught: Python-only redirection misses aliases and native writes."""

        capture_type = module._StrictProcessFDCapture
        saved_stdout = sys.stdout
        saved_stderr = sys.stderr
        stdout_parts = [
            b"print-out\n", b"alias-out", b"\x00\xff", b"native-out"
        ]
        stderr_parts = [
            b"print-err\n", b"alias-err", b"\xfe\x00", b"native-err"
        ]
        capture = capture_type()
        with capture:
            print("print-out")
            print("print-err", file=sys.stderr)
            saved_stdout.write("alias-out")
            saved_stderr.write("alias-err")
            saved_stdout.flush()
            saved_stderr.flush()
            sys.__stdout__.buffer.write(b"\x00\xff")
            sys.__stderr__.buffer.write(b"\xfe\x00")
            os.write(1, b"native-out")
            os.write(2, b"native-err")
        result = capture.result
        self.assertEqual(result["state"], "SEALED")
        self.assertTrue(result["complete"])
        self.assertTrue(result["restored"])
        self.assertEqual(result["failureCodes"], [])
        self.assertEqual(result["stdout"], {
            "byteCount": sum(map(len, stdout_parts)),
            "sha256": hashlib.sha256(b"".join(stdout_parts)).hexdigest(),
        })
        self.assertEqual(result["stderr"], {
            "byteCount": sum(map(len, stderr_parts)),
            "sha256": hashlib.sha256(b"".join(stderr_parts)).hexdigest(),
        })
        self.assertFalse(hasattr(capture, "getvalue"))
        self.assertEqual(
            result["captureContractDigest"],
            module._STRICT_PROCESS_FD_CAPTURE_CONTRACT_DIGEST,
        )

