    def test_process_fd_capture_lifecycle_calls_are_centralized(self):
        """Break caught: a new direct probe silently bypasses quarantine."""

        source = AUDIT_PATH.read_text(encoding="utf-8")
        tree = ast.parse(source)
        capture = next(
            node for node in tree.body
            if isinstance(node, ast.ClassDef)
            and node.name == "_StrictProcessFDCapture"
        )
        allowed = {
            "_probe_reader_liveness", "_join_reader_bounded"
        }
        violations = []
        for function in (
            node for node in capture.body
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
        ):
            for node in ast.walk(function):
                if (
                    isinstance(node, ast.Call)
                    and isinstance(node.func, ast.Attribute)
                    and node.func.attr in {"is_alive", "join"}
                    and function.name not in allowed
                ):
                    violations.append(
                        (function.name, node.func.attr)
                    )
        self.assertEqual(violations, [])

    def test_process_fd_capture_nonfatal_fault_and_resource_matrix(self):
        """Break caught: recoverable faults leak partial evidence or resources."""

        results = {}
        for case_name in (
            "ready-fail", "hash-fail", "read-fail", "overflow",
            "sys-drift", "fd-drift", "concurrency", "repeat",
        ):
            child = _run_fd_capture_b1_case(case_name)
