    def test_process_fd_capture_poison_commit_precedes_no_result_return(self):
        """Break caught: source ordering reintroduces the poison bypass."""

        tree = ast.parse(AUDIT_PATH.read_text(encoding="utf-8"))
        capture = next(
            node for node in tree.body
            if isinstance(node, ast.ClassDef)
            and node.name == "_StrictProcessFDCapture"
        )
        stop = next(
            node for node in capture.body
            if isinstance(node, ast.FunctionDef) and node.name == "_stop"
        )
        preactive = next(
            node for node in ast.walk(stop)
            if isinstance(node, ast.If)
            and isinstance(node.test, ast.Attribute)
            and node.test.attr == "_preactive_no_result"
        )
        poison_commits = [
            node for node in ast.walk(stop)
            if isinstance(node, ast.Assign)
            and any(
                isinstance(target, ast.Name)
                and target.id == "_STRICT_PROCESS_FD_CAPTURE_POISONED"
                for target in node.targets
            )
            and isinstance(node.value, ast.Constant)
            and node.value.value is True
        ]
        self.assertTrue(poison_commits)
        self.assertLess(min(
            node.lineno for node in poison_commits
        ), preactive.lineno)

    def _assert_real_typed_execution_fd_fault_cases(self, selected):
        """Real typed execution binds every capture fault to durable state."""

        expected = {
            "task-d0-ready": (0, 0, None, []),
            "task-d1-hash": (1, 1, "INCOMPLETE", ["hash-update-failed"]),
            "task-d1-overflow": (
                1, 1, "INCOMPLETE", ["byte-count-overflow"]
            ),
            "task-d1-sys": (1, 1, "INCOMPLETE", ["sys-slot-drift"]),
            "task-d1-fd": (1, 1, "INCOMPLETE", ["fd-capture-drift"]),
            "task-d2-read": (
                1, 1, "INCOMPLETE",
                ["reader-read-failed", "reader-read-unrecoverable"],
            ),
            "task-d3-leak-out": (
                1, 1, "INCOMPLETE",
                ["reader-eof-timeout", "unknown-writer"],
            ),
            "task-d3-leak-err": (
                1, 1, "INCOMPLETE",
                ["reader-eof-timeout", "unknown-writer"],
            ),
            "task-d3-fork": (
                1, 1, "INCOMPLETE",
                ["reader-eof-timeout", "unknown-writer"],
            ),
            "task-d4-fatal": (1, 0, None, []),
        }
        for case_name in selected:
            contract = expected[case_name]
            with self.subTest(case=case_name):
                child = _run_fd_capture_b2_case(case_name)
                self.assertFalse(
                    child["timedOut"],
                    case_name + ":" + child["stderr"].decode(
                        "ascii", "replace"
                    ),
                )
                self.assertEqual(child["returncode"], 0, case_name)
                self.assertEqual(child["stderr"], b"", case_name)
                self.assertTrue(child["frameValidated"], case_name)
                self.assertIsNone(child["controlError"], case_name)
                row = child["controlObject"]
                self.assertEqual(set(row), {
                    "case", "runId", "elapsed", "startCount",
                    "terminalCount", "coldState", "evidenceState",
                    "codes", "digest", "hasStdout", "hasStderr",
                    "rows", "total", "poison", "futureState",
                    "futureType", "futureComplete", "futureErrorExact",
                    "instantiated", "dispatchError",
                    "dispatchErrorExact", "controllerError",
                    "captureCount", "holderRealClass",
                    "preactiveNoResult", "captureState",
                    "captureResultNone", "readyWaitCalls",
                    "activationCalls", "lockRetained",
                    "quarantineCodes", "ownedReadChannels",
                    "ownedReadRoles",
                    "readFaultCalls", "surfaces", "restored",
                    "fdGrowth", "threadGrowth",
                }, case_name)
                self.assertEqual(row["case"], case_name)
                self.assertIsNone(row["controllerError"], case_name)
                self.assertEqual(
                    row["dispatchError"],
                    (
                        "AuditError" if case_name == "task-d0-ready"
                        else "AuditError"
                        if case_name == "task-d4-fatal"
                        else None
                    ),
                    case_name,
                )
                self.assertTrue(row["dispatchErrorExact"], case_name)
                self.assertEqual(row["captureCount"], 1, case_name)
                self.assertTrue(row["holderRealClass"], case_name)
                self.assertEqual(
                    row["activationCalls"],
                    0 if case_name == "task-d0-ready" else 1,
                    case_name,
                )
                if case_name == "task-d0-ready":
                    self.assertTrue(row["preactiveNoResult"], case_name)
                    self.assertEqual(row["captureState"], "INCOMPLETE")
                    self.assertTrue(row["captureResultNone"], case_name)
                    self.assertEqual(row["readyWaitCalls"], 1, case_name)
                elif case_name == "task-d4-fatal":
                    self.assertEqual(row["captureState"], "QUARANTINED")
                    self.assertTrue(row["captureResultNone"], case_name)
                    self.assertTrue(row["lockRetained"], case_name)
                    self.assertEqual(row["quarantineCodes"], [
                        "reader-lifecycle-probe-failed",
                        "reader-termination-unproven",
                    ], case_name)
                    self.assertEqual(
                        row["ownedReadChannels"], [1, 2], case_name
                    )
                    self.assertEqual(
                        row["ownedReadRoles"], ["read", "read"], case_name
                    )
                if case_name == "task-d2-read":
                    self.assertEqual(row["readFaultCalls"], 3, case_name)
                self.assertEqual(
                    (row["startCount"], row["terminalCount"],
                     row["evidenceState"], row["codes"]),
                    contract,
                    case_name + ":" + json.dumps(row, sort_keys=True),
                )
                self.assertEqual(row["instantiated"], 1, case_name)
                self.assertFalse(row["hasStdout"], case_name)
                self.assertFalse(row["hasStderr"], case_name)
                if row["terminalCount"]:
                    self.assertEqual(row["rows"], [], case_name)
                    self.assertEqual(row["total"], 0, case_name)
                    self.assertEqual(
                        row["digest"],
                        hashlib.sha256(json.dumps(
                            row["codes"], separators=(",", ":")
                        ).encode()).hexdigest(),
                        case_name,
                    )
                    self.assertEqual(
                        row["coldState"],
                        "task-tests-indeterminate-no-replay",
                        case_name,
                    )
                elif row["startCount"]:
                    self.assertEqual(
                        row["coldState"], "task-tests-running", case_name
                    )
                if case_name.startswith("task-d3") or case_name in (
                    "task-d2-read", "task-d4-fatal"
                ):
                    self.assertTrue(row["poison"], case_name)
                    self.assertEqual(
                        (row["futureState"], row["futureType"],
                         row["futureComplete"], row["futureErrorExact"]),
                        ("error", "AuditError", None, True), case_name,
                    )
                    self.assertTrue(row["surfaces"], case_name)
                    self.assertTrue(row["restored"], case_name)
                    if case_name != "task-d4-fatal":
                        self.assertEqual(row["fdGrowth"], [], case_name)
                        self.assertEqual(row["threadGrowth"], [], case_name)
                else:
                    self.assertFalse(row["poison"], case_name)
                    self.assertEqual(
                        (row["futureState"], row["futureType"],
                         row["futureComplete"], row["futureErrorExact"]),
                        ("complete", None, True, True), case_name,
                    )
                    self.assertTrue(row["surfaces"], case_name)
                    self.assertTrue(row["restored"], case_name)
                    self.assertEqual(row["fdGrowth"], [], case_name)
                    self.assertEqual(row["threadGrowth"], [], case_name)

