    def test_process_fd_capture_leaks_faults_and_honest_boundary(self):
        """Break caught: leaked writers hang or yield authoritative evidence."""

        rows = {}
        children = {}
        for case_name in (
            "leaked-dup", "leaked-dup-stderr", "fork-writer",
            "permanent-read", "negative-boundary", "surface-edges",
            "closed-fd1", "closed-fd2",
        ):
            child = _run_fd_capture_b2_case(case_name)
            children[case_name] = child
            self.assertFalse(child["timedOut"], case_name)
            self.assertEqual(
                child["returncode"], 0,
                case_name + ": " + child["stderr"].decode(
                    "utf-8", "replace"
                ),
            )
            self.assertTrue(child["frameValidated"], case_name)
            self.assertIsNone(child["controlError"], case_name)
            self.assertEqual(
                child["controlObject"], json.loads(child["control"]),
                case_name,
            )
            rows[case_name] = child["controlObject"]
            self.assertLess(rows[case_name]["elapsed"], 2.0, case_name)

        for case_name in (
            "leaked-dup", "leaked-dup-stderr", "fork-writer"
        ):
            row = rows[case_name]
            self.assertIsNone(row["error"], case_name)
            self.assertEqual(row["state"], "INCOMPLETE", case_name)
            self.assertFalse(row["result"]["complete"], case_name)
            self.assertNotIn("stdout", row["result"], case_name)
            self.assertNotIn("stderr", row["result"], case_name)
            self.assertEqual(row["result"]["failureCodes"], [
                "reader-eof-timeout", "unknown-writer",
            ], case_name)
            self.assertEqual(
                row["result"]["failureDigest"],
                "2e44e2a092a80377437c562e17df3de28cd620fdc7e6edaf082d36c8fd210bca",
                case_name,
            )
            self.assertEqual(
                row["future"], ["AuditError", "fd capture is poisoned"],
                case_name,
            )

        permanent = rows["permanent-read"]
        self.assertEqual(permanent["state"], "INCOMPLETE")
        self.assertFalse(permanent["result"]["complete"])
        self.assertIn(
            "reader-read-unrecoverable",
            permanent["result"]["failureCodes"],
        )
        self.assertNotIn("stdout", permanent["result"])
        self.assertNotIn("stderr", permanent["result"])
        self.assertEqual(
            permanent["result"]["failureCodes"],
            ["reader-read-failed", "reader-read-unrecoverable"],
        )
        self.assertEqual(
            permanent["result"]["failureDigest"],
            "4ccea6e2379c3a52793991255157f33b5a07ec769119f681d830d37835c55704",
        )
        self.assertEqual(
            permanent["future"],
            ["AuditError", "fd capture is poisoned"],
        )
        self.assertIsNone(permanent["captureError"])
        self.assertNotIn("secret", json.dumps(permanent["result"]))
        self.assertIsNotNone(permanent["writeError"])

        negative = rows["negative-boundary"]
        self.assertTrue(negative["result"]["complete"])
        self.assertEqual(negative["result"]["stdout"], {
            "byteCount": len(b"captured-only"),
            "sha256": hashlib.sha256(b"captured-only").hexdigest(),
        })
        self.assertEqual(
            negative["authority"], "cooperative-process-fd-observation"
        )
        self.assertFalse(negative["mergedOrder"])
        escaped = children["negative-boundary"]["stdout"]
        self.assertIn(
            b"escaped-old:" + negative["runId"].encode(), escaped
        )
        self.assertIn(
            b"escaped-transient:" + negative["runId"].encode(), escaped
        )
        self.assertNotIn(negative["runId"].encode(), b"captured-only")

        surface = rows["surface-edges"]
        self.assertTrue(surface["identity"])
        self.assertTrue(surface["slotsRestored"])
        self.assertTrue(surface["flagsRestored"])
        self.assertTrue(surface["result"]["complete"])

        for case_name in ("closed-fd1", "closed-fd2"):
            closed = rows[case_name]
            self.assertEqual(closed["error"], [
                "AuditError", "fd capture requires open fd 1 and 2"
            ], case_name)
            self.assertTrue(closed["resultAbsent"], case_name)
            self.assertTrue(closed["lockFree"], case_name)
            self.assertFalse(closed["poisoned"], case_name)
            self.assertTrue(closed["slotsExact"], case_name)
            self.assertTrue(closed["otherExact"], case_name)
            self.assertEqual(closed["rejectedErrno"], errno.EBADF, case_name)
            self.assertEqual(closed["mutations"], {
                "dup": 0, "pipe": 0, "dup2": 0, "setInheritable": 0,
                "setSysSlot": 0, "lockAcquire": 0,
            }, case_name)
            self.assertTrue(closed["nextComplete"], case_name)

