    def test_atomic_validator_classifies_exact_fsynced_staged_bytes(self):
        """Break caught: final validation reads the caller's old mapping."""

        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._fixture(Path(temporary))
            recovered = module.recover_run_state(fixture["root"])
            sequence = recovered["nextSequence"]
            original = module._new_record(
                recovered["identity"], sequence,
                recovered["records"][-1]["recordDigest"],
                "bootstrap-completed", "a" * 64, [], "complete",
                {
                    "bootstrapImportCount": 0,
                    "bootstrapImportsDigest": hashlib.sha256(b"").hexdigest(),
                },
            )
            changed = json.loads(json.dumps(original))
            changed["inputDigest"] = "b" * 64
            changed.pop("recordDigest")
            changed["recordDigest"] = self._record_digest(changed)
            original_bytes = module.canonical_json_bytes(original)
            changed_bytes = module.canonical_json_bytes(changed)
            self.assertEqual(len(original_bytes), len(changed_bytes))
            final_path = (
                fixture["root"] / "ledger" / "records"
                / ("%016d.json" % sequence)
            )
            observed_digests = []

            def mutate_stage(boundary, _operation_kind, _subject):
                if boundary != "record-stage-parent-fsync":
                    return
                names = [
                    name for name in os.listdir(
                        fixture["root"] / "tmp"
                    )
                    if name.startswith(".qinao-record-stage-")
                ]
                self.assertEqual(len(names), 1)
                parent_fd = os.open(
                    fixture["root"] / "tmp",
                    os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
                )
                descriptor = os.open(
                    names[0], os.O_WRONLY, dir_fd=parent_fd
                )
                try:
                    os.lseek(descriptor, 0, os.SEEK_SET)
                    module._write_all(descriptor, changed_bytes)
                    os.ftruncate(descriptor, len(changed_bytes))
                    os.fsync(descriptor)
                finally:
                    os.close(descriptor)
                    os.close(parent_fd)

            def validate(staged):
                observed_digests.append(staged["inputDigest"])
                module._validate_ledger_record_shape(staged)
                if staged["inputDigest"] != original["inputDigest"]:
                    raise module.AuditError(
                        "injected staged mapping reached validator"
                    )

            with self.assertRaisesRegex(
                module.AuditError, "injected staged mapping reached validator"
            ):
                with module.LedgerTransaction(
                    fixture["root"], operation_kind="secret-scan-terminal",
                    faults=module.DurabilityFaults(callback=mutate_stage),
                ) as transaction:
                    transaction.write_record_atomic(
                        sequence, original,
                        _pre_rename_validator=validate,
                    )
            self.assertEqual(observed_digests, [changed["inputDigest"]])
            self.assertFalse(final_path.exists())

