    def test_atomic_publication_requires_exact_expected_staged_bytes(self):
        """Break caught: a canonical staged mutation replaces caller bytes."""

        validators = (
            ("absent", None),
            ("incomplete", lambda _record: None),
        )
        for label, validator in validators:
            with self.subTest(validator=label), \
                    tempfile.TemporaryDirectory() as temporary:
                fixture = self._fixture(Path(temporary))
                recovered = module.recover_run_state(fixture["root"])
                sequence = recovered["nextSequence"]
                final_path = (
                    fixture["root"] / "ledger" / "records"
                    / ("%016d.json" % sequence)
                )
                changed_digests = []

                def mutate_stage(boundary, _operation_kind, _subject):
                    if boundary != "record-stage-parent-fsync":
                        return
                    scratch = fixture["root"] / "tmp"
                    names = [
                        name for name in os.listdir(scratch)
                        if name.startswith(".qinao-record-stage-")
                    ]
                    self.assertEqual(len(names), 1)
                    parent_fd = os.open(
                        scratch,
                        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
                    )
                    descriptor = os.open(
                        names[0], os.O_RDWR, dir_fd=parent_fd
                    )
                    try:
                        current_bytes = os.read(
                            descriptor, module.MAX_JSON_BYTES
                        )
                        current = module.parse_canonical_json(current_bytes)
                        changed = dict(current)
                        changed["inputDigest"] = "b" * 64
                        changed.pop("recordDigest")
                        changed["recordDigest"] = self._record_digest(changed)
                        changed_bytes = module.canonical_json_bytes(changed)
                        self.assertEqual(
                            len(changed_bytes), len(current_bytes)
                        )
                        os.lseek(descriptor, 0, os.SEEK_SET)
                        module._write_all(descriptor, changed_bytes)
                        os.ftruncate(descriptor, len(changed_bytes))
                        os.fsync(descriptor)
                        changed_digests.append(changed["recordDigest"])
                    finally:
                        os.close(descriptor)
                        os.close(parent_fd)

                with self.assertRaisesRegex(
                    module.AuditError, "expected staged bytes"
                ):
                    with module.LedgerTransaction(
                        fixture["root"],
                        operation_kind="secret-scan-terminal",
                        faults=module.DurabilityFaults(
                            callback=mutate_stage
                        ),
                    ) as transaction:
                        transaction.append_record(
                            recovered,
                            "bootstrap-completed",
                            "a" * 64,
                            [],
                            "complete",
                            {
                                "bootstrapImportCount": 0,
                                "bootstrapImportsDigest":
                                    hashlib.sha256(b"").hexdigest(),
                            },
                            atomic_publication=True,
                            _pre_rename_validator=validator,
                        )
                self.assertEqual(len(changed_digests), 1)
                self.assertFalse(final_path.exists())

    def test_atomic_publication_rechecks_bytes_after_validator(self):
        """Break caught: a validator mutates staged bytes before rename."""

        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._fixture(Path(temporary))
            recovered = module.recover_run_state(fixture["root"])
            sequence = recovered["nextSequence"]
            original = module._new_record(
                recovered["identity"], sequence,
                recovered["records"][-1]["recordDigest"],
                "bootstrap-completed", "a" * 64, [], "complete",
                {
                    "bootstrapImportCount": 0,
                    "bootstrapImportsDigest": hashlib.sha256(b"").hexdigest(),
                },
            )
            final_path = (
                fixture["root"] / "ledger" / "records"
                / ("%016d.json" % sequence)
            )

            def mutate_after_validation(staged):
                self.assertEqual(staged, original)
                changed = dict(staged)
                changed["inputDigest"] = "b" * 64
                changed.pop("recordDigest")
                changed["recordDigest"] = self._record_digest(changed)
                original_bytes = module.canonical_json_bytes(staged)
                changed_bytes = module.canonical_json_bytes(changed)
                self.assertEqual(len(changed_bytes), len(original_bytes))
                scratch = fixture["root"] / "tmp"
                names = [
                    name for name in os.listdir(scratch)
                    if name.startswith(".qinao-record-stage-")
                ]
                self.assertEqual(len(names), 1)
                parent_fd = os.open(
                    scratch,
                    os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
                )
                descriptor = os.open(
                    names[0], os.O_RDWR, dir_fd=parent_fd
                )
                try:
                    os.lseek(descriptor, 0, os.SEEK_SET)
                    module._write_all(descriptor, changed_bytes)
                    os.ftruncate(descriptor, len(changed_bytes))
                    os.fsync(descriptor)
                finally:
                    os.close(descriptor)
                    os.close(parent_fd)

            with self.assertRaisesRegex(
                module.AuditError, "changed after validation"
            ):
                with module.LedgerTransaction(
                    fixture["root"],
                    operation_kind="secret-scan-terminal",
                ) as transaction:
                    transaction.write_record_atomic(
                        sequence,
                        original,
                        _pre_rename_validator=mutate_after_validation,
                    )
            self.assertFalse(final_path.exists())

    def test_acquisition_receipt_binds_exact_published_inode(self):
        """Break caught: byte-identical inode replacement satisfies receipt."""

        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._fixture(Path(temporary))
            outer, _context = self._append_outer(
                fixture["root"], fixture["repository"], fixture["argv"]
            )
            guard, payload, input_digest, capability = (
                self._prepared_execution_lease_acquisition(fixture, outer)
            )
            receipts = []
            retained = None
            try:
                with module.LedgerTransaction(
                    fixture["root"],
                    operation_kind="task-test-execution-lease-acquired",
                ) as transaction:
                    record = transaction.append_record(
                        transaction.recover(),
                        "task-test-execution-lease-acquired",
                        input_digest, [],
                        "task-test-execution-lease-acquired", payload,
                        atomic_publication=True,
                        _pre_rename_validator=lambda _record: None,
                        _execution_append_capability=capability,
                        _publication_receipt_sink=receipts,
                    )
                self.assertEqual(len(receipts), 1)
                record_path = (
                    fixture["root"] / "ledger" / "records"
                    / ("%016d.json" % record["sequence"])
                )
                retained = os.open(
                    record_path,
                    os.O_RDONLY | getattr(os, "O_CLOEXEC", 0),
                )
                original_identity = os.fstat(retained)
                exact_bytes = module.canonical_json_bytes(record)
                os.unlink(record_path)
                replacement = os.open(
                    record_path,
                    os.O_WRONLY | os.O_CREAT | os.O_EXCL
                    | getattr(os, "O_NOFOLLOW", 0)
                    | getattr(os, "O_CLOEXEC", 0),
                    0o600,
                )
                try:
                    os.fchmod(replacement, 0o600)
                    module._write_all(replacement, exact_bytes)
                    os.fsync(replacement)
                finally:
                    os.close(replacement)
                records_fd = os.open(
                    record_path.parent,
                    os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
                )
                try:
                    os.fsync(records_fd)
                finally:
                    os.close(records_fd)
                replacement_identity = os.lstat(record_path)
                self.assertNotEqual(
                    (original_identity.st_dev, original_identity.st_ino),
                    (replacement_identity.st_dev,
                     replacement_identity.st_ino),
                )
                with self.assertRaisesRegex(
                    module.AuditError, "publication receipt.*inode"
                ):
                    guard.bind_acquired(record, receipts[0])
                self.assertIsNone(guard._pending_acquisition)
                with self.assertRaisesRegex(
                    module.AuditError, "publication receipt"
                ):
                    guard.bind_acquired(record, receipts[0])
            finally:
                if retained is not None:
                    os.close(retained)
                self._cleanup_prepared_execution_guard(fixture, guard)

