    def test_authentic_receipt_is_one_shot_from_initial_revalidation(self):
        """Break caught: the pre-consumption guard check preserves receipt."""

        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._fixture(Path(temporary))
            outer, _context = self._append_outer(
                fixture["root"], fixture["repository"], fixture["argv"]
            )
            guard, payload, input_digest, capability = (
                self._prepared_execution_lease_acquisition(fixture, outer)
            )
            try:
                record, receipt = (
                    self._publish_prepared_execution_lease_acquisition(
                        fixture, guard, payload, input_digest, capability
                    )
                )
                original_revalidate = guard.revalidate
                injected = RuntimeError("injected initial revalidation failure")
                calls = []

                def fail_first_revalidation():
                    calls.append("revalidate")
                    if len(calls) == 1:
                        raise injected
                    original_revalidate()

                with mock.patch.object(
                    guard, "revalidate", side_effect=fail_first_revalidation
                ):
                    with self.assertRaises(RuntimeError) as raised:
                        guard.bind_acquired(record, receipt)
                self.assertIs(raised.exception, injected)
                self.assertEqual(calls, ["revalidate"])
                self.assertIsNone(guard._pending_acquisition)
                self.assertFalse(guard._closed)
                self.assertIs(
                    module._TASK_TEST_EXECUTION_GUARDS.get(str(guard.root)),
                    guard,
                )
                with self.assertRaisesRegex(
                    module.AuditError, "publication receipt"
                ):
                    guard.bind_acquired(record, receipt)
            finally:
                self._cleanup_prepared_execution_guard(fixture, guard)

    def test_projection_baseexceptions_clear_matching_receipt_pending_state(self):
        """Break caught: projection aborts strand the matching pending grant."""

        class ProjectionAbort(BaseException):
            pass

        exceptions = (
            OSError("injected projection operating-system failure"),
            RuntimeError("injected projection runtime failure"),
            ProjectionAbort("injected projection baseexception"),
        )
        for index, injected in enumerate(exceptions):
            with self.subTest(exception=type(injected).__name__), \
                    tempfile.TemporaryDirectory() as temporary:
                fixture = self._fixture(Path(temporary))
