    def test_identity_close_fault_retains_guard_in_strong_quarantine(self):
        """Break caught: failed identity close loses all strong ownership."""

        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._fixture(Path(temporary))
            outer, _context = self._append_outer(
                fixture["root"], fixture["repository"], fixture["argv"]
            )
            environment = {
                "HOME": os.environ.get("HOME", "/tmp"),
                "TMPDIR": os.environ.get("TMPDIR", "/tmp"),
                "LANG": "C", "LC_ALL": "C", "PATH": "/usr/bin:/bin",
            }
            probe = subprocess.run(
                [
                    sys.executable, "-I", "-S", "-B",
                    str(Path(__file__).resolve()),
                    "--task-test-execution-guard-close-fault",
                    str(fixture["root"]), str(fixture["repository"]),
                    outer["recordDigest"], json.dumps(fixture["targets"]),
                ],
                cwd=str(Path(__file__).resolve().parents[1]),
                env=environment, stdin=subprocess.DEVNULL,
                stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                timeout=15, check=False,
            )
            self.assertEqual(
                probe.returncode, 0,
                probe.stderr.decode("utf-8", "replace"),
            )
            report = json.loads(probe.stdout.decode("utf-8"))
            self.assertIn("injected identity close fault", report["error"])
            self.assertFalse(report["closed"])
            self.assertTrue(report["registered"])
            self.assertTrue(report["quarantined"])
            self.assertEqual(
                report["subsequent"],
                "task test execution lease is active",
            )

