    def test_reserved_records_require_capability_at_every_durable_publication_primitive(self):
        """Break caught: raw durable writers bypass execution capability."""

        for primitive in ("atomic", "record", "bytes"):
            with self.subTest(primitive=primitive), \
                    tempfile.TemporaryDirectory() as temporary:
                fixture = self._fixture(Path(temporary))
                outer, _context = self._append_outer(
                    fixture["root"], fixture["repository"], fixture["argv"]
                )
                recovered = module.recover_run_state(fixture["root"])
                observed = os.lstat(
                    fixture["root"] / "ledger" / "identity.json"
                )
                lock_identity = {
                    "device": str(observed.st_dev),
                    "inode": str(observed.st_ino), "mode": "0600",
                    "linkCount": 1,
                    "identityDigest":
                        recovered["identity"]["identityDigest"],
                }
                payload = {
                    "executionContractVersion": 1,
                    "executionContractDigest":
                        module._TASK_TEST_EXECUTION_CONTRACT_DIGEST,
                    "leaseId": "8" * 32, "holderId": "9" * 32,
                    "generation": 1,
                    "frontierId": fixture["task"]["frontierId"],
                    "frontierStartRecordDigest":
                        fixture["task"]["recordDigest"],
                    "outerInvocationStartRecordDigest": outer["recordDigest"],
                    "invocationDigest": outer["invocation"]["recordDigest"],
                    "expectedTestsDigest":
                        module._task_test_expected_tests_digest(
                            fixture["targets"]
                        ),
                    "predecessorLeaseTerminalRecordDigest": None,
                    "lockName": "ledger/identity.json",
                    "lockIdentity": lock_identity,
                    "lockIdentityDigest": hashlib.sha256(
                        module.canonical_json_bytes(lock_identity)
                    ).hexdigest(),
                    "releaseRule": "darwin-flock-close-only-v1",
                    "authorityScope": "cooperative-canonical-root-v1",
                }
                input_digest = hashlib.sha256(module.canonical_json_bytes({
                    "schemaVersion": (
                        "qinao.task-test-execution-lease-acquisition-input.v1"
                    ), **payload,
                })).hexdigest()
                sequence = recovered["nextSequence"]
                record = module._new_record(
                    recovered["identity"], sequence,
                    recovered["records"][-1]["recordDigest"],
                    "task-test-execution-lease-acquired", input_digest, [],
                    "task-test-execution-lease-acquired", payload,
                )
                name = "%016d.json" % sequence
                path = fixture["root"] / "ledger" / "records" / name
                with module.LedgerTransaction(
                    fixture["root"], operation_kind="raw-reserved-write"
                ) as transaction:
                    with self.assertRaisesRegex(
                        module.AuditError,
                        "live execution lease guard capability",
                    ):
                        if primitive == "atomic":
                            transaction.write_record_atomic(sequence, record)
                        elif primitive == "record":
                            transaction.write_record(sequence, record)
                        else:
                            transaction.write_bytes_at(
                                transaction._fds["records"], name,
                                module.canonical_json_bytes(record),
                            )
                self.assertFalse(path.exists())
                self.assertEqual(module.recover_run_state(
                    fixture["root"]
                )["nextSequence"], sequence)

