    def _run_dead_owner_execution_case(self, fixture, outer, case):
        environment = {
            "HOME": os.environ.get("HOME", "/tmp"),
            "TMPDIR": os.environ.get("TMPDIR", "/tmp"),
            "LANG": "C", "LC_ALL": "C", "PATH": "/usr/bin:/bin",
        }
        return subprocess.run(
            [
                sys.executable, "-I", "-S", "-B",
                str(Path(__file__).resolve()),
                "--task-test-dead-owner-case", case,
                str(fixture["root"]), str(fixture["repository"]),
                outer["recordDigest"], json.dumps(fixture["targets"]),
            ],
            cwd=str(Path(__file__).resolve().parents[1]), env=environment,
            stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
            stderr=subprocess.PIPE, timeout=15, check=False,
        )

    def _run_owner_lost_fsync_crash_case(
        self, fixture, outer, *, case
    ):
        environment = {
            "HOME": os.environ.get("HOME", "/tmp"),
            "TMPDIR": os.environ.get("TMPDIR", "/tmp"),
            "LANG": "C", "LC_ALL": "C", "PATH": "/usr/bin:/bin",
        }
        return subprocess.run(
            [
                sys.executable, "-I", "-S", "-B",
                str(Path(__file__).resolve()),
                "--task-test-owner-lost-fsync-crash",
                case, str(fixture["root"]), outer["recordDigest"],
                json.dumps(fixture["argv"]),
            ],
            cwd=str(Path(__file__).resolve().parents[1]), env=environment,
            stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
            stderr=subprocess.PIPE, timeout=15, check=False,
        )

    def _assert_real_process_death_recovery(
        self, *, case, expected_binding
    ):
        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._fixture(Path(temporary))
            old_outer, _old_context = self._append_outer(
                fixture["root"], fixture["repository"], fixture["argv"]
            )
            probe = self._run_dead_owner_execution_case(
                fixture, old_outer, case
            )
            self.assertEqual(
                probe.returncode, 0,
                probe.stderr.decode("utf-8", "replace"),
            )
            report = json.loads(probe.stdout.decode("utf-8"))
            initial = module.recover_run_state(fixture["root"])
            old_lease = next(
                value
                for value in initial[
                    "taskTestExecutionLeases"
                ].values()
                if value["acquired"]["recordDigest"]
                == report["leaseAcquiredRecordDigest"]
            )
            self.assertEqual(old_lease["state"], "active")
            self.assertNotIn("terminal", old_lease)
            old_attempts = [
                value for value in initial["taskTestAttempts"].values()
                if value["start"].get(
                    "executionLeaseAcquiredRecordDigest"
                ) == report["leaseAcquiredRecordDigest"]
            ]
            self.assertEqual(
                len(old_attempts),
                0 if expected_binding == "absent" else 1,
            )
            if old_attempts:
                self.assertEqual(
                    old_attempts[0]["start"]["recordDigest"],
                    report["attemptStartRecordDigest"],
                )
                self.assertEqual(
                    old_attempts[0]["state"],
                    (
                        "task-tests-running"
                        if expected_binding == "running"
                        else "task-tests-indeterminate-no-replay"
                    ),
                )

            builtins.__dict__.pop(self._IMPORT_WITNESS_KEY, None)
            _cold_outer, cold_context = self._append_outer(
                fixture["root"], fixture["repository"], fixture["argv"]
            )
            with mock.patch.object(
                module,
                "_run_task_test_targets",
                wraps=module._run_task_test_targets,
            ) as runner:
                self.assertEqual(
                    module._dispatch_command(
                        fixture["argv"], context=cold_context
                    ),
                    0,
                )
            self.assertEqual(runner.call_count, 1)

            recovered = module.recover_run_state(fixture["root"])
            leases = sorted(
                recovered["taskTestExecutionLeases"].values(),
                key=lambda value: value["acquired"]["generation"],
            )
            self.assertEqual(
                [value["acquired"]["generation"] for value in leases],
                [1, 2],
            )
            old_lease, fresh_lease = leases
            self.assertEqual(
                old_lease["acquired"]["recordDigest"],
                report["leaseAcquiredRecordDigest"],
            )
            self.assertEqual(old_lease["state"], "owner-lost")
            lease_terminal = old_lease["terminal"]
            self.assertEqual(
                (
                    lease_terminal["disposition"],
                    lease_terminal["attemptBinding"],
                    lease_terminal["attemptStartRecordDigest"],
                    lease_terminal["taskTestTerminalRecordDigest"],
                ),
                (
                    "owner-lost", expected_binding,
                    report["attemptStartRecordDigest"],
                    report["taskTestTerminalRecordDigest"],
                ),
            )
            old_lease_terminals = [
                row for row in recovered["records"]
                if row["operationKind"]
                == "task-test-execution-lease-terminal"
                and row.get("leaseAcquiredRecordDigest")
                == report["leaseAcquiredRecordDigest"]
            ]
            self.assertEqual(old_lease_terminals, [lease_terminal])

            projected_outer = recovered["sterileInvocations"][
                old_outer["recordDigest"]
            ]
            self.assertEqual(projected_outer["state"], "failed")
            self.assertEqual(projected_outer["completion"]["exitCode"], 2)
            outer_completions = [
                row for row in recovered["records"]
                if row["operationKind"]
                == "sterile-invocation-completed-linked"
                and row.get("invocationStartRecordDigest")
                == old_outer["recordDigest"]
            ]
            self.assertEqual(
                outer_completions, [projected_outer["completion"]]
            )

            old_attempts = [
                value for value in recovered[
                    "taskTestAttempts"
                ].values()
                if value["start"].get(
                    "executionLeaseAcquiredRecordDigest"
                ) == report["leaseAcquiredRecordDigest"]
            ]
            fresh_attempts = [
                value for value in recovered[
                    "taskTestAttempts"
                ].values()
                if value["start"].get(
                    "executionLeaseAcquiredRecordDigest"
                ) == fresh_lease["acquired"]["recordDigest"]
            ]
            self.assertEqual(len(fresh_attempts), 1)
            self.assertEqual(fresh_attempts[0]["state"], "task-tests-success")

            ordered = [old_lease["acquired"]["sequence"]]
            if expected_binding != "absent":
                self.assertEqual(len(old_attempts), 1)
                old_attempt = old_attempts[0]
                ordered.append(old_attempt["start"]["sequence"])
                if expected_binding == "terminal":
                    self.assertEqual(
                        old_attempt["terminal"]["recordDigest"],
                        report["taskTestTerminalRecordDigest"],
                    )
                    ordered.append(old_attempt["terminal"]["sequence"])
                ordered.append(lease_terminal["sequence"])
                if expected_binding == "running":
                    terminal = old_attempt["terminal"]
                    self.assertEqual(
                        (
                            old_attempt["state"],
                            terminal["terminalAuthority"],
                            terminal["result"]["reasonCode"],
                        ),
                        (
                            "task-tests-indeterminate-no-replay",
                            "closedLeaseRecovery",
                            "durable-start-no-terminal",
                        ),
                    )
                    ordered.append(terminal["sequence"])
            else:
                self.assertEqual(old_attempts, [])
                ordered.append(lease_terminal["sequence"])
            ordered.extend((
                projected_outer["completion"]["sequence"],
                fresh_lease["acquired"]["sequence"],
            ))
            self.assertEqual(ordered, sorted(ordered))

    def test_real_process_death_after_running_start_recovers_without_replay(self):
        """Break caught: os._exit strands a running lease forever."""

        self._assert_real_process_death_recovery(
            case="recover-running", expected_binding="running"
        )

    def test_real_process_death_after_acquisition_closes_absent_owner(self):
        """Break caught: os._exit before start blocks every later run."""

        self._assert_real_process_death_recovery(
            case="recover-acquired", expected_binding="absent"
        )

    def test_real_process_death_after_attempt_terminal_preserves_terminal(self):
        """Break caught: os._exit after terminal duplicates old evidence."""

        self._assert_real_process_death_recovery(
            case="recover-terminal", expected_binding="terminal"
        )

