    def test_v3_attempt_and_terminal_bind_explicit_execution_lease_authority(self):
        """Break caught: task evidence is publishable without lease authority."""

        base_fields = {
            "schemaVersion", "runId", "sequence", "previousRecordDigest",
            "recordId", "operationKind", "inputDigest",
            "declaredFilenames", "completionState", "recordDigest",
        }
        lease_terminal_fields = {
            "executionContractVersion", "executionContractDigest",
            "leaseId", "holderId", "generation", "frontierId",
            "frontierStartRecordDigest", "leaseAcquiredRecordDigest",
            "lockIdentityDigest", "disposition", "attemptBinding",
            "attemptStartRecordDigest", "taskTestTerminalRecordDigest",
        }
        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._fixture(Path(temporary))
            outer, context = self._append_outer(
                fixture["root"], fixture["repository"], fixture["argv"]
            )
            self.assertEqual(
                module._dispatch_command(fixture["argv"], context=context),
                0,
            )
            recovered = module.recover_run_state(fixture["root"])
            acquired = [
                row for row in recovered["records"]
                if row["operationKind"]
                == "task-test-execution-lease-acquired"
            ]
            lease_terminals = [
                row for row in recovered["records"]
                if row["operationKind"]
                == "task-test-execution-lease-terminal"
            ]
            starts = [
                row for row in recovered["records"]
                if row["operationKind"] == "task-test-attempt-started"
            ]
            terminals = [
                row for row in recovered["records"]
                if row["operationKind"] == "task-test-attempt-terminal"
            ]
            self.assertEqual(
                [len(acquired), len(starts), len(terminals),
                 len(lease_terminals)],
                [1, 1, 1, 1],
            )
            lease, start, terminal, lease_terminal = (
                acquired[0], starts[0], terminals[0], lease_terminals[0]
            )
            lease_digest = lease["recordDigest"]
            self.assertEqual(
                start["executionLeaseAcquiredRecordDigest"], lease_digest
            )
            self.assertEqual(
                start["subject"]["schemaVersion"],
                "qinao.task-test-subject.v4",
            )
            self.assertEqual(terminal["terminalAuthority"], "incumbent")
            self.assertEqual(
                terminal["executionLeaseAcquiredRecordDigest"],
                lease_digest,
            )
            result = terminal["result"]
            self.assertEqual(
                result["schemaVersion"], "qinao.task-test-result.v4"
            )
            self.assertEqual(result["terminalAuthority"], "incumbent")
            self.assertEqual(
                result["executionLeaseAcquiredRecordDigest"],
                lease_digest,
            )
            self.assertEqual(
                terminal["executionLeaseAcquiredRecordDigest"],
                result["executionLeaseAcquiredRecordDigest"],
            )
            self.assertGreater(terminal["sequence"], start["sequence"])
            self.assertGreater(
                lease_terminal["sequence"], terminal["sequence"]
            )
            self.assertEqual(
                set(lease_terminal), base_fields | lease_terminal_fields
            )
            for field in (
                "executionContractVersion", "executionContractDigest",
                "leaseId", "holderId", "generation", "frontierId",
                "frontierStartRecordDigest", "lockIdentityDigest",
            ):
                self.assertEqual(lease_terminal[field], lease[field])
            self.assertEqual(
                lease_terminal["leaseAcquiredRecordDigest"], lease_digest
            )
            self.assertEqual(lease_terminal["attemptBinding"], "terminal")
            self.assertEqual(
                lease_terminal["attemptStartRecordDigest"],
                start["recordDigest"],
            )
            self.assertEqual(
                lease_terminal["taskTestTerminalRecordDigest"],
                terminal["recordDigest"],
            )
            self.assertIn(
                lease_terminal["disposition"],
                self._EXECUTION_LEASE_DISPOSITIONS,
            )
            self.assertEqual(lease_terminal["disposition"], "completed")
            terminal_input = {
                "schemaVersion": (
                    "qinao.task-test-execution-lease-terminal-input.v2"
                ),
                **{
                    field: lease_terminal[field]
                    for field in lease_terminal_fields
                },
            }
            self.assertEqual(
                lease_terminal["inputDigest"],
                hashlib.sha256(
                    module.canonical_json_bytes(terminal_input)
                ).hexdigest(),
            )


    def test_ledger_public_writers_preserve_exact_signatures_and_binding(self):
        """Break caught: capability wrappers erase the ordinary call contract."""

        self.assertEqual(
            str(inspect.signature(module.LedgerTransaction.append_record)),
            "(self, recovered: 'Mapping[str, Any]', operation_kind: 'str', "
            "input_digest: 'str', declared_filenames: 'Sequence[str]', "
            "completion_state: 'str', payload: 'Mapping[str, Any]', *, "
            "predecessor: 'Optional[Mapping[str, Any]]' = None, "
            "atomic_publication: 'bool' = False, "
            "_pre_rename_validator: 'Optional[Any]' = None, "
            "_execution_append_capability: 'Optional[Any]' = None, "
            "_publication_receipt_sink: 'Optional[List[Any]]' = None) -> "
            "'Dict[str, Any]'",
        )
        self.assertEqual(
            str(inspect.signature(module.LedgerTransaction.write_record_atomic)),
            "(self, sequence: 'int', record: 'Mapping[str, Any]', *, "
            "_pre_rename_validator: 'Optional[Any]' = None, "
            "_execution_append_capability: 'Optional[Any]' = None) -> 'Any'",
        )
        self.assertEqual(
            str(inspect.signature(module._append_record)),
            "(root: 'Path', operation_kind: 'str', input_digest: 'str', "
            "declared_filenames: 'Sequence[str]', completion_state: 'str', "
            "payload: 'Mapping[str, Any]', *, "
            "state_validator: 'Optional[Any]' = None, "
            "allow_resource_drift_id: 'Optional[str]' = None, "
            "atomic_publication: 'bool' = False, "
            "_pre_rename_validator: 'Optional[Any]' = None, "
            "_execution_append_capability: 'Optional[Any]' = None, "
            "_faults: 'Optional[DurabilityFaults]' = None) -> "
            "'Dict[str, Any]'",
        )

        payload = {
            "frontierId": "a" * 32,
            "frontierKind": "remote-mutation",
            "declaredPaths": [],
            "expectedTests": [],
            "allowedChildKinds": [],
            "parentFrontierId": None,
            "componentKind": None,
            "resourceId": None,
            "operationClass": None,
            "operationContext": None,
        }

        def initialize(base, label):
            parent = base / label
            parent.mkdir()
            root = _new_run_root(parent)
            module.init_run_state(root, _identity_fields(parent), bootstrap_imports=[])
            return root

        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)
            root = initialize(base, "first")
            with module.LedgerTransaction(
                root, operation_kind="ordinary-call-contract"
            ) as transaction:
                recovered = transaction.recover()
                positional = transaction.append_record(
                    recovered, "frontier-start", "1" * 64, [], "open", payload
                )
                keyword = transaction.append_record(
                    recovered=transaction.recover(),
                    operation_kind="frontier-start",
                    input_digest="2" * 64,
                    declared_filenames=[],
                    completion_state="open",
                    payload=payload,
                )
                self.assertEqual(positional["sequence"], 2)
                self.assertEqual(keyword["sequence"], 3)

            root = initialize(base, "second")
            with module.LedgerTransaction(
                root, operation_kind="ordinary-call-contract"
            ) as transaction:
                recovered = transaction.recover()
                first = module._new_record(
                    recovered["identity"], recovered["nextSequence"],
                    recovered["records"][-1]["recordDigest"],
                    "frontier-start", "3" * 64, [], "open", payload,
                )
                second = module._new_record(
                    recovered["identity"], recovered["nextSequence"] + 1,
                    first["recordDigest"], "frontier-start", "4" * 64,
                    [], "open", payload,
                )
                self.assertIsNone(
                    transaction.write_record_atomic(2, first)
                )
                self.assertIsNone(
                    transaction.write_record_atomic(sequence=3, record=second)
                )

            root = initialize(base, "third")
            positional = module._append_record(
                root, "frontier-start", "5" * 64, [], "open", payload
            )
            keyword = module._append_record(
                root=root,
                operation_kind="frontier-start",
                input_digest="6" * 64,
                declared_filenames=[],
                completion_state="open",
                payload=payload,
            )
            self.assertEqual(positional["sequence"], 2)
            self.assertEqual(keyword["sequence"], 3)

    def test_transaction_result_sink_is_delivered_after_successful_exit(self):
        """Break caught: a publication result leaks while the lock is active."""

        events = []
        transaction_ref = []

        def observe(boundary, _operation, _subject):
            transaction = transaction_ref[0]
            events.append((boundary, transaction._locked, bool(transaction._fds)))

        class ObservedSink(list):
            def append(sink, value):
                transaction = transaction_ref[0]
                events.append(("sink-append", transaction._locked, bool(transaction._fds)))
                return super().append(value)

        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._fixture(Path(temporary))
            outer, _context = self._append_outer(
                fixture["root"], fixture["repository"], fixture["argv"]
            )
            guard, payload, input_digest, capability = (
                self._prepared_execution_lease_acquisition(fixture, outer)
            )
            sink = ObservedSink()
            try:
                with module.LedgerTransaction(
                    fixture["root"],
                    operation_kind="task-test-execution-lease-acquired",
                    faults=module.DurabilityFaults(callback=observe),
                ) as transaction:
                    transaction_ref.append(transaction)
                    transaction.append_record(
                        transaction.recover(),
                        "task-test-execution-lease-acquired",
                        input_digest,
                        [],
                        "task-test-execution-lease-acquired",
                        payload,
                        atomic_publication=True,
                        _pre_rename_validator=lambda _record: None,
                        _execution_append_capability=capability,
                        _publication_receipt_sink=sink,
                    )
                events.append(("after-exit", transaction._locked, bool(transaction._fds)))
                observed = [
                    event for event in events
                    if event[0] in {
                        "record-atomic-publish", "record-stage-source-fsync",
                        "records-fsync", "unlock", "close", "sink-append",
                        "after-exit",
                    }
                ]
                self.assertEqual([event[0] for event in observed], [
                    "record-atomic-publish", "record-stage-source-fsync",
                    "records-fsync", "unlock", "close", "sink-append",
                    "after-exit",
                ])
                self.assertEqual(observed[3], ("unlock", False, True))
                self.assertEqual(observed[4], ("close", False, False))
                self.assertEqual(observed[5], ("sink-append", False, False))
                self.assertEqual(observed[6], ("after-exit", False, False))
                self.assertEqual(len(sink), 1)
            finally:
                self._cleanup_prepared_execution_guard(fixture, guard)

