    def test_receipt_sink_reentry_is_inert_until_delivery_commits(self):
        """A sink callback cannot consume the receipt being delivered."""

        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._fixture(Path(temporary))
            outer, _context = self._append_outer(
                fixture["root"], fixture["repository"], fixture["argv"]
            )
            guard, payload, input_digest, capability = (
                self._prepared_execution_lease_acquisition(fixture, outer)
            )
            private_token = getattr(
                guard,
                "_TaskTestExecutionLeaseGuard__execution_authority_token",
            )

            class ReentrantSink(list):
                expected_record = None
                captured = None
                consumed_during_append = False
                rejection = None

                def append(sink, value):
                    sink.captured = value
                    try:
                        module._consume_task_test_execution_publication_receipt(
                            value,
                            guard,
                            private_token,
                            fixture["root"],
                            sink.expected_record,
                        )
                    except module.AuditError as exc:
                        sink.rejection = str(exc)
                    else:
                        sink.consumed_during_append = True
                    return super().append(value)

            sink = ReentrantSink()
            try:
                with module.LedgerTransaction(
                    fixture["root"],
                    operation_kind="task-test-execution-lease-acquired",
                ) as transaction:
                    record = transaction.append_record(
                        transaction.recover(),
                        "task-test-execution-lease-acquired",
                        input_digest,
                        [],
                        "task-test-execution-lease-acquired",
                        payload,
                        atomic_publication=True,
                        _pre_rename_validator=lambda _record: None,
                        _execution_append_capability=capability,
                        _publication_receipt_sink=sink,
                    )
                    sink.expected_record = record
                self.assertFalse(sink.consumed_during_append)
                self.assertRegex(sink.rejection, "publication receipt")
                self.assertEqual(len(sink), 1)
                self.assertIs(sink[0], sink.captured)
                guard.bind_acquired(record, sink.pop())
                self.assertEqual(guard._acquired_record, record)
            finally:
                self._cleanup_prepared_execution_guard(fixture, guard)

