    def test_direct_internal_staged_continuation_without_preparation_is_rejected(self):
        """Break caught: a caller bypasses the atomic writer preparation."""

        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._fixture(Path(temporary))
            outer, _context = self._append_outer(
                fixture["root"], fixture["repository"], fixture["argv"]
            )
            guard, payload, input_digest, capability = (
                self._prepared_execution_lease_acquisition(fixture, outer)
            )
            before = len(module.recover_run_state(fixture["root"])["records"])
            rejected = False
            try:
                with module.LedgerTransaction(
                    fixture["root"],
                    operation_kind="task-test-execution-lease-acquired",
                ) as transaction:
                    recovered = transaction.recover()
                    sequence = recovered["nextSequence"]
                    record = module._new_record(
                        recovered["identity"],
                        sequence,
                        recovered["records"][-1]["recordDigest"],
                        "task-test-execution-lease-acquired",
                        input_digest,
                        [],
                        "task-test-execution-lease-acquired",
                        payload,
                    )
                    staging_name = (
                        ".qinao-record-stage-%016d-%s.json"
                        % (sequence, "a" * 16)
                    )
                    final_name = "%016d.json" % sequence
                    scratch_fd = transaction._fds["scratch"]
                    flags = (
                        os.O_RDWR | os.O_CREAT | os.O_EXCL
                        | getattr(os, "O_NOFOLLOW", 0)
                        | getattr(os, "O_CLOEXEC", 0)
                    )
                    descriptor = module._open_owned_at(
                        scratch_fd, staging_name, flags, 0o600
                    )
                    try:
                        descriptor.chmod(0o600)
                        module._write_owned_all(
                            descriptor, module.canonical_json_bytes(record)
                        )
                        descriptor._operate(os.fsync)
                        scratch_fd._operate(os.fsync)
                        try:
                            module._publish_task_test_execution_staged_once(
                                capability,
                                transaction,
                                descriptor,
                                staging_name,
                                final_name,
                            )
                        except module.AuditError:
                            rejected = True
                    finally:
                        descriptor.close()
                        try:
                            module._fd_at(scratch_fd, os.unlink, staging_name)
                        except FileNotFoundError:
                            pass
                after = len(
                    module.recover_run_state(fixture["root"])["records"]
                )
                self.assertEqual((rejected, after), (True, before))
            finally:
                self._cleanup_prepared_execution_guard(fixture, guard)

