    def test_receipt_fd_close_fault_attempts_both_closes_without_resurrection(self):
        """Break caught: the first receipt close skips the second close."""

        class CloseAbort(BaseException):
            pass

        for phase in ("finish", "consume"):
            with self.subTest(phase=phase), tempfile.TemporaryDirectory() as temporary:
                fixture = self._fixture(Path(temporary))
                outer, _context = self._append_outer(
                    fixture["root"], fixture["repository"], fixture["argv"]
                )
                guard, payload, input_digest, capability = (
                    self._prepared_execution_lease_acquisition(
                        fixture, outer
                    )
                )
                sink = []
                record = receipt = None
                real_open = module.os.open
                real_close = module.os.close
                real_fstat = module.os.fstat
                opened = {}
                attempts = []
                armed = [False]
                injected = CloseAbort(phase + " record close abort")

                def tracked_open(path, *args, **kwargs):
                    descriptor = real_open(path, *args, **kwargs)
                    if armed[0]:
                        parent = kwargs.get("dir_fd")
                        if (path == "records" and parent
                                == guard._ledger_fd.generation_descriptor):
                            opened["records"] = descriptor
                        elif (
                            isinstance(path, str)
                            and path.endswith(".json")
                            and parent == opened.get("records")
                        ):
                            opened["record"] = descriptor
                    return descriptor

                def fault_close(descriptor):
                    if armed[0] and descriptor == opened.get("record"):
                        attempts.append("record")
                        real_close(descriptor)
                        raise injected
                    if armed[0] and descriptor == opened.get("records"):
                        attempts.append("records")
                    return real_close(descriptor)

                try:
                    if phase == "consume":
                        record, receipt = (
                            self._publish_prepared_execution_lease_acquisition(
                                fixture,
                                guard,
                                payload,
                                input_digest,
                                capability,
                            )
                        )
                    module.os.open = tracked_open
                    module.os.close = fault_close
                    with self.assertRaises(CloseAbort) as raised:
                        if phase == "finish":
                            with module.LedgerTransaction(
                                fixture["root"],
                                operation_kind=(
                                    "task-test-execution-lease-acquired"
                                ),
                            ) as transaction:
                                record = transaction.append_record(
                                    transaction.recover(),
                                    "task-test-execution-lease-acquired",
                                    input_digest,
                                    [],
                                    "task-test-execution-lease-acquired",
                                    payload,
                                    atomic_publication=True,
                                    _pre_rename_validator=(
                                        lambda _record: None
                                    ),
                                    _execution_append_capability=capability,
                                    _publication_receipt_sink=sink,
                                )
                                armed[0] = True
                        else:
                            armed[0] = True
                            private_token = getattr(
                                guard,
                                "_TaskTestExecutionLeaseGuard__"
                                "execution_authority_token",
                            )
                            module._consume_task_test_execution_publication_receipt(
                                receipt,
                                guard,
                                private_token,
                                fixture["root"],
                                record,
                            )
                    self.assertIs(raised.exception, injected)
                finally:
                    module.os.open = real_open
                    module.os.close = real_close
                    for descriptor in tuple(opened.values()):
                        try:
                            real_fstat(descriptor)
                        except OSError:
                            continue
                        real_close(descriptor)

                pending_cleared = guard._pending_acquisition is None
                receipts = inspect.getclosurevars(
                    module._consume_task_test_execution_publication_receipt
                ).nonlocals["receipts"]
                candidate = receipt if phase == "consume" else (
                    sink[0] if sink else None
                )
                registered = (
                    candidate is not None and id(candidate) in receipts
                )
                bindable = False
                if candidate is not None and record is not None:
                    try:
                        guard.bind_acquired(record, candidate)
                    except module.AuditError:
                        pass
                    else:
                        bindable = True
                try:
                    self.assertEqual(
                        (
                            attempts, registered, bindable,
                            pending_cleared,
                        ),
                        (["record", "records"], False, False, True),
                    )
                finally:
                    self._cleanup_prepared_execution_guard(fixture, guard)

    def test_receipt_reopen_error_retains_ordered_sibling_close_evidence(self):
        """Break caught: normalized reopen failure drops both later cleanup errors."""
        for phase in ("finish", "consume"):
            with self.subTest(phase=phase), tempfile.TemporaryDirectory() as temporary:
                fixture = self._fixture(Path(temporary))
                outer, _context = self._append_outer(fixture["root"], fixture["repository"], fixture["argv"])
                guard, payload, input_digest, capability = self._prepared_execution_lease_acquisition(fixture, outer)
                real_open, real_read, real_close = module.os.open, module.os.read, module.os.close
                opened, reads, closes, sink = {}, [], [], []
                primary = KeyboardInterrupt("receipt read interrupted")
                cleanups = {"record": SystemExit("record close interrupted"),
                            "records": RuntimeError("records close interrupted")}
                armed = [False]
                def open_fd(path, *args, **kwargs):
                    fd = real_open(path, *args, **kwargs)
                    if armed[0]:
                        if path == "records" and kwargs.get("dir_fd") == guard._ledger_fd.generation_descriptor:
                            opened["records"] = fd
                        elif kwargs.get("dir_fd") == opened.get("records"):
                            opened["record"] = fd
                    return fd
                def read(fd, count):
                    if armed[0] and fd == opened.get("record"):
                        reads.append(fd)
                        raise primary
                    return real_read(fd, count)
                def close(fd):
                    real_close(fd)
                    for label in ("record", "records"):
                        if armed[0] and fd == opened.get(label):
                            closes.append(label)
                            raise cleanups[label]
                try:
                    if phase == "consume":
                        record, receipt = self._publish_prepared_execution_lease_acquisition(
                            fixture, guard, payload, input_digest, capability)
                    with mock.patch.object(module.os, "open", open_fd), \
                            mock.patch.object(module.os, "read", read), \
                            mock.patch.object(module.os, "close", close):
                        with self.assertRaises(module.AuditError) as caught:
                            if phase == "finish":
                                with module.LedgerTransaction(fixture["root"], operation_kind="task-test-execution-lease-acquired") as transaction:
                                    transaction.append_record(
                                        transaction.recover(), "task-test-execution-lease-acquired",
                                        input_digest, [], "task-test-execution-lease-acquired", payload,
                                        atomic_publication=True, _pre_rename_validator=lambda _record: None,
                                        _execution_append_capability=capability, _publication_receipt_sink=sink)
                                    armed[0] = True
                            else:
                                armed[0] = True
                                module._consume_task_test_execution_publication_receipt(
                                    receipt, guard,
                                    guard._TaskTestExecutionLeaseGuard__execution_authority_token,
                                    fixture["root"], record)
                    self.assertEqual(reads, [opened["record"]])
                    self.assertEqual(closes, ["record", "records"])
                    self.assertIs(caught.exception.__cause__, primary)
                    self.assertEqual(getattr(caught.exception, "cleanup_errors", []), [cleanups["record"]])
                    self.assertEqual(cleanups["record"].cleanup_errors, [cleanups["records"]])
                    self.assertIsNone(guard._pending_acquisition)
                    self.assertEqual(sink, [])
                finally:
                    self._cleanup_prepared_execution_guard(fixture, guard)

    def test_quarantine_between_projector_and_reserved_rename_prevents_publication(self):
        """Break caught: cancellation can complete before the reserved rename."""

        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._fixture(Path(temporary))
            outer, _context = self._append_outer(
                fixture["root"], fixture["repository"], fixture["argv"]
            )
            guard, payload, input_digest, capability = (
                self._prepared_execution_lease_acquisition(fixture, outer)
            )
            records_path = fixture["root"] / "ledger" / "records"
            before = len(os.listdir(records_path))
            sink = []
            window_open = threading.Event()
            revoked = threading.Event()
            thread_errors = []
            real_cdll = module.ctypes.CDLL
            real_library = real_cdll(None, use_errno=True)
            rename_lookups = [0]

            class RenameGateLibrary:
                def __init__(self, library):
                    self.library = library

                def __getattr__(self, name):
                    return getattr(self.library, name)

                @property
                def renameatx_np(self):
                    rename_lookups[0] += 1
                    if rename_lookups[0] == 2:
                        window_open.set()
                        if not revoked.wait(5):
                            raise AssertionError(
                                "quarantine thread did not finish before rename"
                            )
                    return self.library.renameatx_np

            def controlled_cdll(*args, **kwargs):
                return RenameGateLibrary(real_cdll(*args, **kwargs))

            def cancel_from_second_thread():
                try:
                    if not window_open.wait(5):
                        raise AssertionError("reserved rename window was absent")
                    guard.quarantine()
                except BaseException as exc:
                    thread_errors.append(exc)
                finally:
                    revoked.set()

            canceller = threading.Thread(
                target=cancel_from_second_thread,
                name="qinao-reserved-rename-canceller",
            )
            canceller.start()
            rejected = False
            module.ctypes.CDLL = controlled_cdll
            try:
                try:
                    with module.LedgerTransaction(
                        fixture["root"],
                        operation_kind="task-test-execution-lease-acquired",
                    ) as transaction:
                        transaction.append_record(
                            transaction.recover(),
                            "task-test-execution-lease-acquired",
                            input_digest,
                            [],
                            "task-test-execution-lease-acquired",
                            payload,
                            atomic_publication=True,
                            _pre_rename_validator=lambda _record: None,
                            _execution_append_capability=capability,
                            _publication_receipt_sink=sink,
                        )
                except module.AuditError:
                    rejected = True
            finally:
                module.ctypes.CDLL = real_cdll
                revoked.set()
                canceller.join(5)
            try:
                recovered = module.recover_run_state(fixture["root"])
                self.assertFalse(canceller.is_alive())
                self.assertEqual(thread_errors, [])
                self.assertTrue(window_open.is_set())
                self.assertEqual(rename_lookups, [2])
                self.assertTrue(revoked.is_set())
                self.assertEqual(
                    (
                        rejected,
                        recovered["classification"],
                        len(os.listdir(records_path)),
                        sink,
                        guard._pending_acquisition,
                    ),
                    (True, "complete", before, [], None),
                )
            finally:
                self._cleanup_prepared_execution_guard(fixture, guard)

