    def test_credential_fill_failed_final_anchor_settlement_destroys_retained_backing(self):
        """Break caught: final close cancels delivery but leaves secret bytes in traceback locals."""
        for error_type, interrupt_release in ((None, False), (OSError, False),
                (KeyboardInterrupt, False), (SystemExit, False),
                (OSError, True), (KeyboardInterrupt, True), (SystemExit, True)):
            with self.subTest(error_type=error_type, interrupt_release=interrupt_release), tempfile.TemporaryDirectory() as temporary:
                base = Path(temporary)
                repository, _source, _dangling = self._repository_fixture(base)
                root = self._run_root(base, repository)
                preflight, _full = self._preflights(repository)
                capsule, snapshot = self._prepare_capsule(root, "credential-read", preflight)
                runtime = _owned_process_runtime_fixture(self,
                    process_seam=lambda **request: (0, self._HELPER_RESPONSE, b""), repository=repository)
                real_process, real_close = runtime._run_process, os.close
                real_release = module.OwnedSecretBuffer.release
                source = os.open(os.devnull, os.O_RDONLY)
                backings, views, anchors, closes, escaped, releases = [], [], [], [], [], []
                primary = None if error_type is None else error_type("credential anchor close interrupted")
                wipe_error = SystemExit("credential release interrupted mid-wipe")
                def process(_runtime, command, **request):
                    result = real_process(command, **request)
                    self.assertEqual(result[0], 0)
                    self.assertEqual(result[1], self._HELPER_RESPONSE)
                    backings.extend((request["stdout_owner"], request["stderr_owner"]))
                    views.extend(memoryview(backing) for backing in backings)
                    anchors.append(request["cwd_anchor_fd"])
                    return result
                def close(fd):
                    real_close(fd)
                    if anchors and fd == anchors[0].generation_descriptor:
                        closes.append(fd)
                        if primary is not None:
                            os.dup2(source, fd)
                            raise primary
                def release(secret):
                    if interrupt_release and backings and secret._owner is backings[0]:
                        releases.append(secret)
                        def interrupt(frame, event, arg):
                            if (event == "line" and frame.f_code is real_release.__code__
                                    and frame.f_locals.get("index") == 1):
                                raise wipe_error
                            return interrupt
                        previous = sys.gettrace()
                        try:
                            sys.settrace(interrupt)
                            return real_release(secret)
                        finally:
                            sys.settrace(previous)
                    return real_release(secret)
                delivered = None
                try:
                    with mock.patch.object(module.ConcreteRuntimeCapability, "_run_process", process), \
                            mock.patch.object(module.os, "close", close), \
                            mock.patch.object(module.OwnedSecretBuffer, "release", release):
                        try:
                            delivered = runtime.credential_fill(module._FIXED_GIT_CREDENTIAL_INPUT,
                                capsule=capsule, snapshot=snapshot, preflight=preflight)
                        except BaseException as exc:
                            escaped.append(exc)  # keep the real traceback and every frame alive
                    self.assertEqual(len(backings), 2)
                    self.assertEqual(closes, [anchors[0].generation_descriptor])
                    if primary is None:
                        self.assertEqual(escaped, [])
                        self.assertIs(delivered.owner(), backings[0])
                        self.assertEqual(bytes(views[0]), self._HELPER_RESPONSE)
                        self.assertEqual(anchors[0].phase, "closed")
                    else:
                        self.assertIsNone(delivered)
                        self.assertEqual(len(escaped), 1)
                        self.assertIsNotNone(escaped[0].__traceback__)
                        self.assertIs(escaped[0].__cause__ if error_type is OSError else escaped[0], primary)
                        self.assertEqual(anchors[0].phase, "uncertain")
                        self.assertEqual(os.fstat(closes[0]), os.fstat(source))
                        self.assertEqual(bytes(views[0]), bytes(len(views[0])))
                        self.assertEqual(backings[0], bytearray(len(backings[0])))
                        if interrupt_release:
                            self.assertEqual(len(releases), 1)
                            self.assertEqual(escaped[0].cleanup_errors, [wipe_error])
                    self.assertEqual(bytes(views[1]), bytes(len(views[1])))
                finally:
                    if delivered is not None:
                        real_release(delivered)
                    if primary is not None and closes:
                        real_close(closes[0])  # independently owned replacement, never the uncertain slot
                    real_close(source)

    def test_credential_fill_rejects_helper_path_or_bytes_drift_pre_child(self):
        """Break caught: sealed helper identity is never reopened at use."""

        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)
            repository, _source_oid, _dangling = (
                self._repository_fixture(base)
            )
            root = self._run_root(base, repository)
            local_preflight, _full_preflight = self._preflights(repository)
            git_path = Path("/usr/bin/git").resolve(strict=True)
            git_stat = git_path.lstat()
            git_bytes = git_path.read_bytes()

            def stale_bytes(row):
                stale = b"stale osxkeychain helper bytes\n"
                row["fileByteCount"] = len(stale)
                row["fileSha256"] = hashlib.sha256(stale).hexdigest()

            def drifted_path(row):
                row["absolutePath"] = str(git_path)
                row["absolutePathDigest"] = module._network_redacted_value(
                    "tool-path:git-credential-osxkeychain",
                    str(git_path).encode("utf-8", "strict"),
                )["valueDigest"]
                row["fileMode"] = stat.S_IMODE(git_stat.st_mode)
                row["fileByteCount"] = len(git_bytes)
                row["fileSha256"] = hashlib.sha256(git_bytes).hexdigest()

            for drift, mutate in (
                ("bytes", stale_bytes),
                ("path", drifted_path),
            ):
                with self.subTest(drift=drift):
                    forged = self._resign_preflight_with_helper_mutation(
                        local_preflight, mutate
                    )
                    calls = []
                    runtime = module.ConcreteRuntimeCapability(
                        process_seam=lambda **request: (
                            calls.append(dict(request))
                            or (0, self._HELPER_RESPONSE, b"")
                        ),
                        repository=repository,
                    )
                    secret = None
                    try:
                        with self.assertRaises(module.AuditError):
                            capsule, snapshot = self._prepare_capsule(
                                root, "credential-read", forged
                            )
                            secret = runtime.credential_fill(
                                module._FIXED_GIT_CREDENTIAL_INPUT,
                                capsule=capsule,
                                snapshot=snapshot,
                                preflight=forged,
                            )
                    finally:
                        if isinstance(secret, module.OwnedSecretBuffer):
                            secret.release()
                    self.assertEqual(calls, [])

