            parameters = inspect.signature(issue).parameters
            self.assertIn("mint_permit", parameters)
            self.assertEqual(
                parameters["mint_permit"].kind,
                inspect.Parameter.KEYWORD_ONLY,
            )
            self.assertIs(
                parameters["mint_permit"].default,
                inspect.Parameter.empty,
            )
            common = {
                "attempt": {"recordDigest": "a" * 64},
                "consumption": {"recordDigest": "b" * 64},
                "operation": "ls-remote",
                "argv": fixture["argv"],
                "preflight": fixture["preflight"],
                "manifest": fixture["manifest"],
                "capsule": fixture["capsule"],
                "snapshot": fixture["snapshot"],
                "broker": broker,
            }
            try:
                with mock.patch.object(
                    module,
                    "recover_run_state",
                    side_effect=AssertionError(
                        "missing permit reached durable recovery"
                    ),
                ) as recover, mock.patch.object(
                    module.os,
                    "open",
                    side_effect=AssertionError(
                        "missing permit reached cwd open"
                    ),
                ) as open_cwd:
                    with self.assertRaisesRegex(TypeError, "mint_permit"):
                        issue(fixture["root"], **common)
                    recover.assert_not_called()
                    open_cwd.assert_not_called()

                with mock.patch.object(
                    module,
                    "recover_run_state",
                    side_effect=AssertionError(
                        "forged permit reached durable recovery"
                    ),
                ) as recover, mock.patch.object(
                    module.os,
                    "open",
                    side_effect=AssertionError(
                        "forged permit reached cwd open"
                    ),
                ) as open_cwd:
                    with self.assertRaisesRegex(
                        module.AuditError,
                        "mint permit|permit.*authority|permit.*required",
                    ):
                        issue(
                            fixture["root"],
                            mint_permit=object(),
                            **common,
                        )
                    recover.assert_not_called()
                    open_cwd.assert_not_called()
            finally:
                broker.close()

