    def test_supervisor_path_or_bytes_drift_rejects_grant_before_child(self):
        """Break caught: consume ignores actual interpreter path/content drift."""
        for drift in ("path", "bytes", "none"):
            with self.subTest(drift=drift), tempfile.TemporaryDirectory() as temporary:
                base = Path(temporary)
                shell, other = base / "shell", base / "other-shell"
                payload = Path("/bin/sh").read_bytes()
                shell.write_bytes(payload)
                other.write_bytes(payload)
                shell.chmod(0o700)
                other.chmod(0o700)
                child_calls, requests, child_arguments = [], [], []
                with mock.patch.object(module, "_NETWORK_GIT_SUPERVISOR_EXECUTABLE", str(shell)):
                    fixture = self._fixture(base)
                    broker = self._broker(fixture["root"])
                    def process_seam(**request):
                        child_calls.append(dict(request))
                        self._consume_broker_child(request)
                        return 0, INDEPENDENT_NETWORK_GIT_LS_REMOTE_STDOUT, b""
                    runtime = self._owned_runtime(process_seam=process_seam, repository=fixture["repository"])
                    owned_runner = module._run_bounded_child
                    def run(command, **request):
                        if request.get("quiescence_callback") is not None:
                            child_arguments.append(request)
                        return owned_runner(command, **request)
                    class Transport:
                        def execute(inner_self, **request):
                            requests.append(request)
                            if drift == "bytes":
                                shell.write_bytes(payload + b"changed")
                            changed_path = mock.patch.object(module, "_NETWORK_GIT_SUPERVISOR_EXECUTABLE", str(other)) if drift == "path" else contextlib.nullcontext()
                            with changed_path:
                                return runtime.execute(**request)
                    try:
                        with mock.patch.object(module, "_run_bounded_child", run):
                            try:
                                terminal = module.execute_network_wrapper(
                                    fixture["root"], fixture["frontierId"], wrapper="network-git", operation="ls-remote",
                                    argv=fixture["argv"], preflight=fixture["preflight"], manifest=fixture["manifest"],
                                    transport=Transport(), credential_broker=broker,
                                    git_execution_capsule=fixture["capsule"], git_execution_capsule_snapshot=fixture["snapshot"])
                            except module.AuditError:
                                if drift == "none":
                                    raise
                            else:
                                if drift != "none":
                                    self.fail("changed interpreter admitted a child")
                                self.assertEqual(terminal["completionState"], "completed")
                        self.assertEqual(len(child_calls), 1 if drift == "none" else 0)
                        if drift == "none":
                            self.assertEqual(child_arguments[0].get("supervisor_executable"), str(shell))
                        else:
                            with self.assertRaises(module.AuditError):
                                runtime.execute(**requests[0])
                            self.assertEqual(child_calls, [])
                        self.assertFalse(module._current_thread_git_child_execution_grants())
                    finally:
                        broker.close()

