    def test_runtime_cleanup_failure_escapes_callers_handled_exception(self):
        """Break caught: a caller's except block swallows this call's cleanup."""
        self._runtime_cleanup_failure_case(interrupt_releases=False)

    def test_runtime_finalizer_failure_destroys_both_partially_released_outputs(self):
        """Break caught: interrupted release leaves secret bytes in tracebacks."""
        self._runtime_cleanup_failure_case(interrupt_releases=True)

    def test_runtime_bulk_wipe_failure_retains_evidence_and_cleans_other_output(self):
        """Break caught: failed fallback masks the primary or skips stderr."""
        self._runtime_cleanup_failure_case(
            interrupt_releases=True, interrupt_fallback=True
        )

    def _runtime_cleanup_failure_case(self, *, interrupt_releases, interrupt_fallback=False):
        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._fixture(Path(temporary))
            caller_error = ValueError("already handled by caller")
            primary = KeyboardInterrupt("finish cleanup interrupted")
            secondary = SystemExit("revoke cleanup interrupted")
            cleanup_calls, escaped, backings = [], [], []
            output_owners, release_calls = [], []
            retained_views, original_lengths = [], []
            release_errors = (
                KeyboardInterrupt("stdout release interrupted mid-wipe"),
                SystemExit("stderr release interrupted mid-wipe"),
            )
            interrupted_backings = []
            destruction_error = MemoryError("synthetic bulk-wipe allocation failure")
            destruction_faults = []
            real_finish = module._finish_git_child_execution_use
            real_revoke = module._revoke_git_child_execution_grant
            real_process = module.ConcreteRuntimeCapability._run_process
            real_take = module.OwnedSecretBuffer.take.__func__
            real_release = module.OwnedSecretBuffer.release

            def completed_child(**request):
                self._consume_broker_child(request)
                return 0, INDEPENDENT_NETWORK_GIT_LS_REMOTE_STDOUT, b"synthetic private stderr"

            runtime = self._owned_runtime(
                process_seam=completed_child,
                repository=fixture["repository"],
            )

            def fail_finish(*args, **kwargs):
                cleanup_calls.append("finish")
                real_finish(*args, **kwargs)
                raise primary

            def fail_revoke(*args, **kwargs):
                cleanup_calls.append("revoke")
                real_revoke(*args, **kwargs)
                raise secondary

            def track_process(runtime_self, command, **request):
                backings.extend((request["stdout_owner"], request["stderr_owner"]))
                result = real_process(runtime_self, command, **request)
                retained_views.extend(memoryview(backing) for backing in backings)
                original_lengths.extend(len(backing) for backing in backings)
                return result

            def track_take(cls, backing):
                output_owner = real_take(cls, backing)
                output_owners.append(output_owner)
                return output_owner

            def track_release(output_owner):
                if any(output_owner is candidate for candidate in output_owners):
                    release_calls.append(output_owner)
                    if interrupt_releases:
                        position = next(
                            index for index, candidate in enumerate(output_owners)
                            if output_owner is candidate
                        )
                        def interrupt_partial_wipe(frame, event, arg):
                            if (
                                event == "line"
                                and frame.f_code is real_release.__code__
                                and frame.f_locals.get("index") == 1
                            ):
                                interrupted_backings.append(frame.f_locals["owner"])
                                raise release_errors[position]
                            return interrupt_partial_wipe
                        previous = sys.gettrace()
                        try:
                            sys.settrace(interrupt_partial_wipe)
                            return real_release(output_owner)
                        finally:
                            sys.settrace(previous)
                return real_release(output_owner)

            source, first_line = inspect.getsourcelines(module.ConcreteRuntimeCapability.execute)
            fallback_line = first_line + next(
                index for index, line in enumerate(source)
                if 'backing[:] = b"\\x00" * len(backing)' in line
            )

            def fail_first_bulk_wipe(frame, event, arg):
                if (
                    interrupt_fallback and event == "line"
                    and frame.f_code.co_name == "destroy_outputs"
                    and frame.f_lineno == fallback_line
                    and frame.f_locals.get("backing") is backings[0]
                    and not destruction_faults
                ):
                    destruction_faults.append("stdout-fallback")
                    raise destruction_error
                return fail_first_bulk_wipe

            class Transport:
                def execute(inner_self, **request):
                    try:
                        raise caller_error
                    except ValueError:
                        with mock.patch.object(
                            module, "_finish_git_child_execution_use", side_effect=fail_finish
                        ), mock.patch.object(
                            module, "_revoke_git_child_execution_grant", side_effect=fail_revoke
                        ), mock.patch.object(
                            module.ConcreteRuntimeCapability, "_run_process", track_process
                        ), mock.patch.object(
                            module.OwnedSecretBuffer, "take", classmethod(track_take)
                        ), mock.patch.object(
                            module.OwnedSecretBuffer, "release", track_release
                        ):
                            previous = sys.gettrace()
                            try:
                                if interrupt_fallback:
                                    sys.settrace(fail_first_bulk_wipe)
                                result = runtime.execute(**request)
                            except BaseException as exc:
                                escaped.append(exc)
                            else:
                                # Dispose an incorrectly returned result in RED.
                                result["stdoutOwner"].release()
                                result["stderrOwner"].release()
                            finally:
                                sys.settrace(previous)
                    return _independent_network_git_transport_result("ls-remote")

            broker = self._broker(fixture["root"])
            try:
                module.execute_network_wrapper(
                    fixture["root"], fixture["frontierId"],
                    wrapper="network-git", operation="ls-remote",
                    argv=fixture["argv"], preflight=fixture["preflight"],
                    manifest=fixture["manifest"], transport=Transport(),
                    credential_broker=broker,
                    git_execution_capsule=fixture["capsule"],
                    git_execution_capsule_snapshot=fixture["snapshot"],
                )
            finally:
                broker.close()
            self.assertEqual(cleanup_calls, ["finish", "revoke"])
            self.assertEqual(len(escaped), 1, "runtime swallowed its cleanup failures")
            self.assertIs(escaped[0], primary)
            self.assertIn(secondary, getattr(primary, "cleanup_errors", ()))
            if interrupt_releases:
                expected_errors = [secondary, release_errors[0]]
                if interrupt_fallback:
                    expected_errors.append(destruction_error)
                expected_errors.append(release_errors[1])
                self.assertEqual(
                    primary.cleanup_errors, expected_errors
                )
                self.assertEqual(len(interrupted_backings), 2)
                for index, backing in enumerate(backings):
                    self.assertIs(interrupted_backings[index], backing)
                    self.assertIsNotNone(release_errors[index].__traceback__)
            self.assertEqual(getattr(caller_error, "cleanup_errors", ()), ())
            self.assertEqual(len(backings), 2)
            self.assertEqual(len(output_owners), 2)
            for output_owner in output_owners:
                self.assertEqual(sum(value is output_owner for value in release_calls), 1)
            if interrupt_fallback:
                self.assertEqual(destruction_faults, ["stdout-fallback"])
                self.assertTrue(any(backings[0]))
            for backing in backings[1 if interrupt_fallback else 0:]:
                self.assertEqual(backing, bytearray(len(backing)))
            for index, view in enumerate(retained_views):
                self.assertIs(view.obj, backings[index])
                self.assertEqual(len(view), original_lengths[index])
                if not interrupt_fallback or index != 0:
                    self.assertTrue(all(value == 0 for value in view))
            if interrupt_fallback:
                # Dispose synthetic residue after checking the documented limit.
                real_release(output_owners[0])

    def test_live_spawn_blocks_parallel_recovery_until_completed(self):
        """Break caught: recovery terminalizes while a child is starting."""

        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._fixture(Path(temporary))
            spawn_admitted = threading.Event()
            release_spawn = threading.Event()
            child_calls = []
            wrapper_results = []
            wrapper_errors = []
            real_run_child = module._run_git_child_execution
            wrapper_thread = None

            def process_seam(**request):
                child_calls.append(dict(request))
                self._consume_broker_child(request)
                return 0, INDEPENDENT_NETWORK_GIT_LS_REMOTE_STDOUT, b""

            runtime = self._owned_runtime(
                process_seam=process_seam,
                repository=fixture["repository"],
            )

            class Transport:
                def execute(inner_self, **request):
                    return runtime.execute(**request)

            def hold_after_spawn_admission(grant, runner):
                def held_runner(mark_quiescent, lease_fd):
                    spawn_admitted.set()
                    if not release_spawn.wait(10):
                        raise AssertionError(
                            "Git child spawn admission was not released"
                        )
                    return runner(mark_quiescent, lease_fd)

                return real_run_child(grant, held_runner)

            def run_wrapper():
                broker = self._broker(fixture["root"])
                try:
                    wrapper_results.append(
                        module.execute_network_wrapper(
                            fixture["root"], fixture["frontierId"],
                            wrapper="network-git",
                            operation="ls-remote",
                            argv=fixture["argv"],
                            preflight=fixture["preflight"],
                            manifest=fixture["manifest"],
                            transport=Transport(),
                            credential_broker=broker,
                            git_execution_capsule=fixture["capsule"],
                            git_execution_capsule_snapshot=(
                                fixture["snapshot"]
                            ),
                        )
                    )
                except BaseException as exc:
                    wrapper_errors.append(exc)
                finally:
                    broker.close()

            try:
                with mock.patch.object(
                    module,
                    "_run_git_child_execution",
                    side_effect=hold_after_spawn_admission,
                ):
                    wrapper_thread = threading.Thread(
                        target=run_wrapper,
                        name="qinao-live-spawn-owner",
                        daemon=True,
                    )
                    wrapper_thread.start()
                    self.assertTrue(
                        spawn_admitted.wait(10),
                        "wrapper never entered Git child spawn admission",
                    )

                    inflight = module.recover_run_state(fixture["root"])
                    self.assertEqual(inflight["classification"], "complete")
                    self.assertEqual(len(inflight["networkAttempts"]), 1)
                    selected = inflight["networkAttempts"][0]
                    self.assertEqual(selected["state"], "attempted-unknown")
                    logical_key = selected["logicalKey"]
                    sequence_before_recovery = inflight["nextSequence"]

                    with self.assertRaisesRegex(
                        module.AuditError,
                        "blocked by live execution|reservation is active",
                    ):
                        module.recover_network_attempt_no_network(
                            fixture["root"], logical_key
                        )

                    still_inflight = module.recover_run_state(
                        fixture["root"]
                    )
                    self.assertEqual(
                        still_inflight["nextSequence"],
                        sequence_before_recovery,
                    )
                    self.assertEqual(
                        still_inflight["networkAttempts"][0]["state"],
                        "attempted-unknown",
                    )
                    self.assertIsNone(
                        still_inflight["networkAttempts"][0].get(
                            "terminal"
                        )
                    )

                    release_spawn.set()
                    wrapper_thread.join(10)

                self.assertFalse(wrapper_thread.is_alive())
                self.assertEqual(wrapper_errors, [])
                self.assertEqual(len(wrapper_results), 1)
                self.assertEqual(
                    wrapper_results[0]["completionState"], "completed"
                )
                self.assertEqual(len(child_calls), 1)

                completed = module.recover_run_state(fixture["root"])
                self.assertEqual(completed["classification"], "complete")
                self.assertEqual(len(completed["networkAttempts"]), 1)
                self.assertEqual(
                    completed["networkAttempts"][0]["state"], "completed"
                )
                self.assertFalse(any(
                    record["operationKind"] == "network-terminal"
                    and record["completionState"] == "unknown-no-replay"
                    for record in completed["records"]
                ))
            finally:
                release_spawn.set()
                if wrapper_thread is not None:
                    wrapper_thread.join(10)

