    def test_intermediate_traversal_close_uncertainty_keeps_grant_arena(self):
        """Break caught: an empty final sink silently retires an uncertain traversal."""
        primary = KeyboardInterrupt("grant intermediate close")
        real_open, real_close = module._open_directory_fd, os.close
        def before_issue(api, owner, permit, root, attempt, consumption, arguments):
            source = os.open(os.devnull, os.O_RDONLY)
            fired = []
            def interrupt_close(fd):
                real_close(fd)
                if not fired:
                    fired.append(fd)
                    os.dup2(source, fd)
                    raise primary
            def traverse(*args, **kwargs):
                self.assertIs(owner["cwdArena"], kwargs["ownership_arena"])
                with mock.patch.object(module.os, "close", interrupt_close):
                    return real_open(*args, **kwargs)
            try:
                with mock.patch.object(module, "_open_directory_fd", traverse):
                    with self.assertRaises(KeyboardInterrupt) as caught:
                        api[1](root, mint_permit=permit, attempt=attempt,
                               consumption=consumption, **arguments)
                self.assertIs(caught.exception, primary)
                self.assertEqual(owner["state"], "poisoned")
                self.assertTrue(any(slot.phase == "uncertain" for slot in owner["cwdArena"].slots))
                self.assertIs(owner["slot"]["entriesByAttempt"][owner["attemptDigest"]], owner)
                self.assertIs(owner["slot"]["entriesByResource"][owner["resourceId"]], owner)
                self.assertEqual(len(fired), 1)
                self.assertEqual(os.fstat(fired[0]), os.fstat(source))
            finally:
                if fired:
                    real_close(fired[0])  # fixture-owned replacement, not stale generation
                real_close(source)
        with self._case(before_issue=before_issue):
            pass

