    @contextlib.contextmanager
    def _case(self, *, before_issue=None):
        api = module._make_git_child_execution_grant_authority()
        publish = inspect.getclosurevars(api[0]).nonlocals["publish_permit"]
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            os.chmod(root, 0o700)
            reservation = module._self_digest_record({"kind": "reservation"})
            attempt = module._self_digest_record({
                "operationKind": "network-attempt", "completionState": "attempted",
                "wrapper": "network-git", "capsuleResourceId": "resource",
                "reservationRecordDigest": reservation["recordDigest"],
            })
            consumption = {"recordDigest": "c" * 64}
            recovered = {
                "classification": "complete",
                "networkAttempts": [{"attempt": attempt, "state": "attempted-unknown", "terminal": None}],
                "resources": {"resource": {"consumption": consumption, "taint": None}},
            }
            broker = object()
            arguments = dict(operation="ls-remote", argv=("ls-remote",),
                preflight={}, manifest={}, capsule={"resourceId": "resource", "workingDirectory": str(root)},
                snapshot={}, broker=broker)
            permit = publish(root, attempt, reservation)
            owner = inspect.getclosurevars(publish).nonlocals["permits"][id(permit)]
            with mock.patch.object(module, "recover_run_state", return_value=recovered), mock.patch.object(
                module, "_git_child_execution_binding", side_effect=lambda **kw: {
                    "operation": kw["operation"],
                    "supervisorInterpreter": {"absolutePath": "/bin/sh", "fileByteCount": 20, "fileSha256": "a" * 64},
                }
            ), tempfile.TemporaryFile() as lease, mock.patch.object(module, "_network_execution_guard") as guard:
                lease_slot = module._ChildFdOwnerSlot(os.dup(lease.fileno()), "claim fixture lease")
                guard.return_value.child_lifetime_lease_fd.return_value = lease_slot
                try:
                    if before_issue is not None:
                        before_issue(api, owner, permit, root, attempt, consumption, arguments)
                        yield None
                    else:
                        grant = api[1](root, mint_permit=permit, attempt=attempt, consumption=consumption, **arguments)
                        yield api, owner, grant, root, arguments
                finally:
                    anchor = owner.get("cwdFd")
                    if owner.get("state") == "poisoned":
                        self._retained_fixture_owners.append((owner, lease_slot))
                    else:
                        if anchor is not None:
                            anchor.close()
                        lease_slot.close()

