    def test_close_primary_survives_partial_retirement_and_quarantines_slot(self):
        """Uncertain close forbids retirement; interrupted clean retirement restores ownership."""
        for interrupted_close in (True, False):
            with self.subTest(interrupted_close=interrupted_close), self._case() as (
                api, owner, grant, root, arguments
            ):
                api[2](grant, root, **arguments)
                primary = KeyboardInterrupt("close returned after interrupt")
                cleanup = SystemExit("retirement interrupted after one index")
                pops = []
                class InterruptedIndex(dict):
                    def pop(index, key, *default):
                        result = super().pop(key, *default)
                        pops.append(key)
                        raise cleanup
                owner["slot"]["entriesByAttempt"] = InterruptedIndex(owner["slot"]["entriesByAttempt"])
                anchor = owner["cwdFd"]
                target = anchor.generation_descriptor
                source = os.open(os.devnull, os.O_RDONLY)
                real_close = os.close
                closes = []
                def close(fd):
                    real_close(fd)
                    if fd == target:
                        closes.append(fd)
                        if interrupted_close:
                            os.dup2(source, fd)
                            raise primary
                try:
                    with mock.patch.object(module.os, "close", side_effect=close):
                        with self.assertRaises(BaseException) as caught:
                            api[4](grant)
                    self.assertIs(caught.exception, primary if interrupted_close else cleanup)
                    self.assertEqual(closes, [target])
                    self.assertEqual(pops, [] if interrupted_close else [owner["attemptDigest"]])
                    self.assertEqual(anchor.phase, "uncertain" if interrupted_close else "closed")
                    self.assertTrue(owner["slot"]["poisoned"])
                    self.assertIs(owner["slot"]["entriesByAttempt"][owner["attemptDigest"]], owner)
                    self.assertIs(owner["slot"]["entriesByResource"][owner["resourceId"]], owner)
                    with self.assertRaises(module.AuditError):
                        api[11](root, owner["attemptDigest"])
                    if interrupted_close:
                        self.assertEqual(os.fstat(target), os.fstat(source))
                        with self.assertRaises(module.AuditError):
                            api[4](grant)
                        self.assertEqual(os.fstat(target), os.fstat(source))
                finally:
                    if interrupted_close and closes:
                        real_close(target)  # independently owned replacement only
                    real_close(source)

