            self.assertEqual({name: hashlib.sha256(Path(name).read_bytes()).hexdigest() for name in originals}, originals)
            self.assertNotIn(b"private marker", result.stdout)
            sys.stdout.write(json.dumps({"cleanupColdReturnCode": result.returncode, "stdoutSha256": hashlib.sha256(result.stdout).hexdigest(),
                "stderrSha256": hashlib.sha256(result.stderr).hexdigest()}, sort_keys=True) + "\n")

