    def test_live_preparer_rejects_second_call_without_ledger_or_resource_write(self):
        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)
            repository, _source_oid, _dangling = (
                self._repository_fixture(base)
            )
            root = self._run_root(base, repository)
            _local, preflight = self._preflights(repository)
            entered = threading.Event()
            release = threading.Event()
            first_result = []
            first_error = []
            owner_ident = []
            real_initialize = (
                module._initialize_git_execution_capsule_repository
            )

            def blocking_initialize(path, object_format):
                if threading.get_ident() == owner_ident[0]:
                    entered.set()
                    if not release.wait(10):
                        raise AssertionError("preparer barrier timed out")
                return real_initialize(path, object_format)

            def prepare_first():
                owner_ident.append(threading.get_ident())
                try:
                    first_result.append(
                        module.prepare_git_execution_capsule(
                            root, "ls-remote-read", preflight
                        )
                    )
                except BaseException as exc:
                    first_error.append(exc)

            with mock.patch.object(
                module,
                "_initialize_git_execution_capsule_repository",
                side_effect=blocking_initialize,
            ):
                worker = threading.Thread(target=prepare_first)
                worker.start()
                try:
                    self.assertTrue(entered.wait(10))
                    before = module.recover_run_state(root)
                    before_records = len(before["records"])
                    before_ids = set(before["resources"])
                    with self.assertRaisesRegex(
                        module.AuditError, "preparation.*active"
                    ):
                        module.prepare_git_execution_capsule(
                            root, "ls-remote-read", preflight
                        )
                    after = module.recover_run_state(root)
                    self.assertEqual(len(after["records"]), before_records)
                    self.assertEqual(set(after["resources"]), before_ids)
                finally:
                    release.set()
                    worker.join(15)
            self.assertFalse(worker.is_alive())
            self.assertEqual(first_error, [])
            self.assertEqual(len(first_result), 1)

