class NetworkRecoveryArmingTests(_ModuleRequired):
    """Recovery remains reachable across publication and retirement faults."""

    @contextlib.contextmanager
    def _case(self, *, git=False):
        api = module._make_network_attempt_recovery_permit_authority()
        cells = dict(zip(api[1].__code__.co_freevars, api[1].__closure__))
        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)
            broker = None
            if git:
                fixture_case = NetworkGitExecutionGrantContractTests("runTest")
                self.addCleanup(fixture_case.doCleanups)
                fixture = fixture_case._fixture(base)
                root = fixture["root"]
                broker = fixture_case._broker(root)
                request = dict(wrapper="network-git", operation="ls-remote",
                    argv=fixture["argv"], preflight=fixture["preflight"],
                    manifest=fixture["manifest"], credential_broker=broker,
                    git_execution_capsule=fixture["capsule"],
                    git_execution_capsule_snapshot=fixture["snapshot"])
                frontier_id = fixture["frontierId"]
            else:
                root = _new_run_root(base)
                module.init_run_state(root, _identity_fields(base), bootstrap_imports=[])
                preflight = NetworkManifestV2Tests._preflight(self, base)
                argv = ["api", "/repos/ChangGeng01/ProjectSix/actions/runs"]
                manifest = module.seal_network_request_manifest_rows(
                    [{"operation": "rest-read", "argv": argv}], preflight
                )
                frontier = module.frontier_start(root, frontier_kind="remote-mutation",
                    input_digest="e" * 64, declared_paths=[], expected_tests=[])
                frontier_id = frontier["frontierId"]
                request = dict(wrapper="network-gh", operation="rest-read",
                    argv=argv, preflight=preflight, manifest=manifest)
            raw = module.execute_network_wrapper.__wrapped__.__wrapped__
            execute = module._git_child_mint_permit_scope(api[0](raw))
            transport = NetworkAttemptColdRecoveryContractTests._NeverTransport()
            def invoke():
                return execute(root, frontier_id, transport=transport, **request)
            with mock.patch.object(module, "_mint_network_attempt_recovery_permit", api[1]), \
                 mock.patch.object(module, "_begin_network_attempt_recovery", api[2]), \
                 mock.patch.object(module, "_revoke_network_attempt_recovery_permit", api[3]):
                try:
                    yield api, cells, root, transport, invoke
                finally:
                    # Dispose only test-local authority after assertions. Production
                    # cleanup is independently checked before this fixture teardown.
                    for guard in module._current_thread_network_execution_guards():
                        if guard.root == root:
                            guard._quarantined = False
                            if guard._phase == "attempt-live":
                                guard.begin_settlement(guard.bound_reservation())
                            guard.close()
                    if broker is not None:
                        broker.close()

    def _assert_cold_once(self, root, transport, calls):
        recovered = module.recover_run_state(root)
        key = recovered["networkAttempts"][0]["logicalKey"]
        first = module.recover_or_reopen_network_logical_key_no_network(root, key)
        second = module.recover_or_reopen_network_logical_key_no_network(root, key)
        self.assertEqual(first, second)
        self.assertEqual(first["completionState"], "unknown-no-replay")
        records = module.recover_run_state(root)["records"]
        self.assertEqual(sum(r["operationKind"] == "network-terminal" for r in records), 1)
        self.assertEqual(transport.calls, calls)

    def test_owner_is_reachable_before_and_after_real_mark(self):
        for git, after in ((False, False), (False, True), (True, False), (True, True)):
            with self.subTest(git=git, after=after), self._case(git=git) as (api, cells, root, transport, invoke):
                primary = KeyboardInterrupt("mark publication fault")
                real_mark = module._NetworkExecutionReservationGuard.mark_attempt_live
                seen = []
                def mark(guard, reservation, attempt):
                    owners = cells["owners"].cell_contents
                    seen.append(tuple(owners.values()))
                    if after:
                        real_mark(guard, reservation, attempt)
                    raise primary
                with mock.patch.object(module._NetworkExecutionReservationGuard, "mark_attempt_live", mark):
                    try:
                        invoke()
                    except BaseException as caught:
                        self.assertIs(caught, primary)
                self.assertEqual(len(seen[0]), 1)
                self.assertFalse(cells["owners"].cell_contents)
                self._assert_cold_once(root, transport, 0)

    def test_every_arming_publication_boundary_leaves_one_cleanup_owner(self):
        boundaries = (
            "owners_by_guard[id(guard)] = owner",
            "permit_sink.append(permit)",
            "guard.mark_attempt_live(reservation_value, attempt_value)",
            'owner["state"] = "dormant"',
            "return permit",
        )
        for boundary in boundaries:
            with self.subTest(boundary=boundary), self._case() as (api, cells, root, transport, invoke):
                source, start = inspect.getsourcelines(api[1])
                target = start + next(i for i, line in enumerate(source) if line.strip() == boundary)
                primary = KeyboardInterrupt("arming boundary")
                seen = []
                def trace(frame, event, arg):
                    if frame.f_code is api[1].__code__ and event == "line" and frame.f_lineno == target:
                        seen.extend(cells["owners"].cell_contents.values())
                        raise primary
                    return trace
                previous = sys.gettrace()
                try:
                    sys.settrace(trace)
                    with self.assertRaises(KeyboardInterrupt) as caught:
                        invoke()
                finally:
                    sys.settrace(previous)
                self.assertIs(caught.exception, primary)
                self.assertEqual(len(seen), 1)
                self.assertFalse(cells["owners"].cell_contents)
                self.assertFalse(cells["owners_by_guard"].cell_contents)
                self._assert_cold_once(root, transport, 0)

