    def test_transport_primary_survives_later_grant_revocation_failure(self):
        """Break caught: transport finally replaces KI/SystemExit with revoke failure."""
        for error_type in (KeyboardInterrupt, SystemExit):
            with self.subTest(error=error_type), self._case(git=True) as (api, cells, root, transport, invoke):
                primary, cleanup = error_type("transport interrupted"), OSError("revoke reporting fault")
                real_revoke = module._revoke_git_child_execution_grants_since
                faults = []
