    def test_wrapper_destroys_both_returned_streams_after_revoke_or_partial_release_failure(self):
        """Break caught: revoke/first-release failure skips owned secret destruction."""
        for revoke_fault in (False, True):
            for error_type in (KeyboardInterrupt, SystemExit):
                with self.subTest(revoke=revoke_fault, error=error_type), self._case(git=True) as (api, cells, root, transport, invoke):
                    stdout, stderr = bytearray(b"secret stdout"), bytearray(b"secret stderr")
                    owners = (module.OwnedSecretBuffer.take(stdout), module.OwnedSecretBuffer.take(stderr))
                    views = (memoryview(stdout), memoryview(stderr))
                    primary = error_type("revocation interrupted") if revoke_fault else module.AuditError("status parse interrupted")
                    release_error = error_type("partial stdout release")
                    stderr_error = OSError("stderr release reporting fault")
                    real_revoke, real_release = module._revoke_git_child_execution_grants_since, module.OwnedSecretBuffer.release
                    revoked, released = [], []
                    def revoke(initial):
                        real_revoke(initial)
                        if revoke_fault and not revoked:
                            revoked.append(True)
                            raise primary
                    def release(owner):
                        if owner is owners[0] and not any(item is owner for item in released):
                            released.append(owner)
                            stdout[0] = 0
                            owner._owner = None
                            raise release_error
                        if owner is owners[1] and not any(item is owner for item in released):
                            released.append(owner)
                            real_release(owner)
                            raise stderr_error
                        return real_release(owner)
                    def response(**request):
                        if not revoke_fault:
                            request["credentialBroker"].projection = lambda: (_ for _ in ()).throw(primary)
                        return {"status": 0, "stdoutOwner": owners[0], "stderrOwner": owners[1]}
                    try:
                        with mock.patch.object(transport, "execute", response), \
                                mock.patch.object(module, "_revoke_git_child_execution_grants_since", revoke), \
                                mock.patch.object(module.OwnedSecretBuffer, "release", release):
                            try:
                                invoke()
                            except BaseException as caught:
                                self.assertIs(caught, primary)
                            else:
                                self.fail("cleanup error was hidden")
                        self.assertEqual(released, list(owners))
                        self.assertEqual(bytes(views[0]), b"\x00" * len(stdout))
                        self.assertEqual(bytes(views[1]), b"\x00" * len(stderr))
                        self.assertEqual(getattr(primary, "cleanup_errors", []), [release_error, stderr_error])
                        self.assertFalse(module._current_thread_git_child_execution_grants())
                        self.assertFalse(cells["owners"].cell_contents)
                        self._assert_cold_once(root, transport, 0)
                    finally:
                        stdout[:] = b"\x00" * len(stdout)
                        stderr[:] = b"\x00" * len(stderr)
                        for owner in owners:
                            real_release(owner)
                        for view in views:
                            view.release()

