    def test_inverted_outer_ownership_cannot_block_before_fork(self):
        """Break caught: blocking before acquisition deadlocks on an outer later-family lock."""
        def case(fresh, _registrations):
            signal.alarm(10)
            earlier = fresh._NETWORK_EXECUTION_RESERVATION_GUARDS_LOCK
            later = fresh._CREDENTIAL_BROKERS_LOCK
            earlier_held = threading.Event()
            waiter_done = threading.Event()
            later.acquire()
            def waiter():
                with earlier:
                    earlier_held.set()
                    with later:
                        waiter_done.set()
            thread = threading.Thread(target=waiter, daemon=True)
            thread.start()
            self.assertTrue(earlier_held.wait(2))
            self.assertEqual(self._fork_status(), 70)
            self.assertFalse(waiter_done.is_set(), "fork parent released caller's later lock")
            later.release()
            thread.join(2)
            self.assertFalse(thread.is_alive())
            self.assertTrue(waiter_done.is_set())
            self.assertEqual(self._fork_status(), 23)
        self._fresh_worker(case)

    def test_native_depth_adapter_rejects_malformed_or_unavailable_observation(self):
        lock = threading.RLock()
        for representation in (
            "unavailable", "<unlocked _thread.RLock object owner=0 count=0 at 0x1>",
            "<locked _thread.RLock object owner=0 count=1 at %s>" % hex(id(lock)),
            "<unlocked _thread.RLock object owner=1 count=0 at %s>" % hex(id(lock)),
            type(lock).__repr__(lock) + " trailing",
        ):
            with self.subTest(representation=representation):
                with mock.patch.object(module, "_NATIVE_FORK_RLOCK_REPR", return_value=representation):
                    with self.assertRaises(module.AuditError):
                        module._fork_rlock_current_depth(lock)
        def case(fresh, _registrations):
            native_repr = fresh._NATIVE_FORK_RLOCK_REPR
            fresh._NATIVE_FORK_RLOCK_REPR = lambda _lock: "unavailable"
            self.assertEqual(self._fork_status(), 70)
            fresh._NATIVE_FORK_RLOCK_REPR = native_repr
            self.assertEqual(self._fork_status(), 23)
        self._fresh_worker(case)

    def test_settlement_never_consumes_unowned_extra_levels(self):
        lock = threading.RLock()
        with lock:
            acquisition = module._ForkLockAcquisition(lock)
            acquisition.acquire()
            lock.acquire()
            try:
                with self.assertRaises(module.AuditError):
                    acquisition.settle()
                self.assertEqual(module._fork_rlock_current_depth(lock), 3)
                self.assertFalse(acquisition.settled)
            finally:
                lock.release()
                acquisition.settle()
            self.assertEqual(module._fork_rlock_current_depth(lock), 1)

    def test_failed_parent_depth_observation_cannot_authorize_release(self):
        lock = threading.RLock()
        with lock:
            acquisition = module._ForkLockAcquisition(lock)
            acquisition.acquire()
            with mock.patch.object(module, "_fork_rlock_current_depth", side_effect=KeyboardInterrupt("depth unavailable")):
                with self.assertRaises(KeyboardInterrupt):
                    acquisition.settle()
            self.assertFalse(acquisition.settled)
            self.assertEqual(module._fork_rlock_current_depth(lock), 2)
            acquisition.settle()
            self.assertEqual(module._fork_rlock_current_depth(lock), 1)

