    def test_repeated_release_failure_is_bounded_and_retains_all_family_errors(self):
        def case(fresh, _registrations):
            locks = self._install_locks(fresh)
            attempts = []
            originals = []
            for index, lock in enumerate(locks):
                originals.append(lock.release)
                def fail(index=index):
                    attempts.append(index)
                    raise OSError("persistent release %d" % index)
                lock.release = fail
            self.assertEqual(self._fork_status(), 23)
            self.assertEqual(attempts, [4, 4, 3, 3, 2, 2, 1, 1, 0, 0])
            primary = fresh._FORK_BARRIER_PARENT_ERROR
            self.assertIsInstance(primary, OSError)
            errors = getattr(primary, "cleanup_errors", [])
            self.assertTrue(any(str(error) == "persistent release 0" for error in errors))
            self.assertEqual(self._fork_status(), 70, "pending settlement allowed a clean fork")
            for lock, original in zip(locks, originals):
                lock.release = original
            fresh._authority_after_fork_parent()
            self._assert_other_thread_available(locks)
            self.assertEqual(self._fork_status(), 23)
        self._fresh_worker(case)

    def test_foreign_parent_preserves_retained_token_until_original_owner_reconciles(self):
        """Break caught: B retires A's unresolved token because foreign depth reads zero."""
        for family, prefix, _cell_name, _global_name in self.FAMILIES:
            with self.subTest(family=family):
                def case(fresh, _registrations):
                    locks = self._install_locks(fresh)
                    selected = locks[[entry[0] for entry in self.FAMILIES].index(family)]
                    original_release = selected.release
                    release_attempts = []
                    owner_a = threading.current_thread()
                    def fail_release():
                        release_attempts.append(threading.current_thread())
                        raise OSError("A retained callback level")
                    selected.release = fail_release

                    def token_for_family():
                        if family == "credential":
                            return fresh._CREDENTIAL_BROKERS_FORK_ACQUISITION
                        if family == "reservation":
                            return fresh._NETWORK_EXECUTION_RESERVATION_FORK_ACQUISITION
                        if family == "ledger":
                            return fresh._LEDGER_TRANSACTION_FORK_ACQUISITION
                        return self._cells(getattr(fresh, prefix + "_after_fork_parent"))["fork_acquisition"].cell_contents

                    # A really acquires the native-backed family lock, then the
                    # real composite parent cleanup exhausts its two releases.
                    self.assertFalse(getattr(fresh, prefix + "_before_fork")())
                    token_a = token_for_family()
                    fresh._authority_after_fork_parent()
                    self.assertIs(token_for_family(), token_a)
                    self.assertFalse(token_a.settled)
                    self.assertEqual(release_attempts, [owner_a, owner_a])
                    self.assertIsInstance(fresh._FORK_BARRIER_PARENT_ERROR, OSError)

                    b_finished_parent = threading.Event()
                    a_reconciled = threading.Event()
                    observations = {}
                    def owner_b():
                        try:
                            observations["status"] = self._fork_status()
                            observations["token"] = token_for_family()
                            observations["parent_error"] = fresh._FORK_BARRIER_PARENT_ERROR
                            observations["selected_available"] = selected.acquire(blocking=False)
                            if observations["selected_available"]:
                                original_release()
                            other_available = []
                            for lock in locks:
                                if lock is selected:
                                    continue
                                acquired = lock.acquire(blocking=False)
                                other_available.append(acquired)
                                if acquired:
                                    lock.release()
                            observations["others_available"] = other_available
                        except BaseException as exc:
                            observations["error"] = exc
                        finally:
                            b_finished_parent.set()
                        if a_reconciled.wait(3):
                            acquired = selected.acquire(timeout=1)
                            observations["available_after_a"] = acquired
                            if acquired:
                                selected.release()

                    thread_b = threading.Thread(target=owner_b, daemon=True)
                    thread_b.start()
                    try:
                        self.assertTrue(b_finished_parent.wait(3))
                        self.assertNotIn("error", observations)
                        self.assertEqual(observations["status"], 70)
                        self.assertIs(observations["token"], token_a,
                                      "B falsely retired A's reachable acquisition token")
                        self.assertIs(token_for_family(), token_a)
                        self.assertFalse(token_a.settled)
                        self.assertIsInstance(observations["parent_error"], fresh.AuditError)
                        self.assertFalse(observations["selected_available"])
                        self.assertEqual(observations["others_available"], [True, True, True, True])
                        self.assertEqual(release_attempts, [owner_a, owner_a], "B attempted a foreign release")
                        self.assertEqual(fresh._fork_rlock_current_depth(selected), 1)
                        selected.release = original_release
                        fresh._authority_after_fork_parent()
                        self.assertTrue(token_a.settled)
                        self.assertIsNone(token_for_family())
                        self.assertIsNone(fresh._FORK_BARRIER_PARENT_ERROR)
                        self.assertEqual(fresh._fork_rlock_current_depth(selected), 0)
                    finally:
                        selected.release = original_release
                        a_reconciled.set()
                        thread_b.join(3)
                    self.assertFalse(thread_b.is_alive())
                    self.assertTrue(observations["available_after_a"])
                    self.assertEqual(self._fork_status(), 23)
                self._fresh_worker(case)

    def test_settlement_refuses_foreign_pid_ident_or_recycled_thread_object_before_depth(self):
        """Break caught: token ownership collapses to a recycled numeric thread ident."""
        for attribute, foreign_value in (
            ("_pid", os.getpid() + 1),
            ("_thread_ident", threading.get_ident() + 1),
            ("_thread_object", threading.Thread()),
        ):
            with self.subTest(attribute=attribute):
                lock = threading.RLock()
                with lock:
                    token = module._ForkLockAcquisition(lock)
                    token.acquire()
                    original = getattr(token, attribute, None)
                    setattr(token, attribute, foreign_value)
                    try:
                        with mock.patch.object(
                            module, "_fork_rlock_current_depth",
                            side_effect=AssertionError("foreign token reached depth observation"),
                        ):
                            with self.assertRaises(module.AuditError):
                                token.settle()
                        self.assertFalse(token.settled)
                        self.assertEqual(module._fork_rlock_current_depth(lock), 2)
                    finally:
                        setattr(token, attribute, original)
                        token.settle()
                    self.assertTrue(token.settled)
                    self.assertEqual(module._fork_rlock_current_depth(lock), 1)

    def test_real_child_cleanup_leaves_classify_close_failure_as_70(self):
        """Break caught: inner swallowed broker errors or direct 71/72 bypass outer catch."""
        for family in ("credential-owned", "credential-callback", "reservation", "capsule", "task-test"):
            with self.subTest(family=family):
                def case(fresh, _registrations):
                    read_fd, write_fd = os.pipe()
                    broker = None
                    if family.startswith("credential"):
                        broker = fresh.OneShotCredentialBroker(
                            fresh.OwnedSecretBuffer.take(bytearray(NetworkGitExecutionGrantContractTests._HELPER_RESPONSE)),
                            generation_digest="a" * 64,
                        )
                        # Snapshot is deliberately empty; publish into child reset
                        # only, to exercise otherwise unreachable legacy leaf cleanup.
                        fresh._CREDENTIAL_BROKERS.clear()
                        hook_name = "_credential_brokers_after_fork_child"
                        guard = broker
                        descriptor = broker._write_fd
                        registry_name = "_CREDENTIAL_BROKERS"
                    else:
                        cls, hook_name, registry_name = {
                            "reservation": (fresh._NetworkExecutionReservationGuard,
                                            "_network_execution_reservation_after_fork_child",
                                            "_NETWORK_EXECUTION_RESERVATION_GUARDS"),
                            "capsule": (fresh._GitCapsulePreparationGuard,
                                        "_git_capsule_preparation_after_fork_child",
                                        "_GIT_CAPSULE_PREPARATION_GUARDS"),
                            "task-test": (fresh._TaskTestExecutionLeaseGuard,
                                          "_task_test_execution_guard_after_fork_child",
                                          "_TASK_TEST_EXECUTION_GUARDS"),
                        }[family]
                        guard = object.__new__(cls)
                        guard._closed = False
                        guard._quarantined = False
                        guard._closing_descriptor = None
                        slot = fresh._ChildFdOwnerSlot(read_fd, "child leaf fixture")
                        guard._lock_fd = slot
                        guard._root_fd = slot
                        guard._ledger_fd = slot
                        guard._identity_fd = None
                        descriptor = read_fd
                    original_hook = getattr(fresh, hook_name)
                    real_close = fresh.os.close
                    def child_reset():
                        setattr(fresh, registry_name, {"leaf": guard})
                        if family == "credential-callback":
                            def failure():
                                os.write(write_fd, b"fault")
                                raise KeyboardInterrupt("broker callback fault")
                            guard._close_after_fork_child = failure
                        elif family == "credential-owned":
                            # Accepted broker policy exits before touching any
                            # inherited endpoint lock or close authority.
                            os.write(write_fd, b"owned")
                        else:
                            def fail_close(fd):
                                if fd == descriptor:
                                    os.write(write_fd, b"fault")
                                    raise OSError("child-only descriptor close fault")
                                return real_close(fd)
                            fresh.os.close = fail_close
                        original_hook()
                    setattr(fresh, hook_name, child_reset)
                    try:
                        self.assertEqual(self._fork_status(), 70)
                        os.set_blocking(read_fd, False)
                        self.assertEqual(os.read(read_fd, 5),
                                         b"owned" if family == "credential-owned" else b"fault")
                        os.fstat(descriptor)  # parent resource remains live
                    finally:
                        setattr(fresh, hook_name, original_hook)
                        if broker is not None:
                            broker.close()
                        os.close(read_fd)
                        os.close(write_fd)
                self._fresh_worker(case)

    def test_interruption_at_composite_clean_publication_reverts_to_must_exit(self):
        """Break caught: an exception just after clean-bit storage remains optimistic."""
        def case(fresh, _registrations):
            target = fresh._authority_before_fork.__code__
            fired = []
            def interrupt_clean_publication(frame, event, _argument):
                if frame.f_code is target:
                    frame.f_trace_opcodes = True
                    if event == "opcode" and not fresh._FORK_BARRIER_MUST_EXIT and not fired:
                        fired.append(True)
                        raise KeyboardInterrupt("after clean publication")
                return interrupt_clean_publication
            sys.settrace(interrupt_clean_publication)
            try:
                self.assertEqual(self._fork_status(), 70)
            finally:
                sys.settrace(None)
            self.assertEqual(fired, [True])
            self.assertIsInstance(fresh._FORK_BARRIER_BEFORE_ERROR, KeyboardInterrupt)
            self.assertEqual(self._fork_status(), 23)
        self._fresh_worker(case)

