    def _publish_resumption(self, fixture, context):
        stream = _ExternalMatrixStdout()
        with mock.patch.object(module.sys, "stdout", stream):
            exit_code = module._dispatch_command(fixture["argv"], context=context)
        output = stream.buffer.getvalue()
        self.assertEqual(exit_code, 0, output)
        try:
            emitted = module.parse_canonical_json(output)
        except module.AuditError as error:
            self.fail("invalid resumption output: %s; captured=%r" % (error, output))
        state = module.recover_run_state(fixture["root"])
        self.assertEqual(state["classification"], "complete", (state.get("reason"), output))
        persisted = state["taskResumptions"][fixture["original"]["frontierId"]]["record"]
        self.assertEqual(emitted, persisted, output)
        return emitted

    def test_continuation_target_bodies_detect_broken_fixture_inputs(self):
        """Break caught: four named typed targets succeed without observing their inputs."""
        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._fixture(Path(temporary))
            self._resume(fixture)
            path = fixture["repository"] / "scripts/test_qinao_convergence_audit.py"
            spec = importlib.util.spec_from_file_location("resumption_behavior_control", path)
            generated = importlib.util.module_from_spec(spec)
            with mock.patch.dict(sys.modules, {"qinao_convergence_audit": module}), \
                    mock.patch.dict(builtins.__dict__, {self._IMPORT_WITNESS_KEY: 0}):
                spec.loader.exec_module(generated)
            cases = (
                ("DiffContentObservationTests", "test_diff_content_observation", "_DIFF_PAYLOAD", b"invalid"),
                ("NetworkBoundaryTests", "test_network_boundary", "_ADVERTISEMENT", b"1" * 40 + b"\tHEAD\n"),
                ("DocumentInventoryTests", "test_document_inventory", "_DOCUMENT", "../escape.md"),
                ("FullRecoveryTests", "test_full_recovery", "_RECOVERY_FRONTIER", "0" * 32),
            )
            for class_name, method, field, broken in cases:
                with self.subTest(target=class_name):
                    case_type = getattr(generated, class_name)
                    positive = unittest.TestResult()
                    case_type(method).run(positive)
                    self.assertEqual(positive.testsRun, 1)
                    self.assertEqual(positive.errors + positive.failures, [])
                    previous = getattr(generated, field, None)
                    setattr(generated, field, broken)
                    try:
                        rejected = unittest.TestResult()
                        case_type(method).run(rejected)
                        self.assertEqual(rejected.testsRun, 1)
                        self.assertEqual(len(rejected.errors + rejected.failures), 1,
                            class_name + " accepted its broken fixture input")
                    finally:
                        setattr(generated, field, previous)
            self.assertEqual(fixture["originalPath"].read_bytes(), fixture["originalBytes"])

    def _fixture(self, base, *, original_changes=None, evidence_changes=None, seal_evidence=True,
                 prior_history=None):
        had_witness = self._IMPORT_WITNESS_KEY in builtins.__dict__
        saved_witness = builtins.__dict__.pop(self._IMPORT_WITNESS_KEY, None)
        def restore_import_witness():
            if had_witness:
                builtins.__dict__[self._IMPORT_WITNESS_KEY] = saved_witness
            else:
                builtins.__dict__.pop(self._IMPORT_WITNESS_KEY, None)
        self.addCleanup(restore_import_witness)
        repository = self._repository_with_test_classes(base)
        root = _new_run_root(base)
        module.init_run_state(root, _identity_fields(repository), bootstrap_imports=[])
        state = module.recover_run_state(root)
        original = module._new_record(state["identity"], state["nextSequence"],
            state["records"][-1]["recordDigest"], "frontier-start", self._INPUT,
            self._PATHS, "open", {
                "frontierId": "6" * 32, "frontierKind": "task",
                "declaredPaths": self._PATHS, "expectedTests": self._TARGETS,
                "allowedChildKinds": [], "parentFrontierId": None,
                "componentKind": None, "resourceId": None,
                "operationClass": None, "operationContext": None,
            })
        if original_changes:
            original.update(original_changes)
            original.pop("recordDigest")
            original = module._self_digest_record(original)
        original_path = root / "ledger" / "records" / ("%016d.json" % original["sequence"])
        module.write_canonical_exclusive(original_path, original)
        original_bytes = original_path.read_bytes()
        self.assertEqual(module.recover_run_state(root)["classification"], "complete")
        if prior_history is not None:
            prior_history({"root": root, "repository": repository, "original": original,
                "originalPath": original_path, "originalBytes": original_bytes})
        for relative in self._PATHS:
            path = repository / relative
            path.write_bytes(path.read_bytes() + b"\n# retained index layer\n")
        module._run_git(repository, ["add", "--"] + self._PATHS)
        for relative in self._PATHS:
            path = repository / relative
            path.write_bytes(path.read_bytes() + b"\n# fresh working layer\n")
        capture = module.allocate_capture(root, "task3-resumption-evidence",
                                          frontier_id=original["frontierId"])
        directory = Path(capture["absolutePath"])
        names = ["task-3-brief.md", "controller-erratum-1.md",
                 "controller-erratum-2.md", "controller-erratum-3.md"]
        payloads = {name: gzip.decompress(base64.b64decode(encoded))
                    for name, encoded in zip(names, _TASK3_ORIGINAL_INPUT_GZIP)}
        self.assertEqual(hashlib.sha256(b"".join(payloads[name] for name in names)).hexdigest(), self._INPUT)
        index_path = Path(module._run_git(repository,
            ["rev-parse", "--path-format=absolute", "--git-path", "index"]).decode().strip())
        payloads.update({"original-start.json": original_path.read_bytes(),
            "observed-index.bin": index_path.read_bytes(),
            "observed-status.bin": module._run_git(repository,
                ["status", "--porcelain=v2", "-z", "--untracked-files=all"]),
        })
        for label, relative in zip(("audit", "tests"), self._PATHS):
            payloads["index-" + label + ".py"] = module._run_git(repository, ["show", ":" + relative])
            payloads["worktree-" + label + ".py"] = (repository / relative).read_bytes()
        if evidence_changes:
            evidence_changes(payloads)
        for name, payload in payloads.items():
            module._write_bytes_exclusive(directory / name, payload)
        seal = module.seal_capture(root, capture["captureId"], list(payloads)) if seal_evidence else None
        seal_path = root / "ledger" / "records" / ("%016d.json" % (seal["sequence"] if seal else 999999))
        argv = ["task3-resume", "--root", str(root), "--frontier-id", original["frontierId"],
                "--original-start-record", str(original_path), "--evidence-seal-record", str(seal_path)]
        return {"root": root, "repository": repository, "original": original,
                "originalPath": original_path, "originalBytes": original_bytes,
                "payloads": payloads, "capture": capture, "sealPath": seal_path,
                "argv": argv, "indexPath": index_path}

    def test_dirty_historical_task3_can_publish_fresh_resumption(self):
        """Break caught: the genuine route cannot accept a real frozen MM continuation."""
        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._fixture(Path(temporary))
            repository, root = fixture["repository"], fixture["root"]
            self.assertEqual(module._run_git(repository, ["status", "--short"]),
                b" MM scripts/qinao_convergence_audit.py\n MM scripts/test_qinao_convergence_audit.py\n".replace(b" MM", b"MM"))
            outer, context = self._append_outer(root, repository, fixture["argv"])
            try:
                self._publish_resumption(fixture, context)
            except module.AuditError as error:
                self.fail("real dirty Task3 resumption rejected: " + str(error))
            state = module.recover_run_state(root)
            self.assertEqual(state["classification"], "complete", state.get("reason"))
            resumed = state["taskResumptions"][fixture["original"]["frontierId"]]
            self.assertEqual(resumed["state"], "published-unsettled")
            observation = resumed["record"]["resumption"]
            self.assertEqual(observation["taskNumber"], 3)
            self.assertNotIn("taskStart", state["openFrontiers"][0])
            self.assertEqual(fixture["originalPath"].read_bytes(), fixture["originalBytes"])
            self.assertEqual(fixture["indexPath"].read_bytes(), fixture["payloads"]["observed-index.bin"])
            for row, label in zip(observation["observedFiles"], ("audit", "tests")):
                self.assertEqual(row["indexSha256"], hashlib.sha256(fixture["payloads"]["index-" + label + ".py"]).hexdigest())
                self.assertEqual(row["worktreeSha256"], hashlib.sha256(fixture["payloads"]["worktree-" + label + ".py"]).hexdigest())
                self.assertNotEqual(row["indexSha256"], row["worktreeSha256"])
            module._append_linked_sterile_invocation_completion(root, outer, exit_code=0)
            self.assertEqual(module.recover_run_state(root)["taskResumptions"][fixture["original"]["frontierId"]]["state"], "settled")

    def _resume(self, fixture, *, settle=True):
        outer, context = self._append_outer(fixture["root"], fixture["repository"], fixture["argv"])
        self._publish_resumption(fixture, context)
        if settle:
            module._append_linked_sterile_invocation_completion(fixture["root"], outer, exit_code=0)
        state = module.recover_run_state(fixture["root"])
        self.assertEqual(state["classification"], "complete", state.get("reason"))
        fixture["resumptionOuter"] = outer
        fixture["resumption"] = state["taskResumptions"][fixture["original"]["frontierId"]]["record"]

    def _cold(self, fixture, argv=None):
        """Execute the actual sterile CLI in another interpreter, with no live object reuse."""
        root, repository = fixture["root"], fixture["repository"]
        command = [sys.executable, "-I", "-S", "-B",
            str(repository / "scripts/qinao_convergence_audit.py"), "sterile-python",
            "--root", str(root), "--repository", str(repository), "--"
        ] + (argv or ["recover-captures", "--root", str(root)])
        result = subprocess.run(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            env={"HOME": str(root / "home"), "TMPDIR": str(root / "tmp"),
                 "LANG": "C", "LC_ALL": "C", "PATH": "/usr/bin:/bin"}, timeout=90)
        try:
            value = json.loads(result.stdout)
        except (ValueError, UnicodeError):
            value = None
        return result, value

    def _scan(self, fixture):
        root, repository = fixture["root"], fixture["repository"]
        argv = ["secret-scan-worktree", "--root", str(root), "--repository", str(repository),
                "--phase", "task3-candidate", "--frontier-id", fixture["original"]["frontierId"]]
        outer, context = self._append_outer(root, repository, argv)
        terminal = module.execute_secret_scan_worktree(root, repository=repository,
            phase="task3-candidate", frontier_id=fixture["original"]["frontierId"], context=context)
        module._select_secret_scan_terminal_for_outer(root, terminal, context)
        module._append_linked_sterile_invocation_completion(root, outer, exit_code=0)
        return terminal

    def _completed_resumption_fixture(self, base):
        fixture = self._fixture(base)
        root, repository = fixture["root"], fixture["repository"]
        self._resume(fixture)
        fixture["before"] = module._run_git(repository, ["rev-parse", "HEAD"]).decode().strip()
        module._run_git(repository, ["add", "--"] + self._PATHS)
        self._scan(fixture)
        module._run_git(repository, ["-c", "user.name=Qinao Test", "-c", "user.email=qinao-test@invalid.local",
            "commit", "--quiet", "-m", "one resumed result"])
        result_head = module._run_git(repository, ["rev-parse", "HEAD"]).decode().strip()
        argv = self._task_test_argv(fixture)
        outer, context = self._append_outer(root, repository, argv)
        self.assertEqual(module._dispatch_command(argv, context=context), 0)
        with self.assertRaises(module.AuditError):
            module.frontier_complete(root, fixture["original"]["frontierId"],
                input_digest=self._INPUT, declared_paths=self._PATHS,
                outcome="completed", result_commit=result_head)
        module._append_linked_sterile_invocation_completion(root, outer, exit_code=0)
        fixture["completed"] = module.frontier_complete(root, fixture["original"]["frontierId"],
            input_digest=self._INPUT, declared_paths=self._PATHS, outcome="completed", result_commit=result_head)
        fixture["resultHead"] = result_head
        return fixture

    def _task_test_argv(self, fixture):
        argv = ["task-test-run", "--root", str(fixture["root"]), "--repository", str(fixture["repository"])]
        for target in self._TARGETS:
            argv += ["--target", target]
        return argv

    def test_resumed_candidate_completes_and_reopens_in_separate_process(self):
        """Break caught: new provenance cannot authorize its sole scanned result child."""
        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._completed_resumption_fixture(Path(temporary))
            root, repository = fixture["root"], fixture["repository"]
            before, result_head, completed = fixture["before"], fixture["resultHead"], fixture["completed"]
            self.assertEqual(completed["taskCompletion"]["schemaVersion"], "qinao.task-completion.v2")
            self.assertEqual(completed["taskCompletion"]["taskResumptionRecordDigest"], fixture["resumption"]["recordDigest"])
            self.assertEqual(completed["taskCompletion"]["parentOid"], before)
            self.assertEqual(module._run_git(repository, ["rev-list", "--count", before + "..HEAD"]), b"1\n")
            self.assertEqual(module._run_git(repository, ["diff", "--name-only", before, "HEAD"]).decode().splitlines(), self._PATHS)
            for _repeat in range(2):
                child, cold = self._cold(fixture)
                self.assertEqual(child.returncode, 0, child.stderr.decode(errors="replace"))
                self.assertEqual(cold["classification"], "complete", cold.get("reason"))
                self.assertEqual(cold["openFrontiers"], [])
                self.assertEqual(cold["taskResumptions"][fixture["original"]["frontierId"]]["record"], fixture["resumption"])
                self.assertEqual(sum(row["operationKind"] == "task-resumption" for row in cold["records"]), 1)
            self.assertEqual(fixture["originalPath"].read_bytes(), fixture["originalBytes"])
            completed_path = root / "ledger" / "records" / ("%016d.json" % completed["sequence"])
            saved = completed_path.read_bytes()
            for variant in ("missing-proof", "downgraded-proof", "wrong-resumption", "wrong-parent"):
                with self.subTest(completion=variant):
                    changed = copy.deepcopy(completed)
                    if variant == "missing-proof":
                        changed.pop("taskCompletion")
                    else:
                        key, replacement = {
                            "downgraded-proof": ("schemaVersion", "qinao.task-completion.v1"),
                            "wrong-resumption": ("taskResumptionRecordDigest", "0" * 64),
                            "wrong-parent": ("parentOid", result_head),
                        }[variant]
                        changed["taskCompletion"][key] = replacement
                        changed["taskCompletion"].pop("completionDigest")
                        changed["taskCompletion"] = module._self_digest_record(changed["taskCompletion"], "completionDigest")
                    changed.pop("recordDigest")
                    changed = module._self_digest_record(changed)
                    # Rewrite only a generated fixture's newest completion; there are
                    # no descendants to trigger an unrelated hash-chain failure.
                    suffix = list((root / "ledger" / "records").iterdir())
                    later = {path: path.read_bytes() for path in suffix if path.name > completed_path.name}
                    for path in later:
                        path.unlink()
                    completed_path.write_bytes(module.canonical_json_bytes(changed))
                    try:
                        rejected = module.recover_run_state(root)
                        self.assertEqual(rejected["classification"], "indeterminate")
                        self.assertNotIn("record chain fork", rejected.get("reason", ""))
                    finally:
                        completed_path.write_bytes(saved)
                        for path, payload in later.items():
                            module._write_bytes_exclusive(path, payload)
            module._run_git(repository, ["-c", "user.name=Qinao Test", "-c", "user.email=qinao-test@invalid.local",
                "commit", "--quiet", "--allow-empty", "-m", "later independent task"])
            child, cold = self._cold(fixture)
            self.assertEqual(child.returncode, 0, child.stderr.decode(errors="replace"))
            self.assertEqual(cold["taskResumptions"][fixture["original"]["frontierId"]]["record"], fixture["resumption"])

    def test_resumed_subject_rejects_relation_downgrade_and_tamper(self):
        """Break caught: a shape-valid substituted relation authorizes resumed test evidence."""
        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._completed_resumption_fixture(Path(temporary))
            root = fixture["root"]
            state = module.recover_run_state(root)
            self.assertEqual(state["classification"], "complete", state.get("reason"))
            start = next(row for row in state["records"] if row["operationKind"] == "task-test-attempt-started")
            path = root / "ledger/records" / ("%016d.json" % start["sequence"])
            saved = path.read_bytes()
            suffix = {member: member.read_bytes() for member in path.parent.iterdir() if member.name > path.name}
            for variant in ("downgrade-v1", "wrong-resumption", "wrong-observed-parent", "wrong-reservation"):
                with self.subTest(relation=variant):
                    changed = copy.deepcopy(start)
                    subject = changed["subject"]
                    relation = subject["scanResultRelation"]
                    if variant == "downgrade-v1":
                        relation["schemaVersion"] = "qinao.task-scan-result-relation.v1"
                        relation["startingHeadOid"] = relation.pop("observedHeadOid")
                        relation["startingTreeOid"] = relation.pop("observedTreeOid")
                        relation.pop("taskResumptionRecordDigest")
                        relation["taskStartDigest"] = "0" * 64
                    elif variant == "wrong-observed-parent":
                        relation["observedHeadOid"] = relation["parentOid"] = fixture["resultHead"]
                    else:
                        relation["taskResumptionRecordDigest" if variant == "wrong-resumption"
                                 else "scanReservationRecordDigest"] = "0" * 64
                    relation.pop("relationDigest")
                    subject["scanResultRelation"] = module._self_digest_record(relation, "relationDigest")
                    subject["scanResultRelationDigest"] = subject["scanResultRelation"]["relationDigest"]
                    subject.pop("subjectDigest")
                    subject = module._self_digest_record(subject, "subjectDigest")
                    module._validate_task_test_subject(subject)
                    changed.update(subject=subject, subjectDigest=subject["subjectDigest"],
                        inputDigest=subject["subjectDigest"], proofKeyDigest=module._task_test_proof_key(subject))
                    changed.pop("recordDigest")
                    changed = module._self_digest_record(changed)
                    module._validate_task_test_attempt_start_shape(changed)
                    # Preserve a genuine predecessor prefix and make the changed
                    # attempt newest, so descendants cannot supply a fork oracle.
                    for member in suffix:
                        member.unlink()
                    path.write_bytes(module.canonical_json_bytes(changed))
                    try:
                        rejected = module.recover_run_state(root)
                        self.assertEqual(rejected["classification"], "indeterminate")
                        self.assertEqual(rejected["reason"], "current task subject historical lineage drift")
                        child, cold = self._cold(fixture)
                        self.assertTrue(child.returncode != 0 or cold.get("classification") == "indeterminate")
                    finally:
                        path.write_bytes(saved)
                        for member, payload in suffix.items():
                            module._write_bytes_exclusive(member, payload)
                    self.assertEqual(fixture["originalPath"].read_bytes(), fixture["originalBytes"])
            self.assertEqual(module.recover_run_state(root)["classification"], "complete")

    def test_resumption_rejects_prior_typed_scan_and_execution_lease(self):
        """Break caught: fresh MM evidence erases prior typed scan or lease authority."""
        for kind in ("scan", "lease"):
            with self.subTest(history=kind), tempfile.TemporaryDirectory() as temporary:
                def prior(fixture):
                    root, repository, original = fixture["root"], fixture["repository"], fixture["original"]
                    if kind == "scan":
                        module.allocate_secret_scan_capture(root, repository=repository,
                            phase="task3-candidate", frontier_id=original["frontierId"])
                    else:
                        outer, _context = self._append_outer(root, repository, self._task_test_argv(fixture))
                        metadata = {"executionContractVersion": 2,
                            "executionContractDigest": module._TASK_TEST_EXECUTION_CONTRACT_V2_DIGEST,
                            "expectedTests": self._TARGETS,
                            "expectedTestsDigest": module._task_test_expected_tests_digest(self._TARGETS)}
                        guard = module._TaskTestExecutionLeaseGuard.acquire_nonblocking(root)
                        acquired = module._append_task_test_execution_lease_acquired(root, guard, original,
                            outer, outer["invocation"], metadata)
                        try:
                            recovered = module.recover_run_state(root)
                            self.assertEqual(recovered["classification"], "complete", recovered.get("reason"))
                            self.assertEqual(recovered["taskTestExecutionLeases"][acquired["leaseId"]]["state"], "active")
                        finally:
                            terminal = module._append_task_test_execution_lease_terminal(root, guard, acquired,
                                disposition="preactivation-failed", attempt_binding="absent",
                                attempt_start=None, task_test_terminal=None)
                            guard.release_after_terminal(terminal)
                        module._append_linked_sterile_invocation_completion(root, outer, exit_code=1)
                fixture = self._fixture(Path(temporary), prior_history=prior)
                root = fixture["root"]
                cold_child, cold = self._cold(fixture)
                self.assertEqual(cold_child.returncode, 0, cold_child.stderr)
                self.assertEqual(cold["classification"], "complete", cold.get("reason"))
                reservations = [value for value in cold["captures"].values() if "reservation" in value]
                self.assertEqual(len(reservations), int(kind == "scan"))
