    def test_publication_rechecks_real_drift_at_atomic_boundary(self):
        """Break caught: a previously observed MM snapshot survives drift before rename."""
        for variant in ("head", "branch", "config", "index", "working", "mode", "extra-path"):
            with self.subTest(drift=variant), tempfile.TemporaryDirectory() as temporary:
                fixture = self._fixture(Path(temporary))
                root, repository = fixture["root"], fixture["repository"]
                _outer, context = self._append_outer(root, repository, fixture["argv"])
                before = module.recover_run_state(root)["records"]
                hit = []
                real_hit = module.DurabilityFaults.hit
                def drift(faults, boundary, kind, subject=""):
                    real_hit(faults, boundary, kind, subject)
                    if boundary != "record-stage-parent-fsync" or kind != "task-resumption" or hit:
                        return
                    hit.append(variant)
                    if variant == "head":
                        module._run_git(repository, ["-c", "user.name=Qinao Test", "-c", "user.email=qinao-test@invalid.local",
                            "commit", "--quiet", "-m", "concurrent index commit"])
                    elif variant == "branch":
                        module._run_git(repository, ["symbolic-ref", "HEAD", "refs/heads/other"])
                    elif variant == "config":
                        module._run_git(repository, ["config", "qinao.concurrent", "changed"])
                    elif variant == "index":
                        module._run_git(repository, ["add", "--", self._PATHS[1]])
                    elif variant == "working":
                        path = repository / self._PATHS[1]
                        path.write_bytes(path.read_bytes() + b"\n# drift\n")
                    elif variant == "mode":
                        (repository / self._PATHS[1]).chmod(0o755)
                    else:
                        (repository / "undeclared.txt").write_bytes(b"extra\n")
                with mock.patch.object(module.DurabilityFaults, "hit", drift):
                    with self.assertRaises(module.AuditError):
                        module._dispatch_command(fixture["argv"], context=context)
                self.assertEqual(hit, [variant])
                self.assertEqual(module.recover_run_state(root)["records"], before)
                self.assertEqual(fixture["originalPath"].read_bytes(), fixture["originalBytes"])

    def test_persisted_prefixes_reopen_without_replay_in_separate_processes(self):
        """Break caught: crash prefixes are promoted, repeated, or tied to the old interpreter."""
        variants = ("incomplete-capture", "sealed-only", "before-rename", "lost-return", "failed-outer")
        for variant in variants:
            with self.subTest(prefix=variant), tempfile.TemporaryDirectory() as temporary:
                fixture = self._fixture(Path(temporary), seal_evidence=variant != "incomplete-capture")
                root, repository = fixture["root"], fixture["repository"]
                if variant in ("before-rename", "lost-return", "failed-outer"):
                    outer, context = self._append_outer(root, repository, fixture["argv"])
                    if variant == "failed-outer":
                        self._publish_resumption(fixture, context)
                        module._append_linked_sterile_invocation_completion(root, outer, exit_code=1)
                    else:
                        boundary_wanted = "record-stage-parent-fsync" if variant == "before-rename" else "records-fsync"
                        real_hit = module.DurabilityFaults.hit
                        def interrupt(faults, boundary, kind, subject=""):
                            real_hit(faults, boundary, kind, subject)
                            if boundary == boundary_wanted and kind == "task-resumption":
                                raise KeyboardInterrupt("simulated lost resumption return")
                        with mock.patch.object(module.DurabilityFaults, "hit", interrupt):
                            with self.assertRaises(KeyboardInterrupt):
                                module._dispatch_command(fixture["argv"], context=context)
                original_before = fixture["originalPath"].read_bytes()
                child, state = self._cold(fixture)
                self.assertEqual(child.returncode, 0, child.stderr.decode(errors="replace"))
                self.assertEqual(state["classification"], "complete", state.get("reason"))
                resumes = state["taskResumptions"]
                if variant in ("lost-return", "failed-outer"):
                    self.assertEqual(resumes[fixture["original"]["frontierId"]]["state"], "published-unsettled")
                else:
                    self.assertEqual(resumes, {})
                child, _value = self._cold(fixture, fixture["argv"] + ["--recover-exact"])
                self.assertNotEqual(child.returncode, 0)
                self.assertEqual(fixture["originalPath"].read_bytes(), original_before)
                final = module.recover_run_state(root)
                self.assertEqual(sum(row["operationKind"] == "task-resumption" for row in final["records"]),
                                 int(variant in ("lost-return", "failed-outer")))

    def test_cold_resumption_schema_is_closed_and_cannot_be_duplicated(self):
        """Break caught: rehashed malformed or duplicate provenance survives cold recovery."""
        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._fixture(Path(temporary))
            root = fixture["root"]
            self._resume(fixture, settle=False)
            original = fixture["resumption"]
            path = root / "ledger" / "records" / ("%016d.json" % original["sequence"])
            saved = path.read_bytes()
            changes = {"schemaVersion": "qinao.task3-resumption.v2", "taskNumber": 4,
                "originalStartRecordDigest": "0" * 64, "originalInputDigest": "1" * 64,
                "observedIndexEntryMapDigest": "2" * 64, "observedIndexSha256": "3" * 64,
                "observedStatusSha256": "4" * 64, "observedLocalConfigDigest": None,
                "observedFiles": [], "outerInvocationStartRecordDigest": "5" * 64,
                "historicalGap": [], "extra": "not allowed"}
            for key, replacement in changes.items():
                with self.subTest(field=key):
                    row = copy.deepcopy(original)
                    row["resumption"][key] = replacement
                    row["resumption"].pop("resumptionDigest")
                    row["resumption"] = module._self_digest_record(row["resumption"], "resumptionDigest")
                    row.pop("recordDigest")
                    row = module._self_digest_record(row)
                    path.write_bytes(module.canonical_json_bytes(row))
                    try:
                        self.assertEqual(module.recover_run_state(root)["classification"], "indeterminate")
                    finally:
                        path.write_bytes(saved)
            before = module.recover_run_state(root)
            duplicate = module._new_record(before["identity"], before["nextSequence"], original["recordDigest"],
                "task-resumption", self._INPUT, self._PATHS, "resumed",
                {"frontierId": original["frontierId"], "resumption": original["resumption"]})
            duplicate_path = root / "ledger" / "records" / ("%016d.json" % duplicate["sequence"])
            module.write_canonical_exclusive(duplicate_path, duplicate)
            child, cold = self._cold(fixture)
            self.assertNotEqual(child.returncode, 0)
            self.assertEqual(module.recover_run_state(root)["classification"], "indeterminate")

    def test_settled_resumption_rejects_candidate_drift_and_allows_exact_reopen(self):
        """Break caught: resumption authorizes later source edits or a different staged candidate."""
        for variant in ("working", "index-only", "extra-index", "missing-index", "config", "head"):
            with self.subTest(candidate=variant), tempfile.TemporaryDirectory() as temporary:
                fixture = self._fixture(Path(temporary))
                repository, root = fixture["repository"], fixture["root"]
                self._resume(fixture)
                module._run_git(repository, ["add", "--"] + self._PATHS)
                if variant == "working":
                    path = repository / self._PATHS[1]
                    path.write_bytes(path.read_bytes() + b"\n# later work\n")
                elif variant == "index-only":
                    path = repository / self._PATHS[1]
                    path.write_bytes(path.read_bytes() + b"\n# different candidate\n")
                    module._run_git(repository, ["add", "--", self._PATHS[1]])
                elif variant == "extra-index":
                    (repository / "extra.txt").write_bytes(b"extra candidate\n")
                    module._run_git(repository, ["add", "--", "extra.txt"])
                elif variant == "missing-index":
                    module._run_git(repository, ["rm", "--cached", "--", self._PATHS[1]])
                elif variant == "config":
                    module._run_git(repository, ["config", "qinao.drift", "true"])
                else:
                    module._run_git(repository, ["-c", "user.name=Qinao Test", "-c", "user.email=qinao-test@invalid.local",
                        "commit", "--quiet", "-m", "premature result"])
                before = module.recover_run_state(root)["records"]
                with self.assertRaises(module.AuditError):
                    module.allocate_secret_scan_capture(root, repository=repository,
                        phase="task3-candidate", frontier_id=fixture["original"]["frontierId"])
                self.assertEqual(module.recover_run_state(root)["records"], before)
                child, reopened = self._cold(fixture, fixture["argv"] + ["--recover-exact"])
                self.assertEqual(child.returncode, 0, child.stderr.decode(errors="replace"))
                self.assertEqual(reopened, fixture["resumption"])

    def test_legacy_generic_prefix_does_not_become_new_authority(self):
        """Break caught: unrelated old outer/capture prefixes prevent or settle new provenance."""
        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._fixture(Path(temporary))
            root, repository = fixture["root"], fixture["repository"]
            for _index in range(2):
                self._append_outer(root, repository, ["recover-captures", "--root", str(root)])
            module.allocate_capture(root, "historical-generic", frontier_id=fixture["original"]["frontierId"])
            self._resume(fixture)
            child, cold = self._cold(fixture)
            self.assertEqual(child.returncode, 0, child.stderr.decode(errors="replace"))
            self.assertEqual(cold["taskResumptions"][fixture["original"]["frontierId"]]["state"], "settled")
            self.assertEqual(sum(value["state"] == "open" for value in cold["sterileInvocations"].values()), 3)
            self.assertEqual(sum(value["state"] == "allocated" for value in cold["captures"].values()), 1)

    def test_dirty_fresh_task4_start_remains_rejected(self):
        """Break caught: the new continuation silently relaxes ordinary clean starts."""
        with tempfile.TemporaryDirectory() as temporary:
            repository = self._repository_with_test_classes(Path(temporary))
            root = _new_run_root(Path(temporary))
            module.init_run_state(root, _identity_fields(repository), bootstrap_imports=[])
            (repository / "dirty.txt").write_bytes(b"dirty fresh task\n")
            before = module.recover_run_state(root)["records"]
            with self.assertRaisesRegex(module.AuditError, "not genuinely clean"):
                module.frontier_start(root, frontier_kind="task", task_number=4,
                    input_digest="4" * 64, declared_paths=["dirty.txt"], expected_tests=["RawDiffTests"])
            self.assertEqual(module.recover_run_state(root)["records"], before)

    def test_cross_run_wrong_frontier_and_unowned_creation_are_rejected(self):
        """Break caught: another run/frontier or absent invocation can create a resumption."""
        with tempfile.TemporaryDirectory() as temporary:
            base = Path(temporary)
            (base / "one").mkdir()
            (base / "two").mkdir()
            fixture = self._fixture(base / "one")
            foreign = self._fixture(base / "two")
            self._activate_repository_module(fixture["repository"])
            for variant in ("wrong-frontier", "foreign-original", "foreign-seal", "no-context"):
                with self.subTest(identity=variant):
                    argv = list(fixture["argv"])
                    if variant == "wrong-frontier":
                        argv[argv.index("--frontier-id") + 1] = "7" * 32
                    elif variant == "foreign-original":
                        argv[argv.index("--original-start-record") + 1] = str(foreign["originalPath"])
                    elif variant == "foreign-seal":
                        argv[argv.index("--evidence-seal-record") + 1] = str(foreign["sealPath"])
                    _outer, context = self._append_outer(fixture["root"], fixture["repository"], argv)
                    before = module.recover_run_state(fixture["root"])["records"]
                    with self.assertRaises(module.AuditError):
                        module._dispatch_command(argv, context=None if variant == "no-context" else context)
                    self.assertEqual(module.recover_run_state(fixture["root"])["records"], before)
            self._resume(fixture)
            before = module.recover_run_state(fixture["root"])["records"]
            with self.assertRaises(module.AuditError):
                module._dispatch_command(fixture["argv"])
            self.assertEqual(module.recover_run_state(fixture["root"])["records"], before)

    def test_raw_writers_cannot_publish_stale_or_nonatomic_resumption(self):
        """Break caught: lower-level publication bypasses real observation or atomicity."""
        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._fixture(Path(temporary))
            root, repository = fixture["root"], fixture["repository"]
            _outer, context = self._append_outer(root, repository, fixture["argv"])
            captured = {}
            real_writer = module.LedgerTransaction.write_record_atomic
            def stop_at_writer(transaction, sequence, record, **kwargs):
                if record.get("operationKind") == "task-resumption":
                    captured.update(copy.deepcopy(record))
                    raise KeyboardInterrupt("fixture stops before publication")
                return real_writer(transaction, sequence, record, **kwargs)
            with mock.patch.object(module.LedgerTransaction, "write_record_atomic", stop_at_writer):
                with self.assertRaises(KeyboardInterrupt):
                    module._dispatch_command(fixture["argv"], context=context)
            self.assertEqual(captured["resumption"]["schemaVersion"], "qinao.task3-resumption.v1")
            before = module.recover_run_state(root)["records"]
            with module.LedgerTransaction(root, operation_kind="task-resumption") as transaction:
                with self.assertRaisesRegex(module.AuditError, "requires atomic"):
                    transaction.write_record(captured["sequence"], captured)
            path = repository / self._PATHS[1]
            path.write_bytes(path.read_bytes() + b"\n# changed after observation\n")
            with module.LedgerTransaction(root, operation_kind="task-resumption") as transaction:
                with self.assertRaises(module.AuditError):
                    transaction.write_record_atomic(captured["sequence"], captured)
            self.assertEqual(module.recover_run_state(root)["records"], before)

    def test_existing_open_peer_prevents_new_resumption(self):
        """Break caught: a disclosed historical gap also bypasses one-open-peer exclusion."""
        with tempfile.TemporaryDirectory() as temporary:
            fixture = self._fixture(Path(temporary))
            root = fixture["root"]
            state = module.recover_run_state(root)
            peer = module._new_record(state["identity"], state["nextSequence"],
                state["records"][-1]["recordDigest"], "frontier-start", self._INPUT,
                self._PATHS, "open", {key: value for key, value in fixture["original"].items()
                    if key not in module._LEDGER_BASE_FIELDS})
            peer["frontierId"] = "9" * 32
            peer.pop("recordDigest")
            peer = module._self_digest_record(peer)
            module.write_canonical_exclusive(root / "ledger" / "records" / ("%016d.json" % peer["sequence"]), peer)
            _outer, context = self._append_outer(root, fixture["repository"], fixture["argv"])
            before = module.recover_run_state(root)
            self.assertEqual(before["classification"], "complete", before.get("reason"))
            self.assertEqual(len(before["openFrontiers"]), 2)
            with self.assertRaises(module.AuditError):
                module._dispatch_command(fixture["argv"], context=context)
            self.assertEqual(module.recover_run_state(root)["records"], before["records"])


